# ── inlined from daemon/nethttp.py (DM3+ bundle) ─────────────────────────
"""nethttp.py — leaf module: the ONE outbound HTTP fetch helper.

DAH1 (initiative `daemon-audit-hardening`). Before this module, nine
call-sites across `bootstrap`, `bootupdate`, `selfupdate`, `selfupdatesvc`,
`render`, `scaffold`, `teamsvc`, `verify` and `verifysvc` each hand-rolled
the same four lines:

    req = urllib.request.Request(url, headers={"User-Agent": ...})
    with urllib.request.urlopen(req, timeout=N) as r:
        payload = r.read()

…with a different User-Agent spelling, a different timeout, no scheme
check, and no ceiling on what they were willing to read into memory. Each
one that gained a hardening rule gained it alone.

What this leaf adds on top of the shared shape:

- **Scheme allow-list.** `urlopen` happily follows `file://`, `ftp://` and
  anything else registered — for a daemon that fetches its OWN NEXT BINARY
  from a URL that comes partly from `cluster.yaml`, that is the wrong
  default. Only http/https here.
- **A read ceiling.** `r.read()` with no argument is unbounded; a hostile
  or broken origin could stream until the daemon OOMs. `max_bytes` caps it.
- **One User-Agent convention**, built from the caller's short label.

Deliberately dependency-free (stdlib only, no sibling imports) so it sits
near the top of `bundle.MODULES` and every layer above can use it. It does
NOT log: each caller already has its own contextual `_log` line and its own
idea of whether a failure is fatal, best-effort, or worth a stamp on disk.
"""


import urllib.error
import urllib.parse
import urllib.request
from typing import Dict, Optional

# Only these ever make sense for the daemon's outbound calls (CDN bundles,
# TLS material, the standard's version file, an LLM API). `file:`/`ftp:`/
# `data:` reaching urlopen from a config-derived URL is a bug, not a feature.
ALLOWED_SCHEMES = ("http", "https")

# Default ceiling on a single response body. dist/daemon.py is ~1 MB, the
# TLS bundle is a few KB, an LLM reply is well under this — 16 MB is roomy
# for every legitimate caller and still bounds a hostile origin.
DEFAULT_MAX_BYTES = 16 * 1024 * 1024


class FetchError(RuntimeError):
    """Any outbound-fetch failure: bad scheme, transport error, oversize."""


def _agent(label: str, version: str = "") -> str:
    """`meshcore-py/<version> <label>` — the convention every call-site was
    already spelling by hand, slightly differently each time."""
    return (
        f"meshcore-py/{version} {label}".strip() if version else f"meshcore-py {label}"
    )


def fetch_bytes(
    url: str,
    *,
    label: str,
    version: str = "",
    timeout: float = 10.0,
    max_bytes: int = DEFAULT_MAX_BYTES,
    headers: Optional[Dict[str, str]] = None,
    data: Optional[bytes] = None,
) -> bytes:
    """GET (or POST, when `data` is given) `url` and return the body.

    Raises `FetchError` on a disallowed scheme, any transport failure, or a
    body that exceeds `max_bytes`. Callers that treat a failure as
    best-effort should catch it — this helper never returns a partial or
    sentinel value, because "empty string" was already indistinguishable
    from "404 page" at several of the old call-sites.
    """
    scheme = (urllib.parse.urlsplit(url).scheme or "").lower()
    if scheme not in ALLOWED_SCHEMES:
        raise FetchError(f"refusing scheme {scheme or '(none)'!r} for {url!r}")
    hdrs = {"User-Agent": _agent(label, version)}
    if headers:
        hdrs.update(headers)
    req = urllib.request.Request(url, headers=hdrs, data=data)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:  # noqa: S310
            # Read one byte past the cap so we can TELL oversize from exact-fit.
            payload = r.read(max_bytes + 1)
    except FetchError:
        raise
    except Exception as e:  # URLError, HTTPError, socket timeout, ssl, OSError
        raise FetchError(str(e)) from e
    if len(payload) > max_bytes:
        raise FetchError(f"response exceeds {max_bytes} bytes: {url!r}")
    return payload


def fetch_head_bytes(
    url: str,
    *,
    label: str,
    n: int,
    version: str = "",
    timeout: float = 10.0,
    headers: Optional[Dict[str, str]] = None,
) -> bytes:
    """First `n` bytes of `url`, asked for with a Range header and TRUNCATED
    on read when the origin ignores it. Used by the version watcher, which
    only needs daemon.py's leading `DAEMON_VERSION = "..."` line, not the
    whole ~1.2 MB bundle.

    py-1.38.2 — this used to delegate to `fetch_bytes(max_bytes=n)`, whose
    contract is "raise on oversize". Cloudflare Pages answers the Range
    request with a plain 200 and the full body, so every tick failed with
    `response exceeds 8192 bytes` and the version watcher had been dead
    fleet-wide for months — only the boot-time check (which fetches the
    whole file) kept clusters updating, and only when they restarted. The
    docstring promised truncation; now the code does it."""
    scheme = (urllib.parse.urlsplit(url).scheme or "").lower()
    if scheme not in ALLOWED_SCHEMES:
        raise FetchError(f"refusing scheme {scheme or '(none)'!r} for {url!r}")
    hdrs = {"User-Agent": _agent(label, version), "Range": f"bytes=0-{n - 1}"}
    if headers:
        hdrs.update(headers)
    req = urllib.request.Request(url, headers=hdrs)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:  # noqa: S310
            return r.read(n)
    except Exception as e:  # URLError, HTTPError, socket timeout, ssl, OSError
        raise FetchError(str(e)) from e


def fetch_text(
    url: str,
    *,
    label: str,
    version: str = "",
    timeout: float = 10.0,
    max_bytes: int = DEFAULT_MAX_BYTES,
    headers: Optional[Dict[str, str]] = None,
    encoding: str = "utf-8",
    errors: str = "replace",
) -> str:
    """`fetch_bytes` decoded. Same error contract."""
    return fetch_bytes(
        url,
        label=label,
        version=version,
        timeout=timeout,
        max_bytes=max_bytes,
        headers=headers,
    ).decode(encoding, errors=errors)


# ── inlined from daemon/wsframe.py (DM3+ bundle) ─────────────────────────
"""wsframe.py — the RFC-6455 frame codec, written once (DAH5).

Three places in this daemon speak WebSocket, and each one carried its own
copy of the frame arithmetic:

    hub.WSClient.send_text   server → client writer, frames NOT masked
    routes._ws_read_frame    server ← client reader, frames ARE masked
    verify._WS               a full client (handshake, masked writes, reads)

They are three genuinely different halves of the protocol, so they stay three
classes — `WSClient` carries the per-connection `RLock` that fixed the native
heap corruption of py-1.31.4, and `_WS` is a masking client that reassembles
fragments. What was duplicated is only the codec: the FIN/opcode byte, the
three length encodings (7-bit / 16-bit / 64-bit), the mask key and the XOR.
That part is pure functions, and it lives here now.

The consolidation buys one thing beyond the line count: a payload ceiling in
ONE place. Both readers used to hand the wire-declared length straight to
their `recv_exact`, so a peer announcing a 2^63-byte payload had the process
growing a buffer until the socket died. `read_frame` refuses above
`max_payload` before a single byte of body is read.

Stdlib-only leaf: no sibling imports, so it inlines first in the bundle.
"""


import os
import struct
from typing import Callable, NamedTuple, Optional

# ── opcodes (RFC 6455 §5.2) ─────────────────────────────────────────────
OP_CONT = 0x0
OP_TEXT = 0x1
OP_BINARY = 0x2
OP_CLOSE = 0x8
OP_PING = 0x9
OP_PONG = 0xA

_FIN = 0x80
_MASK_BIT = 0x80

# 1 MiB. Every inbound frame this daemon actually expects is tiny — the
# cockpit sends nothing but close frames, and CDP replies are JSON — so the
# ceiling is a guard rail, not a tuning knob. Screenshot payloads travel the
# other way (browser → us) on the verify client, which is why it is not
# smaller: a full-page base64 PNG is legitimately large.
MAX_PAYLOAD_BYTES = 8 * 1024 * 1024


class FrameTooLarge(ValueError):
    """Peer declared a payload above the caller's ceiling. Raised BEFORE the
    body is read, so refusing costs nothing."""


class Frame(NamedTuple):
    opcode: int
    payload: bytes
    fin: bool


def mask_payload(data: bytes, key: bytes) -> bytes:
    """XOR `data` with the 4-byte `key`. Symmetric: masks and unmasks."""
    if not data or not key:
        return data
    return bytes(b ^ key[i % 4] for i, b in enumerate(data))


def encode(payload: bytes, *, opcode: int = OP_TEXT, mask: bool = False) -> bytes:
    """One unfragmented frame. `mask=True` for the client half (RFC 6455
    §5.3 requires client→server frames to be masked), `False` for the
    server half (which must NOT mask)."""
    header = bytearray()
    header.append(_FIN | opcode)
    bit = _MASK_BIT if mask else 0
    n = len(payload)
    if n < 126:
        header.append(bit | n)
    elif n < 65536:
        header.append(bit | 126)
        header.extend(struct.pack(">H", n))
    else:
        header.append(bit | 127)
        header.extend(struct.pack(">Q", n))
    if not mask:
        return bytes(header) + payload
    key = os.urandom(4)
    header.extend(key)
    return bytes(header) + mask_payload(payload, key)


def encode_text(text: str, *, mask: bool = False) -> bytes:
    return encode(text.encode("utf-8"), opcode=OP_TEXT, mask=mask)


def close_frame(*, mask: bool = False) -> bytes:
    return encode(b"", opcode=OP_CLOSE, mask=mask)


def read_frame(
    recv_exact: Callable[[int], bytes],
    *,
    max_payload: int = MAX_PAYLOAD_BYTES,
) -> Optional[Frame]:
    """Read exactly ONE frame off the wire and return it, or None at EOF.

    `recv_exact(n)` must return n bytes. The two callers disagree on how they
    signal EOF — the server reader returns b"", the verify client raises —
    and both work here: a short read becomes None, an exception propagates to
    the caller that owns the socket.

    Raises `FrameTooLarge` when the declared length exceeds `max_payload`.
    """
    hdr = recv_exact(2)
    if not hdr or len(hdr) < 2:
        return None
    b0, b1 = hdr[0], hdr[1]
    fin = bool(b0 & _FIN)
    opcode = b0 & 0x0F
    masked = bool(b1 & _MASK_BIT)
    length = b1 & 0x7F
    if length == 126:
        ext = recv_exact(2)
        if len(ext) < 2:
            return None
        length = struct.unpack(">H", ext)[0]
    elif length == 127:
        ext = recv_exact(8)
        if len(ext) < 8:
            return None
        length = struct.unpack(">Q", ext)[0]
    # Refuse BEFORE reading the body — that is the whole point of the check.
    if length > max_payload:
        raise FrameTooLarge(f"frame declares {length} bytes (max {max_payload})")
    key = recv_exact(4) if masked else b""
    if masked and len(key) < 4:
        return None
    payload = recv_exact(length) if length else b""
    if length and len(payload) < length:
        return None
    if masked:
        payload = mask_payload(payload, key)
    return Frame(opcode, payload, fin)


# ── inlined from daemon/crypto_ed25519.py (DM3+ bundle) ─────────────────────────
"""crypto_ed25519.py — vendored pure-Python Ed25519 (sign + verify + keygen).

Why this exists (py-1.27.5). The daemon auto-updates by downloading a new
`daemon.py` from the CDN and re-exec'ing into it. Before this module the only
check was "does it parse + contain a DAEMON_VERSION marker" — so whoever
controls the CDN (or breaks TLS) could swap in arbitrary code that runs as the
operator. This adds CRYPTOGRAPHIC verification: every release is Ed25519-signed
with a private key that lives OFF the CDN (operator's machine only); the daemon
pins the PUBLIC key (constants.RELEASE_PUBKEY_HEX) and refuses to swap to a
build whose detached signature doesn't verify.

Stdlib-only by necessity — the daemon ships as a single zero-install `.py`, no
pip, so we can't use `cryptography`. This is the well-known public-domain
reference implementation (D. J. Bernstein et al., RFC 8032), with modular
exponentiation delegated to Python's built-in `pow(b, e, m)` for speed. Verify
runs once per update check (~0.1–0.5 s for two scalar-mults); fine for that.

NOT a general-purpose crypto library — it is constant-time-naive and only used
for release-signature verification of a public artifact. Do not repurpose it
for secrets handling.
"""


import hashlib

_b = 256
_q = 2**255 - 19
_L = 2**252 + 27742317777372353535851937790883648493


def _H(m: bytes) -> bytes:
    return hashlib.sha512(m).digest()


def _inv(x: int) -> int:
    return pow(x, _q - 2, _q)


_d = (-121665 * _inv(121666)) % _q
_I = pow(2, (_q - 1) // 4, _q)


def _xrecover(y: int) -> int:
    xx = (y * y - 1) * _inv(_d * y * y + 1)
    x = pow(xx, (_q + 3) // 8, _q)
    if (x * x - xx) % _q != 0:
        x = (x * _I) % _q
    if x % 2 != 0:
        x = _q - x
    return x


_By = (4 * _inv(5)) % _q
_Bx = _xrecover(_By)
_B = [_Bx % _q, _By % _q]


def _edwards(P, Q):
    x1, y1 = P
    x2, y2 = Q
    x3 = (x1 * y2 + x2 * y1) * _inv(1 + _d * x1 * x2 * y1 * y2)
    y3 = (y1 * y2 + x1 * x2) * _inv(1 - _d * x1 * x2 * y1 * y2)
    return [x3 % _q, y3 % _q]


def _scalarmult(P, e: int):
    # Iterative double-and-add (avoids deep recursion on a 253-bit scalar).
    Q = [0, 1]
    bits = []
    while e > 0:
        bits.append(e & 1)
        e >>= 1
    for bit in reversed(bits):
        Q = _edwards(Q, Q)
        if bit:
            Q = _edwards(Q, P)
    return Q


def _encodeint(y: int) -> bytes:
    return y.to_bytes(_b // 8, "little")


def _encodepoint(P) -> bytes:
    x, y = P
    val = y | ((x & 1) << (_b - 1))
    return val.to_bytes(_b // 8, "little")


def _bit(h: bytes, i: int) -> int:
    return (h[i // 8] >> (i % 8)) & 1


def _Hint(m: bytes) -> int:
    h = _H(m)
    return sum(2**i * _bit(h, i) for i in range(2 * _b))


def _secret_scalar(seed: bytes) -> int:
    h = _H(seed)
    return 2 ** (_b - 2) + sum(2**i * _bit(h, i) for i in range(3, _b - 2))


def ed25519_publickey(seed: bytes) -> bytes:
    """32-byte Ed25519 public key from a 32-byte seed (private key)."""
    if len(seed) != 32:
        raise ValueError("seed must be 32 bytes")
    A = _scalarmult(_B, _secret_scalar(seed))
    return _encodepoint(A)


def ed25519_sign(msg: bytes, seed: bytes, pub: bytes) -> bytes:
    """64-byte detached Ed25519 signature over msg."""
    h = _H(seed)
    a = _secret_scalar(seed)
    r = _Hint(h[_b // 8 : _b // 4] + msg)
    R = _scalarmult(_B, r)
    S = (r + _Hint(_encodepoint(R) + pub + msg) * a) % _L
    return _encodepoint(R) + _encodeint(S)


def _isoncurve(P) -> bool:
    x, y = P
    return (-x * x + y * y - 1 - _d * x * x * y * y) % _q == 0


def _decodeint(s: bytes) -> int:
    return int.from_bytes(s, "little")


def _decodepoint(s: bytes):
    y = int.from_bytes(s, "little") & ((1 << (_b - 1)) - 1)
    x = _xrecover(y)
    if x & 1 != _bit(s, _b - 1):
        x = _q - x
    P = [x, y]
    if not _isoncurve(P):
        raise ValueError("point not on curve")
    return P


def ed25519_verify(pub: bytes, msg: bytes, sig: bytes) -> bool:
    """True iff `sig` is a valid Ed25519 signature of `msg` under `pub`.
    Never raises — any malformed input returns False."""
    try:
        if len(sig) != 64 or len(pub) != 32:
            return False
        R = _decodepoint(sig[: _b // 8])
        A = _decodepoint(pub)
        S = _decodeint(sig[_b // 8 : _b // 4])
        h = _Hint(_encodepoint(R) + pub + msg)
        return _scalarmult(_B, S) == _edwards(R, _scalarmult(A, h))
    except Exception:
        return False


# ── inlined from daemon/fsatomic.py (DM3+ bundle) ─────────────────────────
"""fsatomic.py — crash-safe atomic file writes (Phase E3 DRY leaf).

Every on-disk JSON/YAML/markdown the daemon persists uses the same dance:
write a sibling ``<name>.tmp``, (optionally) fsync, then ``os.replace`` —
atomic on POSIX, so a crash mid-write leaves the OLD file intact, never a
truncated one that a later read silently parses as empty. That idiom was
copy-pasted across ~9 modules; this leaf is the single source of truth.

Leaf module: stdlib only, no daemon imports. Callers pass the exact JSON
flags they need (``sort_keys`` changes the bytes; ``fsync`` adds durability
without changing content) so the swap is byte-for-byte behaviour-preserving."""


import json
import os
from pathlib import Path
from typing import Any


def atomic_write_text(path: Path, text: str, *, fsync: bool = False) -> None:
    """Write ``text`` to ``path`` atomically via a sibling ``.tmp`` + replace.

    ``fsync=True`` flushes the kernel buffer to disk before the rename (use
    for state that must survive a hard crash — chat queues, archives)."""
    tmp = path.with_suffix(path.suffix + ".tmp")
    with open(tmp, "w", encoding="utf-8") as fh:
        fh.write(text)
        if fsync:
            fh.flush()
            os.fsync(fh.fileno())
    os.replace(tmp, path)


def atomic_write_json(
    path: Path,
    obj: Any,
    *,
    indent: int = 2,
    sort_keys: bool = False,
    fsync: bool = False,
    trailing_newline: bool = False,
) -> None:
    """``json.dumps(obj, …)`` then :func:`atomic_write_text`. Flags mirror the
    call sites so output stays byte-identical to the hand-rolled versions."""
    text = json.dumps(obj, indent=indent, sort_keys=sort_keys)
    if trailing_newline:
        text += "\n"
    atomic_write_text(path, text, fsync=fsync)


# ── inlined from daemon/timeutil.py (DM3+ bundle) ─────────────────────────
"""timeutil.py — UTC ISO-8601 timestamp helpers.

Extracted from utils.py (daemon-architecture-v2 Phase 3d). Verbatim move;
imported back where used."""


from datetime import datetime, timezone


def _iso_now() -> str:
    return (
        datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.")
        + f"{datetime.now(timezone.utc).microsecond // 1000:03d}Z"
    )


def _iso_at(epoch_secs: int) -> str:
    """ISO-8601 UTC for a given epoch — used for pause expiry stamps
    (py-1.10.26). Cheap; no ms component (we only care about the
    minute granularity for rate-limit cooldowns)."""
    return datetime.fromtimestamp(epoch_secs, timezone.utc).strftime(
        "%Y-%m-%dT%H:%M:%SZ"
    )


# ── inlined from daemon/yamlparse.py (DM3+ bundle) ─────────────────────────
"""yamlparse.py — tiny YAML + frontmatter parser.

Extracted from utils.py (daemon-architecture-v2 Phase 3d). Verbatim move;
imported back where used."""


import re
from typing import Any, Dict, List, Tuple

_FM_RE = re.compile(r"^---\s*\n(.*?)\n---\s*\n", re.DOTALL)


def parse_simple_yaml(text: str) -> Dict[str, Any]:
    """Parses a YAML subset sufficient for our cluster.yaml + frontmatter
    blocks. Supports scalars, dicts, lists, list-of-dicts, and inline
    list scalars (`tags: [a, b]`). NOT a general YAML parser — fail
    loudly for shapes we don't handle."""
    out: Dict[str, Any] = {}
    # Stack entry: (indent, container, key_in_parent, parent_ref_or_None)
    stack: List[Tuple[int, Any, str, Any]] = [(-1, out, "", None)]
    lines = text.splitlines()
    i = 0
    while i < len(lines):
        raw = lines[i]
        line = raw.rstrip()
        stripped = line.lstrip()
        if not stripped or stripped.startswith("#"):
            i += 1
            continue
        indent = len(line) - len(stripped)
        while stack and indent <= stack[-1][0] and len(stack) > 1:
            stack.pop()
        parent = stack[-1][1]

        if stripped.startswith("- "):
            value = stripped[2:].strip()
            # Promote: if the current container is an empty dict that was
            # just created as a nested holder for some key, convert it to
            # a list in the grandparent — we now know the value is a list.
            if isinstance(parent, dict) and not parent:
                key = stack[-1][2]
                gp = stack[-1][3]
                if key and isinstance(gp, dict) and gp.get(key) is parent:
                    new_list: List[Any] = []
                    gp[key] = new_list
                    stack[-1] = (stack[-1][0], new_list, key, gp)
                    parent = new_list
            if isinstance(parent, list):
                # Two shapes:
                #   "- value"               → scalar item
                #   "- key: val\n  key2: …" → dict item (continues below)
                if ":" in value:
                    item: Dict[str, Any] = {}
                    parent.append(item)
                    # Treat the inline "key: val" as the first dict entry
                    k2, _, v2 = value.partition(":")
                    k2 = k2.strip()
                    v2 = v2.strip()
                    if v2:
                        item[k2] = _coerce(_strip_inline_comment(v2))
                        stack.append((indent, item, "", parent))
                    else:
                        # Nested key with no value yet
                        nested: Dict[str, Any] = {}
                        item[k2] = nested
                        stack.append((indent, item, "", parent))
                        stack.append((indent + 2, nested, k2, item))
                else:
                    parent.append(
                        _coerce(_strip_inline_comment(value)) if value else None
                    )

        elif ":" in stripped:
            key, _, val = stripped.partition(":")
            key = key.strip()
            val = _strip_inline_comment(val.strip())
            if val == "":
                nxt: Dict[str, Any] = {}
                if isinstance(parent, dict):
                    parent[key] = nxt
                stack.append((indent, nxt, key, parent))
            elif val.startswith("[") and val.endswith("]"):
                # Inline list scalar: [a, b, "c d"]
                inner = val[1:-1].strip()
                items = (
                    [_coerce(x.strip()) for x in _split_top_level_commas(inner)]
                    if inner
                    else []
                )
                if isinstance(parent, dict):
                    parent[key] = items
            else:
                if isinstance(parent, dict):
                    parent[key] = _coerce(val)
        i += 1
    return out


def _strip_inline_comment(v: str) -> str:
    """Drop a trailing ` # comment` — but never one INSIDE a quoted scalar.

    JL-1: jobs.yaml stores shell commands (`git commit -m "fix #3"`), and the
    naive regex truncated any value containing a space-hash. It was already
    silently eating prose in links.yaml `notes:`. A quoted scalar ends at its
    closing quote; anything after that is the comment."""
    s = v.lstrip()
    q = s[:1]
    if q in ('"', "'"):
        i = 1
        while i < len(s):
            if q == '"' and s[i] == "\\":
                i += 2
                continue
            if s[i] == q:
                return s[: i + 1]
            i += 1
        # Unterminated quote — fall through to the legacy behaviour.
    return re.sub(r"\s+#.*$", "", v)


def _unescape_double_quoted(s: str) -> str:
    """`\\"` → `"` and `\\\\` → `\\`, left to right (JL-1: the jobs emitter
    escapes a command that contains BOTH quote characters)."""
    out, i = [], 0
    while i < len(s):
        if s[i] == "\\" and i + 1 < len(s) and s[i + 1] in ('"', "\\"):
            out.append(s[i + 1])
            i += 2
            continue
        out.append(s[i])
        i += 1
    return "".join(out)


def _split_top_level_commas(s: str) -> List[str]:
    out, buf, depth, in_str = [], "", 0, None
    for ch in s:
        if in_str:
            buf += ch
            if ch == in_str:
                in_str = None
            continue
        if ch in ('"', "'"):
            in_str = ch
            buf += ch
            continue
        if ch == "," and depth == 0:
            out.append(buf)
            buf = ""
            continue
        if ch in "[{":
            depth += 1
        elif ch in "]}":
            depth -= 1
        buf += ch
    if buf.strip():
        out.append(buf)
    return out


def _coerce(v: str) -> Any:
    s = v.strip()
    if not s:
        return ""
    if len(s) >= 2 and s.startswith('"') and s.endswith('"'):
        return _unescape_double_quoted(s[1:-1])
    if len(s) >= 2 and s.startswith("'") and s.endswith("'"):
        return s[1:-1]
    if s.lower() in ("true", "yes"):
        return True
    if s.lower() in ("false", "no"):
        return False
    if s.lower() in ("null", "~"):
        return None
    try:
        return int(s)
    except ValueError:
        pass
    try:
        return float(s)
    except ValueError:
        pass
    return s


def parse_frontmatter(text: str) -> Dict[str, Any]:
    m = _FM_RE.match(text)
    if not m:
        return {}
    return parse_simple_yaml(m.group(1))


def split_frontmatter(text: str) -> Tuple[Dict[str, Any], str]:
    """`(frontmatter dict, body)` for a `---`-fenced markdown file. Returns
    `({}, text)` when there is no complete frontmatter block.

    DAH1 (daemon-audit-hardening) — moved here VERBATIM from `registries.py`
    (where it was `_split_frontmatter`, which still re-exports it). It belongs
    in the leaf that already owns `_FM_RE`, next to `parse_frontmatter`, and it
    is the strictly better of the four frontmatter readers this codebase had
    grown: `prompts.py` hand-rolled the same fence walk TWICE with a different
    start offset, and unlike `parse_frontmatter`'s regex this one still parses
    a file whose closing `---` has no trailing newline.

    (`team.split_member_file` stays separate on purpose: it must return the
    body byte-for-byte so a parse→serialise round-trip preserves a member's
    init prompt exactly.)"""
    if not text.startswith("---"):
        return {}, text
    end = text.find("\n---", 4)
    if end == -1:
        return {}, text
    fm_text = text[4:end]
    body = text[end + 4 :].lstrip("\n")
    return parse_simple_yaml(fm_text), body


# ── inlined from daemon/timeline.py (DM3+ bundle) ─────────────────────────
"""timeline.py — timeline JSONL read/append helpers.

Extracted from utils.py (daemon-architecture-v2 Phase 3d). Verbatim move;
imported back where used."""


import json
import os
from typing import Any, Dict, List



def _iter_timeline_files(paths: "Paths") -> List[Any]:
    """All timeline files (jsonl + jsonl.gz from rotation)."""
    if not paths.timeline_dir.exists():
        return []
    files = list(paths.timeline_dir.glob("*.jsonl"))
    files.extend(paths.timeline_dir.glob("*.jsonl.gz"))
    # Also look in the archive subdir produced by rotation.
    archive_dir = paths.timeline_dir / "archive"
    if archive_dir.exists():
        files.extend(archive_dir.glob("*.jsonl"))
        files.extend(archive_dir.glob("*.jsonl.gz"))
    return files


def _read_timeline_file(path: Any) -> List[Dict[str, Any]]:
    """Parse one timeline file (jsonl or jsonl.gz) → list of events.
    Never raises; bad lines / unreadable files yield empty list."""
    try:
        if str(path).endswith(".gz"):
            import gzip

            with gzip.open(path, "rt", encoding="utf-8", errors="replace") as fh:
                lines = fh.read().splitlines()
        else:
            lines = path.read_text(errors="replace").splitlines()
    except OSError:
        return []
    out: List[Dict[str, Any]] = []
    for line in lines:
        try:
            out.append(json.loads(line))
        except json.JSONDecodeError:
            continue
    return out


def _append_timeline(paths: "Paths", event: Dict[str, Any]) -> Dict[str, Any]:
    """Append one JSON-line event to today's timeline file.
    Returns the event enriched with `ts` if it wasn't already set.

    py-1.5.0 — atomic append. The line is rendered fully in memory,
    then written + flushed + fsync'd in a single open/close cycle so
    a daemon crash mid-write can't leave a half-written line in the
    jsonl. We rely on the OS guarantee that `write()` is atomic for
    buffers < PIPE_BUF (~4KB on most systems); for larger events
    (very long assistant.final replies) we still get atomicity at the
    page-cache level under POSIX. The added fsync forces durability
    so we don't lose events on a power cut either."""
    paths.timeline_dir.mkdir(parents=True, exist_ok=True)
    if "ts" not in event:
        event = {**event, "ts": _iso_now()}
    date = event["ts"][:10]
    f = paths.timeline_dir / f"{date}.jsonl"
    payload = json.dumps(event, separators=(",", ":")) + "\n"
    encoded = payload.encode("utf-8")
    # Open with O_APPEND so concurrent writers (the StateManager poll
    # loop + ChatRunner reader threads) interleave at line boundaries
    # rather than overwrite each other. O_APPEND is atomic per write()
    # on POSIX for any size up to PIPE_BUF; for larger writes (a multi-
    # KB assistant.final) the worst case is interleaved bytes, but the
    # daemon's writers never race on the same line. Single line per
    # write() call preserves jsonl integrity.
    fd = os.open(f, os.O_WRONLY | os.O_APPEND | os.O_CREAT, 0o644)
    try:
        os.write(fd, encoded)
        try:
            os.fsync(fd)
        except OSError:
            pass  # best-effort durability
    finally:
        os.close(fd)
    return event


