# Module-level singleton so `_log()` and any free function can emit
# without threading a `daemon` ref through every call site. Set by
# Daemon.serve_forever during boot (see daemon.py).

_DEBUG_LOG: Optional["DebugLog"] = None


def set_debug_log(log: Optional["DebugLog"]) -> None:
    """Daemon boot calls this to wire the singleton. Sibling modules
    don't need to know which module owns the global — they just call
    ``debug_enabled()`` or ``_debug_emit(...)``."""
    global _DEBUG_LOG
    _DEBUG_LOG = log


def debug_enabled() -> bool:
    return _DEBUG_LOG is not None


def get_debug_log() -> Optional["DebugLog"]:
    """Live ref for callers that need to call methods on the singleton
    (``DebugLog.tail``, ``DebugLog.emit``). Returns ``None`` when the
    debug stream is disabled."""
    return _DEBUG_LOG


def _log(msg: str) -> None:
    print(f"[meshcore-py {_iso_now()}] {msg}", flush=True)
    # py-1.10.17 — mirror every daemon log line into the debug stream
    # so a single tail covers the unstructured prose + the structured
    # event hooks (architect-wake, chat-dispatch, …) below.
    if _DEBUG_LOG is not None:
        try:
            _DEBUG_LOG.emit(tag="log", lvl="info", msg=msg, src="daemon")
        except Exception:
            # Debug stream failures must never block the program.
            pass


_REDACT_KEYS = {
    "token",
    "authorization",
    "bearer",
    "api_key",
    "apikey",
    "secret",
    "password",
}


def _debug_redact(data: Any) -> Any:
    """Best-effort scrub of token-like values in arbitrary payloads."""
    if isinstance(data, dict):
        out: Dict[str, Any] = {}
        for k, v in data.items():
            if str(k).lower() in _REDACT_KEYS:
                out[k] = "<redacted>"
            else:
                out[k] = _debug_redact(v)
        return out
    if isinstance(data, list):
        return [_debug_redact(x) for x in data]
    if isinstance(data, str) and len(data) > 24 and data.startswith("Bearer "):
        return "Bearer <redacted>"
    return data


def _debug_emit(
    tag: str,
    *,
    msg: str = "",
    lvl: str = "info",
    src: str = "daemon",
    conv: Optional[str] = None,
    agent_id: Optional[str] = None,
    data: Optional[Dict[str, Any]] = None,
) -> None:
    """Convenience: skip the `if _DEBUG_LOG is not None:` dance at
    every emit site. No-op when the daemon hasn't initialised yet OR
    when the operator opted out via `cluster.yaml.debug.enabled: false`
    (py-1.10.21)."""
    if _DEBUG_LOG is None:
        return
    try:
        _DEBUG_LOG.emit(
            tag=tag,
            msg=msg,
            lvl=lvl,
            src=src,
            conv=conv,
            agent_id=agent_id,
            data=data,
        )
    except Exception:
        pass


def _debug_enabled(cluster: Any) -> bool:
    """Read `cluster.yaml.debug.enabled` (default `True`). Falsy disables
    DebugLog initialisation entirely — no file written, /debug/tail
    returns empty, /debug/log accepts but drops. py-1.10.21. Note the
    default is ON for MeshKore native development; downstream clusters
    that want zero disk footprint flip it to false."""
    try:
        block = cluster.data.get("debug") if isinstance(cluster.data, dict) else None
        if not isinstance(block, dict):
            return True
        v = block.get("enabled")
        if v is None:
            return True
        if isinstance(v, bool):
            return v
        return str(v).strip().lower() not in ("0", "false", "no", "off")
    except Exception:
        return True


# ───────────────────────────────────────────────────────────────────────
# Tiny YAML reader (stdlib has no yaml module — we only need flat scalars)
#
# DM-modularize-2 (py-1.14.4): relocated from daemon.py. parse_simple_yaml
# + parse_frontmatter are pure helpers used by Cluster, every frontmatter
# read, and the prompts module's StateIntegrityChecker. Living in utils
# keeps the layering top-down (prompts.py imports them from here instead
# of reaching back into daemon.py). daemon.py re-exports them so
# `daemon.parse_simple_yaml` stays a stable attribute.


# ───────────────────────────────────────────────────────────────────────
# Timeline append (DM-modularize-2: relocated from daemon.py). Shared by
# ChatRunner (runner.py) and the daemon's own chat/user event writers.


# ───────────────────────────────────────────────────────────────────────
# TLS bundle discovery + in-prompt base URL (DM-modularize-2: relocated
# from daemon.py). `_find_tls_bundle` resolves the (cert, key) sitting
# next to the running file via `Path(__file__).parent` — in the source
# tree that's `daemon/` (same parent as daemon.py), in the bundle it's
# `dist/` (everything inlined into one file). `_daemon_base_url` is used
# by the prompts module to bake endpoint URLs into agent briefings.


def _find_tls_bundle() -> Optional[Tuple[Path, Path]]:
    """Locate (cert, key) next to daemon.py. Returns None if either
    file is missing — daemon then falls back to plain HTTP, so older
    operators who don't have the bundle keep working unchanged."""
    here = Path(__file__).resolve().parent
    cert = here / TLS_BUNDLE_NAME / TLS_CERT_FILENAME
    key = here / TLS_BUNDLE_NAME / TLS_KEY_FILENAME
    if not cert.is_file() or not key.is_file():
        return None
    try:
        cert.read_bytes()
        key.read_bytes()
    except OSError as e:
        _log(f"tls: bundle exists but unreadable ({e}); falling back to HTTP")
        return None
    return cert, key


def _daemon_base_url(port: int) -> str:
    """Authoritative base URL for in-prompt daemon endpoints.

    py-1.10.14 — when the TLS bundle is present the listener wraps its
    socket and plain HTTP returns RST. Subprocess agents that the
    daemon spawns (architect, custom, deploy, …) get their endpoint
    URLs baked into the briefing string; previously those were always
    `http://localhost:<port>`, which silently broke the moment TLS was
    enabled. Now: prefer `https://daemon.meshkore.com:<port>` whenever
    the bundle exists, falling back to plain HTTP only when it's not.
    Same logic as `Daemon.health().endpoint`, kept in sync here because
    the briefing is composed off the request path (no daemon ref)."""
    if _find_tls_bundle() is not None:
        return f"https://daemon.meshkore.com:{port}"
    return f"http://localhost:{port}"


# ── inlined from daemon/sweeper.py (DM3+ bundle) ─────────────────────────
"""sweeper.py — leaf module: the background loop that runs over EVERY project.

DAH1 (initiative `daemon-audit-hardening`). `ChatSessionReaper` and
`QuotaProber` are unrelated in what they do and were identical in how they
did it: the same `_thread`/`_stop` lifecycle, the same `start()` guard, the
same `stop()`, and — the part that actually matters — the same FC-2
per-project binding dance:

    reg = getattr(self.daemon, "_registry", None)
    pids = [c.cluster.id for c in reg.built_contexts()] if reg else [None]
    for pid in pids:
        try:
            if pid is not None: self.daemon._set_req_project(pid)
            ...work...
        finally:
            if pid is not None: self.daemon._clear_req_project()

That block is easy to get subtly wrong (forget the `finally` and one
project's threadlocal leaks into the next project's sweep — every
`self.daemon.paths` afterwards resolves to the WRONG cluster). Having it
written twice meant two chances to get it wrong and two places to fix it.
Any future periodic sweeper should subclass this rather than re-type it.

Subclass contract: set `TICK_SECS` and implement `tick()`, which runs ONCE
per project per tick with that project already bound on this thread.
"""


import threading
from typing import Any, List, Optional



class ProjectSweeper:
    """A daemon-thread loop that calls `tick()` once per registered project
    every `TICK_SECS`, with the project bound on the calling thread."""

    TICK_SECS = 30.0
    #: Shown in logs and used as the thread name. Subclasses override.
    NAME = "sweeper"

    def __init__(self, daemon: Any) -> None:
        self.daemon = daemon
        self._stop = threading.Event()
        self._thread: Optional[threading.Thread] = None

    # ── lifecycle ───────────────────────────────────────────────────────
    def start(self) -> None:
        if self._thread is not None:
            return
        self.on_start()
        self._thread = threading.Thread(target=self._loop, name=self.NAME, daemon=True)
        self._thread.start()
        _log(f"{self.NAME}: started (tick={self.TICK_SECS}s)")

    def stop(self) -> None:
        self._stop.set()

    def on_start(self) -> None:
        """Optional one-shot work before the loop thread starts (e.g. the
        chat reaper's boot sweep). Failures are logged, never fatal."""

    # ── the loop ────────────────────────────────────────────────────────
    def _project_ids(self) -> List[Optional[str]]:
        """Every project this daemon serves, or `[None]` (bind nothing → the
        default/boot project) when the registry isn't available yet."""
        reg = getattr(self.daemon, "_registry", None)
        if reg is None:
            return [None]
        try:
            return [c.cluster.id for c in reg.built_contexts()]
        except Exception as e:  # noqa: BLE001 — a registry hiccup must not stop the loop
            _log(f"{self.NAME}: project enumeration failed ({e})")
            return [None]

    def _loop(self) -> None:
        while not self._stop.wait(self.TICK_SECS):
            for pid in self._project_ids():
                if self._stop.is_set():
                    break
                try:
                    if pid is not None:
                        self.daemon._set_req_project(pid)
                    self.tick()
                except Exception as e:  # noqa: BLE001 — one project must not stop the rest
                    _log(f"{self.NAME}: tick failed ({e})")
                finally:
                    # Non-negotiable: leaving the threadlocal set would make the
                    # NEXT project's sweep resolve self.daemon.* to the previous
                    # cluster's paths/stores.
                    if pid is not None:
                        self.daemon._clear_req_project()

    def tick(self) -> None:
        """One unit of work for the currently-bound project. Subclass this."""
        raise NotImplementedError


# ── inlined from daemon/debuglog.py (DM3+ bundle) ─────────────────────────
"""debuglog.py — DebugLog — the debug.jsonl ring stream.

Extracted from utils.py (daemon-architecture-v2 Phase 3d). Verbatim move;
imported back where used."""


import json
import os
import threading
import time
from datetime import datetime
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple



class DebugLog:
    """Append-only JSONL debug stream.

    Path: `.meshkore/.runtime/debug.jsonl`. Each line is one event:
        {"ts": "...", "src": "daemon|cockpit|agent", "lvl": "...",
         "tag": "...", "conv"?: ..., "agent_id"?: ..., "msg": "...",
         "data"?: { ... }}

    Retention: when the file exceeds `MAX_BYTES`, the writer reads it
    back, keeps only events whose `ts` falls within `RETAIN_SECS` of
    the current instant, and atomically rewrites the file. Worst-case
    trim cost: O(file_size) but bounded by MAX_BYTES.

    Thread-safe. Failures never raise — the daemon must keep running
    even if the log disk is full or read-only."""

    MAX_BYTES = 5 * 1024 * 1024  # 5 MB
    # LT-4 — 30 minutes was too short to diagnose anything that happened
    # while nobody was watching. A turn was killed at 02:00 and the
    # operator asked about it at 09:47: by then every debug event behind
    # it had been trimmed, and the only surviving evidence was the raw
    # daemon stdout. The byte cap still dominates on a busy day, so this
    # costs nothing there and buys a night's history on a quiet one.
    RETAIN_SECS = 12 * 60 * 60  # 12 h
    TRIM_CHECK_EVERY = 50  # check size every N appends, not every time

    def __init__(self, path: "Path") -> None:
        self.path = path
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._lock = threading.Lock()
        self._writes_since_check = 0
        # Touch the file so subsequent appends never hit ENOENT mid-write.
        if not self.path.exists():
            try:
                self.path.write_text("")
            except OSError:
                pass
        # py-1.10.21 — Trim once on boot. A long-running daemon that
        # writes < TRIM_CHECK_EVERY events between restarts (low-traffic
        # day) was leaving the file with stale head events that
        # predated the rolling window by hours. One trim at startup
        # gives the operator a clean window immediately.
        with self._lock:
            self._maybe_trim_locked()

    def emit(
        self,
        *,
        tag: str,
        msg: str = "",
        lvl: str = "info",
        src: str = "daemon",
        conv: Optional[str] = None,
        agent_id: Optional[str] = None,
        project: Optional[str] = None,
        data: Optional[Dict[str, Any]] = None,
    ) -> None:
        rec: Dict[str, Any] = {
            "ts": _iso_now(),
            "src": src,
            "lvl": lvl,
            "tag": tag,
            "msg": msg,
        }
        # centralized/multi-project — which project this entry belongs to (from
        # the X-MeshKore-Project header on cockpit posts, or the daemon's
        # request context). Lets the ONE centralized debug stream be filtered
        # per project (GET /debug/tail?project=<id>).
        if project:
            rec["project"] = project
        if conv:
            rec["conv"] = conv
        if agent_id:
            rec["agent_id"] = agent_id
        if data:
            # Best-effort redaction. Token-like values get masked.
            rec["data"] = _debug_redact(data)
        line = json.dumps(rec, ensure_ascii=False) + "\n"
        with self._lock:
            try:
                with open(self.path, "a", encoding="utf-8") as f:
                    f.write(line)
            except OSError:
                return
            self._writes_since_check += 1
            if self._writes_since_check >= self.TRIM_CHECK_EVERY:
                self._writes_since_check = 0
                self._maybe_trim_locked()

    def _maybe_trim_locked(self) -> None:
        # py-1.10.21 — Trim by EITHER size OR age. The original code
        # only checked size, so on low-traffic days the file kept
        # events from 2-3 hours ago even though the convention says
        # "30 min rolling window". We now also inspect the first line
        # cheaply: if it's older than RETAIN_SECS we know the head is
        # stale and read the full file to rewrite.
        try:
            size = self.path.stat().st_size
        except OSError:
            return
        cutoff = time.time() - self.RETAIN_SECS
        need_trim = size > self.MAX_BYTES
        if not need_trim:
            # Cheap age probe: read just the first non-empty line.
            try:
                with open(self.path, "r", encoding="utf-8") as f:
                    for line in f:
                        line = line.strip()
                        if not line:
                            continue
                        try:
                            rec = json.loads(line)
                            ts_str = str(rec.get("ts") or "")
                            norm = (
                                ts_str[:-1] + "+00:00"
                                if ts_str.endswith("Z")
                                else ts_str
                            )
                            head_ts = datetime.fromisoformat(norm).timestamp()
                            if head_ts < cutoff:
                                need_trim = True
                        except (ValueError, TypeError):
                            pass
                        break
            except OSError:
                return
        if not need_trim:
            return
        try:
            raw = self.path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            return
        kept: List[str] = []
        for line in raw.splitlines():
            if not line.strip():
                continue
            ts_str = ""
            try:
                rec = json.loads(line)
                ts_str = rec.get("ts") or ""
            except (ValueError, TypeError):
                continue
            try:
                # ts ends with Z; strptime via fromisoformat after Z→+00:00.
                norm = ts_str[:-1] + "+00:00" if ts_str.endswith("Z") else ts_str
                if datetime.fromisoformat(norm).timestamp() >= cutoff:
                    kept.append(line)
            except (ValueError, TypeError):
                continue
        new_blob = "\n".join(kept) + ("\n" if kept else "")
        tmp = self.path.with_suffix(self.path.suffix + ".tmp")
        try:
            tmp.write_text(new_blob, encoding="utf-8")
            os.replace(tmp, self.path)
        except OSError:
            return

    def tail(
        self,
        *,
        last_secs: int = 300,
        tags: Optional[set[str]] = None,
        min_level: str = "debug",
    ) -> Tuple[List[Dict[str, Any]], int]:
        """Return (events, retained_secs). `retained_secs` is the
        actual age of the oldest event still on disk — useful to detect
        when the operator asked for a window wider than retention."""
        levels = {"debug": 0, "info": 1, "warn": 2, "error": 3}
        min_rank = levels.get(min_level.lower(), 0)
        cutoff = time.time() - max(1, last_secs)
        out: List[Dict[str, Any]] = []
        oldest_ts: Optional[float] = None
        try:
            raw = self.path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            return out, 0
        for line in raw.splitlines():
            if not line.strip():
                continue
            try:
                rec = json.loads(line)
            except (ValueError, TypeError):
                continue
            ts_str = str(rec.get("ts") or "")
            try:
                norm = ts_str[:-1] + "+00:00" if ts_str.endswith("Z") else ts_str
                ts = datetime.fromisoformat(norm).timestamp()
            except (ValueError, TypeError):
                continue
            if oldest_ts is None or ts < oldest_ts:
                oldest_ts = ts
            if ts < cutoff:
                continue
            if tags and rec.get("tag") not in tags:
                continue
            if levels.get(str(rec.get("lvl") or "info"), 1) < min_rank:
                continue
            out.append(rec)
        retained = int(time.time() - oldest_ts) if oldest_ts else 0
        return out, retained


# ── HTTP surfaces ────────────────────────────────────────────────────────
#
# Audit 2026-09-27 — `/debug/tail` and `/debug/log` were ~70 lines inline in
# the routers, the only code in the daemon that parsed the debug query
# grammar or shaped a cockpit event into `emit()`. Both live here now and
# return `(code, body)`; the routers know the two paths and nothing else.


def debug_tail_http(q: Dict[str, str]) -> Tuple[int, Dict[str, Any]]:
    """`GET /debug/tail?last=<secs>&tag=a,b&level=<lvl>&project=<id>`."""

    if not debug_enabled():
        return 200, {"events": [], "retained_secs": 0}
    try:
        last_secs = int(q.get("last") or "300")
    except ValueError:
        last_secs = 300
    tag_csv = (q.get("tag") or "").strip()
    tags = set(t for t in tag_csv.split(",") if t) or None
    events, retained = get_debug_log().tail(
        last_secs=last_secs,
        tags=tags,
        min_level=(q.get("level") or "debug").lower(),
    )
    # centralized/multi-project — one debug stream, sliced per project.
    proj = (q.get("project") or "").strip()
    if proj:
        events = [e for e in events if e.get("project") == proj]
    return 200, {
        "events": events,
        "retained_secs": retained,
        "window_secs": last_secs,
        "generated_at": _iso_now(),
    }


def debug_ingest_http(
    body: Any, header_project: Optional[str]
) -> Tuple[int, Dict[str, Any]]:
    """`POST /debug/log` — cockpit events into the shared debug stream.

    Body is `{events: [...]}` or a single event. Each event is tagged with
    the project it names, else the request's `X-MeshKore-Project`."""

    if not debug_enabled():
        return 503, {"error": "debug stream not ready"}
    events = body.get("events") if isinstance(body, dict) else None
    if not isinstance(events, list):
        events = [body] if isinstance(body, dict) else []
    accepted = 0
    for ev in events:
        if not isinstance(ev, dict):
            continue
        conv = ev.get("conv")
        agent_id = ev.get("agent_id")
        project = ev.get("project") or header_project
        get_debug_log().emit(
            tag=str(ev.get("tag") or "log")[:64],
            msg=str(ev.get("msg") or "")[:4000],
            lvl=str(ev.get("lvl") or "info"),
            src="cockpit",
            conv=(str(conv) if conv else None),
            agent_id=(str(agent_id) if agent_id else None),
            project=(str(project) if project else None),
            data=ev.get("data") if isinstance(ev.get("data"), dict) else None,
        )
        accepted += 1
    return 200, {"accepted": accepted}


# ── inlined from daemon/cluster.py (DM3+ bundle) ─────────────────────────
"""cluster.py — Cluster (cluster.yaml + roadmap frontmatter) + frontmatter helpers.

Extracted from daemon.py (DA-CLUSTER-01, daemon-architecture-v2). Owns
parsing cluster.yaml, the modules/initiatives/tasks frontmatter read+patch
(_patch_frontmatter), and status normalization. Pure config/IO over Paths +
the utils YAML/frontmatter helpers — no daemon backref. Consumers
(prompts/runner/cron/daemon) type-ref Cluster only.
"""



from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple



class Cluster:
    def __init__(self, paths: Paths):
        self.paths = paths
        self.data: Dict[str, Any] = {}
        # Cron scheduler (D-CRON-01): validated job set + ownership.
        # Populated by reload(); empty + None until a `crons:` block
        # appears in cluster.yaml.
        self.crons: List[Dict[str, Any]] = []
        self.crons_owner: Optional[str] = None
        self.reload()

    def reload(self) -> None:
        if not self.paths.cluster_yaml.exists():
            raise SystemExit(
                f"\n .meshkore/public/cluster.yaml not found at {self.paths.cluster_yaml}."
                "\n   Run `meshcore init` (or hand-author cluster.yaml from"
                "\n   https://meshkore.com/reference/cluster/templates/) and re-run.\n"
            )
        # GH1-WINBOOT (meshkore/daemon#1): explicit UTF-8 — this is the exact
        # read that dies on a cp1252-poisoned half-scaffold.
        self.data = parse_simple_yaml(
            self.paths.cluster_yaml.read_text(encoding="utf-8")
        )
        # Validate the cron block last so a bad config logs warnings but
        # never blocks the daemon's other features.
        self.crons, errs = _validate_crons_block(self.data)
        for e in errs:
            _log(f"cluster.yaml crons: {e}")
        owner = self.data.get("crons_owner")
        self.crons_owner = (
            owner.strip() if isinstance(owner, str) and owner.strip() else None
        )
        if self.crons and not self.crons_owner:
            _log(
                "cluster.yaml has crons: but no crons_owner — scheduler will tick but never fire"
            )

    @property
    def id(self) -> str:
        """The cluster's identifier from cluster.yaml.

        LOCAL-ONLY today: it scopes THIS machine's daemon and its local
        agents. It is the reserved ANCHOR for a possible future where the
        daemon orchestrates off-device agents (cross-device cluster
        membership / admission). No cross-device behaviour is wired today —
        the facilitated cross-device channel work lives in initiative
        `private-clusters`, which is intentionally out of the daemon's scope
        for now. This placeholder exists so that future capability has a
        stable identity to build on.
        """
        return str(self.data.get("id") or "unknown")

    @property
    def name(self) -> str:
        return str(self.data.get("name") or self.id)

    @property
    def type(self) -> str:
        return str(self.data.get("type") or "dev")

    @property
    def architect_port(self) -> Optional[int]:
        # cluster.yaml.architect.port (preferred) → fall back to legacy portal.port
        for key in ("architect", "portal"):
            sec = self.data.get(key)
            if isinstance(sec, dict) and "port" in sec:
                try:
                    return int(sec["port"])
                except (TypeError, ValueError):
                    pass
        return None

    @property
    def modules(self) -> List[Dict[str, Any]]:
        m = self.data.get("modules") or []
        return m if isinstance(m, list) else []


def _patch_frontmatter(fp: "Path", patch: Dict[str, Any]) -> bool:
    """Idempotent frontmatter merge. Writes only the fields in `patch`
    that differ from current. Preserves field order: known fields keep
    their position, new fields append in `patch` order.

    py-1.12.4 — a `None` value in the patch REMOVES that key from the
    frontmatter (used by the bidirectional reconcile to wipe stale
    `completed_at` / `commit_sha` when a partially-done initiative is
    reverted from done → active).

    Returns True iff the file was actually rewritten."""
    text = fp.read_text(errors="replace")
    m = _FM_RE.match(text)
    if not m:
        # No frontmatter to patch — refuse rather than corrupt.
        return False
    fm_block = m.group(1)
    rest = text[m.end() :]
    current = parse_simple_yaml(fm_block)
    # Detect any actual change. A None patch entry counts as a change
    # iff the key currently exists.
    changed = False
    for k, v in patch.items():
        if v is None:
            if k in current and current.get(k) not in (None, ""):
                changed = True
                break
        else:
            if str(current.get(k) or "") != str(v):
                changed = True
                break
    if not changed:
        return False
    lines = fm_block.splitlines()
    handled: set[str] = set()
    new_lines: List[str] = []
    for line in lines:
        if ":" in line and not line.startswith((" ", "\t", "-", "#")):
            key = line.split(":", 1)[0].strip()
            if key in patch:
                handled.add(key)
                if patch[key] is None:
                    # Skip the line — that's the removal.
                    continue
                new_lines.append(f"{key}: {patch[key]}")
                continue
        new_lines.append(line)
    for k, v in patch.items():
        if k in handled or v is None:
            continue
        new_lines.append(f"{k}: {v}")
    new_fm = "\n".join(new_lines)
    if not new_fm.endswith("\n"):
        new_fm += "\n"
    new_text = "---\n" + new_fm + "---\n" + rest.lstrip("\n")
    atomic_write_text(fp, new_text)
    return True


# RSV1 — the alias table. The roadmap files use 17 distinct `status` values;
# this maps every one of them onto the six the rest of the system reasons
# about. It used to be an `if` chain that recognised five values and silently
# returned `backlog` for everything else, which was wrong in both directions:
# a finished initiative marked `shipped` read as pending work, and 36 `draft`
# / `planned` / `ready` initiatives reached the cockpit as their raw literal,
# where its `done/backlog/next` test fell through to the ACTIVE branch — so
# three quarters of the "active" roadmap were sketches.
#
# Add an alias here rather than teaching a consumer a new spelling.
STATUS_ALIASES = {
    # in flight
    "in_progress": "active",
    "in-progress": "active",
    "doing": "active",
    "wip": "active",
    # finished
    "shipped": "done",
    "completed": "done",
    "complete": "done",
    "archived": "done",
    # not started — a sketch is backlog, it is not work in progress
    "planned": "backlog",
    "pending": "backlog",
    "draft": "backlog",
    "ready": "backlog",
    "todo": "backlog",
    "new": "backlog",
    # closed without being carried out (see is_resolved_status)
    "canceled": "cancelled",
    "dropped": "cancelled",
    "wontfix": "cancelled",
    "won't-fix": "cancelled",
    "superseded": "cancelled",
    "obsolete": "cancelled",
}

CANONICAL_STATUSES = ("backlog", "next", "active", "blocked", "done", "cancelled")


def normalize_status(s: Any) -> str:
    s = str(s or "backlog").strip().lower()
    if s in CANONICAL_STATUSES:
        return s
    alias = STATUS_ALIASES.get(s)
    if alias:
        return alias
    # Unrecognised: still `backlog` (fail toward "there is work here", never
    # toward "this is finished"), but it is a typo or a value that wants an
    # alias above — `StateIntegrityChecker` surfaces it rather than swallowing.
    return "backlog"


# Statuses that CLOSE a task without it having been carried out — deliberately
# abandoned, superseded by another task, or measured and found not worth doing.
# They are terminal: the work will never become `done`.
#
# DAH7 — `normalize_status` collapses every unknown value to `backlog`, which
# for these means "still pending". That is wrong in a way that compounds:
# `_reconcile_initiative_archive` requires ALL children `done` before it will
# archive an initiative, so ONE cancelled task pins its initiative `active`
# forever. Reproduced on `daemon-audit-hardening` itself — set it to `done`,
# and the next /state build reverted it to `active` within seconds, on the
# strength of a task that had been deliberately closed.
#
# Kept separate from `normalize_status` on purpose: this predicate answers
# "does this need more work?", which is not the same question as "what should
# the board render?". Widening the wire vocabulary is a cockpit-coordinated
# change — see task DAH8 for the survey of what the repo actually uses.
TERMINAL_RESOLVED_STATUSES = frozenset(
    {
        "cancelled",
        "canceled",
        "dropped",
        "wontfix",
        "won't-fix",
        "superseded",
        "obsolete",
    }
)


def is_resolved_status(s: Any) -> bool:
    """True when a task needs NO further work — either it is `done`, or it was
    closed on purpose and never will be.

    Accepts a raw frontmatter literal OR an already-normalised value: since
    RSV1 `cancelled` is canonical, so both spellings land in the same place."""
    raw = str(s or "").strip().lower()
    return (
        normalize_status(raw) in ("done", "cancelled")
        or raw in TERMINAL_RESOLVED_STATUSES
    )


# ── cluster.yaml `crons:` validation (DA-CLUSTER-01, moved from daemon.py) ──

_CRON_RESTART_POLICIES = frozenset({"never", "on-failure", "always"})

_CRON_DEFAULTS = {
    "enabled": True,
    "max_runtime_sec": 7200,  # 2h
    "restart_policy": "never",
    "retention_runs": 30,
    "destructive": False,
}


def _validate_cron_expr(expr: str) -> Optional[str]:
    """Lightweight validation. Full parsing lands in D-CRON-02. Here we
    only need to reject obviously malformed values at config load so the
    daemon doesn't carry junk into the scheduler later.

    Returns None on OK, or a short error message string on reject.
    Accepts 5 space-separated fields. Each field is non-empty and
    consists of characters from [0-9*/,\\-]. Quartz (6 fields with
    seconds), `@daily`-style aliases, and the `L/W/#` modifiers are
    explicitly NOT supported in v1.
    """
    if not isinstance(expr, str) or not expr.strip():
        return "schedule must be a non-empty string"
    fields = expr.strip().split()
    if len(fields) != 5:
        return f"schedule must have 5 space-separated fields, got {len(fields)}"
    allowed = set("0123456789*/,-")
    for i, f in enumerate(fields):
        if not f:
            return f"schedule field {i} is empty"
        if not set(f).issubset(allowed):
            return f"schedule field {i} ({f!r}) contains unsupported characters"
    return None


def _validate_crons_block(
    data: Dict[str, Any],
) -> Tuple[List[Dict[str, Any]], List[str]]:
    """Validates the `crons:` section of cluster.yaml in isolation.
    Returns (cleaned_jobs, errors). Bad entries are skipped (not raised)
    so a single broken job doesn't disable the entire scheduler.

    Each returned job has defaults filled in and the schema's shape
    enforced. Invariants:
      - id is a non-empty kebab-case string, unique within the list
      - cmd is non-empty string
      - schedule passes _validate_cron_expr
      - restart_policy is in _CRON_RESTART_POLICIES
      - env values are strings
    """
    raw = data.get("crons") or []
    if not isinstance(raw, list):
        return [], ["crons: must be a list"]
    out: List[Dict[str, Any]] = []
    errors: List[str] = []
    seen_ids: set = set()
    for idx, entry in enumerate(raw):
        if not isinstance(entry, dict):
            errors.append(f"crons[{idx}] is not a dict — skipped")
            continue
        cid = entry.get("id")
        if not isinstance(cid, str) or not cid.strip():
            errors.append(f"crons[{idx}] missing id — skipped")
            continue
        cid = cid.strip()
        if cid in seen_ids:
            errors.append(f"crons[{idx}] duplicate id {cid!r} — skipped")
            continue
        cmd = entry.get("cmd")
        if not isinstance(cmd, str) or not cmd.strip():
            errors.append(f"crons[{cid}] missing cmd — skipped")
            continue
        sched = entry.get("schedule")
        sched_err = (
            _validate_cron_expr(sched) if isinstance(sched, str) else "schedule missing"
        )
        if sched_err:
            errors.append(f"crons[{cid}] {sched_err} — skipped")
            continue
        policy = entry.get("restart_policy", _CRON_DEFAULTS["restart_policy"])
        if policy not in _CRON_RESTART_POLICIES:
            errors.append(
                f"crons[{cid}] restart_policy={policy!r} not in "
                f"{sorted(_CRON_RESTART_POLICIES)} — defaulting to 'never'"
            )
            policy = "never"
        env = entry.get("env") or {}
        if not isinstance(env, dict):
            errors.append(f"crons[{cid}] env must be a dict — replaced with empty")
            env = {}
        env_clean: Dict[str, str] = {}
        for k, v in env.items():
            if not isinstance(k, str) or not isinstance(v, str):
                errors.append(
                    f"crons[{cid}] env {k!r}: values must be strings — dropped"
                )
                continue
            env_clean[k] = v

        cleaned = {
            "id": cid,
            "name": str(entry.get("name") or cid),
            "schedule": sched.strip(),
            "cmd": cmd.strip(),
            "cwd": entry.get("cwd"),
            "env": env_clean,
            "enabled": bool(entry.get("enabled", _CRON_DEFAULTS["enabled"])),
            "max_runtime_sec": int(
                entry.get("max_runtime_sec", _CRON_DEFAULTS["max_runtime_sec"])
            ),
            "restart_policy": policy,
            "retention_runs": int(
                entry.get("retention_runs", _CRON_DEFAULTS["retention_runs"])
            ),
            "destructive": bool(
                entry.get("destructive", _CRON_DEFAULTS["destructive"])
            ),
        }
        out.append(cleaned)
        seen_ids.add(cid)
    return out, errors


# ── inlined from daemon/scaffold.py (DM3+ bundle) ─────────────────────────
"""scaffold.py — `daemon.py init`: authoritative first-boot scaffolding.

Why this exists (py-1.27.0). Before this module, a brand-new cluster was
scaffolded entirely by a "paste this in your coding agent" prompt
generated by the Architect frontend (genPrompt.ts). That prompt hand-wrote
cluster.yaml, the folder layout, the .gitignore and the starter task
against the standard schema — and it drifted: it was pinned to
STANDARD_VERSION=7 while the live standard was v26, slugged ids wrong,
broke on names with spaces, and stopped to ask the operator questions.
A coding agent following it produced divergences and alerts instead of a
clean cluster.

The fix: the DAEMON owns scaffolding. The daemon ships matching the
standard version it targets, so the files it writes are correct by
construction — no drift class possible. In the centralized model the
already-running machine daemon adopts a new project (`POST /projects
{path}`) and runs this scaffolding for it when the target has no
cluster.yaml yet — the project never gets daemon code of its own.

`scaffold_cluster()` is idempotent-safe: it REFUSES to clobber an
existing cluster.yaml (the `--force` flag in daemon.py overrides). It is
self-contained — only `Paths` + stdlib + two best-effort HTTP fetches
(canonical preamble + live standard version), each with an offline
fallback so `init` always completes.

Layout written (Standard v26 §2 folder_layout, git contract = commit
public/docs/modules/roadmap, gitignore runtime/credentials/timeline/log):

    .meshkore/STANDARD_VERSION
    .meshkore/public/cluster.yaml
    .meshkore/public/README.md
    .meshkore/public/AGENT_INSTRUCTIONS.md   (+ rendered CLAUDE/AGENTS/GEMINI/…)
    .meshkore/docs/governance.md
    .meshkore/docs/INDEX.md
    .meshkore/modules/{general,project}/README.md  (+ tasks/ log/)
    .meshkore/modules/general/tasks/T1-hello.md
    .meshkore/roadmap/initiatives/
    .meshkore/{log,timeline,credentials(0700),scripts/tls}/
    .gitignore   (repo root)
"""


# NB: aliased to a unique name on purpose. In the single-file bundle the
# flat namespace rebinds bare `datetime` to the CLASS (sibling modules do
# `from datetime import datetime`), so `datetime.date` would resolve to a
# method descriptor and explode. A unique alias is collision-proof.
import datetime as _dtmod
import os
import re
from pathlib import Path
from typing import Optional

# REL2 — the END markers are identical in both modules and there is now
# exactly one definition of each (render.py).


# The standard version this daemon build targets. Used only as the
# OFFLINE fallback — `init` prefers the live published version so a fresh
# cluster is always born at the current standard, never frozen behind.
DEFAULT_STANDARD_VERSION = 26

_PREAMBLE_URL = "https://api.meshkore.com/v1/standard/agent-instructions.md"
_VERSION_URL = "https://api.meshkore.com/v1/standard/version"
_FETCH_TIMEOUT = 8

# §17 per-CLI render targets (mirror of render._TARGETS). Kept in sync by
# the daemon's boot render anyway — this inline copy just means the files
# exist the instant `init` finishes, before the daemon is even launched.
_CLI_TARGETS = (
    ("CLAUDE.md", "Claude Code (Anthropic)."),
    ("AGENTS.md", "Codex / Aider / general convention."),
    ("GEMINI.md", "Gemini CLI (Google)."),
    (".cursor/rules/meshkore.mdc", "Cursor (Anysphere)."),
    (".clinerules", "Cline (VSCode extension)."),
)

# REL2 — the full marker LINES this module WRITES (render.py holds the
# prefixes it matches on). Four shared names, one flat namespace: see
# render.py.
_PREAMBLE_BEGIN_LINE = (
    "<!-- MESHKORE_PREAMBLE_BEGIN — managed by the daemon, do not hand-edit -->"
)
_OPERATOR_BEGIN_LINE = (
    "<!-- OPERATOR_CONTENT_BEGIN — this is your project. Edit freely. -->"
)


class ScaffoldError(Exception):
    """Raised when init cannot proceed (e.g. cluster.yaml exists, no --force)."""


def slugify_id(name: str) -> str:
    """Map a display name to a cluster/module id matching the schema
    pattern ``^[a-z0-9-]{2,40}$``. Lowercases, replaces every run of
    non-[a-z0-9] with a single ``-``, trims leading/trailing ``-``,
    clamps to 40, and guarantees ≥2 chars (falls back to ``cluster``)."""
    s = re.sub(r"[^a-z0-9]+", "-", (name or "").lower()).strip("-")
    s = s[:40].strip("-")
    if len(s) < 2:
        s = "cluster"
    return s


def _preferred_port(slug: str) -> int:
    """Stable hash-derived port in PORT_RANGE for the informational
    transport.endpoint URI. The daemon binds the first FREE port at boot;
    the cockpit identifies the cluster by cluster_id, not by port. This
    only needs to be a valid, plausible URI."""
    lo, hi = PORT_RANGE
    span = hi - lo + 1
    h = 0
    for ch in slug:
        h = (h * 31 + ord(ch)) & 0xFFFFFFFF
    return lo + (h % span)


def _offline() -> bool:
    """Skip the best-effort network fetches (live standard version +
    canonical preamble) and use the offline fallbacks immediately. Honours
    `MESHKORE_OFFLINE` (air-gapped first boot — don't hang ~16s on two
    failing fetches) and `MESHKORE_DAEMON_NO_BOOT_UPDATE` (the hermetic
    flag the test suite already sets, so `init`/auto-scaffold are
    deterministic + network-free under pytest)."""
    return bool(
        os.environ.get("MESHKORE_OFFLINE")
        or os.environ.get("MESHKORE_DAEMON_NO_BOOT_UPDATE")
    )


def _fetch(url: str) -> Optional[str]:
    if _offline():
        return None
    try:
        return fetch_text(url, label="init", timeout=_FETCH_TIMEOUT)
    except FetchError as e:
        _log(f"init: fetch {url} failed ({e}) — using offline fallback")
        return None


def _live_standard_version() -> int:
    txt = _fetch(_VERSION_URL)
    if txt:
        try:
            return int(txt.strip()[:8])
        except ValueError:
            pass
    return DEFAULT_STANDARD_VERSION


def _fallback_preamble() -> str:
    """Minimal preamble used only when the canonical fetch fails offline.
    Carries the markers so the daemon's renderer heals it to the full
    canonical text on its first VersionWatcher tick."""
    return (
        "# MeshKore — agent instructions (canonical preamble)\n\n"
        "> This is a placeholder. The daemon will replace this block with the\n"
        "> canonical preamble from <https://meshkore.com/standard> on its next\n"
        "> refresh tick. Until then: this project follows the MeshKore standard\n"
        "> (<https://meshkore.com/standard>). Read `.meshkore/public/RESOURCES.md`\n"
        "> and the standard before doing substantial work in this repo.\n"
    )


def _yaml_str(s: str) -> str:
    """Quote a scalar for our tiny YAML subset — double-quote and escape
    embedded quotes/backslashes so names like `O'Brien "X"` survive."""
    return '"' + (s or "").replace("\\", "\\\\").replace('"', '\\"') + '"'


def _w(path: Path, text: str) -> None:
    # GH1-WINBOOT (meshkore/daemon#1): explicit UTF-8. Stock Windows decodes
    # Path.write_text() with cp1252, which chokes on template chars (⟦/→)
    # and leaves half-written files that break the retry on read.
    path.parent.mkdir(parents=True, exist_ok=True)
    if not text.endswith("\n"):
        text += "\n"
    path.write_text(text, encoding="utf-8")


def scaffold_cluster(
    root: Path,
    name: str,
    description: Optional[str] = None,
    *,
    cluster_id: Optional[str] = None,
    force: bool = False,
) -> Paths:
    """Write the full v26 .meshkore tree under `root`. Returns the Paths.

    Refuses (ScaffoldError) if cluster.yaml already exists unless force.
    Self-contained: completes even with no network (offline fallbacks)."""
    paths = Paths(root)
    name = (name or "").strip() or "My MeshKore Project"
    slug = slugify_id(cluster_id or name)
    desc = (description or "").strip() or f"Local-first MeshKore cluster — {name}."

    if paths.cluster_yaml.exists() and not force:
        raise ScaffoldError(
            f"cluster.yaml already exists at {paths.cluster_yaml} — refusing to "
            "overwrite. Re-run with `--force` to re-scaffold (destructive)."
        )

    std_ver = _live_standard_version()
    today = _dtmod.date.today().isoformat()
    port = _preferred_port(slug)

    # ── directories (Standard v26 folder_layout) ───────────────────────
    for d in (
        paths.public,
        paths.docs_dir,
        paths.modules_dir / "general" / "tasks",
        paths.modules_dir / "general" / "log",
        paths.modules_dir / "project" / "tasks",
        paths.modules_dir / "project" / "log",
        paths.initiatives,
        paths.log_dir,
        paths.timeline_dir,
        paths.scripts_dir / "tls",
    ):
        d.mkdir(parents=True, exist_ok=True)
    paths.credentials.mkdir(parents=True, exist_ok=True)
    try:
        paths.credentials.chmod(0o700)
    except OSError:
        pass

    # ── STANDARD_VERSION ────────────────────────────────────────────────
    _w(paths.meshkore / "STANDARD_VERSION", str(std_ver))

    # ── public/cluster.yaml (schema 'cluster_yaml', required + sensible) ─
    cluster_yaml = (
        f"# MeshKore cluster config — Standard v{std_ver} (schema 'cluster_yaml').\n"
        f"# Written by `daemon.py init`. Canonical schema:\n"
        f"#   https://api.meshkore.com/v1/standard.json\n"
        f"version: 1\n"
        f"id: {slug}\n"
        f"type: dev\n"
        f"name: {_yaml_str(name)}\n"
        f"description: {_yaml_str(desc)}\n"
        f"\n"
        f"transport:\n"
        f"  protocol: websocket\n"
        f"  # Informational only. The cockpit reads the live endpoint from\n"
        f"  # /health.endpoint and identifies this cluster by `id`, NOT by port.\n"
        f"  # The daemon picks a port in {PORT_RANGE[0]}-{PORT_RANGE[1]} on first boot\n"
        f"  # and STICKS to it (~/.meshkore/ports.json, py-1.15.0+) — it should stay\n"
        f"  # stable across restarts. If external integrations hardcode this port,\n"
        f"  # a drift here breaks them (2026-07-08 incident) — set `architect.port`\n"
        f"  # below to make the assignment durable even if the registry is wiped.\n"
        f'  endpoint: "https://daemon.meshkore.com:{port}"\n'
        f"\n"
        f"storage:\n"
        f"  mode: local\n"
        f"\n"
        f"# Durable seed for _pick_port's sticky registry — only consulted on a\n"
        f"# from-scratch assignment (registry wiped, or first boot on a new\n"
        f"# machine); an existing sticky entry always wins. Safe to bump if you\n"
        f"# deliberately want to move this cluster's daemon to a new port, but\n"
        f"# check for hardcoded consumers first.\n"
        f"architect:\n"
        f"  port: {port}\n"
        f"\n"
        f"modules:\n"
        f"  - id: general\n"
        f"    kind: area\n"
        f"    name: General\n"
        f"  - id: project\n"
        f"    kind: area\n"
        f"    name: Project\n"
        f"\n"
        f"# Standard §10.4 — daemon self-update (architect.meshkore.com CDN).\n"
        f"# Set auto_update: false to require explicit confirmation per update.\n"
        f"daemon:\n"
        f"  auto_update: true\n"
        f"  auto_update_source: https://architect.meshkore.com/reference/cluster/scripts/daemon.py\n"
    )
    _w(paths.cluster_yaml, cluster_yaml)

    # ── public/README.md ────────────────────────────────────────────────
    _w(
        paths.public / "README.md",
        f"# {name}\n\n"
        f"This is a [MeshKore](https://meshkore.com/standard) cluster — a "
        f"local-first multi-agent project. Its entire state lives in this "
        f"repo's `.meshkore/` ledger; the project carries **no daemon code "
        f"of its own** — clone it anywhere and it stays portable.\n\n"
        f"One MeshKore daemon per machine serves every project on that "
        f"machine, routing each request to this cluster by its id "
        f"(`{slug}`), not by port. To work on this project, open the cockpit "
        f"at <https://architect.meshkore.com> and add it by its path — the "
        f"running daemon adopts it and the cockpit auto-detects it. If no "
        f"daemon is running on this machine yet, install MeshKore once (see "
        f"<https://meshkore.com/standard>) and it will serve this and all "
        f"your other clusters.\n",
    )

    # ── public/AGENT_INSTRUCTIONS.md + per-CLI render ───────────────────
    preamble = _fetch(_PREAMBLE_URL) or _fallback_preamble()
    instructions = (
        f"{_PREAMBLE_BEGIN_LINE}\n\n"
        f"{preamble.strip(chr(10))}\n\n"
        f"{_PREAMBLE_END_LINE}\n\n"
        f"{_OPERATOR_BEGIN_LINE}\n\n"
        f"# {name} — operator instructions\n\n"
        f"{desc}\n\n"
        f"Project-specific rules go here. This block is yours — the daemon "
        f"never touches it; it only manages the preamble above.\n\n"
        f"{_OPERATOR_END_LINE}\n"
    )
    src = paths.public / "AGENT_INSTRUCTIONS.md"
    _w(src, instructions)
    _render_cli_targets(paths, instructions, std_ver)

    # ── docs/ ───────────────────────────────────────────────────────────
    _w(
        paths.docs_dir / "governance.md",
        "# Governance\n\n"
        "This cluster follows the MeshKore standard. The canonical, "
        "authoritative spec lives at <https://meshkore.com/standard> "
        "(machine-readable: <https://api.meshkore.com/v1/standard.json>). "
        "Per standard R5 we link to it rather than copy it — read it there.\n",
    )
    _w(
        paths.docs_dir / "INDEX.md",
        "# docs/ — map\n\n"
        "- [governance.md](governance.md) — pointer to the MeshKore standard.\n",
    )

    # ── modules READMEs (Context tab reads these) ───────────────────────
    _w(
        paths.modules_dir / "general" / "README.md",
        "# general\n\n"
        "Catch-all area module for work that doesn't yet belong to a "
        "dedicated code module. Tasks live in `tasks/`; done tasks archive "
        "to `log/<YYYY-MM>/`.\n",
    )
    _w(
        paths.modules_dir / "project" / "README.md",
        "# project\n\n"
        "Cross-cutting meta area: deploy, docs, design, ops — work that "
        "spans the whole cluster rather than one code module.\n",
    )

    # ── starter task (schema 'task_frontmatter'; category == module) ────
    _w(
        paths.modules_dir / "general" / "tasks" / "T1-hello.md",
        f"---\n"
        f"id: T1\n"
        f"title: Hello, MeshKore\n"
        f"status: backlog\n"
        f"priority: medium\n"
        f"owner: unassigned\n"
        f"category: general\n"
        f"created: {today}\n"
        f"updated: {today}\n"
        f"---\n\n"
        f"Starter task — replace me. Describe the first real piece of work "
        f"for **{name}**.\n",
    )

    # ── team roster (initiative `agent-team`, ATM2) ─────────────────────
    # Seed the canonical 9-member default team into `.meshkore/team/` at init
    # so a fresh cluster is born with the roster. Idempotent + committed with
    # the repo (v27 git contract; no secrets). Boot re-seeds too (belt+braces).
    # TEG-1 — members seeded `exposure: external` (consultant) get their
    # bearer token minted into credentials/team-tokens.yaml (deny-listed).
    try:

        _team = TeamStore(paths)
        _team.seed_defaults()
        TeamTokenStore(paths).ensure_for_external(_team)
    except Exception as e:  # noqa: BLE001 — seeding is best-effort at init
        _log(f"init: team seed skipped: {e}")

    # ── repo-root .gitignore (deny-list git contract) ───────────────────
    _write_gitignore(root)

    _log(
        f"init: scaffolded cluster '{slug}' ({name}) at standard v{std_ver} "
        f"under {paths.meshkore}"
    )
    return paths


def _render_cli_targets(paths: Paths, body: str, std_ver: int) -> None:
    """Mirror AGENT_INSTRUCTIONS.md into the §17 per-CLI files so they
    exist the moment init finishes (the daemon's renderer re-syncs them at
    every boot anyway). The two v19+ targets are written only when the
    cluster's standard version is ≥ 19."""
    for rel, audience in _CLI_TARGETS:
        if rel in (".cursor/rules/meshkore.mdc", ".clinerules") and std_ver < 19:
            continue
        header = (
            "<!-- Auto-rendered from .meshkore/public/AGENT_INSTRUCTIONS.md per\n"
            "     MeshKore standard §17 (v18+). Edit the source, not this file.\n"
            f"     Audience: {audience} -->\n\n"
        )
        dest = paths.root / rel
        try:
            dest.parent.mkdir(parents=True, exist_ok=True)
            dest.write_text(
                header + body, encoding="utf-8"
            )  # GH1-WINBOOT: cp1252 locale
        except OSError as e:
            _log(f"init: render {rel} failed: {e}")


def _write_gitignore(root: Path) -> None:
    """Append the MeshKore runtime deny-list to the repo-root .gitignore
    (idempotent — skips lines already present). Git contract: commit
    public/ + docs/ + modules/ + roadmap/initiatives/; ignore runtime
    state, credentials, timeline, logs, queues, uploads, build artifacts."""
    block_header = "# MeshKore — runtime state (do not commit)"
    entries = [
        ".meshkore/.runtime/",
        ".meshkore/credentials/",
        ".meshkore/agents/",
        ".meshkore/timeline/",
        ".meshkore/log/",
        ".meshkore/queues/",
        ".meshkore/uploads/",
        ".meshkore/snapshots/",
        ".meshkore/state.json",
        ".meshkore/roadmap/state.json",
        ".meshkore/roadmap/state.js",
        # scripts/ holds the downloaded daemon (auto-updates → churns diffs
        # if committed) + the loopback TLS bundle (privkey is secret) — all
        # re-fetchable from /reference/cluster/scripts/, so never committed.
        ".meshkore/scripts/",
    ]
    gi = root / ".gitignore"
    existing = (
        gi.read_text(encoding="utf-8").splitlines() if gi.exists() else []
    )  # GH1-WINBOOT: cp1252 locale
    have = set(line.strip() for line in existing)
    add = [e for e in entries if e not in have]
    if not add:
        return
    out = list(existing)
    if out and out[-1].strip() != "":
        out.append("")
    out.append(block_header)
    out.append(
        "# Everything else under .meshkore/ (public, docs, modules, "
        "roadmap/initiatives) IS versioned."
    )
    out.extend(add)
    gi.write_text("\n".join(out) + "\n", encoding="utf-8")  # GH1-WINBOOT: cp1252 locale


# ── inlined from daemon/hub.py (DM3+ bundle) ─────────────────────────
"""WebSocket Hub — subscriber registry + broadcast fan-out + heartbeat.

A daemon instance has exactly one ``Hub``. Every component that needs
to push events to connected cockpits / mesh peers / SSE listeners
gets the hub via constructor injection and calls ``hub.broadcast({…})``.

The broadcast loop holds ``_lock`` for the snapshot of the subscriber
set, NOT during the per-client send — a slow / dead client never
blocks the broadcast (dead clients are detected by the
``OSError`` on send and discarded next iteration).

The heartbeat thread keeps an idle ws open through aggressive proxies
(every ``HEARTBEAT_SEC`` seconds) and tells the cockpit the daemon
is still alive even when no real events fire.

Bundler note (see storage.py for the full pattern): the local
``_iso_now`` is shadowed in ``dist/daemon.py`` by daemon.py's
debug-stream-aware version because daemon.py is appended last."""


import json
import socket
import struct
import threading
from typing import Any, Dict

# REL2 — the one _iso_now lives in timeutil; a byte-identical copy here
# defined the same top-level name twice in the flat bundle namespace, which
# is how `_q` broke release-signature verification fleet-wide.


HEARTBEAT_SEC = 20.0
SEND_TIMEOUT_SEC = 5.0  # py-1.16.0 (D-WS-02) — bound a send so a stalled client can't wedge a broadcaster


class WSClient:
    __slots__ = ("sock", "closed", "_send_lock")

    def __init__(self, sock: socket.socket):
        self.sock = sock
        self.closed = False
        # py-1.31.4 (daemon-centralized) — SERIALIZE every write to this
        # socket. `broadcast()` is called from MANY threads (heartbeat, agent
        # runners, anchor, state-rebuild) AND the ws handler thread itself
        # sends frames — all onto the SAME `SSLSocket`. Two concurrent
        # `sendall`s become two concurrent `SSL_write`s on ONE OpenSSL
        # connection object, which is undefined behavior → native heap
        # corruption ("BUG IN CLIENT OF LIBMALLOC" in `tls_setup_write_buffer`,
        # 5 hard crashes 2026-07-05→09). The GIL does NOT prevent it: `SSL_write`
        # releases the GIL for the duration of the I/O. One lock per connection
        # guarantees at most one writer at a time (reads stay lock-free — OpenSSL
        # allows one concurrent reader + one writer). Version-independent fix.
        # RLock (reentrant): `send_text` calls `close()` on its own OSError while
        # still holding the lock — a plain Lock would self-deadlock there.
        self._send_lock = threading.RLock()
        # py-1.16.0 (D-WS-02) — bound sends so a client with a full TCP
        # send buffer (suspended laptop, paused devtools) can't block a
        # broadcaster forever. SO_SNDTIMEO affects ONLY send, not the
        # ws-pump's recv. Best-effort: the timeval struct layout is
        # platform-specific, so fall back to untimed sends on failure
        # (the broadcast-outside-the-lock change still prevents the
        # whole-Hub stall; this just bounds the per-client cost).
        try:
            sock.setsockopt(
                socket.SOL_SOCKET,
                socket.SO_SNDTIMEO,
                struct.pack("ll", int(SEND_TIMEOUT_SEC), 0),
            )
        except (OSError, struct.error):
            pass

    def send_text(self, payload: str) -> None:
        """Send a single, unmasked, unfragmented text frame (server → client).

        DAH5 — the frame arithmetic moved to `wsframe.encode_text`; this
        method keeps what is actually its own: the closed-check and the
        per-connection send lock below."""
        if self.closed:
            return
        frame = encode_text(payload, mask=False)
        # Hold the per-connection lock across the WHOLE sendall so no other
        # thread can interleave an SSL_write on this socket (see __init__).
        with self._send_lock:
            if self.closed:
                return
            try:
                self.sock.sendall(frame)
            except OSError:
                self.close()

    def close(self) -> None:
        # Serialize teardown against in-flight sends (same per-connection lock)
        # so we never shutdown/close the socket mid-`SSL_write`. Reentrant, so
        # `send_text`'s own error-path `close()` (already holding the lock) is
        # fine; an external `remove()` waits for the bounded send to finish.
        with self._send_lock:
            if self.closed:
                return
            self.closed = True
            try:
                self.sock.shutdown(socket.SHUT_RDWR)
            except OSError:
                pass
            try:
                self.sock.close()
            except OSError:
                pass


class Hub:
    """Broadcaster — keeps the set of connected clients and a heartbeat."""

    def __init__(self):
        self._clients: set[WSClient] = set()
        self._lock = threading.Lock()
        self._stop = threading.Event()
        threading.Thread(target=self._heartbeat_loop, daemon=True).start()

    def add(self, client: WSClient) -> None:
        with self._lock:
            self._clients.add(client)

    def remove(self, client: WSClient) -> None:
        with self._lock:
            self._clients.discard(client)
        client.close()

    def broadcast(self, event: Dict[str, Any]) -> None:
        # py-1.16.0 (D-WS-02) — snapshot the client set UNDER the lock,
        # then send OUTSIDE it. Previously the per-client blocking
        # `sendall` ran while holding `_lock`, so one stalled client
        # froze every broadcaster (chat deltas, run.* events, heartbeat)
        # — the docstring claimed sends were outside the lock but the
        # code did the opposite. Sends are now bounded by SO_SNDTIMEO
        # (see WSClient), so a wedged client is dropped within the
        # timeout instead of blocking the fan-out.
        payload = json.dumps(event, separators=(",", ":"))
        with self._lock:
            clients = list(self._clients)
        dead = []
        for c in clients:
            c.send_text(payload)
            if c.closed:
                dead.append(c)
        if dead:
            with self._lock:
                for c in dead:
                    self._clients.discard(c)

    def shutdown(self) -> None:
        self._stop.set()
        with self._lock:
            for c in list(self._clients):
                c.close()
            self._clients.clear()

    def _heartbeat_loop(self) -> None:
        while not self._stop.wait(HEARTBEAT_SEC):
            self.broadcast({"type": "heartbeat", "ts": _iso_now()})


class ProjectHub:
    """A per-project view of the one global Hub (DC-6, daemon-centralized).

    Each per-project component (state_manager, runs, cron, the registries, the
    ChatRunner …) broadcasts through one of these instead of the raw Hub, so
    every event is auto-tagged with its ``project_id``. The single WS
    connection then carries events for all projects and the cockpit routes them
    (its event-bus already filters by cluster). Any non-broadcast attribute
    (add / remove / shutdown / _clients …) delegates straight to the real Hub.
    """

    __slots__ = ("_hub", "_project_id")

    def __init__(self, hub: "Hub", project_id: str) -> None:
        self._hub = hub
        self._project_id = project_id

    def broadcast(self, event: Dict[str, Any]) -> None:
        if isinstance(event, dict) and event.get("project_id") is None:
            event = {**event, "project_id": self._project_id}
        self._hub.broadcast(event)

    def __getattr__(self, name: str) -> Any:
        # Everything that isn't an explicit slot/method here → the real Hub.
        return getattr(self._hub, name)


# ── inlined from daemon/registries.py (DM3+ bundle) ─────────────────────────
"""Links + Protocols registries (Standard §13 + §14).

DM-modularize-3 (py-1.14.5): two self-contained registry classes lifted
verbatim from daemon.py. ``LinksRegistry`` parses/validates/serves
``.meshkore/public/links.yaml`` (module → local/prod/version, plus the
``bookmarks:`` section added by JL-4);
``WorkflowsRegistry`` (in workflows.py, renamed from ProtocolsRegistry
2026-06-21) indexes ``.meshkore/workflows/`` (reusable ordered runbooks)
+ their per-day logs. Zero daemon coupling — pure FS + parsing, fed only
a ``Paths``. The YAML emitter (``_emit_links_yaml`` / ``_emit_scalar``)
and ``_split_frontmatter`` travel with them; daemon.py re-imports
``LinksRegistry`` / ``WorkflowsRegistry`` / ``_split_frontmatter``.

Bundler note: imports shared helpers from utils/paths (stripped; resolved
via the flat namespace)."""



import threading
from typing import Any, Dict, List, Optional, Tuple



# ───────────────────────────────────────────────────────────────────────
# Links registry — standard §13
#
# .meshkore/public/links.yaml maps each module to where it runs locally,
# where it is deployed in production, and what version is live. The
# daemon parses it on boot and on file change, validates entries, serves
# them at GET /links + /links/<id>, accepts patches at POST /links/<id>,
# and broadcasts `links.updated` on the WebSocket.

_LINKS_PROVIDERS = frozenset(
    {
        "fly",
        "cloudflare-pages",
        "cloudflare-workers",
        "vercel",
        "render",
        "self-hosted",
        "other",
    }
)
_LINKS_BLOCKS = ("local", "prod", "repo")


def _validate_links_block(
    data: Dict[str, Any],
) -> Tuple[List[Dict[str, Any]], List[str]]:
    errs: List[str] = []
    if not isinstance(data, dict):
        return [], ["links.yaml: top level must be a mapping"]
    mods = data.get("modules") or []
    if not isinstance(mods, list):
        return [], ["links.yaml: `modules:` must be a list"]
    out: List[Dict[str, Any]] = []
    for i, m in enumerate(mods):
        if not isinstance(m, dict):
            errs.append(f"links.yaml: modules[{i}] is not a mapping")
            continue
        mid = m.get("id")
        if not isinstance(mid, str) or not mid.strip():
            errs.append(f"links.yaml: modules[{i}] missing string `id`")
            continue
        entry: Dict[str, Any] = {"id": mid.strip()}
        for blk in _LINKS_BLOCKS:
            v = m.get(blk)
            if v is None:
                continue
            if not isinstance(v, dict):
                errs.append(f"links.yaml: {mid}.{blk} must be a mapping")
                continue
            entry[blk] = v
        prov = (m.get("prod") or {}).get("provider")
        if isinstance(prov, str) and prov.strip() and prov not in _LINKS_PROVIDERS:
            errs.append(
                f"links.yaml: {mid}.prod.provider `{prov}` is not in the canonical set (rendered as plain text)"
            )
        if "notes" in m:
            entry["notes"] = m["notes"]
        out.append(entry)
    return out, errs


def _validate_bookmarks_block(
    data: Dict[str, Any],
) -> Tuple[List[Dict[str, Any]], List[str]]:
    """JL-4 — the `bookmarks:` section of the SAME links.yaml.

    Decision (initiative `jobs-and-links`): no second registry and no
    `bookmarks.yaml`. Internal deployment links and curated project
    bookmarks are the same kind of thing — project-owned URLs — so they
    share one file, one watcher and one `links.updated` event; the cockpit's
    two tabs are a view, not a storage boundary. A `bookmarks.yaml` was
    never created in any project (verified across every registered project
    on 2026-09-20), so there is nothing to migrate."""
    errs: List[str] = []
    if not isinstance(data, dict):
        return [], []
    raw = data.get("bookmarks") or []
    if not isinstance(raw, list):
        return [], ["links.yaml: `bookmarks:` must be a list"]
    out: List[Dict[str, Any]] = []
    seen = set()
    for i, b in enumerate(raw):
        if not isinstance(b, dict):
            errs.append(f"links.yaml: bookmarks[{i}] is not a mapping")
            continue
        url = b.get("url")
        if not isinstance(url, str) or not url.strip():
            errs.append(f"links.yaml: bookmarks[{i}] missing string `url`")
            continue
        bid = b.get("id")
        bid = bid.strip() if isinstance(bid, str) and bid.strip() else f"bm{i + 1}"
        if bid in seen:
            errs.append(f"links.yaml: duplicate bookmark id {bid!r} (ignored)")
            continue
        seen.add(bid)
        entry: Dict[str, Any] = {"id": bid, "url": url.strip()}
        title = b.get("title")
        entry["title"] = (
            title.strip() if isinstance(title, str) and title.strip() else bid
        )
        tags = b.get("tags")
        if isinstance(tags, list):
            entry["tags"] = [str(t) for t in tags]
        elif isinstance(tags, str) and tags.strip():
            entry["tags"] = [t.strip() for t in tags.split(",") if t.strip()]
        if b.get("notes") not in (None, ""):
            entry["notes"] = b["notes"]
        out.append(entry)
    return out, errs


class _PollingRegistry:
    """Shared poll-and-reload machinery for the file-backed registries.

    DAH1 (daemon-audit-hardening) — `LinksRegistry` and `WorkflowsRegistry`
    carried byte-identical `__init__` tails, `_watch_loop`s and `shutdown`s.
    Each subclass still owns `POLL_SEC` and the interesting part (`reload`);
    this base owns only the thread lifecycle, so a change to how watching
    works (backoff, a shared timer, honouring `stopping`) lands once.

    Contract for a subclass: define `POLL_SEC` and `reload(broadcast: bool)`,
    then call `self._start_watching()` as the LAST line of its `__init__` —
    the thread must not observe a half-built object."""

    POLL_SEC = 3.0

    def _start_watching(self) -> None:
        self._stop = threading.Event()
        self.reload(broadcast=False)
        threading.Thread(
            target=self._watch_loop,
            name=f"{type(self).__name__}-watch",
            daemon=True,
        ).start()

    def _watch_loop(self) -> None:
        while not self._stop.wait(self.POLL_SEC):
            try:
                self.reload(broadcast=True)
            except Exception as e:  # noqa: BLE001 — a bad file must not kill the watcher
                _log(f"{type(self).__name__}: reload failed: {e}")

    def shutdown(self) -> None:
        self._stop.set()


class LinksRegistry(_PollingRegistry):
    """Loads + watches .meshkore/public/links.yaml; broadcasts on change.

    Serves BOTH halves of the cockpit's Links zone (JL-4): `modules` (the
    §13 deployment registry) and `bookmarks` (curated project URLs). One
    file, one registry, one `links.updated` event."""

    POLL_SEC = 3.0

    def __init__(self, paths: Paths, hub: "Hub"):
        self.paths = paths
        self.hub = hub
        self.modules: List[Dict[str, Any]] = []
        self.bookmarks: List[Dict[str, Any]] = []
        self.errors: List[str] = []
        self._mtime: Optional[float] = None
        self._start_watching()

    def reload(self, broadcast: bool = True) -> bool:
        """Reread the file. Returns True if content changed."""
        if not self.paths.links_yaml.exists():
            changed = bool(self.modules or self.bookmarks) or self._mtime is not None
            self.modules, self.bookmarks, self.errors, self._mtime = [], [], [], None
            if changed and broadcast:
                self.hub.broadcast(
                    {"type": "links.updated", "modules": [], "bookmarks": []}
                )
            return changed
        try:
            mt = self.paths.links_yaml.stat().st_mtime
        except OSError:
            mt = None
        if mt is not None and mt == self._mtime:
            return False
        try:
            text = self.paths.links_yaml.read_text()
            data = parse_simple_yaml(text)
            mods, errs = _validate_links_block(data)
            marks, berrs = _validate_bookmarks_block(data)
            errs = errs + berrs
        except Exception as exc:
            _log(f"links.yaml: parse error — {exc}")
            return False
        self.modules, self.bookmarks = mods, marks
        self.errors, self._mtime = errs, mt
        for e in errs:
            _log(f"links.yaml: {e}")
        if broadcast:
            self.hub.broadcast(
                {
                    "type": "links.updated",
                    "modules": [m["id"] for m in self.modules],
                    "bookmarks": [b["id"] for b in self.bookmarks],
                }
            )
        return True

    def as_dict(self) -> Dict[str, Any]:
        return {
            "version": 1,
            "modules": self.modules,
            "bookmarks": self.bookmarks,
            "_errors": self.errors,
        }

    def get(self, mid: str) -> Optional[Dict[str, Any]]:
        for m in self.modules:
            if m["id"] == mid:
                return m
        return None

    def patch(self, mid: str, patch_body: Dict[str, Any]) -> Tuple[bool, str]:
        """Merge `patch_body` (allowed keys: local/prod/repo/notes) into the
        module entry, write the file atomically, broadcast."""
        if not isinstance(patch_body, dict):
            return False, "patch body must be an object"
        allowed = {"local", "prod", "repo", "notes"}
        unknown = set(patch_body) - allowed
        if unknown:
            return False, f"patch keys not allowed: {sorted(unknown)}"
        # Make sure the file exists with a baseline
        if not self.paths.links_yaml.exists():
            self.paths.links_yaml.parent.mkdir(parents=True, exist_ok=True)
            self.paths.links_yaml.write_text("version: 1\nmodules: []\n")
        # Reread → merge → write. We round-trip through parse_simple_yaml +
        # a minimal serializer below so we don't depend on PyYAML.
        try:
            data = parse_simple_yaml(self.paths.links_yaml.read_text())
        except Exception as exc:
            return False, f"current links.yaml unparseable: {exc}"
        mods = data.get("modules")
        if not isinstance(mods, list):
            mods = []
            data["modules"] = mods
        found = None
        for m in mods:
            if isinstance(m, dict) and m.get("id") == mid:
                found = m
                break
        if found is None:
            found = {"id": mid}
            mods.append(found)
        for k, v in patch_body.items():
            if k == "notes":
                found["notes"] = v
            else:
                base = found.get(k) if isinstance(found.get(k), dict) else {}
                if isinstance(v, dict):
                    base.update(v)
                    found[k] = base
                else:
                    found[k] = v
        data["version"] = 1
        atomic_write_text(self.paths.links_yaml, _emit_links_yaml(data))
        self.reload(broadcast=True)
        return True, "ok"

    # ── bookmarks (JL-4) — same file, same watcher, same WS event ─────
    def get_bookmark(self, bid: str) -> Optional[Dict[str, Any]]:
        for b in self.bookmarks:
            if b["id"] == bid:
                return b
        return None

    def _read_data(self) -> Tuple[Optional[Dict[str, Any]], str]:
        if not self.paths.links_yaml.exists():
            self.paths.links_yaml.parent.mkdir(parents=True, exist_ok=True)
            self.paths.links_yaml.write_text("version: 1\nmodules: []\n")
        try:
            return parse_simple_yaml(self.paths.links_yaml.read_text()), ""
        except Exception as exc:  # noqa: BLE001
            return None, f"current links.yaml unparseable: {exc}"

    def put_bookmark(self, bid: str, body: Dict[str, Any]) -> Tuple[bool, str]:
        """Create-or-update one bookmark. Allowed keys: title/url/tags/notes."""
        if not isinstance(body, dict):
            return False, "body must be an object"
        allowed = {"title", "url", "tags", "notes"}
        unknown = set(body) - allowed - {"id"}
        if unknown:
            return False, f"bookmark keys not allowed: {sorted(unknown)}"
        data, err = self._read_data()
        if data is None:
            return False, err
        marks = data.get("bookmarks")
        if not isinstance(marks, list):
            marks = []
        found = None
        for b in marks:
            if isinstance(b, dict) and b.get("id") == bid:
                found = b
                break
        if found is None:
            if not str(body.get("url") or "").strip():
                return False, "`url` is required to create a bookmark"
            found = {"id": bid}
            marks.append(found)
        for k in ("title", "url", "notes"):
            if k in body:
                found[k] = body[k]
        if "tags" in body:
            tags = body["tags"]
            found["tags"] = (
                [str(t) for t in tags]
                if isinstance(tags, list)
                else [t.strip() for t in str(tags).split(",") if t.strip()]
            )
        found.setdefault("title", bid)
        data["bookmarks"] = marks
        data["version"] = 1
        atomic_write_text(self.paths.links_yaml, _emit_links_yaml(data))
        self._mtime = None
        self.reload(broadcast=True)
        return True, "ok"

    def delete_bookmark(self, bid: str) -> Tuple[bool, str]:
        data, err = self._read_data()
        if data is None:
            return False, err
        marks = data.get("bookmarks")
        if not isinstance(marks, list):
            return False, "unknown bookmark"
        kept = [b for b in marks if not (isinstance(b, dict) and b.get("id") == bid)]
        if len(kept) == len(marks):
            return False, "unknown bookmark"
        data["bookmarks"] = kept
        data["version"] = 1
        atomic_write_text(self.paths.links_yaml, _emit_links_yaml(data))
        self._mtime = None
        self.reload(broadcast=True)
        return True, "ok"


def _emit_links_yaml(data: Dict[str, Any]) -> str:
    """Tiny serializer for the links.yaml subset we care about. Stdlib-only.
    Preserves block-mapping layout the file template ships with.

    JL-4: emits the `bookmarks:` section too. Every write goes
    parse → mutate → emit, so an emitter that forgot a section would erase
    it on the next unrelated patch."""
    out: List[str] = [
        "# .meshkore/public/links.yaml — Deployment links + bookmarks registry (standard §13).",
        "# Agent-maintained. Do not check in secrets — URLs only.",
        "",
        f"version: {int(data.get('version') or 1)}",
        "",
        "modules:",
    ]
    mods = data.get("modules") or []
    if not mods:
        out[-1] = "modules: []"
        return "\n".join(out) + _emit_bookmarks_section(data) + "\n"
    for m in mods:
        if not isinstance(m, dict):
            continue
        mid = m.get("id") or "unknown"
        out.append(f"  - id: {mid}")
        for blk in ("local", "prod", "repo"):
            v = m.get(blk)
            if not isinstance(v, dict) or not v:
                continue
            out.append(f"    {blk}:")
            for k, kv in v.items():
                out.append(f"      {k}: {_emit_scalar(kv)}")
        if "notes" in m and m["notes"] not in (None, ""):
            out.append(f"    notes: {_emit_scalar(m['notes'])}")
    return "\n".join(out) + _emit_bookmarks_section(data) + "\n"


def _emit_bookmarks_section(data: Dict[str, Any]) -> str:
    """The `bookmarks:` half of links.yaml (JL-4). Returns "" when the file
    has no bookmarks at all, so existing clusters keep a byte-identical
    links.yaml until someone adds one."""
    marks = data.get("bookmarks")
    if marks is None:
        return ""
    lines: List[str] = ["", ""]
    if not marks:
        lines.append("bookmarks: []")
        return "\n".join(lines)
    lines.append("bookmarks:")
    for b in marks:
        if not isinstance(b, dict):
            continue
        lines.append(f"  - id: {b.get('id') or 'bookmark'}")
        lines.append(f"    title: {_emit_scalar(b.get('title') or b.get('id') or '')}")
        lines.append(f"    url: {_emit_scalar(b.get('url') or '')}")
        tags = b.get("tags") or []
        if tags:
            lines.append("    tags: [" + ", ".join(str(t) for t in tags) + "]")
        if b.get("notes") not in (None, ""):
            lines.append(f"    notes: {_emit_scalar(b['notes'])}")
    return "\n".join(lines)


def _emit_scalar(v: Any) -> str:
    if v is None:
        return '""'
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, (int, float)):
        return str(v)
    s = str(v)
    if s == "" or any(c in s for c in ":#\"'"):
        return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'
    return s


# ───────────────────────────────────────────────────────────────────────
# Workflows registry — standard §14 (the class lives in workflows.py)
#
# `.meshkore/workflows/W<N>-<slug>.md` files are reusable ordered runbooks for
# multi-step work (legacy `protocols/P<N>-` still read). The daemon parses
# frontmatter on boot and on file change, serves the list at /workflows,
# individual bodies at /workflows/<id>, recent run logs at /workflows/<id>/runs,
# and broadcasts `workflows.updated` on the WS (`/protocols*` + `protocols.updated`
# kept as deprecated aliases).


# DAH1 — the implementation moved to `yamlparse.split_frontmatter` (the leaf
# that owns _FM_RE). Re-exported under the old private name so the ~5 existing
# importers (fsread, daemon) don't churn — the re-export convention from
# ARCHITECTURE.md, "Re-exports keep call sites stable".
_split_frontmatter = split_frontmatter


# ── inlined from daemon/workflows.py (DM3+ bundle) ─────────────────────────
"""workflows.py — WorkflowsRegistry — .meshkore/workflows/ runbooks.

Renamed from protocols.py (2026-06-21): "protocol" is reserved in MeshKore for
agent-COMMUNICATION standards (A2A / MCP / HTTP). An ordered, reviewable
operational runbook (deploy, audit, system-upgrade, PR-review) is a **workflow**
— the term the AI/dev community uses (CI / agentic workflows). See
`.meshkore/docs/conventions/workflows.md`.

Back-compat during the rename: reads the new `.meshkore/workflows/` dir AND the
legacy `.meshkore/protocols/` dir, accepts both `W<N>-` and legacy `P<N>-`
file/log prefixes, and broadcasts BOTH `workflows.updated` and (deprecated)
`protocols.updated` so an un-updated cockpit keeps working."""


import hashlib
import struct

from typing import Any, Dict, List, Optional

import re


# Accept the new W-prefix and the legacy P-prefix during/after the rename.
_WF_FILE_RE = re.compile(r"^[WP](\d+)-[a-z0-9-]+\.md$")
# slug allows dots so version-tagged daemon-upgrade logs (…-py-1.10.0-…) match.
_WF_LOG_RE = re.compile(r"^([WP]\d+)-(\d{4}-\d{2}-\d{2})-[a-z0-9.-]+\.md$")


class WorkflowsRegistry(_PollingRegistry):
    """Loads + watches .meshkore/workflows/ (legacy .meshkore/protocols/);
    broadcasts on change."""

    POLL_SEC = 3.0

    def __init__(self, paths: Paths, hub: "Hub"):
        self.paths = paths
        self.hub = hub
        # Each entry: { id, title, scope, status, updated, file, log_count }
        self.workflows: List[Dict[str, Any]] = []
        self._sig: str = ""
        self._start_watching()  # LAST — see _PollingRegistry

    # ── dir resolution (new workflows/, legacy protocols/ fallback) ──────
    def _dir(self):
        wf = self.paths.workflows_dir
        return wf if wf.exists() else self.paths.protocols_dir

    def _log_dir(self):
        wf = self.paths.workflows_log
        return wf if wf.exists() else self.paths.protocols_log

    def _glob_files(self):
        d = self._dir()
        if not d.exists():
            return []
        # both prefixes, de-duped + sorted by id
        return sorted(set(d.glob("W*-*.md")) | set(d.glob("P*-*.md")))

    def reload(self, broadcast: bool = True) -> bool:
        sig = self._compute_sig()
        if sig == self._sig and self.workflows:
            return False
        self._sig = sig
        out: List[Dict[str, Any]] = []
        for fp in self._glob_files():
            m = _WF_FILE_RE.match(fp.name)
            if not m:
                continue
            try:
                text = fp.read_text()
            except OSError:
                continue
            fm, _body = _split_frontmatter(text)
            wid = str(fm.get("id") or f"{fp.name[0]}{m.group(1)}")
            out.append(
                {
                    "id": wid,
                    "title": str(fm.get("title") or wid),
                    "scope": str(fm.get("scope") or "cluster"),
                    "status": str(fm.get("status") or "draft"),
                    "priority": str(fm.get("priority") or "medium"),
                    "owner": str(fm.get("owner") or ""),
                    "updated": str(fm.get("updated") or ""),
                    "tags": fm.get("tags") or [],
                    "file": fp.name,
                    "log_count": self._count_logs(wid),
                }
            )
        self.workflows = out
        if broadcast:
            ids = [w["id"] for w in out]
            # new event + deprecated alias (un-updated cockpit still listens).
            self.hub.broadcast({"type": "workflows.updated", "ids": ids})
            self.hub.broadcast({"type": "protocols.updated", "ids": ids})
        return True

    def _compute_sig(self) -> str:
        files = self._glob_files()
        if not files:
            return ""
        h = hashlib.sha1()
        for fp in files:
            try:
                st = fp.stat()
                h.update(fp.name.encode())
                h.update(struct.pack(">dq", st.st_mtime, st.st_size))
            except OSError:
                pass
        return h.hexdigest()

    def list(self) -> List[Dict[str, Any]]:
        return list(self.workflows)

    def get(self, wid: str) -> Optional[Dict[str, Any]]:
        wid = wid.strip()
        for fp in sorted(self._dir().glob(f"{wid}-*.md")):
            if not _WF_FILE_RE.match(fp.name):
                continue
            try:
                text = fp.read_text()
            except OSError:
                return None
            fm, body = _split_frontmatter(text)
            return {
                "id": str(fm.get("id") or wid),
                "title": str(fm.get("title") or wid),
                "frontmatter": fm,
                "body": body,
                "file": fp.name,
            }
        return None

    def runs(self, wid: str, limit: int = 50) -> List[Dict[str, Any]]:
        wid = wid.strip()
        log_dir = self._log_dir()
        if not log_dir.exists():
            return []
        runs: List[Dict[str, Any]] = []
        for month_dir in sorted(log_dir.iterdir(), reverse=True):
            if not month_dir.is_dir():
                continue
            for fp in sorted(month_dir.iterdir(), reverse=True):
                m = _WF_LOG_RE.match(fp.name)
                if not m or m.group(1) != wid:
                    continue
                try:
                    text = fp.read_text()
                except OSError:
                    continue
                fm, _ = _split_frontmatter(text)
                runs.append(
                    {
                        "workflow": wid,
                        "date": m.group(2),
                        "file": f"{month_dir.name}/{fp.name}",
                        "outcome": str(fm.get("outcome") or ""),
                        "operator": str(fm.get("operator") or ""),
                        "agent": str(fm.get("agent") or ""),
                        "commit": str(fm.get("commit") or ""),
                    }
                )
                if len(runs) >= limit:
                    return runs
        return runs

    def _count_logs(self, wid: str) -> int:
        log_dir = self._log_dir()
        if not log_dir.exists():
            return 0
        n = 0
        for month_dir in log_dir.iterdir():
            if not month_dir.is_dir():
                continue
            for fp in month_dir.iterdir():
                m = _WF_LOG_RE.match(fp.name)
                if m and m.group(1) == wid:
                    n += 1
        return n


# Back-compat alias: some imports/tests may still reference the old name.
ProtocolsRegistry = WorkflowsRegistry


# ── inlined from daemon/clidrivers/base.py (DM3+ bundle) ─────────────────────────
"""clidrivers/base.py — ClientDriver interface + normalized stream events.

DM-CLI-01 (multi-cli-clients). Every CLI a team member can be dispatched
through (claude-code, gemini, codex, ...) implements ClientDriver so
runnerspawn.py/runnerloop.py can spawn + parse a turn without knowing
which binary is actually running.

`parse_stream_line()` is the one method every driver MUST get right: it
translates one raw stdout line from the client's own wire format into
zero or more of the four NormalizedEvent shapes below. Everything
downstream of that call — anchor-marker buffering, tool timeline
persistence, WS broadcast, usage/cost capture, frontend rendering — is
untouched by which driver produced the events; it was written once
against these four shapes and stays that way."""


from dataclasses import dataclass
from typing import Any, Dict, List, Optional


@dataclass
class TextDelta:
    """One incremental chunk of assistant text (not cumulative)."""

    text: str


@dataclass
class ToolUse:
    name: Optional[str]
    input: Any


@dataclass
class ToolInput:
    """BT-16 — the full arguments of a tool call that already started
    (claude-code sends `content_block_start` with an empty input, then the
    whole assistant message). Updates what the call is working on; it is
    NOT a new call."""

    name: Optional[str]
    input: Any


@dataclass
class ToolResult:
    ok: bool
    #: OBS-1 — what ran and how it ended, when the CLI reports it after the
    #: fact (`command`, `exit_code`, `status`, `output_tail`). Persisted on
    #: the timeline's `tool.result` so a stuck loop can be read back.
    detail: Optional[Dict[str, Any]] = None


@dataclass
class Final:
    """Terminal event for the turn. `usage`/`cost_usd` are None when the
    client doesn't report them (not every CLI will)."""

    text: str
    usage: Optional[Dict[str, int]] = None
    cost_usd: Optional[float] = None


NormalizedEvent = Any  # TextDelta | ToolUse | ToolResult | Final


# Model-id namespaces that only ever name claude-code provider-catalog
# entries: the `auto` sentinel + Anthropic aliases (bare ids), the
# `claude-` pins, ZAI's `glm-` models and Meta's `muse-spark` models.
# Vendor namespaces — no Codex/Gemini/Muse-CLI model will ever carry one —
# so a NON-Claude driver receiving such an id is looking at a stale member
# file saved before the chained team combos (ATM17/ATM18), and handing it
# to the CLI as `-m`/`--model` would fail or misroute the turn. Unknown ids
# (a pinned `gpt-5.4`, any future model) are NOT covered: the daemon
# forwards unlisted ids, and pinning must survive.
_CLAUDE_FAMILY_EXACT = frozenset({"auto", "fable", "opus", "sonnet", "haiku"})
_CLAUDE_FAMILY_PREFIXES = ("claude-", "glm-", "glm_", "muse-spark", "muse_spark")
# The muse CLI's own catalog shares the `muse-spark` namespace with the Meta
# provider, so those ids are only foreign under a driver that is neither
# claude-code nor muse.
_MUSE_PREFIXES = ("muse-spark", "muse_spark")


class ClientDriver:
    """Base class. `id`/`label` identify the driver in `team.py`'s
    `client` field and the `GET /clients` catalog. Concrete drivers
    override the methods they need; the defaults here keep a minimal
    driver (e.g. one with no catalog yet) safe to register."""

    def coerce_foreign_model(self, model: Optional[str]) -> Optional[str]:
        """Drop a claude-family model id that reached a non-Claude driver.

        Returns None when `model` can never run under this driver (stale
        cross-client save — the caller omits the `-m`/`--model` flag and
        the CLI runs its own default); returns `model` untouched otherwise,
        including ''/None and any unknown id. `claude-code` accepts its
        own catalogs by definition and is never coerced."""
        if self.id == "claude-code":
            return model
        m = (model or "").strip()
        if not m:
            return model
        low = m.lower()
        if low in _CLAUDE_FAMILY_EXACT or low.startswith(_CLAUDE_FAMILY_PREFIXES):
            if self.id == "muse" and low.startswith(_MUSE_PREFIXES):
                return model
            return None
        return model

    prompt_file_stdin: bool = False
    id: str = "base"
    label: str = "Base"

    def find_binary(self) -> Optional[str]:
        """Locate the CLI binary on this machine, or None if absent.
        Cheap/local only (shutil.which + known install-path globs) —
        never a network call."""
        raise NotImplementedError

    def install_hint(self) -> str:
        return f"install the {self.label} CLI"

    def auth_configured(self) -> Optional[bool]:
        """Best-effort local check (env var / credentials file
        presence). None means "can't tell" — never claim a false
        positive/negative when the driver genuinely doesn't know."""
        return None

    def models_catalog(self) -> List[Dict[str, Any]]:
        """[{id, label, ...}] — this driver's current model options."""
        return []

    def efforts_catalog(self) -> List[Dict[str, Any]]:
        """[{id, label, ...}] — this driver's current effort/reasoning
        options."""
        return []

    def build_args(
        self,
        binary: str,
        *,
        prompt: str,
        model: Optional[str],
        effort: Optional[str],
        session_id: str,
        use_session: bool,
    ) -> List[str]:
        """Full argv (binary as argv[0]) for a one-shot non-interactive
        turn. `prompt` (the built briefing) is passed in so a driver
        whose CLI wants it as an argv flag (not stdin) can include it
        here; a driver that delivers it via stdin instead (the default
        — see `write_prompt()`) simply ignores this parameter."""
        raise NotImplementedError

    def write_prompt(self, proc: Any, prompt: str) -> None:
        """Deliver the briefing to the already-spawned process. Default:
        pipe via stdin then close (works for claude-code and codex —
        override to a no-op, closing stdin without writing, when
        `build_args()` already put the prompt into argv instead, e.g.
        Gemini's `-p <text>`)."""
        try:
            if proc.stdin is not None:
                proc.stdin.write(prompt.encode("utf-8"))
                proc.stdin.close()
        except (BrokenPipeError, OSError):
            pass

    def parse_stream_line(self, line: str) -> List[NormalizedEvent]:
        """Translate one decoded, non-empty stdout line into zero or
        more NormalizedEvents. Must swallow malformed/non-JSON lines
        (return []) rather than raising — a client's banner/noise
        output must never crash the reader loop."""
        raise NotImplementedError

    def is_transient_error(self, text: str) -> bool:
        """True iff `text` is a TRANSPORT-class failure (rate limit,
        upstream 5xx, timeout) that a fresh spawn of the SAME turn can
        plausibly clear — as opposed to a task outcome or a
        request-shape error a retry won't fix. Conservative default:
        never retry unless a driver explicitly knows its own error
        vocabulary."""
        return False


# ── inlined from daemon/clidrivers/claudecode.py (DM3+ bundle) ─────────────────────────
"""clidrivers/claudecode.py — ClaudeCodeDriver.

DM-CLI-01 (multi-cli-clients). Verbatim extraction of the logic that
used to live inline in runnerspawn.py/runnerloop.py — the argv-build
block, `claude` binary discovery, and the `stream-json` line-parsing
branch. This is a pure code move: every comment explaining WHY a given
flag/behavior exists (py-1.6.1 hotfix, MP1/MP3, the stdin-piping
workaround, CU1 usage capture) travels with the code, unchanged."""


import json
import os
import re
from typing import Any, Dict, List, Optional



def _find_claude() -> Optional[str]:
    """Locate the `claude` CLI. Heuristic — try shell PATH, then the
    nvm + Homebrew locations we expect on a typical operator laptop."""
    import shutil

    found = shutil.which("claude")
    if found:
        return found
    import glob

    for pattern in [
        os.path.expanduser("~/.nvm/versions/node/v*/bin/claude"),
        "/opt/homebrew/bin/claude",
        "/usr/local/bin/claude",
    ]:
        hits = sorted(glob.glob(pattern), reverse=True)
        if hits and os.access(hits[0], os.X_OK):
            return hits[0]
    return None


# Tools whose JSON schemas Meta's Model API rejects (DM-CLI-16).
# Verified 2026-09-19 with real `claude` 2.1.267 turns against
# https://api.meta.ai: the built-in `Artifact` tool's schema carries a
# `pattern` using `\p{...}` unicode-property escapes + lookahead, and Meta
# answers `400 Invalid JSON schema: "..." is not a "regex"` — rejecting the
# whole request even when the turn never uses the tool. Disallowing it
# client-side keeps it out of the sent schemas; the other ~25 tools
# (Bash/Read/Edit/Write/Task/...) are accepted, and a real Bash tool-use
# turn succeeds end-to-end.
META_INCOMPATIBLE_TOOLS = ("Artifact",)


def with_meta_tool_compat(args: List[str]) -> List[str]:
    """Copy of claude-code argv with Meta-rejected tools folded into
    `--disallowed-tools` (idempotent, no duplicates). Appends to the
    existing value when the flag is present, else adds the flag."""
    out = list(args)
    if "--disallowed-tools" in out:
        i = out.index("--disallowed-tools")
        current = (
            [t.strip() for t in out[i + 1].split(",") if t.strip()]
            if i + 1 < len(out)
            else []
        )
        for tool in META_INCOMPATIBLE_TOOLS:
            if tool not in current:
                current.append(tool)
        if i + 1 < len(out):
            out[i + 1] = ",".join(current)
        else:
            out.append(",".join(current))
    else:
        out.extend(["--disallowed-tools", ",".join(META_INCOMPATIBLE_TOOLS)])
    return out


class ClaudeCodeDriver(ClientDriver):
    id = "claude-code"
    label = "Claude Code"

    def find_binary(self) -> Optional[str]:
        return _find_claude()

    def install_hint(self) -> str:
        return "install via `npm i -g @anthropic-ai/claude-code`"

    def auth_configured(self) -> Optional[bool]:
        # claude-code manages its own login state (`claude /login`) outside
        # any single env var MeshKore can check non-interactively — a
        # missing ANTHROPIC_API_KEY does NOT mean unauthenticated (it may
        # be using a Claude subscription login instead). Unknown, not a
        # false negative.
        return None

    def models_catalog(self) -> List[Dict[str, Any]]:
        # Kept in step with `providers.PROVIDERS["anthropic"]["models"]` — the
        # list the cockpit reads once a provider is selected. It cannot IMPORT
        # that list (bundle.py inlines `clidrivers` BEFORE `providers.py`), so
        # `test_clidrivers_claudecode.py::test_anthropic_catalogs_agree` fails
        # the build on drift instead. It used to say it mirrored models.ts and
        # then offered aliases only: `opus` cannot reach Fable, which has no
        # alias, so the flagship was unreachable from every surface that read
        # THIS list rather than the provider one.
        # Catalog refresh 2026-09-12 (DM-CLI-12): `fable` alias added
        # (verified in local `claude --help`: aliases are fable/opus/
        # sonnet) + pinned `claude-opus-5` (cheaper SOTA coding flagship
        # alongside Fable; on Bedrock + press). Older pins KEPT — Anthropic
        # still serves them and members may be pinned to one.
        return [
            {"id": "auto", "label": "Auto"},
            {"id": "fable", "label": "Fable"},
            {"id": "opus", "label": "Opus"},
            {"id": "sonnet", "label": "Sonnet"},
            {"id": "haiku", "label": "Haiku"},
            {"id": "claude-fable-5-1", "label": "Fable 5.1"},
            {"id": "claude-fable-5", "label": "Fable 5"},
            {"id": "claude-opus-5", "label": "Opus 5"},
            {"id": "claude-opus-4-8", "label": "Opus 4.8"},
            {"id": "claude-sonnet-5", "label": "Sonnet 5"},
        ]

    def efforts_catalog(self) -> List[Dict[str, Any]]:
        return [
            {"id": "default", "label": "Default"},
            {"id": "low", "label": "Low"},
            {"id": "medium", "label": "Medium"},
            {"id": "high", "label": "High"},
            {"id": "xhigh", "label": "XHigh"},
            {"id": "max", "label": "Max"},
        ]

    def build_args(
        self,
        binary: str,
        *,
        prompt: str,
        model: Optional[str],
        effort: Optional[str],
        session_id: str,
        use_session: bool,
    ) -> List[str]:
        # claude-code takes the briefing via stdin (write_prompt's
        # default) — see the py-1.10.5 note below for why.
        _ = prompt
        args = [
            binary,
            "-p",
            "--output-format",
            "stream-json",
            "--verbose",
            "--include-partial-messages",
            "--permission-mode",
            "bypassPermissions",
            # Headless: cockpit has no UI to surface interactive question
            # tools. Disallow them so the model defaults to plain-text
            # asks in the chat bubble instead of stalling on a hanging
            # AskUserQuestion / ExitPlanMode call.
            "--disallowed-tools",
            "AskUserQuestion,ExitPlanMode",
        ]
        # MP1 (py-1.13.3) — Per-conv model override. `--model` accepts
        # one of `opus` / `sonnet` / `haiku` or an explicit model id
        # (claude-opus-4-7, etc.). When unset (`auto` / None), we omit
        # the flag entirely and let claude-code pick its default.
        if model:
            args.extend(["--model", model])
        # MP3 (py-1.13.4) — reasoning-depth dial. Omitted when None
        # ('default' sentinel) so claude-code uses its own default.
        if effort:
            args.extend(["--effort", effort])
        # py-1.6.1 HOTFIX — --session-id from py-1.6.0 caused empty
        # assistant responses in production (claude-code exited
        # silently on subsequent turns of the same conv). Reverted to
        # opt-in via env var MESHKORE_CLAUDE_SESSION_ID=1. Default off
        # until the failure mode is understood and re-tested. The
        # uuid5 helper (`_session_id_for_conv`, runnerutil.py) is
        # preserved so reintroduction is a one-line flip once safe.
        if use_session:
            args[2:2] = ["--session-id", session_id]
        return args

    # py-1.10.5 — Pipe the briefing through stdin instead of appending it
    # as a positional argument (base class default already does this —
    # claude 2.1.145 rejects a trailing positional that arrives AFTER a
    # multi-value flag like `--disallowed-tools <comma,list>`; the parser
    # consumes our prompt as another disallowed-tool name or drops it,
    # exiting 1 with "Input must be provided either through stdin or as a
    # prompt argument when using --print". Stdin works regardless of argv
    # order, so it's the forward-compatible answer — no override needed
    # here, `ClientDriver.write_prompt`'s default IS this behavior.)

    def parse_stream_line(self, line: str) -> List[Any]:
        try:
            ev = json.loads(line)
        except json.JSONDecodeError:
            return []
        if not isinstance(ev, dict):
            return []
        out: List[Any] = []
        ev_type = ev.get("type")
        if ev_type == "stream_event":
            inner = ev.get("event") or {}
            if (
                inner.get("type") == "content_block_delta"
                and (inner.get("delta") or {}).get("type") == "text_delta"
            ):
                delta = (inner.get("delta") or {}).get("text") or ""
                if delta:
                    out.append(TextDelta(text=delta))
            elif (
                inner.get("type") == "content_block_start"
                and (inner.get("content_block") or {}).get("type") == "tool_use"
            ):
                cb = inner.get("content_block") or {}
                out.append(ToolUse(name=cb.get("name"), input=cb.get("input")))
            return out
        if ev_type == "assistant":
            # BT-16 — the complete message repeats each tool call WITH its
            # arguments (the stream's content_block_start had none). Only
            # the target is taken from it; the call was already counted.
            for c in (ev.get("message") or {}).get("content") or []:
                if (
                    isinstance(c, dict)
                    and c.get("type") == "tool_use"
                    and c.get("input")
                ):
                    out.append(ToolInput(name=c.get("name"), input=c.get("input")))
            return out
        if ev_type == "user":
            for c in (ev.get("message") or {}).get("content") or []:
                if isinstance(c, dict) and c.get("type") == "tool_result":
                    out.append(ToolResult(ok=not c.get("is_error")))
            return out
        if ev_type == "result" and isinstance(ev.get("result"), str):
            # CU1 (py-1.13.3) — Capture token usage + cost from the
            # SDK's terminal event. claude-code emits e.g.
            #   {"type":"result","result":"…","usage":{
            #       "input_tokens":N,"output_tokens":N,
            #       "cache_read_input_tokens":N,
            #       "cache_creation_input_tokens":N},
            #    "total_cost_usd":N,"num_turns":N}
            usage_raw = ev.get("usage")
            usage: Optional[Dict[str, int]] = None
            if isinstance(usage_raw, dict):
                usage = {
                    "input_tokens": int(usage_raw.get("input_tokens") or 0),
                    "output_tokens": int(usage_raw.get("output_tokens") or 0),
                    "cache_read_input_tokens": int(
                        usage_raw.get("cache_read_input_tokens") or 0
                    ),
                    "cache_creation_input_tokens": int(
                        usage_raw.get("cache_creation_input_tokens") or 0
                    ),
                }
            cost_raw = ev.get("total_cost_usd")
            cost = float(cost_raw) if isinstance(cost_raw, (int, float)) else None
            out.append(Final(text=ev["result"], usage=usage, cost_usd=cost))
        return out

    # py-1.21.1 — TRANSIENT API-ERROR RETRY SHIELD (TR1). claude-code
    # 2.1.145 occasionally fails a long interleaved-thinking + multi-
    # tool turn with `API Error: 400 … thinking/redacted_thinking
    # blocks in the latest assistant message cannot be modified` — a
    # CLI bug reconstructing the multi-block assistant message for the
    # tool-loop continuation, so a fresh spawn rebuilds a clean array
    # and the same turn succeeds. Siblings: transient 5xx / overloaded /
    # rate-limit. These are TRANSPORT failures, not task outcomes.
    _TRANSIENT_STATUS_RE = re.compile(r"api error:\s*(?:429|5\d\d)\b")

    def is_transient_error(self, text: str) -> bool:
        if not text:
            return False
        low = text.strip().lower()
        if not low.startswith("api error"):
            return False
        # NEVER retry request-shape failures — a re-spawn rebuilds the same
        # oversized/invalid request and burns the budget for nothing.
        if "too long" in low or "prompt is too" in low:
            return False
        # The specific 400 we DO retry: the thinking/redacted_thinking
        # "cannot be modified" CLI reconstruction bug — a fresh message
        # array makes it disappear.
        if "cannot be modified" in low or "redacted_thinking" in low:
            return True
        # Transient upstream conditions.
        markers = (
            "overloaded",
            "rate limit",
            "rate_limit",
            "internal server error",
            "service unavailable",
            "bad gateway",
            "gateway timeout",
            "timed out",
            "timeout",
        )
        if any(m in low for m in markers):
            return True
        return bool(self._TRANSIENT_STATUS_RE.search(low))


