def known_provider_ids() -> List[str]:
    return sorted(PROVIDERS.keys())


# A provider and a CLIENT can be the same vendor behind the same bearer —
# Meta's key authenticates both the `muse` CLI and the `meta` endpoint. The
# operator stores ONE key; whichever slot they happened to fill, both work.
# Without this the Config screen would silently demand the same secret
# twice, and the second omission looks exactly like "Muse doesn't work".
PROVIDER_KEY_ALIASES: Dict[str, str] = {"meta": "muse"}


def key_alias_for(slot_id: Optional[str]) -> Optional[str]:
    """The other slot whose stored key authenticates this one, in EITHER
    direction: `meta` ↔ `muse`. Whichever box the operator filled, the
    other one is satisfied too."""
    sid = str(slot_id or "").strip().lower()
    if sid in PROVIDER_KEY_ALIASES:
        return PROVIDER_KEY_ALIASES[sid]
    for provider_id, client_id in PROVIDER_KEY_ALIASES.items():
        if client_id == sid:
            return provider_id
    return None


