#
# Codex and Gemini are not "providers" of claude-code — they ARE the
# client, each talking only to its own vendor's API. There is no base-url
# swap here, just an optional daemon-managed API key so headless agents
# don't depend on an interactive `codex login` / `gcloud auth` having
# already happened in that shell. Absent a stored key, the client's own
# native login/env keeps working exactly as before (zero behavior change).
# Reuses the SAME chmod-0600 store as providers (providersvc.ProviderKeyStore
# is generic over any id) — shown alongside Anthropic/ZAI in one "Providers"
# list in Config → General settings so the operator has ONE place for every
# daemon-managed AI credential (capped at a handful, not a sprawling list).
CLIENT_KEY_SPECS: Dict[str, Dict[str, Any]] = {
    "muse": {"id": "muse", "label": "Muse Code (Meta)", "env_var": "META_API_KEY"},
    "codex": {
        "id": "codex",
        "label": "Codex (OpenAI)",
        "env_var": "OPENAI_API_KEY",
    },
    "gemini": {
        "id": "gemini",
        "label": "Gemini (Google)",
        "env_var": "GEMINI_API_KEY",
    },
}


def known_client_key_ids() -> List[str]:
    return sorted(CLIENT_KEY_SPECS.keys())


def provider_for(provider_id: Optional[str]) -> Dict[str, Any]:
    """Metadata dict for a provider id; unknown/absent → anthropic (so a
    stale member file or a provider from a future daemon degrades safely
    to native Anthropic instead of crashing a spawn)."""
    if not provider_id:
        return PROVIDERS[DEFAULT_PROVIDER]
    return PROVIDERS.get(str(provider_id).strip().lower(), PROVIDERS[DEFAULT_PROVIDER])


def provider_models(provider_id: Optional[str]) -> List[Dict[str, Any]]:
    return list(provider_for(provider_id).get("models") or [])


def build_launch_env(
    base_env: Dict[str, str],
    provider_id: Optional[str],
    *,
    resolved: Optional[Dict[str, Any]] = None,
) -> Dict[str, str]:
    """Return a NEW env dict for `subprocess.Popen(env=…)`.

    The contract (security-critical, tested in tests/test_providers.py):

      1. ALWAYS start from a COPY of `base_env` and REMOVE the
         cross-provider keys (`ANTHROPIC_BASE_URL`, `ANTHROPIC_AUTH_TOKEN`)
         so a value from the daemon's own shell can never leak a session
         onto the wrong endpoint — in EITHER direction.
      2. `anthropic` (default / unknown): return the scrubbed env AS-IS
         (native login/config). Also drop `ANTHROPIC_MODEL` /
         `ANTHROPIC_SMALL_FAST_MODEL` so a stray override from a
         previously-ZAI-configured shell doesn't bleed in.
      3. non-anthropic: overlay `ANTHROPIC_BASE_URL` / `ANTHROPIC_AUTH_TOKEN`
         / `ANTHROPIC_MODEL` / `ANTHROPIC_SMALL_FAST_MODEL` from `resolved`
         ({base_url, auth_token, model, small_fast_model}); also drop
         `ANTHROPIC_API_KEY` so only the provider's token authenticates.

    Never mutates `base_env`. `resolved` is provided by the caller
    (providersvc.resolve_provider, augmented with the per-turn model).
    """
    env = dict(base_env)
    for k in _CROSS_KEYS:
        env.pop(k, None)

    pid = str(provider_id or DEFAULT_PROVIDER).strip().lower()
    if pid not in PROVIDERS or pid == DEFAULT_PROVIDER:
        # Native Anthropic — a clean slate. Drop model overrides too.
        for k in _DEFAULT_MODEL_KEYS:
            env.pop(k, None)
        return env

    resolved = resolved or {}
    base_url = str(resolved.get("base_url") or "").strip()
    token = str(resolved.get("auth_token") or "").strip()
    model = str(resolved.get("model") or "").strip()
    small = str(resolved.get("small_fast_model") or "").strip()

    if base_url:
        env["ANTHROPIC_BASE_URL"] = base_url
    if token:
        env["ANTHROPIC_AUTH_TOKEN"] = token
    if model:
        env["ANTHROPIC_MODEL"] = model
        # Meta's setup guide pins all three tier defaults to the same
        # model id; harmless for ZAI, required for Meta alias resolution.
        env["ANTHROPIC_DEFAULT_OPUS_MODEL"] = model
        env["ANTHROPIC_DEFAULT_SONNET_MODEL"] = model
        env["ANTHROPIC_DEFAULT_HAIKU_MODEL"] = model
    if small:
        env["ANTHROPIC_SMALL_FAST_MODEL"] = small
    # A custom-endpoint provider authenticates with AUTH_TOKEN — a
    # lingering ANTHROPIC_API_KEY (used by the daemon's own /team/draft
    # call) would confuse the CLI's credential precedence. Drop it.
    env.pop("ANTHROPIC_API_KEY", None)
    return env


# ── inlined from daemon/team.py (DM3+ bundle) ─────────────────────────
"""team.py — the agent-team data model + TeamStore (in-process CRUD + seed).

Initiative `agent-team` (ATM2), reduced to its minimal expression by
`generic-agents` (GA-1, 2026-09-26). A "team member" is a reusable agent
PROFILE the operator defines once and instantiates many times: a chat
session becomes an INSTANCE of a member (ATM10), inheriting its client,
model and — on its first turn — its prompt body.

There is no longer a second specialisation axis. Every agent runs the SAME
generic role (GA-2); what makes a Deployer a Deployer is two things and
nothing else: the prompt the operator wrote, and the slice of the
knowledge tree it is given.

Storage: one markdown file per member at `.meshkore/team/<id>.md`,
YAML frontmatter + prompt body. The frontmatter is committed with the
repo (v27 git contract commits `.meshkore/` minus the runtime deny-list);
no secrets live here.

TeamStore is pure per-project state: construct it with a `Paths` and it
reads/writes `<root>/.meshkore/team/`. It starts no threads, holds no
locks beyond a filesystem read, and is safe to build per-call (mirrors
how the crud/readapi mixins touch `.meshkore/agents/`).

Schema — SIX authored keys, and the operator types four of them:

    id: deployer               # slug; ^[a-z][a-z0-9-]{1,31}$
    title: "Deployer"          # what the cockpit shows
    client: claude-code        # which CLI spawns this member's turns
    model: sonnet              # MANDATORY unless the driver allows ""
    context: [deploy, workflows, credentials]
                               # GA-4 — branches of the knowledge tree
                               # (`context/_index.yaml`) pinned into this
                               # member's briefing. Empty = the project
                               # default. THIS is what makes a member
                               # specialised; there is no other mechanism.
    exposure: internal         # internal | external — external mints a
                               # revocable token and opens /team/<id>/ask.
                               # Never in the create form; the public
                               # consultant is the only member that uses it.

plus `provider` and `effort`, which the client/model picker sets, and
`created` / `updated`, which the daemon stamps.

`emoji` and `color` are DERIVED from the id (`derived_look`) and are not
stored: they are decoration the cockpit needs, and picking a hex code is
not part of describing what an agent does.

Everything in `LEGACY_FIELDS` — `kind`, `required`, `agent_type`,
`pinned_order`, `owns`, `never`, `delegates_to`, `refs`,
`credentials_hint` — was carried by the old schema and is dropped on
read and on write. `migrate_to_minimal_schema()` rewrites the files, and
the boot hook runs it per project, so nothing needs migrating by hand.

Validation: `model` required + non-empty (unless the driver declares ""
as its own "use the account default" entry); `client` ∈
`clidrivers.known_ids()`; `effort` ∈ that client's own
`efforts_catalog()` (NOT a single global enum — different clients can
offer different reasoning-depth vocabularies); `context` entries are
knowledge-node slugs, existence checked at spawn, not here."""


import re
import time
from pathlib import Path
from typing import Any, Dict, List, Tuple


# REL2 — was `_MEMBER_ID_RE` (see providersvc.py): same name, different rule.
_MEMBER_ID_RE = re.compile(r"^[a-z][a-z0-9-]{1,31}$")
#: GA-4 — a knowledge-tree node id: a branch (`deploy`) or a leaf
#: (`project.idea`). Same shape `_index.yaml` uses.
_CONTEXT_ID_RE = re.compile(r"^[a-z][a-z0-9-]*(\.[a-z0-9-]+)*$")
# TEG-1 (team-external-gateway) — who may consume this member. `internal`
# (default when absent) = operator/cockpit only; `external` = the member
# additionally answers the /team/<id>/ask surface with a per-member bearer
# token (stored in credentials/, NEVER here). Enum leaves room for a future
# `mesh` value (Phase 2) without another migration. Orthogonal to `kind`.
_EXPOSURES = ("internal", "external")

# The strongest available alias — policy is "strongest model, tune with
# effort" (mirrors the cockpit's lib/models.ts default). Every seed +
# every draft is born at this alias.
STRONGEST_MODEL_ALIAS = "opus"


def slug_member_id(name: str) -> str:
    """TMR1 — a member id derived from its display name.

    The cockpit's "New member" form asks for a NAME, never an id: an
    operator types "SEO writer", not "seo-writer". The id is ours to mint
    (it is the file name under `.meshkore/team/`), so mint it here rather
    than making every client reimplement the slug rule. Returns "" when
    nothing usable survives — the caller then raises the normal
    validation error.
    """
    txt = (name or "").strip().lower()
    # Latin-1 letters an operator will type in a Spanish/French name.
    for a, b in (
        ("áàä", "a"),
        ("éèë", "e"),
        ("íìï", "i"),
        ("óòö", "o"),
        ("úùü", "u"),
        ("ñ", "n"),
        ("ç", "c"),
    ):
        for ch in a:
            txt = txt.replace(ch, b)
    txt = re.sub(r"[^a-z0-9]+", "-", txt).strip("-")
    txt = re.sub(r"-{2,}", "-", txt)
    if not txt:
        return ""
    # The id rule wants a leading letter and at most 32 chars total.
    if not txt[0].isalpha():
        txt = "m-" + txt
    return txt[:32].rstrip("-")


class TeamError(Exception):
    """Base for TeamStore failures; carries an HTTP-ish code + message."""

    code = 400

    def __init__(self, message: str, **extra: Any) -> None:
        super().__init__(message)
        self.message = message
        self.extra = extra


class TeamValidationError(TeamError):
    code = 400


class TeamNotFound(TeamError):
    code = 404


class TeamConflict(TeamError):
    code = 409


class TeamProtected(TeamError):
    code = 409


# ── serialisation ──────────────────────────────────────────────────────

_FM_SPLIT_RE = re.compile(r"^---\s*\n(.*?)\n---\s*\n?(.*)$", re.DOTALL)

# GA-1 (generic-agents, 2026-09-26) — the member schema in its minimal
# expression. It used to carry EIGHTEEN frontmatter keys, so defining "a
# coder" meant filling in `kind`, `required`, `pinned_order`,
# `credentials_hint`, `agent_type`, `owns`, `never`, `delegates_to`,
# `refs`… The operator's rule: "cuantas menos cosas para definir un
# agente mejor".
#
# What an operator authors is now SIX things — `id`, `title`, `client`,
# `model`, `context`, and the prompt body. `provider` and `effort` are
# dials the client picker sets; `exposure` exists only because the public
# consultant needs revocable tokens and never appears in the form.
#
# `emoji` and `color` are DERIVED from the id (see `derived_look`): they
# are decoration, the cockpit needs them, and nobody should have to pick
# a hex code to create an agent.
_FIELD_ORDER = (
    "id",
    "title",
    "client",
    "provider",
    "model",
    "effort",
    # GA-4 — which branches of the knowledge tree (`context/_index.yaml`)
    # this member gets pinned into its briefing. The whole point of the
    # field: a deployer reads the deploy context, a UI agent does not.
    "context",
    "exposure",
    # BT-19 — `single` (one session batches every brief: git-manager,
    # deployer) or `per-brief` (a fresh session per brief, run in parallel).
    "sessions",
    "created",
    "updated",
)

#: Keys the old schema carried that the new one does not. Dropped on every
#: write (the serialiser otherwise preserves unknown operator keys, which
#: would make the migration a no-op on a round-trip).
LEGACY_FIELDS = frozenset(
    {
        "name",  # → title
        "emoji",  # derived
        "color",  # derived
        "kind",  # singleton/profile: a business rule in the data model
        "required",
        "agent_type",  # the second specialisation axis GA-2 removes
        "pinned_order",
        "owns",  # the delegation contract: derived from the prompt now
        "never",
        "delegates_to",
        "refs",  # → context
        "credentials_hint",
    }
)

_LIST_FIELDS = frozenset({"context"})

_QUOTED_FIELDS = frozenset({"title"})


def split_member_file(text: str) -> Tuple[Dict[str, Any], str]:
    """Parse a member .md into (frontmatter dict, body). The body is
    returned VERBATIM (everything after the closing `---`) so a
    parse→serialise round-trip preserves the init prompt exactly."""
    m = _FM_SPLIT_RE.match(text)
    if not m:
        # No frontmatter — treat the whole thing as body, empty fm.
        return {}, text
    fm = parse_frontmatter(text)
    body = m.group(2)
    return fm, body


def _yaml_scalar(v: Any) -> str:
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, (int, float)):
        return str(v)
    return str(v)


def serialise_member(fm: Dict[str, Any], body: str) -> str:
    """Render a member back to `<frontmatter>\\n---\\n<body>` text with the
    canonical field order + quoting. Unknown fields are appended after
    the known ones so nothing the operator added is lost."""
    lines: List[str] = ["---"]
    written: set = set()

    def emit(key: str) -> None:
        if key not in fm or key in written:
            return
        written.add(key)
        val = fm[key]
        if key in _LIST_FIELDS:
            items = val if isinstance(val, list) else []
            if not items:
                lines.append(f"{key}: []")
            else:
                lines.append(f"{key}:")
                for r in items:
                    lines.append(f"  - {r}")
            return
        if key in _QUOTED_FIELDS:
            s = str(val).replace("\\", "\\\\").replace('"', '\\"')
            lines.append(f'{key}: "{s}"')
            return
        # DM-CLI-05 follow-up (live smoke test, 2026-07-08) — a bare
        # `key:` with nothing after it (the naive `_yaml_scalar("")`
        # output) round-trips through this project's simplified YAML
        # parser as `{}` (an empty MAPPING), not an empty string — the
        # parser's block-mapping heuristic treats "nothing on this
        # line" as "the value is a nested block starting below", same
        # as real YAML. `client: codex` + empty `model` (Codex/Gemini's
        # own "use account default" sentinel, DM-CLI-05) hit this
        # exactly: saved as `model: ` (blank), reloaded as `model: {}`.
        # Quote empty values explicitly so the round-trip preserves
        # "empty string", not "empty mapping".
        if val == "":
            lines.append(f'{key}: ""')
            return
        lines.append(f"{key}: {_yaml_scalar(val)}")

    for key in _FIELD_ORDER:
        emit(key)
    # Preserve any extra operator-added frontmatter keys — EXCEPT the ones
    # the old eighteen-key schema used. Without that exclusion the
    # migration would be a no-op: `migrate_fm` strips them from the dict,
    # but anything still present would be written straight back out.
    for key in fm:
        if key not in written and key not in LEGACY_FIELDS:
            emit(key)
    lines.append("---")
    # `<frontmatter>\n---\n<body>` — the body (as returned by
    # split_member_file) carries no leading newline, so one newline after
    # the closing `---` reconstructs the source layout exactly.
    out = "\n".join(lines) + "\n"
    body = body or ""
    if body:
        out += body
    if not out.endswith("\n"):
        out += "\n"
    return out


# ── GA-1: migration + derived decoration ───────────────────────────────

#: Palette the derived colour picks from. Deliberately small and legible
#: on the cockpit's dark ground; index chosen by a stable hash of the id,
#: so a member keeps its colour for life without anyone authoring one.
_LOOK_COLORS = (
    "#7C5CFF",
    "#10B981",
    "#F59E0B",
    "#38BDF8",
    "#F472B6",
    "#14B8A6",
    "#A78BFA",
    "#FB7185",
)

#: Recognisable glyphs for the ids the base team ships with. Anything else
#: falls back to the generic robot — an agent is an agent.
_LOOK_EMOJI = {
    "a01": "🏛",
    "architect": "🏛",
    "orchestrator": "🎯",
    "developer": "💻",
    "deployer": "🚀",
    "consultant": "🛎",
    "tester": "🧪",
}


def derived_look(mid: str) -> Tuple[str, str]:
    """`(emoji, color)` for a member id — never authored, always the same.

    Picking a hex code is not part of describing what an agent does, and
    making it a field meant every create form had a colour well in it."""
    mid = (mid or "").strip()
    emoji = _LOOK_EMOJI.get(mid, "🤖")
    h = 0
    for ch in mid:
        h = (h * 31 + ord(ch)) & 0xFFFFFFFF
    return emoji, _LOOK_COLORS[h % len(_LOOK_COLORS)]


def migrate_fm(fm: Dict[str, Any]) -> Dict[str, Any]:
    """Old eighteen-key frontmatter → the minimal schema. Idempotent.

    Applied on READ so a project that has not been rewritten yet still
    works, and on WRITE so the file is cleaned the first time anyone
    touches it. Never raises: a member that cannot be migrated is better
    served half-converted than not loaded at all."""
    out = dict(fm or {})
    mid = str(out.get("id") or "").strip()
    # `name` → `title`. Both may be present mid-migration; `title` wins.
    if not str(out.get("title") or "").strip():
        out["title"] = str(out.get("name") or "").strip() or (
            mid.replace("-", " ").title() if mid else ""
        )
    # `refs` (file paths) → `context` (knowledge-tree branch ids). A path
    # cannot be mapped to a branch reliably, and guessing wrong would pin
    # the wrong documents into every spawn — so an unmigrated member gets
    # an EMPTY context, which means "the default pinned set", exactly what
    # it received before the field existed.
    ctx = out.get("context")
    if not isinstance(ctx, list):
        out["context"] = [] if ctx in (None, "") else [str(ctx).strip()]
    out["context"] = [str(c).strip() for c in out["context"] if str(c or "").strip()]
    for key in LEGACY_FIELDS:
        out.pop(key, None)
    # BT-19 — the git/deploy members keep one batching session; stamping it
    # on the card makes that visible (and editable) instead of implicit.
    if mid in SINGLE_SESSION_DEFAULT_IDS and not str(out.get("sessions") or "").strip():
        out["sessions"] = "single"
    return out


def decorate(fm: Dict[str, Any]) -> Dict[str, Any]:
    """Add the fields the API still serves but the FILE no longer stores.

    `emoji`/`color` are derived; `name` is kept as an alias of `title` so
    every existing consumer (cockpit cards, chat header, briefing) keeps
    working without a coordinated rename."""
    out = dict(fm or {})
    mid = str(out.get("id") or "").strip()
    emoji, color = derived_look(mid)
    out.setdefault("emoji", emoji)
    out.setdefault("color", color)
    title = str(out.get("title") or "").strip() or mid
    out["title"] = title
    out["name"] = title
    return out


# ── validation ─────────────────────────────────────────────────────────


def validate_member(fm: Dict[str, Any]) -> None:
    """Enforce the schema invariants. Raises TeamValidationError."""
    mid = str(fm.get("id") or "").strip()
    if not _MEMBER_ID_RE.match(mid):
        raise TeamValidationError(
            "id must match ^[a-z][a-z0-9-]{1,31}$ (lowercase slug)"
        )
    # DM-CLI-02 (multi-cli-clients) — absent/empty means claude-code
    # (every pre-existing member file validates unchanged). Resolved
    # BEFORE effort so effort can be checked against THIS client's own
    # vocabulary rather than one global enum.
    client = str(fm.get("client") or "claude-code").strip().lower()
    if client not in known_ids():
        raise TeamValidationError(f"client must be one of {known_ids()}")
    # multi-provider-agents (MPV1) — which LLM backend the claude-code
    # client talks to. Absent/empty means anthropic (every pre-MPV1 member
    # file validates unchanged); anything else must be a known provider.
    # Orthogonal to `client`; only acted on when client == claude-code.
    provider = str(fm.get("provider") or "anthropic").strip().lower()
    if provider not in known_provider_ids():
        raise TeamValidationError(f"provider must be one of {known_provider_ids()}")
    model = str(fm.get("model") or "").strip()
    # DM-CLI-05 follow-up (live smoke test, 2026-07-08) — a driver may
    # declare "" as a legitimate "use the CLI/account default" catalog
    # entry (codex, gemini — neither has a claude-style alias to fall
    # back on). Only THOSE drivers get an empty-model exemption; every
    # other client (claude-code included) keeps the original mandatory-
    # non-empty rule unchanged.
    if not model:
        allowed = {m.get("id") for m in driver_for(client).models_catalog()}
        if "" not in allowed:
            raise TeamValidationError("model is mandatory and must be non-empty")
    effort = str(fm.get("effort") or "default").strip().lower()
    valid_efforts = sorted(e["id"] for e in driver_for(client).efforts_catalog())
    if effort not in valid_efforts:
        raise TeamValidationError(
            f"effort must be one of {valid_efforts} for client {client!r}"
        )
    # TEG-1 — exposure enum. Absent/empty means internal (all pre-v1.30
    # member files validate unchanged); anything else must be in the enum.
    exposure = str(fm.get("exposure") or "internal").strip().lower()
    if exposure not in _EXPOSURES:
        raise TeamValidationError(f"exposure must be one of {_EXPOSURES}")
    # BT-19 — how the member takes briefs. Absent = the id's default.
    sessions = str(fm.get("sessions") or "").strip().lower()
    if sessions and sessions not in SESSION_MODES:
        raise TeamValidationError(f"sessions must be one of {SESSION_MODES}")
    # GA-4 — `context` names branches of the knowledge tree
    # (`context/_index.yaml`). Validated as slugs only: whether a branch
    # EXISTS is a per-project question the briefing answers at spawn time
    # by simply skipping unknown ids, so a member file stays valid across
    # a project whose tree is still being written.
    ctx = fm.get("context")
    if ctx not in (None, "", []):
        if not isinstance(ctx, list):
            raise TeamValidationError("context must be a list of knowledge branch ids")
        for node in ctx:
            if not _CONTEXT_ID_RE.match(str(node or "").strip()):
                raise TeamValidationError(
                    f"context entry {node!r} is not a valid knowledge node id"
                )


# ── TeamStore ──────────────────────────────────────────────────────────


class TeamStore:
    def __init__(self, paths: Any) -> None:
        self.paths = paths
        self.dir: Path = paths.team_dir

    # ── read ────────────────────────────────────────────────────────────
    def _path(self, mid: str) -> Path:
        return self.dir / f"{mid}.md"

    def team_list(self) -> List[Dict[str, Any]]:
        """Frontmatter-only list, in base-team order then alphabetical.

        GA-1 — every card is migrated and decorated ON READ, so a project
        whose files are still in the old eighteen-key schema serves the
        new shape without anyone running a migration first. The file on
        disk is only rewritten when something else writes it."""
        out: List[Dict[str, Any]] = []
        if not self.dir.exists():
            return out
        for f in sorted(self.dir.glob("*.md")):
            try:
                fm, body = split_member_file(f.read_text(encoding="utf-8"))
            except OSError:
                continue
            if not fm.get("id"):
                fm["id"] = f.stem
            # BT-5 — the card's opening sentence, for the cockpit's "+"
            # picker. Derived, never stored: it cannot drift from the prompt.
            out.append({**decorate(migrate_fm(fm)), "summary": member_summary(body)})
        out.sort(key=lambda m: (_order_of(m), str(m.get("id") or "")))
        return out

    def team_get(self, mid: str) -> Dict[str, Any]:
        """Full member: frontmatter + body. Raises TeamNotFound."""
        p = self._path(mid)
        if not p.is_file():
            raise TeamNotFound(f"team member {mid!r} not found")
        fm, body = split_member_file(p.read_text(encoding="utf-8"))
        if not fm.get("id"):
            fm["id"] = mid
        return {"frontmatter": decorate(migrate_fm(fm)), "body": body}

    def exists(self, mid: str) -> bool:
        return self._path(mid).is_file()

    def ids(self) -> List[str]:
        if not self.dir.exists():
            return []
        return sorted(p.stem for p in self.dir.glob("*.md"))

    # ── write ────────────────────────────────────────────────────────────
    def team_create(self, payload: Dict[str, Any], *, today: str) -> Dict[str, Any]:
        fm = _normalise_payload(payload, today=today)
        # TMR1 — the cockpit posts a NAME and no id (an operator types
        # "SEO writer"), and the daemon used to answer 400 "id must match
        # ^[a-z]..." for every single create: the New-member form could
        # not create anybody. Mint the id from the name, and make it
        # unique instead of 409-ing on a name that already exists — a
        # second "Developer" is a legitimate thing to want.
        if not str(fm.get("id") or "").strip():
            base = slug_member_id(str(payload.get("name") or ""))
            if base:
                fm["id"] = self._free_id(base)
        validate_member(fm)
        mid = fm["id"]
        if self.exists(mid):
            raise TeamConflict(f"team member {mid!r} already exists", id=mid)
        body = str(payload.get("body") or payload.get("prompt") or "").strip()
        if body:
            body += "\n"
        self.dir.mkdir(parents=True, exist_ok=True)
        text = serialise_member(fm, body)
        self._path(mid).write_text(text, encoding="utf-8")
        return self.team_get(mid)

    def team_update(
        self, mid: str, patch: Dict[str, Any], *, today: str
    ) -> Dict[str, Any]:
        cur = self.team_get(mid)
        raw_before = self._path(mid).read_text(encoding="utf-8")
        fm = dict(cur["frontmatter"])
        body = cur["body"]
        # Apply frontmatter patch (ignore id changes — file name is the id —
        # and `updated`, which is server-owned: the daemon stamps it, and
        # only when something actually changed).
        #
        # GA-1 — `name` is still accepted from an older cockpit and lands on
        # `title`; every other legacy key is dropped rather than written
        # back, so touching any member finishes its migration.
        if "name" in patch and "title" not in patch:
            patch = dict(patch)
            patch["title"] = patch.pop("name")
        for k, v in patch.items():
            if k in ("body", "prompt", "id", "updated") or k in LEGACY_FIELDS:
                continue
            fm[k] = v
        # Body replace when provided.
        new_body = patch.get("body", patch.get("prompt"))
        if new_body is not None:
            nb = str(new_body).strip()
            body = (nb + "\n") if nb else ""
        fm["id"] = mid
        # Idempotency: render the candidate with the CURRENT `updated` stamp
        # and compare against the bytes on disk. The cockpit PATCHes per
        # section even when the operator changed nothing, and every such
        # save used to bump `updated` + rewrite the file — leaving a dirty
        # git diff under .meshkore/team/ on EVERY save. A no-op save now
        # returns the member untouched (no write, no stamp bump).
        candidate = serialise_member(fm, body)
        if candidate == raw_before:
            return cur
        fm["updated"] = today
        validate_member(fm)
        text = serialise_member(fm, body)
        self._path(mid).write_text(text, encoding="utf-8")
        return self.team_get(mid)

    def _free_id(self, base: str) -> str:
        """`base`, or the first `base-2`, `base-3`… that is free."""
        base = base[:32].rstrip("-") or "member"
        if not self.exists(base):
            return base
        for n in range(2, 100):
            suffix = f"-{n}"
            cand = (base[: 32 - len(suffix)]).rstrip("-") + suffix
            if not self.exists(cand):
                return cand
        raise TeamConflict(f"no free id left for {base!r}", id=base)

    def team_duplicate(self, mid: str, *, today: str) -> Dict[str, Any]:
        """TMR3 — copy a member card whole: frontmatter, prompt, context.

        One field is deliberately NOT copied: `exposure: external`. The
        token is per-member, and minting one for a copy the operator has
        not thought about widens the attack surface silently — the copy is
        born internal. Everything else (client/provider/model/effort,
        context, body) is byte-identical."""
        src = self.team_get(mid)
        fm = migrate_fm(src.get("frontmatter") or {})
        body = src.get("body") or ""
        new_id = self._free_id(f"{mid}-copy")
        fm["id"] = new_id
        base_title = str(fm.get("title") or mid).strip()
        fm["title"] = f"{base_title} (duplicate)"
        fm["exposure"] = "internal"
        fm["created"] = today
        fm["updated"] = today
        validate_member(fm)
        self.dir.mkdir(parents=True, exist_ok=True)
        atomic_write_text(self._path(new_id), serialise_member(fm, body))
        return self.team_get(new_id)

    def team_delete(self, mid: str) -> None:
        p = self._path(mid)
        if not p.is_file():
            raise TeamNotFound(f"team member {mid!r} not found")
        # GA-1 — nothing is undeletable any more. `required: true` existed
        # to protect the two system singletons, but a member is now just a
        # profile: deleting the Architect card removes a profile, not a
        # capability, and the operator who wants their team to be three
        # agents is not doing anything wrong.
        #
        # Archived, never unlinked: a card carries prose the operator may have
        # spent weeks on (meshkore's `seo` card was lost this way in the v36
        # migration). `.archive/` is one `mv` from restoring it and
        # `team_list` never looks inside a dotted subdirectory.
        archive = self.dir / ".archive"
        archive.mkdir(parents=True, exist_ok=True)
        dest = archive / p.name
        if dest.exists():
            dest = archive / f"{p.stem}.{int(time.time())}{p.suffix}"
        p.replace(dest)

    # ── seed ─────────────────────────────────────────────────────────────
    def seed_defaults(self) -> int:
        """Write the canonical 9-member default team iff `.meshkore/team/`
        is missing or empty. Idempotent: a non-empty dir is left untouched
        (operator edits + deletions survive; existing files are NEVER
        overwritten). Returns the count written. Token minting for members
        seeded `exposure: external` (consultant) is the caller's job —
        see teamext.TeamTokenStore.ensure_for_external (secrets never
        touch `.meshkore/team/`)."""
        try:
            has_any = self.dir.exists() and any(self.dir.glob("*.md"))
        except OSError:
            has_any = False
        if has_any:
            return 0
        self.dir.mkdir(parents=True, exist_ok=True)
        written = 0
        for mid, text in SEED_FILES.items():
            dest = self._path(mid)
            if dest.exists():
                continue
            dest.write_text(text, encoding="utf-8")
            written += 1
        return written

    def migrate_to_minimal_schema(self) -> List[str]:
        """GA-1 — rewrite this project's cards into the minimal schema.

        Runs once per project the first time the daemon resolves it, which
        is what migrates every project on the machine without anyone
        running a script: `name` becomes `title`, the twelve keys in
        `LEGACY_FIELDS` are dropped, and the file is left with the six
        things that actually describe an agent.

        The BODY is never touched — the init prompt is the operator's prose
        and it survives byte-identical. Idempotent: a card already in the
        new shape serialises to the same bytes and is skipped, so this
        costs one read per member per boot and no writes.

        Returns the ids actually rewritten."""
        touched: List[str] = []
        if not self.dir.exists():
            return touched
        for f in sorted(self.dir.glob("*.md")):
            try:
                raw = f.read_text(encoding="utf-8")
            except OSError:
                continue
            try:
                fm, body = split_member_file(raw)
            except Exception:  # noqa: BLE001 — a broken card must not stop the rest
                continue
            fm.setdefault("id", f.stem)
            after = serialise_member(migrate_fm(fm), body)
            if after == raw:
                continue
            try:
                atomic_write_text(f, after)
            except OSError:
                continue
            touched.append(f.stem)
        return touched

    # ── GA-6 — one agent, not a cast ─────────────────────────────────────
    def migrate_to_single_agent(self) -> Dict[str, List[str]]:
        """GA-6 — collapse this project's roster to the single agent.

        Runs once per project, on the same resolve hook that migrated the
        cards to the minimal schema, so there is no script to run and no
        project that quietly stays on the old six-member team.

        Two moves, both idempotent:

        1. The Architect card becomes `a01` / "Architect Agent". Same file,
           new id. Its frontmatter is kept (the `context:` branches the
           operator tuned are data, not decoration) and its BODY is
           replaced only when it is still one of the bodies WE shipped —
           see `body_is_shipped`. An operator who rewrote their card keeps
           every word of it.
        2. Every OTHER card whose id this daemon seeded is moved into
           `.meshkore/team/.archive/`. Archived, not deleted: the folder is
           one `mv` away from bringing a member back, and `team_list` never
           looks inside a dotted subdirectory.

        Repointing the conv sidecars that name the old id is the caller's
        job — see `teamsvc._team_upgrade_for_project`. TeamStore owns files,
        not conversations, and a conv whose `member` no longer resolves
        loses its model dial and its context slice, so the two have to
        happen together or not at all.

        Returns `{"renamed": [<old id>], "archived": [...]}`."""
        out: Dict[str, List[str]] = {"renamed": [], "archived": []}
        if not self.dir.exists():
            return out

        if not self.exists(SINGLE_AGENT_ID):
            src = resolve_system_member(self, ARCHITECT_IDS)
            if src and src != SINGLE_AGENT_ID:
                try:
                    fm, body = split_member_file(
                        self._path(src).read_text(encoding="utf-8")
                    )
                except (OSError, ValueError):
                    fm, body = {"id": src}, ""
                fm = migrate_fm({**fm, "id": src})
                fm["id"] = SINGLE_AGENT_ID
                fm["title"] = SINGLE_AGENT_TITLE
                if body_is_shipped(body):
                    body = A01_BODY
                try:
                    atomic_write_text(
                        self._path(SINGLE_AGENT_ID), serialise_member(fm, body)
                    )
                    self._path(src).unlink()
                    out["renamed"].append(src)
                except OSError:
                    return out

        archive = self.dir / ".archive"
        for mid in RETIRED_SEED_IDS:
            f = self._path(mid)
            if not f.is_file():
                continue
            try:
                archive.mkdir(parents=True, exist_ok=True)
                f.replace(archive / f.name)
            except OSError:
                continue
            out["archived"].append(mid)
        return out

    def ensure_canonical_members(self) -> List[str]:
        """BT-1 (base-team, v38) — give this project the base team, once.

        `seed_defaults` only fires on an empty roster, so every project
        seeded under v37 has `a01` alone. This offers each missing
        base-team member ONCE and records the offer in
        `.meshkore/.runtime/team-offered-v38.json`, so an operator who
        deletes a member does not get it back on the next boot. A fresh
        marker on purpose: the v29–v36 marker lists `developer`,
        `deployer` and `consultant` as already offered, which would have
        kept them away from exactly the projects that need them.

        Two equivalences, so nobody gets a duplicate of what they have:
        any Architect spelling counts as `a01`, and any card with
        `exposure: external` counts as the consultant (meshkore's own is
        `consultant-ext`, with the operator's public-links prose).

        Also upgrades `a01`'s body when it is still one WE shipped — the
        v37 "you are the whole team" card becomes the coordinator. An
        edited card is the operator's and is left alone. Returns the ids
        written (a body upgrade counts)."""
        written: List[str] = []
        try:
            import json

            marker = self.paths.runtime / "team-offered-v38.json"
            offered = set()
            if marker.exists():
                offered = set(json.loads(marker.read_text() or "[]") or [])
            # Nothing to offer on a roster that was never seeded at all —
            # seed_defaults owns that case and writes the full team.
            if not (self.dir.exists() and any(self.dir.glob("*.md"))):
                return written
            members = self.team_list()
            has_external = any(
                str(m.get("exposure") or "") == "external" for m in members
            )
            for mid in SEED_FILES:
                if mid in offered or self.exists(mid):
                    continue
                if mid in ARCHITECT_IDS and resolve_system_member(self, ARCHITECT_IDS):
                    continue
                if mid == "consultant" and has_external:
                    continue
                self._path(mid).write_text(SEED_FILES[mid], encoding="utf-8")
                written.append(mid)
            if self.exists(SINGLE_AGENT_ID) and SINGLE_AGENT_ID not in offered:
                f = self._path(SINGLE_AGENT_ID)
                fm, body = split_member_file(f.read_text(encoding="utf-8"))
                if body_is_shipped(body) and body.strip() != A01_BODY.strip():
                    atomic_write_text(f, serialise_member(fm, A01_BODY))
                    written.append(SINGLE_AGENT_ID)
            if written or not marker.exists():
                marker.parent.mkdir(parents=True, exist_ok=True)
                atomic_write_text(
                    marker,
                    json.dumps(sorted(offered | set(SEED_FILES)), indent=1),
                )
        except (OSError, ValueError):
            return written
        return written


#: The SYSTEM member ids, newest spelling first. The card has been renamed
#: twice — `architect-master` → `architect` (v36) → `a01` (v37) — and a
#: project seeded before either rename still has the old id on disk, with
#: conv sidecars pointing at it. ALL spellings therefore have to resolve,
#: everywhere, including the remote-control gate, where getting it wrong
#: means either locking the operator out of their own master chat or
#: widening an auth check.
#:
#: Ordered: the canonical id first, so `resolve_system_member` prefers it
#: on a roster that somehow has two.
ARCHITECT_IDS = ("a01", "architect", "architect-master")

#: BT-19 — how a member takes briefs. `per-brief`: each brief opens its own
#: session, so several run in parallel. `single`: one session holds every
#: brief and decides what collapses into one piece of work (HD-12) — right
#: for the members that touch the shared git tree or a deploy target.
SESSION_MODES = ("per-brief", "single")
SINGLE_SESSION_DEFAULT_IDS = ("git-manager", "deployer")


def member_sessions_mode(member: str, fm: Dict[str, Any]) -> str:
    raw = str((fm or {}).get("sessions") or "").strip().lower()
    if raw in SESSION_MODES:
        return raw
    return "single" if member in SINGLE_SESSION_DEFAULT_IDS else "per-brief"


ORCHESTRATOR_IDS = ("orchestrator", "roadmap-orchestrator")


def resolve_system_member(store: Any, candidates: Tuple[str, ...]) -> str:
    """The id of the system member that actually EXISTS on this roster.

    Returns "" when the operator has deleted it — which is allowed, and
    callers must handle: a project with no Architect card is a project
    where the master chat is simply unbound."""
    for mid in candidates:
        try:
            if store.exists(mid):
                return mid
        except Exception:  # noqa: BLE001
            continue
    return ""


def member_summary(body: str, limit: int = 160) -> str:
    """The first sentence of a card's prompt, past its heading. Cards open
    with a one-line mission on purpose — this is where it is read."""
    for para in str(body or "").strip().split("\n\n"):
        line = " ".join(para.split())
        if not line or line.startswith("#"):
            continue
        for stop in (". ", "; "):
            if stop in line:
                line = line.split(stop)[0] + "."
                break
        return (line[:limit] + "…") if len(line) > limit else line
    return ""


def is_architect_id(mid: str) -> bool:
    return str(mid or "").strip() in ARCHITECT_IDS


#: GA-1 — display order, by id, replacing the authored `pinned_order`.
#: The project's own agent leads, under whichever of its three historic
#: ids this roster carries; everything the operator added is alphabetical
#: after it, which is predictable without anyone maintaining a number.
_BASE_ORDER = (
    "a01",
    "architect",
    "architect-master",
    # BT-1 — the base team in the order of the usual chain.
    "developer",
    "git-manager",
    "deployer",
    "consultant",
    "orchestrator",
    "roadmap-orchestrator",
)


def _order_of(m: Dict[str, Any]) -> int:
    mid = str(m.get("id") or "")
    try:
        return _BASE_ORDER.index(mid)
    except ValueError:
        return len(_BASE_ORDER)


def _normalise_payload(payload: Dict[str, Any], *, today: str) -> Dict[str, Any]:
    """Coerce a create/update payload into minimal-schema frontmatter.

    GA-1 — the payload may still arrive in the old shape (an older cockpit,
    a duplicate of an unmigrated card, a hand-rolled curl). Legacy keys are
    accepted as INPUT and dropped from the result: `name` feeds `title`,
    everything else in `LEGACY_FIELDS` is discarded."""
    client = str(payload.get("client") or "claude-code").strip().lower()
    model = str(payload.get("model") or "").strip()
    if not model:
        # DM-CLI-05 follow-up (live smoke test, 2026-07-08) — "opus" is a
        # Claude-specific alias; defaulting an omitted model to it for a
        # non-claude-code member produces an invalid `-m opus` argv for
        # that client (confirmed live: Codex rejects it outright). Only
        # default to the strongest alias when the resolved driver does
        # NOT declare "" as its own "use default" catalog entry.
        allows_empty = "" in {m.get("id") for m in driver_for(client).models_catalog()}
        model = "" if allows_empty else STRONGEST_MODEL_ALIAS
    title = str(
        payload.get("title") or payload.get("name") or payload.get("id") or ""
    ).strip()
    ctx = payload.get("context")
    fm: Dict[str, Any] = {
        "id": str(payload.get("id") or "").strip(),
        "title": title,
        "client": client,
        "provider": str(payload.get("provider") or "anthropic").strip().lower(),
        "model": model,
        "effort": str(payload.get("effort") or "default").strip().lower(),
        "context": (
            [str(c).strip() for c in ctx if str(c or "").strip()]
            if isinstance(ctx, list)
            else []
        ),
        "exposure": str(payload.get("exposure") or "internal").strip().lower(),
        "created": str(payload.get("created") or today),
        "updated": today,
    }
    return fm


#: The project's own agent — the one session the rail opens with.
#:
#: GA-6 (v37) seeded it ALONE and let it `become` every other profile; BT-1
#: (v38) seeds it with the base team below and makes it the coordinator.
#: What GA-6 got right stays: the rail lists SESSIONS, not cards, so a team
#: of five still opens as one row — the Architect — and the others appear
#: only while they are doing something for it.
SINGLE_AGENT_ID = "a01"
SINGLE_AGENT_TITLE = "Architect Agent"

#: Seed ids that are no longer part of any team we ship (BT-1 took
#: developer, deployer and consultant off this list).
#: `migrate_to_single_agent` archives these and ONLY these: an id the
#: operator invented is not on the list, so their own members survive a
#: migration that is otherwise happy to empty the roster.
RETIRED_SEED_IDS = (
    "orchestrator",
    "roadmap-orchestrator",
    "tester",
    "api-developer",
    "ui-developer",
    "ui-reviewer",
    "commit-pr-reviewer",
    # NOT "seo": that card was never a seed — meshkore's operator created it
    # (2026-08-04) and listing it here deleted it in the v36 migration.
)

#: md5 of every Architect BODY this daemon has ever written, stripped.
#: The migration rewrites the body only when it matches one of these —
#: when it is still our prose. The moment the operator edits their card
#: it stops matching and the migration keeps its hands off it. That is
#: the whole contract: the frontmatter is the daemon's, the body is
#: theirs, and a migration that cannot tell the two apart is a migration
#: nobody should run unattended.
_SHIPPED_ARCHITECT_BODIES = frozenset(
    {
        "b959f2774550e23def6279a67819dfca",  # v29 "Architect" — the CEO card
        "e8aea9221315d64042e434f66632f5a8",  # pre-v29 "Architect Master"
        "d31d1ede10f0136cd4f36fc2d68f2ea1",  # v36 "Architect"
        "4b57391d65b30094be933c3f07eb671b",  # v37 "Architect Agent" (does it all)
    }
)


def body_is_shipped(body: str) -> bool:
    """Is this member body one the daemon wrote, byte for byte?"""
    import hashlib

    digest = hashlib.md5(str(body or "").strip().encode("utf-8")).hexdigest()
    return digest in _SHIPPED_ARCHITECT_BODIES


#: BT-3 (base-team, v38) — the Architect coordinates. v37's card told it
#: to be the whole team and `become` each profile in turn; on a real
#: project (mf27) that is one thread carrying the developer's diff, the
#: commit rules and the deploy runbook at once. Now each teammate carries
#: its own profile and slice, and the Architect keeps the plan.
A01_BODY = """# Architect Agent

You coordinate this project: you hold the plan, hand each piece of work to
the teammate whose profile fits it, and chain the next step from their
report.

## Where things are

- Plan: initiatives in `.meshkore/roadmap/initiatives/`, tasks in
  `.meshkore/modules/<module>/tasks/`. Anchor every turn to an
  `(initiative, task)` pair; create the pair when none fits.
- Knowledge: the context tree in `.meshkore/context/`; runbooks in
  `.meshkore/workflows/INDEX.md`.

## How you work

- **Delegate, don't absorb.** For each step write a short brief (what,
  acceptance, where the code is), `delegate` it to the member from
  `## Your team`, and end your turn — the daemon wakes you with the report.
  Each teammate loads its own profile and only its slice of the context;
  your thread stays about the plan.
- The usual chain is `developer` (build + test) → `git-manager` (commit,
  PR or release) → `deployer` (ship + verify). Skip the steps a change does
  not need; give independent steps to different teammates at once.
- Do small things yourself — a one-line fix, a roadmap edit, an answer.
  Delegation is for work with its own shape.
- The team is whoever `## Your team` lists. If it lists nobody, do the work
  yourself.

## Talking to the operator

Say what happened in plain sentences: who did what, which commit, what is
live. Never paste a teammate's report object or any other machine payload.

## What is not yours to bend

Take a §20 snapshot before editing an existing file. Never paste a secret.
Write ONE daily entry in `.meshkore/log/<YYYY-MM-DD>.md` for the unit of
work you rooted, however many agents it took.
"""

DEVELOPER_BODY = """# Developer

You implement the code change you are briefed on and prove it works; you do
not commit.

## Your context

Pinned for you: architecture, stack, constraints, acceptance criteria and
glossary. The module's docs and tasks are in `.meshkore/modules/<module>/`.
Everything else is in the knowledge map — fetch a node only when the task
needs it.

## How you work

- Read the code before changing it; make the smallest correct change and
  match the surrounding style.
- Take a §20 snapshot before editing an existing file.
- Build and run the tests the change touches. Report failures as they are.
- Leave the change in the working tree. Commits are `git-manager`'s job.

## Team

You report to whoever briefed you (usually `a01`). Your report names the
files you touched, the branch, the tests you ran and what remains, so the
Architect can hand it straight to `git-manager`.
"""

GIT_MANAGER_BODY = """# Git Manager

You own the repository history: commits, branches, pull requests and
releases, made the way this project wants them.

## Your context

Pinned for you: constraints. The commit rules are in
`.meshkore/docs/conventions/closure-protocol.md`; release runbooks in
`.meshkore/workflows/INDEX.md`. You do not need the product, the data model
or the roadmap.

## How you work

- The brief gives you the files, the branch, what changed and the task id.
  Check that `git status` and `git diff` match it, and commit with explicit
  paths — never sweep in files you were not given.
- One commit per concern. Subject: imperative, at most 72 characters, with
  the task id. Body: why. Then the standard trailers (`Agent:`, `Model:`,
  `MeshKore:`, and `Parent:` when delegated). Never `Co-Authored-By`, never
  `--no-verify`: a failing hook goes back to whoever wrote the code.
- Branches, pull requests, tags and pushes follow the project's workflow or
  the brief. When neither says, commit to the current branch and do not push.

## Team

You report to whoever briefed you, with the commit SHAs (and the PR URL when
you opened one). You never change code to make a check pass.
"""

DEPLOYER_BODY = """# Deployer

You take committed, verified work to its target and prove it is live.

## Your context

Pinned for you: constraints. The deploy runbooks are in
`.meshkore/workflows/INDEX.md`; targets and credential handles are in the
context tree — fetch its deploy or infrastructure node when the map has one.
You do not need the data model, the stack detail or the roadmap.

## How you work

- Deploy only committed work. If the change is still uncommitted, send it
  back for `git-manager`.
- Follow the matching workflow step by step; its order is not optional.
- Verify on the deployed target, never on localhost, and say what you
  checked.
- Use credential handles; never print a secret.

## Team

You report to whoever briefed you: target, version or URL, the verification
result and how to roll back.
"""

CONSULTANT_BODY = """# Consultant

You answer questions about this project for agents outside it. They reach
you from other projects on this machine, or from anywhere through the public
`/team/consultant/ask` gateway.

## Your context

Pinned for you: overview, product, architecture and glossary. For anything
else, open the doc or the source before you answer.

## How you work

- Check every fact in the repo before stating it, and cite the file path.
- If it is not implemented, not documented or you cannot verify it, say so.
  Never invent.
- Read-only: you never edit, commit or deploy. Never reveal a secret or
  anything under `.meshkore/credentials/`.

## Team

You answer the caller directly and do not delegate.
"""

SEED_FILES: Dict[str, str] = {}


def _seed(
    mid: str,
    title: str,
    client: str,
    model: str,
    context,
    body: str,
    exposure: str = "internal",
) -> None:
    fm = {
        "id": mid,
        "title": title,
        "client": client,
        "provider": "anthropic",
        "model": model,
        "effort": "default",
        "context": list(context),
        "exposure": exposure,
        "created": "2026-09-28",
        "updated": "2026-09-28",
    }
    if mid in SINGLE_SESSION_DEFAULT_IDS:
        fm["sessions"] = "single"
    SEED_FILES[mid] = serialise_member(fm, body)


#: BT-1 (base-team, v38) — the team a project is born with. Five, not ten
#: (v29) and not one (v37): the Architect that coordinates, and the four
#: shapes of work it hands out on every real project.
#:
#: `context:` is each card's slice — the knowledge its turns get in full.
#: Keys are resolved against the project's tree by node id or by file
#: (`context/<key>.md`), so the same card works in a project with a curated
#: `_index.yaml` and in one with only the plain context files. The
#: Architect's `[]` means "the project's default set": it needs the whole
#: picture, the others explicitly do not.
BASE_TEAM = ("a01", "developer", "git-manager", "deployer", "consultant")

_seed(SINGLE_AGENT_ID, SINGLE_AGENT_TITLE, "claude-code", "opus", [], A01_BODY)
_seed(
    "developer",
    "Developer",
    "claude-code",
    "opus",
    ["architecture", "stack", "constraints", "criteria", "glossary"],
    DEVELOPER_BODY,
)
_seed(
    "git-manager",
    "Git Manager",
    "claude-code",
    "sonnet",
    ["constraints"],
    GIT_MANAGER_BODY,
)
_seed("deployer", "Deployer", "claude-code", "sonnet", ["constraints"], DEPLOYER_BODY)
_seed(
    "consultant",
    "Consultant",
    "claude-code",
    "opus",
    ["overview", "product", "architecture", "glossary"],
    CONSULTANT_BODY,
    exposure="external",
)


# ── inlined from daemon/teamext.py (DM3+ bundle) ─────────────────────────
"""teamext.py — Team External Gateway (initiative `team-external-gateway`).

TEG-1/TEG-2/TEG-4. Lets software OUTSIDE the cockpit consume a team member
as a service. A member whose frontmatter says `exposure: external` gets:

- a per-member NON-EXPIRING bearer token (`TeamTokenStore`) stored at
  `.meshkore/credentials/team-tokens.yaml` — credentials/ is §2.2
  deny-listed, so the secret never travels with the repo. No TTL, no
  scheduled rotation: lifecycle is operator-driven (rotate / revoke).
- an async ask/poll HTTP surface (`TeamExtMixin`):
    POST /team/<id>/ask            {text, session?, context_docs?} → 202
    GET  /team/requests/<rid>      → {status, result_text?, error?, …}
  Both gated by the MEMBER token (NOT the portal token); the member token
  authorizes NOTHING else. The ask is a thin façade over the existing
  chat_dispatch(member=<id>) path, so external convs are ordinary
  instances: `ext-<member>-<session|stamp>` slugs in the chat rail, init
  prompt on turn 1, member model/effort, singleton rules — all for free.
- an A2A Public Card (TEG-4, `build_member_card` — PURE on purpose:
  Phase 2 `exposure: mesh` republishes the same card to the hub, only
  WHERE it's published changes):
    GET /team/<id>/.well-known/agent.json   (no auth; loopback = perimeter)

The requests index lives at `.meshkore/.runtime/team-requests.json`
(gitignored runtime state); entries are GC'd after ~24 h. Completion is
observed by a small watcher thread per request that polls the live
ChatSessions + the conv's timeline for the turn's `chat.assistant.final`,
then broadcasts `team.request.done|error {member, request_id, ts}`.
"""


import hmac
import os
import re
import secrets
import threading
import time
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional, Tuple


# Per-member concurrent-ask cap (TEG-2 guard-rail). Loopback binding is the
# perimeter; no rate limiting beyond this in v1. Config knob comes later.
# Raised 2 -> 6 (2026-07-08, operator): a single local operator legitimately
# fires off several ask/poll probes in quick succession while debugging —
# 2 was tight enough that ONE orphaned request (see _teamext_reap_stale)
# was enough to lock the member out entirely.
EXT_ASK_CONCURRENT_CAP = 6
# Requests older than this are GC'd from the runtime index.
EXT_REQUEST_TTL_HOURS = 24
# Watcher poll cadence + overall turn budget. Agent turns take 30 s – minutes;
# the chat runner owns the real limits — this is only the observer's ceiling.
_WATCH_POLL_SECS = 2.0
_WATCH_MAX_SECS = 60 * 60
# Grace: how long a conv may sit idle (no live runner) with no final on the
# timeline before the watcher declares the request errored (spawn died, turn
# cancelled, …).
_IDLE_GRACE_SECS = 20.0
# DAH1 — the same grace, but for a request whose OWN turn hasn't started yet
# (it was queued behind one that was already running). The hand-off from the
# previous turn's exit to our spawn goes through the chat queue's flush, which
# is prompt but not instantaneous; 20 s was tight enough to error a healthy ask.
_QUEUE_GRACE_SECS = 120.0

_SESSION_SAFE_RE = re.compile(r"[^a-z0-9-]+")


class TeamTokenStore:
    """`.meshkore/credentials/team-tokens.yaml` — `{<member-id>: <token>}`.

    SECRETS live here and ONLY here (never in `.meshkore/team/`). Tokens do
    NOT expire — no TTL anywhere; mint/rotate/revoke are the only writes.
    File is chmod 600 and sits in the §2.2 deny-listed credentials/ dir.
    Cheap to construct per call; every write is atomic (tmp+rename)."""

    FILENAME = "team-tokens.yaml"

    def __init__(self, paths: Any) -> None:
        self.path = paths.credentials / self.FILENAME

    def _load(self) -> Dict[str, str]:
        try:
            if not self.path.is_file():
                return {}
            data = parse_simple_yaml(self.path.read_text(encoding="utf-8"))
        except OSError:
            return {}
        return {
            str(k): str(v)
            for k, v in (data or {}).items()
            if isinstance(v, (str, int, float)) and str(v).strip()
        }

    def _save(self, data: Dict[str, str]) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        lines = ["# MeshKore team-member bearer tokens (TEG-1). SECRET — never commit."]
        for mid in sorted(data):
            lines.append(f"{mid}: {data[mid]}")
        atomic_write_text(self.path, "\n".join(lines) + "\n", fsync=True)
        try:
            os.chmod(self.path, 0o600)
        except OSError:
            pass

    def get(self, mid: str) -> Optional[str]:
        return self._load().get(mid)

    def mint(self, mid: str) -> str:
        """Mint a FRESH token for `mid` (rotate semantics: any previous
        value dies with this write). 32 urlsafe random bytes (43 chars)."""
        token = secrets.token_urlsafe(32)
        data = self._load()
        data[mid] = token
        self._save(data)
        return token

    def ensure(self, mid: str) -> str:
        """Return the existing token, minting one only when absent
        (seed-time idempotency: re-boots never rotate silently)."""
        existing = self.get(mid)
        return existing if existing else self.mint(mid)

    def delete(self, mid: str) -> bool:
        data = self._load()
        if mid not in data:
            return False
        del data[mid]
        self._save(data)
        return True

    def matches(self, mid: str, presented: str) -> bool:
        """Constant-time comparison of a presented bearer against the
        member's stored token. False when the member has no token."""
        stored = self.get(mid)
        if not stored or not presented:
            return False
        return hmac.compare_digest(stored, presented)

    def ensure_for_external(self, team_store: Any) -> int:
        """Mint tokens for every `exposure: external` member that has none
        (seed-time + boot repair). Never rotates an existing token; never
        touches internal members. Returns the count minted."""
        minted = 0
        try:
            members = team_store.team_list()
        except Exception:
            return 0
        for fm in members:
            mid = str(fm.get("id") or "").strip()
            if not mid:
                continue
            if str(fm.get("exposure") or "internal").strip().lower() != "external":
                continue
            if self.get(mid) is None:
                self.mint(mid)
                minted += 1
        return minted


# ── TEG-4: A2A Public Card (pure builder) ───────────────────────────────


def _first_paragraph(body: str) -> str:
    """First prose paragraph of the init prompt: skip markdown headings and
    blank lines, collect until the next blank line, join into one string."""
    para: List[str] = []
    for raw in (body or "").splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            if para:
                break
            continue
        para.append(line)
    return " ".join(para)


def build_member_card(
    fm: Dict[str, Any],
    body: str,
    *,
    base_url: str,
    project_id: str,
) -> Dict[str, Any]:
    """A2A Public Card for one EXPOSED member (TEG-4). PURE — no I/O, no
    daemon state — so Phase 2 (`exposure: mesh`) can republish the exact
    same card to hub.meshkore.com by only changing where it's sent.

    `url` is the ask endpoint; the required headers + the poll contract are
    documented in the skill description, `metadata.required_headers` and the
    example, so a stranger A2A client can self-configure from this one URL."""
    mid = str(fm.get("id") or "")
    name = str(fm.get("name") or mid)
    ask_url = f"{base_url}/team/{mid}/ask"
    poll_url = f"{base_url}/team/requests/{{request_id}}"
    example = (
        f"curl -sk -X POST {ask_url} "
        f"-H 'Authorization: Bearer <member-token>' "
        f"-H 'X-MeshKore-Project: {project_id}' "
        f"-H 'content-type: application/json' "
        '-d \'{"text": "What is this project and what does it do?"}\''
    )
    return {
        "protocolVersion": "0.3.0",
        "name": name,
        "description": _first_paragraph(body),
        "url": ask_url,
        "preferredTransport": "HTTP+JSON",
        "version": "1.0.0",
        "capabilities": {"streaming": False, "pushNotifications": False},
        "defaultInputModes": ["text/plain"],
        "defaultOutputModes": ["text/plain"],
        "securitySchemes": {
            "bearer": {
                "type": "http",
                "scheme": "bearer",
                "description": (
                    "Per-member token issued by the cluster operator "
                    "(Team UI / GET /team/<id> with the portal token)."
                ),
            }
        },
        "security": [{"bearer": []}],
        "skills": [
            {
                "id": "ask",
                "name": f"Ask {name}",
                "description": (
                    f"Async ask/poll. POST {ask_url} with headers "
                    f"'Authorization: Bearer <member-token>' and "
                    f"'X-MeshKore-Project: {project_id}', body "
                    "{text, session?, context_docs?} -> 202 {request_id, conv}. "
                    f"Poll GET {poll_url} (same bearer + project header) until "
                    "status is 'done' (read result_text) or 'error'. Passing the "
                    "same `session` keeps one conversation (the member remembers "
                    "the thread)."
                ),
                "tags": ["ask", "consulting", "meshkore-team"],
                "examples": [example],
                "inputModes": ["text/plain"],
                "outputModes": ["text/plain"],
            }
        ],
        "metadata": {
            "id": mid,
            "kind": fm.get("kind"),
            "model": fm.get("model"),
            "exposure": "external",
            "project": project_id,
            "required_headers": {
                "Authorization": "Bearer <member-token>",
                "X-MeshKore-Project": project_id,
            },
            "poll_url": poll_url,
        },
    }


# ── TEG-2: ask/poll surface ─────────────────────────────────────────────


class TeamExtMixin:
    """External ask/poll + token lifecycle + A2A card HTTP handlers.
    Inherited by the Daemon (like TeamMixin) so self.* resolves per-project
    via the DC-4 property accessors (team_store, chat_sessions, paths, …)."""

    # One lock guards every requests-index read-modify-write (all projects;
    # the file op inside is per-project and cheap).
    _teamext_lock = threading.Lock()

    # ── requests index (runtime, not committed) ────────────────────────
    def _teamext_requests_path(self) -> Any:
        return self.paths.runtime / "team-requests.json"

    def _teamext_load(self) -> Dict[str, Dict[str, Any]]:
        p = self._teamext_requests_path()
        try:
            if not p.is_file():
                return {}
            import json as _json

            data = _json.loads(p.read_text(encoding="utf-8") or "{}") or {}
            return data if isinstance(data, dict) else {}
        except Exception:
            return {}

    def _teamext_save(self, data: Dict[str, Dict[str, Any]]) -> None:
        p = self._teamext_requests_path()
        p.parent.mkdir(parents=True, exist_ok=True)
        atomic_write_json(p, data, sort_keys=True)

    @staticmethod
    def _teamext_gc(data: Dict[str, Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:
        """Drop entries older than EXT_REQUEST_TTL_HOURS (ISO ts compare)."""
        cutoff = (
            datetime.now(timezone.utc) - timedelta(hours=EXT_REQUEST_TTL_HOURS)
        ).strftime("%Y-%m-%dT%H:%M:%S")
        return {
            rid: e
            for rid, e in data.items()
            if str((e or {}).get("started_at") or "") >= cutoff
        }

    def _teamext_reap_stale(
        self, data: Dict[str, Dict[str, Any]]
    ) -> Dict[str, Dict[str, Any]]:
        """Self-heal requests orphaned by a daemon restart mid-turn.

        `_teamext_watch` is a daemon thread with no persisted registry of
        its own — if the PROCESS dies (crash, `/shutdown`, a manual
        restart between different ports) while a watch is in flight, the
        thread dies with it and nothing will ever call `_teamext_update`
        to mark the request done/error. The entry is then indistinguishable
        from a genuinely live request by data shape alone, and sits
        `running`/`queued` forever — occupying an `EXT_ASK_CONCURRENT_CAP`
        slot until the 24h GC eventually erases it outright (2026-07-08
        incident: a daemon port-restart orphaned one, which then silently
        ate a cap slot for hours).

        Age is the tell: no watcher legitimately survives past
        `_WATCH_MAX_SECS` — its own hard-timeout branch would have fired
        and marked it `error` first. So anything `queued`/`running` older
        than that ceiling belongs to a process that no longer exists;
        flip it to `error` here so it (a) frees the cap slot immediately
        and (b) a client polling it sees a terminal status instead of
        hanging indefinitely."""
        cutoff = (
            datetime.now(timezone.utc) - timedelta(seconds=_WATCH_MAX_SECS)
        ).strftime("%Y-%m-%dT%H:%M:%S")
        for rid, e in data.items():
            if e.get("status") not in ("queued", "running"):
                continue
            if str(e.get("started_at") or "") >= cutoff:
                continue
            e["status"] = "error"
            e["error"] = (
                "orphaned by a daemon restart mid-turn (no watcher survived to finish it)"
            )
            e["finished_at"] = _iso_now()
            try:
                self._teamext_broadcast(
                    "team.request.error", str(e.get("member") or ""), rid
                )
            except Exception:
                pass
        return data

    def _teamext_update(self, rid: str, **fields: Any) -> Optional[Dict[str, Any]]:
        with self._teamext_lock:
            data = self._teamext_load()
            entry = data.get(rid)
            if entry is None:
                return None
            entry.update(fields)
            self._teamext_save(data)
            return dict(entry)

    def _teamext_broadcast(self, event: str, member: str, rid: str) -> None:
        """team.request.created|done|error {member, request_id, ts} on the
        chat.* WS bus so the cockpit can surface external activity."""
        try:
            if getattr(self, "hub", None) is not None:
                self.hub.broadcast(
                    {
                        "type": event,
                        "member": member,
                        "request_id": rid,
                        "ts": _iso_now(),
                    }
                )
        except Exception as e:  # noqa: BLE001 — broadcast failure is non-fatal
            _log(f"teamext broadcast {event} failed: {e}")

    # ── CPL-1: resolve a singleton's bound conv ─────────────────────────
    def _member_bound_conv(self, mid: str) -> Tuple[Optional[str], bool]:
        """Return (conv, archived) for the conv this member is bound to, or
        (None, False) when none exists. A NON-archived binding wins; an
        archived one is returned only when there is no live binding (the
        caller then unarchives it — the singleton's history IS the value).
        Used by the singleton ask path so talking to a singleton always
        lands in ITS one conversation."""
        try:
            meta = self._conv_meta_load()
        except Exception:
            return None, False
        archived_conv: Optional[str] = None
        for conv, entry in (meta or {}).items():
            if not isinstance(entry, dict):
                continue
            if str(entry.get("member") or "").strip() != mid:
                continue
            try:
                is_arch = self.chat_archive.is_archived(conv)
            except Exception:
                is_arch = False
            if not is_arch:
                return conv, False
            archived_conv = conv
        if archived_conv is not None:
            return archived_conv, True
        return None, False

    # ── POST /team/<id>/ask ─────────────────────────────────────────────
    def team_ask_http(
        self,
        mid: str,
        *,
        bearer: Optional[str],
        body: Dict[str, Any],
        remote: bool = False,
    ) -> Tuple[int, Dict[str, Any]]:
        """Member-token gated (NOT the portal token). Error order per TEG-2:
        401 bad/missing token · 403 member internal · 404 unknown member ·
        429 over the per-member concurrent cap.

        CPL-2 (master-copilot): when `remote` is set the caller presented the
        machine remote-control token (the operator's hand). That path is
        MASTER-ONLY — asks to any member other than the Architect → 403 —
        and it BYPASSES the exposure check + the per-member token match (the
        remote token IS the operator; `exposure: external` + member tokens stay
        the third-party TEG surface, untouched)."""
        if not bearer:
            return 401, {
                "error": "unauthorized",
                "hint": "Authorization: Bearer <member-token> required",
            }
        # GA-1 — `is_architect_id` accepts BOTH spellings of the Architect
        # (`architect` and the pre-rename `architect-master`) and nothing
        # else. Kept as an explicit allow-list rather than "the member the
        # roster calls the architect": this is an auth gate, and resolving
        # it through mutable roster state would let a renamed card widen
        # what the remote token reaches.
        if remote and not is_architect_id(mid):
            # The remote token authorizes ONLY the operator's master, per
            # project. Any other member id is the TEG member-token surface.
            return 403, {
                "error": "remote_token_master_only",
                "member": mid,
                "hint": "the remote-control token can only ask the architect; "
                "use a member token for other members",
            }
        try:
            member = self.team_store.team_get(mid)
        except TeamError:
            return 404, {"error": f"unknown team member {mid!r}", "member": mid}
        fm = member.get("frontmatter") or {}
        if not remote:
            exposure = str(fm.get("exposure") or "internal").strip().lower()
            if exposure != "external":
                # Revoke semantics: PATCH {exposure: internal} deleted the token,
                # so any in-flight caller lands here — 403, access is gone.
                return 403, {
                    "error": "member_not_exposed",
                    "member": mid,
                    "hint": "this member has exposure: internal — ask the operator to expose it",
                }
            tokens = TeamTokenStore(self.paths)
            if not tokens.matches(mid, bearer):
                return 401, {"error": "unauthorized", "member": mid}
        if not isinstance(body, dict):
            return 400, {"error": "JSON object body required"}
        text = str(body.get("text") or "").strip()
        if not text:
            return 400, {"error": "text required"}

        # Per-member concurrent cap (queued|running requests).
        #
        # DAH6 — the slot is RESERVED here, inside the same lock that counts
        # it. It used to be check-then-release-then-insert: two asks arriving
        # together at `active == cap - 1` both read cap-1, both passed, and
        # both inserted, so the member ran cap+1. Harmless at cap 6 with one
        # local operator; not harmless once the external gateway is what it
        # exists to be — an endpoint third parties drive, where concurrent
        # asks are the normal case and the cap is the only rate limit there
        # is (loopback is the perimeter, TEG-2 ships no other throttle).
        #
        # The reservation is a real entry, so the count that follows it sees
        # it. It is invisible to everyone else: `rid` is only disclosed in the
        # 202 below, so nothing can poll a request that has not been created
        # yet, and `_teamext_reap_stale` would only ever flip an abandoned
        # reservation to `error` — which is the correct outcome anyway.
        rid = "req-" + secrets.token_urlsafe(9)
        reserved_at = _iso_now()
        with self._teamext_lock:
            data = self._teamext_reap_stale(self._teamext_gc(self._teamext_load()))
            active = sum(
                1
                for e in data.values()
                if e.get("member") == mid and e.get("status") in ("queued", "running")
            )
            if active >= EXT_ASK_CONCURRENT_CAP:
                self._teamext_save(data)
                return 429, {
                    "error": "too_many_requests",
                    "member": mid,
                    "cap": EXT_ASK_CONCURRENT_CAP,
                    "hint": "poll your in-flight requests before asking again",
                }
            data[rid] = {
                "request_id": rid,
                "member": mid,
                "conv": "",
                "status": "queued",
                "started_at": reserved_at,
                "stream_id": None,
            }
            self._teamext_save(data)

        # Conv slug resolution.
        # CPL-1 — a `kind: singleton` member has exactly ONE conversation:
        # talking to it means talking to THAT thread. Resolve its bound conv
        # (live → use it; archived → unarchive + use it; none → create + bind,
        # letting the member's init prompt inject on turn 1). `session` is
        # meaningless for a singleton (one thread by definition) and ignored;
        # the 202 returns the real conv. Serialization is the existing dispatch
        # queue: a second ask while a turn runs is queued into the same conv
        # (chat_dispatch returns queued=True), never a duplicate conv.
        # Profiles keep today's behaviour EXACTLY.
        kind = str(fm.get("kind") or "").strip().lower()
        if kind == "singleton":
            conv, archived = self._member_bound_conv(mid)
            if conv is None:
                # A stable single-thread slug for this singleton; conv_meta
                # binds `member` on turn 1 (dispatch_body below carries it).
                conv = mid
            elif archived:
                self.chat_archive.unarchive(conv)
                try:
                    if getattr(self, "hub", None) is not None:
                        self.hub.broadcast(
                            {"type": "conv.unarchived", "conv": conv, "ts": _iso_now()}
                        )
                except Exception:  # noqa: BLE001 — broadcast failure is non-fatal
                    pass
        else:
            # Profile: session → continuity (same session = same conv = the
            # member remembers the thread); no session → one-shot stamp conv.
            session = str(body.get("session") or "").strip().lower()
            session = _SESSION_SAFE_RE.sub("-", session).strip("-")[:48]
            if session:
                conv = f"ext-{mid}-{session}"
            else:
                stamp = (
                    _iso_now()[:19].replace(":", "").replace("-", "").replace("T", "-")
                )
                conv = f"ext-{mid}-{stamp}"

        dispatch_body: Dict[str, Any] = {
            "text": text,
            "conv": conv,
            "member": mid,
            "author": f"{'remote' if remote else 'ext'}:{mid}",
        }
        if isinstance(body.get("context_docs"), list):
            dispatch_body["context_docs"] = body["context_docs"]

        started_at = _iso_now()
        # DAH1 — remember which turn (if any) already owns this conv BEFORE we
        # dispatch. If our ask gets queued behind it, that turn's final must
        # never be mistaken for our answer (see _teamext_latest_final).
        exclude_stream = self._teamext_live_stream(conv)
        # Reuse the EXISTING dispatch path — init prompt on turn 1, member
        # model/effort, rail visibility, singleton rules all come for free.
        code, resp = self.chat_dispatch(dispatch_body)
        if code != 202:
            # DAH6 — hand the reserved slot back; a failed dispatch must not
            # cost the member a slot until the 24 h TTL reaps it.
            with self._teamext_lock:
                data = self._teamext_load()
                data.pop(rid, None)
                self._teamext_save(data)
            return code, resp

        queued = bool(resp.get("queued"))
        status = "queued" if queued else "running"
        # Our own turn's identity — present only when the dispatch spawned
        # immediately. When queued we carry `exclude_stream` instead and the
        # watcher latches the real one as soon as our turn goes live.
        own_stream = None if queued else (resp.get("stream_id") or None)
        entry = {
            "request_id": rid,
            "member": mid,
            "conv": conv,
            "status": status,
            "started_at": started_at,
            "stream_id": own_stream,
        }
        with self._teamext_lock:
            data = self._teamext_gc(self._teamext_load())
            data[rid] = entry  # DAH6 — fills in the reservation made above
            self._teamext_save(data)
        self._teamext_broadcast("team.request.created", mid, rid)
        _debug_emit(
            "team.ask",
            msg=f"external ask → {mid} (conv={conv}, request={rid})",
            conv=conv,
            data={"member": mid, "request_id": rid, "status": status},
        )
        # Watcher observes the turn to completion (final → done, else error).
        # Auto-archive ONLY profile instances: they're one-shot/session API
        # artifacts, not operator-facing sessions, and must never clutter
        # the chat rail once their turn ends. Singletons (architect-master,
        # roadmap-orchestrator) keep their ONE conversation visible — that
        # IS the operator's real working thread with that member.
        auto_archive = kind != "singleton"
        project_id = self._current_project_id()
        threading.Thread(
            target=self._teamext_watch,
            args=(project_id, rid, mid, conv, started_at, auto_archive),
            kwargs={"stream_id": own_stream, "exclude_stream": exclude_stream},
            name=f"teamext-{rid}",
            daemon=True,
        ).start()
        return 202, {"request_id": rid, "conv": conv}

    # ── GET /team/requests/<rid> ────────────────────────────────────────
    def team_request_get_http(
        self, rid: str, *, bearer: Optional[str], remote: bool = False
    ) -> Tuple[int, Dict[str, Any]]:
        """Same bearer auth as the ask; a member token can ONLY read the
        requests created for its own member (token identity = member).

        CPL-2: the machine remote-control token additionally reads any
        `architect-master` request (the operator polls the asks it made)."""
        if not bearer:
            return 401, {"error": "unauthorized"}
        with self._teamext_lock:
            data = self._teamext_reap_stale(self._teamext_load())
            self._teamext_save(data)
            entry = data.get(rid)
        if entry is None:
            return 404, {"error": f"unknown request {rid!r}"}
        mid = str(entry.get("member") or "")
        tokens = TeamTokenStore(self.paths)
        authorized = tokens.matches(mid, bearer) or (remote and is_architect_id(mid))
        if not authorized:
            # Wrong member's token, revoked member, or a stale token after a
            # rotate — in every case the presented bearer no longer names the
            # member this request belongs to.
            return 401, {"error": "unauthorized"}
        out = {
            "request_id": rid,
            "status": entry.get("status"),
            "conv": entry.get("conv"),
            "started_at": entry.get("started_at"),
        }
        if entry.get("finished_at"):
            out["finished_at"] = entry["finished_at"]
        if entry.get("status") == "done":
            out["result_text"] = entry.get("result_text") or ""
        if entry.get("status") == "error":
            out["error"] = entry.get("error") or "unknown error"
        return 200, out

    # ── POST /team/<id>/token/rotate (portal-token gated at the route) ──
    def team_token_rotate_http(self, mid: str) -> Tuple[int, Dict[str, Any]]:
        try:
            member = self.team_store.team_get(mid)
        except TeamError as e:
            return self._team_err(e)
        fm = member.get("frontmatter") or {}
        if str(fm.get("exposure") or "internal").strip().lower() != "external":
            return 409, {
                "error": "member is not external — nothing to rotate",
                "member": mid,
            }
        token = TeamTokenStore(self.paths).mint(mid)  # old token dies here
        self._team_broadcast("team.updated", mid)
        _debug_emit(
            "team.token.rotate",
            msg=f"token rotated for member {mid}",
            data={"member": mid},
        )
        return 200, {"id": mid, "token": token, "rotated_at": _iso_now()}

    # ── GET /team/<id>/.well-known/agent.json (no auth) ─────────────────
    def team_agent_card_http(self, mid: str) -> Tuple[int, Dict[str, Any]]:
        try:
            member = self.team_store.team_get(mid)
        except TeamError:
            return 404, {"error": f"unknown team member {mid!r}"}
        fm = member.get("frontmatter") or {}
        if str(fm.get("exposure") or "internal").strip().lower() != "external":
            # Internal members have no public card — indistinguishable from
            # absent on purpose (don't leak the roster shape).
            return 404, {"error": f"no public card for {mid!r}"}
        scheme = "https" if getattr(self, "tls_enabled", True) else "http"
        base_url = f"{scheme}://127.0.0.1:{getattr(self, 'port', 0)}"
        card = build_member_card(
            fm,
            member.get("body") or "",
            base_url=base_url,
            project_id=str(self.cluster.id),
        )
        return 200, card

    # ── watcher: observe the turn to completion ─────────────────────────
    def _teamext_live_stream(self, conv: str) -> Optional[str]:
        """stream_id of the turn running on `conv` right now, or None.
        Reads the same SRL2 snapshot the cockpit rehydrates from."""
        try:
            snap = self.chat_sessions.turn_snapshot(conv) or {}
            return (snap.get("current_turn") or {}).get("stream_id") or None
        except Exception:
            return None

    def _teamext_latest_final(
        self,
        conv: str,
        after_ts: str,
        *,
        stream_id: Optional[str] = None,
        exclude_stream: Optional[str] = None,
    ) -> Optional[str]:
        """Text of the `chat.assistant.final` that belongs to THIS request,
        or None. Timeline walk mirrors chatread.py.

        DAH1 (daemon-audit-hardening) — matching on `(conv, ts >= after_ts)`
        alone was wrong for the case the external gateway hits most: an ask
        that lands while another turn is already running on that conv (the
        normal shape for a `kind: singleton` like `architect-master`, which is
        exactly what the remote-control token talks to). `chat_dispatch`
        returns `queued: True`, the operator's in-flight turn finishes with a
        ts NEWER than our `started_at`, and the old predicate handed THAT
        turn's answer back to the external caller as if it were the reply to
        its own question.

        Every emitter of `chat.assistant.final` (runnerloop + both runnerspawn
        error paths) stamps `stream_id`, so the turn identity is already on the
        wire — we just never used it:

        - `stream_id` set  → accept ONLY that stream's final (exact identity).
        - `stream_id` None → the turn hasn't spawned yet (still queued); accept
          any final EXCEPT one belonging to `exclude_stream`, the turn that was
          already running when we asked. The watcher latches our real stream_id
          the moment our turn goes live, so this branch is a short-lived
          fallback, not the steady state.

        Events with NO `stream_id` (pre-py-1.13 timelines) stay eligible under
        the ts predicate — never regress an old cluster into a 1 h timeout."""
        best_ts, best_text = "", None
        try:
            if not self.paths.timeline_dir.exists():
                return None
            for f in _iter_timeline_files(self.paths):
                for ev in _read_timeline_file(f):
                    if ev.get("conv") != conv:
                        continue
                    if ev.get("type") != "chat.assistant.final":
                        continue
                    ev_stream = str(ev.get("stream_id") or "")
                    if stream_id:
                        if ev_stream and ev_stream != stream_id:
                            continue
                    elif exclude_stream and ev_stream == exclude_stream:
                        continue
                    ts = str(ev.get("ts") or "")
                    if ts >= after_ts and ts >= best_ts:
                        best_ts, best_text = ts, str(ev.get("text") or "")
        except Exception:
            return None
        return best_text

    def _teamext_archive_conv(self, conv: str) -> None:
        """Archive a one-shot/session profile-member conv once its turn
        ends, so it never lingers in the operator's chat rail (only
        History → Archived). Mirrors chatsvc.chat_archive_set's broadcast
        so the cockpit updates live without a manual refresh. Best-effort —
        never let an archive failure turn a successful ask into an error."""
        try:
            entry = self.chat_archive.archive(conv, by="teamext")
            if getattr(self, "hub", None) is not None:
                self.hub.broadcast(
                    {
                        "type": "conv.archived",
                        "conv": conv,
                        "archived_at": entry.get("archived_at"),
                        "by": entry.get("by"),
                        "ts": entry.get("archived_at"),
                    }
                )
        except Exception:  # noqa: BLE001 — archiving is cosmetic, never fatal
            pass

    def _teamext_watch(
        self,
        project_id: Optional[str],
        rid: str,
        mid: str,
        conv: str,
        after_ts: str,
        auto_archive: bool = False,
        stream_id: Optional[str] = None,
        exclude_stream: Optional[str] = None,
    ) -> None:
        """Background observer for one external request. Re-binds the
        originating project on THIS thread (FC-2 pattern — the request
        threadlocal died with the 202) so every self.* property resolves to
        the right ProjectContext. Terminal states: done (final found on the
        timeline) or error (turn ended finalless / observer budget spent).

        `auto_archive` (profile members only, see the call site): the conv
        is archived on either terminal state so it never appears in the
        chat rail's agents list — dispatch doesn't care about the archived
        flag, so a later ask on the same `session` still works (it just
        re-archives on completion).

        DAH1 — `stream_id` is OUR turn's identity (present when the dispatch
        spawned immediately) and `exclude_stream` is the turn that was already
        running when we asked (present when it got queued behind one). Exactly
        one of them is normally set. While queued we keep polling the live slot
        and LATCH our own stream_id the instant a turn other than
        `exclude_stream` goes live — from then on the match is exact, so a
        neighbouring turn's final can never be reported as our answer."""
        try:
            self._set_req_project(project_id)
        except Exception:
            pass
        deadline = time.time() + _WATCH_MAX_SECS
        idle_since: Optional[float] = None
        marked_running = False
        try:
            while time.time() < deadline and not self.stopping.is_set():
                live = False
                try:
                    live = self.chat_sessions.has(conv)
                except Exception:
                    pass
                if live and not stream_id:
                    # Still queued (or racing the spawn): latch our own turn as
                    # soon as a stream that ISN'T the one we queued behind goes
                    # live. After this the final match is by exact identity.
                    current = self._teamext_live_stream(conv)
                    if current and current != exclude_stream:
                        stream_id = current
                        exclude_stream = None
                if live:
                    idle_since = None
                    if not marked_running:
                        # Flip queued → running ONCE (don't rewrite the
                        # index every poll). None = entry GC'd; stop.
                        if self._teamext_update(rid, status="running") is None:
                            return
                        marked_running = True
                else:
                    final = self._teamext_latest_final(
                        conv,
                        after_ts,
                        stream_id=stream_id,
                        exclude_stream=exclude_stream,
                    )
                    if final is not None:
                        self._teamext_update(
                            rid,
                            status="done",
                            result_text=final,
                            finished_at=_iso_now(),
                        )
                        self._teamext_broadcast("team.request.done", mid, rid)
                        return
                    # No runner and no final (yet): allow a short grace for
                    # the timeline append / spawn hand-off, then declare error.
                    # DAH1 — a request still waiting for its OWN turn (queued
                    # behind another one, so `stream_id` hasn't latched yet)
                    # gets the longer queue grace: the gap between the previous
                    # turn's exit and our spawn is a queue-flush hand-off, not
                    # a dead runner, and 20 s was tight enough to error a
                    # perfectly healthy ask.
                    grace = _IDLE_GRACE_SECS if stream_id else _QUEUE_GRACE_SECS
                    if idle_since is None:
                        idle_since = time.time()
                    elif time.time() - idle_since > grace:
                        self._teamext_update(
                            rid,
                            status="error",
                            error="turn ended without an assistant final "
                            "(spawn failure, cancel, or crash)",
                            finished_at=_iso_now(),
                        )
                        self._teamext_broadcast("team.request.error", mid, rid)
                        return
                time.sleep(_WATCH_POLL_SECS)
            self._teamext_update(
                rid,
                status="error",
                error=f"request watcher timed out after {_WATCH_MAX_SECS}s",
                finished_at=_iso_now(),
            )
            self._teamext_broadcast("team.request.error", mid, rid)
        except Exception as e:  # noqa: BLE001 — watcher must never take the daemon down
            _log(f"teamext watcher {rid} failed: {e}")
        finally:
            # Single choke point for all three terminal paths (done, idle
            # error, timeout error) AND an unexpected exception above —
            # archive before clearing the project threadlocal so path
            # resolution still points at the right cluster.
            if auto_archive:
                self._teamext_archive_conv(conv)
            try:
                self._clear_req_project()
            except Exception:
                pass


# ── inlined from daemon/statebuild.py (DM3+ bundle) ─────────────────────────
"""statebuild.py — FS→state projection (build_state + ordering/reconcile/git helpers).

Extracted from state.py (daemon-architecture-v2 Phase 3d). Verbatim move;
imported back where used."""


import subprocess
from datetime import datetime
from pathlib import Path
from typing import Any, Dict, List, Optional



def build_state(paths: Paths, cluster: Cluster) -> Dict[str, Any]:
    """Walk the FS and produce a state.json equivalent — the same shape
    the architect's renderInitiativesPanel + renderTasksList expect."""
    tasks: List[Dict[str, Any]] = []
    docs: List[Dict[str, Any]] = []
    initiatives: List[Dict[str, Any]] = []
    by_module: Dict[str, List[str]] = {}
    stats = {
        "backlog": 0,
        "next": 0,
        "in_progress": 0,
        "active": 0,
        "blocked": 0,
        "done": 0,
        "cancelled": 0,  # RSV1 — canonical since py-1.35.3
        "total": 0,
    }

    # Tasks live at .meshkore/modules/<id>/tasks/*.md (+ archived under log/)
    if paths.modules_dir.exists():
        for mdir in paths.modules_dir.iterdir():
            if not mdir.is_dir():
                continue
            mid = mdir.name
            by_module.setdefault(mid, [])
            for tasks_dir in (mdir / "tasks", mdir / "log"):
                if not tasks_dir.exists():
                    continue
                for md in tasks_dir.rglob("*.md"):
                    if md.name.startswith("_"):
                        continue
                    try:
                        text = md.read_text(errors="replace")
                    except OSError:
                        continue
                    fm = parse_frontmatter(text)
                    if not fm.get("id"):
                        continue
                    t = {
                        "id": str(fm.get("id")),
                        "title": str(fm.get("title") or fm["id"]),
                        "status": normalize_status(fm.get("status")),
                        # DAH7b — keep the ORIGINAL literal alongside the
                        # normalised one. `normalize_status` is lossy by
                        # design (six values out), and the archive reconciler
                        # has to tell `cancelled` from `backlog`: the first is
                        # resolved, the second is pending work. py-1.35.1
                        # added `is_resolved_status` but fed it the ALREADY
                        # normalised value, so it could never see the
                        # difference and the fix did nothing in production —
                        # the unit tests passed because they called the
                        # reconciler with raw frontmatter, which is not how
                        # the build calls it. Additive field: a consumer that
                        # only knows `status` is unaffected.
                        "status_raw": str(fm.get("status") or "").strip().lower(),
                        "priority": str(fm.get("priority") or "medium"),
                        "owner": str(fm.get("owner") or "unknown"),
                        "category": str(fm.get("category") or mid),
                        "created": str(fm.get("created") or ""),
                        "updated": str(fm.get("updated") or ""),
                        "tags": fm.get("tags")
                        if isinstance(fm.get("tags"), list)
                        else [],
                        "depends_on": fm.get("depends_on")
                        if isinstance(fm.get("depends_on"), list)
                        else [],
                        "initiative": str(fm.get("initiative") or "") or None,
                        "path": str(md.relative_to(paths.root)),
                        # Standard v26 — resolution record pointers. The rich
                        # `## Resolution` body stays out of /state (fetched on
                        # demand); these let the cockpit paint the collapsed
                        # "ejecutado · fecha · agente" line without a body read.
                        "completed_at": str(fm.get("completed_at") or "") or None,
                        "resolved_by": str(fm.get("resolved_by") or "") or None,
                        "resolved_by_conv": str(fm.get("resolved_by_conv") or "")
                        or None,
                        "commit_shas": fm.get("commit_shas")
                        if isinstance(fm.get("commit_shas"), list)
                        else [],
                    }
                    tasks.append(t)
                    by_module[t["category"]] = by_module.get(t["category"], []) + [
                        t["id"]
                    ]
                    stats[t["status"]] = stats.get(t["status"], 0) + 1
                    stats["total"] += 1

    # Docs
    if paths.docs_dir.exists():
        for md in paths.docs_dir.rglob("*.md"):
            if md.name in ("INDEX.md", "README.md"):
                continue
            try:
                text = md.read_text(errors="replace")
            except OSError:
                continue
            fm = parse_frontmatter(text)
            if not fm:
                continue
            docs.append(
                {
                    "title": str(fm.get("title") or md.stem),
                    "category": str(fm.get("category") or ""),
                    "tags": fm.get("tags") if isinstance(fm.get("tags"), list) else [],
                    "updated": str(fm.get("updated") or ""),
                    "owner": str(fm.get("owner") or ""),
                    "status": str(fm.get("status") or "draft"),
                    "path": str(md.relative_to(paths.root)),
                }
            )

    # Initiatives
    if paths.initiatives.exists():
        for md in paths.initiatives.glob("*.md"):
            try:
                text = md.read_text(errors="replace")
            except OSError:
                continue
            fm = parse_frontmatter(text)
            if not fm.get("id"):
                continue
            child_ids = [
                t["id"] for t in tasks if (t.get("initiative") or "") == fm["id"]
            ]
            initiatives.append(
                {
                    "id": str(fm["id"]),
                    "title": str(fm.get("title") or fm["id"]),
                    # RSV1 — initiative status was published RAW while task
                    # status was normalised. The cockpit's InitiativeCard only
                    # tests done/backlog/next and treats anything else as
                    # ACTIVE, so 36 `draft`/`planned`/`ready` initiatives (and
                    # one `archived`) rendered as live work — three quarters of
                    # the active roadmap. Normalise here like tasks, and keep
                    # the literal in `status_raw` so nothing is lost and a
                    # future draft column has something to read.
                    "status": normalize_status(fm.get("status")),
                    "status_raw": str(fm.get("status") or "").strip().lower(),
                    "priority": str(fm.get("priority") or "medium"),
                    "oneliner": str(fm.get("oneliner") or ""),
                    "modules": fm.get("modules")
                    if isinstance(fm.get("modules"), list)
                    else [],
                    "target": str(fm.get("target") or ""),
                    "owner": str(fm.get("owner") or ""),
                    "created": str(fm.get("created") or ""),
                    "updated": str(fm.get("updated") or ""),
                    "child_task_ids": child_ids,
                    "task_total": len(child_ids),
                    "path": str(md.relative_to(paths.root)),
                    # py-1.10.15 — Roadmap ordering (initiative
                    # `roadmap-ordering-archive`). The operator curates
                    # order via a linked-list pointer in each .md
                    # frontmatter; absent/dangling pointers degrade to
                    # bucket-sort below. `completed_at` + `commit_sha`
                    # populate when the daemon auto-archives the
                    # initiative (D-RM-ARCHIVE-02).
                    "next": (str(fm.get("next")) if fm.get("next") else None),
                    "completed_at": str(fm.get("completed_at") or "") or None,
                    "commit_sha": str(fm.get("commit_sha") or "") or None,
                    # py-1.20.0 — roadmap wall ordering; the cockpit reads
                    # this to paint each wall in order. Optional → None.
                    "wall_order": (
                        int(fm["wall_order"])
                        if isinstance(fm.get("wall_order"), int)
                        and not isinstance(fm.get("wall_order"), bool)
                        else None
                    ),
                }
            )

    # py-1.10.15 — Auto-archive reconcile pass (D-RM-ARCHIVE-02).
    # MUST run before the linked-list sort so newly-archived items
    # land in the `done` bucket (the bottom of the active section).
    _reconcile_initiative_archive(initiatives, tasks, paths)

    # py-1.10.15 — Linked-list ordering (D-RM-LINKED-01). Walks the
    # operator-curated `next:` chain, then bucket-sorts by:
    #   0 = active/next with task_total > 0
    #   1 = active/next with task_total == 0 (empty-at-bottom)
    #   2 = backlog
    #   3 = done (archived view filters from here)
    initiatives = _order_initiatives(initiatives)

    # py-1.11.1 — `timeline.recent_events` removed from /state. The
    # cockpit lazy-loads per-conv history via GET /chat/conv/<id>/messages
    # when the operator focuses the conv; the boot snapshot
    # (/chat/snapshot) carries enough conv metadata to render the rail
    # immediately without replaying any events.
    return {
        "$schema": "https://api.meshkore.com/v1/standard.json",
        "cluster": {
            "id": cluster.id,
            "name": cluster.name,
            "type": cluster.type,
        },
        "modules": cluster.modules,
        "roadmap": {
            "tasks": tasks,
            "stats": stats,
        },
        "docs": docs,
        "initiatives": initiatives,
        "generated_at": _iso_now(),
        "generator": {"name": "meshcore-py", "version": DAEMON_VERSION},
    }


_ORDER_BUCKET_ACTIVE_WITH_TASKS = 0
_ORDER_BUCKET_ACTIVE_NO_TASKS = 1
_ORDER_BUCKET_BACKLOG = 2
_ORDER_BUCKET_DONE = 3


def _order_initiatives(initiatives: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Linked-list walk + bucket sort. Deterministic + stable."""
    if not initiatives:
        return initiatives
    by_id = {it["id"]: it for it in initiatives}
    edges: Dict[str, str] = {}
    for it in initiatives:
        nxt = it.get("next")
        if nxt and nxt in by_id and nxt != it["id"]:
            edges[it["id"]] = nxt

    pointed_to = set(edges.values())
    # Heads = initiatives no one points to. Stable order: by `updated` desc
    # then id asc, so the most recently-touched chain leads when there
    # are several disconnected lists.
    heads = sorted(
        [i for i in by_id.keys() if i not in pointed_to],
        key=lambda i: (-_sortable_ts(by_id[i].get("updated")), i),
    )

    visited: set[str] = set()
    walked: List[str] = []
    for h in heads:
        cur: Optional[str] = h
        while cur is not None and cur not in visited:
            visited.add(cur)
            walked.append(cur)
            cur = edges.get(cur)
    # Orphans (everything not visited — i.e. members of a pure cycle):
    # append in `updated` order so they don't randomly shuffle.
    orphans = sorted(
        [i for i in by_id.keys() if i not in visited],
        key=lambda i: (-_sortable_ts(by_id[i].get("updated")), i),
    )
    flat_ids = walked + orphans

    def bucket(it: Dict[str, Any]) -> int:
        status = normalize_status(it.get("status"))
        if status == "done":
            return _ORDER_BUCKET_DONE
        if status == "backlog":
            return _ORDER_BUCKET_BACKLOG
        # active / next / in_progress / blocked
        if int(it.get("task_total") or 0) > 0:
            return _ORDER_BUCKET_ACTIVE_WITH_TASKS
        return _ORDER_BUCKET_ACTIVE_NO_TASKS

    # Stable sort: Python's `sorted` preserves the linked-list order
    # within each bucket.
    ordered_items = sorted(
        [by_id[i] for i in flat_ids],
        key=bucket,
    )
    return ordered_items


def _sortable_ts(v: Any) -> float:
    """Best-effort ISO/YYYY-MM-DD → epoch seconds. 0 on parse failure
    so items without `updated` sort last (because we negate the key)."""
    s = str(v or "").strip()
    if not s:
        return 0.0
    try:
        # Strip trailing Z if present (Python 3.10 fromisoformat doesn't
        # accept it on older versions; 3.11+ does — be conservative).
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        return datetime.fromisoformat(s).timestamp()
    except (ValueError, TypeError):
        try:
            return datetime.strptime(s[:10], "%Y-%m-%d").timestamp()
        except (ValueError, TypeError):
            return 0.0


def _child_status(task: Dict[str, Any]) -> Any:
    """The status to JUDGE a child by: the raw frontmatter literal when the
    record carries it (DAH7b), else the normalised one. The fallback keeps
    callers that build records by hand — the tests, and any pre-py-1.35.2
    state.json still on disk — working unchanged."""
    return task.get("status_raw") or task.get("status")


def _reconcile_initiative_archive(
    initiatives: List[Dict[str, Any]],
    tasks: List[Dict[str, Any]],
    paths: "Paths",
) -> None:
    """Bidirectional reconcile between initiative status + child tasks.

    py-1.10.15 (forward): active → done when ALL tasks done.
    py-1.12.4 (BACKWARD): done → active when ANY task is not done.
      Closes the bug where the architect prematurely set
      `status: done` on a partial initiative (operator field report
      2026-05-31: Visual identity v2 archived with 5/7 done). The
      cockpit was showing the initiative as DONE in the archived
      view despite 2 tasks still pending. The architect's prompt
      already forbids this, but a server-side guard is the only
      reliable defense.

    For both directions: idempotent — the second pass sees the
    consistent state and skips.
    """
    # tasks_by_initiative reused so we don't iterate N×M times.
    children: Dict[str, List[Dict[str, Any]]] = {}
    for t in tasks:
        iid = t.get("initiative")
        if iid:
            children.setdefault(iid, []).append(t)

    head_sha: Optional[str] = None
    head_sha_attempted = False
    iso_now = _iso_now()

    for it in initiatives:
        status = normalize_status(it.get("status"))
        # RSV1 — `cancelled` joins `backlog` here. An initiative that was
        # abandoned is not a candidate for auto-archival: flipping it to
        # `done` would record work as delivered that never happened.
        if status in ("backlog", "cancelled"):
            continue
        kids = children.get(it["id"], [])
        if not kids:
            continue

        # DAH7 — "nothing left to do" is not the same as "every child says
        # done". A task closed as `cancelled` / `dropped` / `superseded` is
        # resolved: it will never become done, so counting it as pending pins
        # the initiative `active` forever (reproduced on
        # `daemon-audit-hardening`, whose DAH3 was cancelled after being
        # measured). The `any(... done)` guard keeps the other direction
        # honest: an initiative whose children were ALL abandoned was not
        # completed, and must not be auto-archived as if it had been.
        all_done = all(is_resolved_status(_child_status(k)) for k in kids) and any(
            normalize_status(k.get("status")) == "done" for k in kids
        )

        # ── Forward path: active/next/in_progress → done ────────────
        if status != "done" and all_done:
            if not head_sha_attempted:
                head_sha_attempted = True
                head_sha = _git_head_sha(paths.root)
            new_fields = {
                "status": "done",
                "completed_at": iso_now,
            }
            if head_sha:
                new_fields["commit_sha"] = head_sha
            try:
                fp = paths.root / it["path"]
                if _patch_frontmatter(fp, new_fields):
                    it["status"] = "done"
                    it["completed_at"] = iso_now
                    if head_sha:
                        it["commit_sha"] = head_sha
                    _log(
                        f"roadmap: auto-archived initiative {it['id']} "
                        f"({len(kids)} tasks done, commit={head_sha or 'none'})"
                    )
                    _debug_emit(
                        "init-archive",
                        msg=f"initiative {it['id']} auto-archived",
                        data={
                            "initiative_id": it["id"],
                            "tasks_done": len(kids),
                            "commit_sha": head_sha,
                            "completed_at": iso_now,
                        },
                    )
            except OSError as e:
                _log(f"roadmap: archive write failed for {it['id']}: {e}")
            continue

        # ── Backward path (py-1.12.4): done → active when partial ───
        if status == "done" and not all_done:
            pending = [
                k.get("id") for k in kids if not is_resolved_status(_child_status(k))
            ]
            new_fields = {"status": "active"}
            # Wipe the completion markers — they're lying.
            for stale in ("completed_at", "commit_sha"):
                if it.get(stale):
                    new_fields[stale] = None  # _patch_frontmatter removes nulls
            try:
                fp = paths.root / it["path"]
                if _patch_frontmatter(fp, new_fields):
                    it["status"] = "active"
                    it.pop("completed_at", None)
                    it.pop("commit_sha", None)
                    _log(
                        f"roadmap: REVERTED initiative {it['id']} from done → active "
                        f"({len(pending)} task(s) still pending: {pending[:5]}"
                        f"{', …' if len(pending) > 5 else ''})"
                    )
                    _debug_emit(
                        "init-archive.reverted",
                        msg=f"initiative {it['id']} reverted: pending tasks remain",
                        lvl="warn",
                        data={
                            "initiative_id": it["id"],
                            "pending_task_ids": pending,
                            "total_tasks": len(kids),
                        },
                    )
            except OSError as e:
                _log(f"roadmap: revert write failed for {it['id']}: {e}")


def _git_head_sha(root: "Path") -> Optional[str]:
    """`git rev-parse HEAD` in `root`. Returns None if the cluster isn't
    a git repo or git is unavailable — auto-archive still proceeds with
    `commit_sha: null`."""
    try:
        proc = subprocess.run(
            ["git", "-C", str(root), "rev-parse", "HEAD"],
            capture_output=True,
            text=True,
            timeout=5,
        )
        if proc.returncode == 0:
            sha = proc.stdout.strip()
            return sha or None
    except (OSError, subprocess.SubprocessError):
        return None
    return None


