class StateIntegrityChecker:
    """Walks the cluster looking for inconsistencies that should be
    surfaced to the agent for repair on its next turn. Surfaces hints,
    not blockers — the agent decides whether to fix them now or later.

    Cheap (single FS walk + a YAML parse). Runs on every briefing.
    """

    def __init__(self, paths: "Paths", cluster: Any, project: ProjectState):
        self.paths = paths
        self.cluster = cluster
        self.project = project

    def check(self) -> List[Dict[str, Any]]:
        violations: List[Dict[str, Any]] = []
        declared_modules = {
            m.get("id")
            for m in (self.cluster.data.get("modules") or [])
            if isinstance(m, dict) and m.get("id")
        }
        # Rule: every .meshkore/modules/<X>/ should be declared in
        # cluster.yaml.modules[]. Otherwise the cockpit's module tree
        # won't show it and child tasks render as orphans.
        for mdir in self.project.module_dirs():
            mid = mdir.name
            if mid not in declared_modules:
                violations.append(
                    {
                        "kind": "module_not_declared",
                        "module_id": mid,
                        "fix": (
                            f"Append `{{id: {mid}, kind: area, name: '{mid.capitalize()}'}}`"
                            " to `.meshkore/public/cluster.yaml.modules[]` so the cockpit's"
                            " module tree shows this module + its tasks."
                        ),
                    }
                )
        # Rule: every task's `initiative:` should reference an existing
        # initiative file. Surfaces typos and renames.
        initiative_ids = {self._read_id(f) for f in self.project.initiative_files()}
        initiative_ids.discard(None)
        for tf in self.project.task_files():
            tid = self._read_id(tf)
            ini = self._read_field(tf, "initiative")
            if ini and ini not in initiative_ids:
                violations.append(
                    {
                        "kind": "task_initiative_broken",
                        "task_id": tid or tf.name,
                        "initiative_ref": ini,
                        "fix": (
                            f"Task `{tid or tf.name}` references initiative"
                            f" `{ini}` which does not exist under"
                            " `.meshkore/roadmap/initiatives/`. Either create"
                            " the initiative file or update the task's"
                            " `initiative:` frontmatter to an existing id"
                            " (the ids live in that folder)."
                        ),
                    }
                )
        # Rule (RSV1): a `status:` value the daemon has no alias for.
        # `normalize_status` maps everything it does not recognise to
        # `backlog` and says nothing, so a typo — or a new word someone
        # invented — quietly becomes "pending work" and the board stops
        # matching reality. That is how `shipped` and `archived` came to
        # render as live initiatives. Surface it instead of swallowing it.
        for f, kind in [
            *((tf, "task") for tf in self.project.task_files()),
            *((inif, "initiative") for inif in self.project.initiative_files()),
        ]:
            raw = (self._read_field(f, "status") or "").strip().lower()
            if not raw or raw in CANONICAL_STATUSES or raw in STATUS_ALIASES:
                continue
            violations.append(
                {
                    "kind": "unknown_status",
                    "path": str(f),
                    "status": raw,
                    "fix": (
                        f"`{f.name}` has `status: {raw}`, which the daemon does"
                        " not recognise — it is being treated as `backlog`."
                        f" Use one of {list(CANONICAL_STATUSES)}, or add an"
                        " alias for it in `cluster.STATUS_ALIASES` if the word"
                        " is one this project means to keep using."
                    ),
                }
            )

        # Rule: every initiative whose status is `active` or `next`
        # should have ≥1 child task. `backlog` / `done` are exempt.
        # This catches "I created an initiative and forgot the tasks".
        tasks_by_initiative: Dict[str, List[str]] = {}
        for tf in self.project.task_files():
            ini = self._read_field(tf, "initiative")
            if ini:
                tasks_by_initiative.setdefault(ini, []).append(tf.name)
        for inif in self.project.initiative_files():
            iid = self._read_id(inif)
            status = (self._read_field(inif, "status") or "").lower()
            if not iid:
                continue
            if status not in ("active", "next"):
                continue
            children = tasks_by_initiative.get(iid) or []
            if not children:
                violations.append(
                    {
                        "kind": "initiative_without_tasks",
                        "initiative_id": iid,
                        "status": status,
                        "fix": (
                            f"Initiative `{iid}` is `{status}` but has no child"
                            " tasks. Either add 1-2 scaffolding tasks (linked"
                            f" via `initiative: {iid}` in their frontmatter)"
                            " or drop the initiative back to `status: backlog`"
                            " until you're ready to populate it."
                        ),
                    }
                )
            # py-1.6.2 — Over-dense initiative. >12 active/next tasks
            # under one initiative is a roadmap anti-pattern: the cockpit
            # card becomes unscannable and the initiative is almost
            # certainly mixing multiple work-streams.
            elif len(children) > 12:
                violations.append(
                    {
                        "kind": "initiative_too_dense",
                        "initiative_id": iid,
                        "child_count": len(children),
                        "fix": (
                            f"Initiative `{iid}` carries {len(children)} child"
                            " tasks — that's almost always multiple work-streams"
                            " grouped under one card. Split into work-stream-"
                            "coherent sub-initiatives (e.g., 'Auth & identity',"
                            " 'Canvas viewer', 'Anchoring chain'), each with"
                            " 3-8 tasks. Repoint each task's `initiative:`"
                            " frontmatter at its new id. Then either repurpose"
                            f" `{iid}` as one of the new work-streams or move"
                            " its file to `.meshkore/roadmap/initiatives/log/`"
                            f" with `status: superseded` + `superseded_by:`."
                        ),
                    }
                )
        # py-1.4.1 — Context coverage gap (heuristic). Finds capitalised
        # tokens (brand / product / proper-noun-ish) mentioned ≥3 times
        # in context.md but 0 times across any task / initiative file.
        # Conservative: stopword filter + frequency floor → low false
        # positives. Surfaced as a single hint, NOT a hard violation.
        coverage_gap = self._check_context_coverage()
        if coverage_gap:
            violations.append(coverage_gap)
        # py-1.4.3 — Coverage matrix discipline.
        cov_v = self._check_coverage_doc()
        if cov_v:
            violations.append(cov_v)
        return violations

    def _check_coverage_doc(self) -> Optional[Dict[str, Any]]:
        """Once the cluster has at least one initiative, enforce that
        `.meshkore/docs/coverage.md` exists and has no `?` / `TBD` /
        `TODO` / `FIXME` placeholders in the Coverage column."""
        if not self.project.initiative_files():
            return None  # bootstrap still in progress; not yet expected
        cov_path = self.paths.docs_dir / "coverage.md"
        if not cov_path.exists():
            return {
                "kind": "coverage_doc_missing",
                "fix": (
                    "Create `.meshkore/docs/coverage.md` mapping every"
                    " numbered requirement from the brief (sections + rules"
                    " + explicit deliverables) to a task id OR a"
                    " `defer: <reason>` marker. See the bootstrap brief's"
                    " 'Coverage matrix' block for the required format —"
                    " three sections: Sections, Rules, Explicit deliverables."
                ),
            }
        try:
            text = cov_path.read_text(errors="replace")
        except OSError:
            return None
        # Detect placeholders in the Coverage column of pipe-tables.
        # Matches `| ? |`, `| TBD |`, `| TODO |`, `| FIXME |`, `|  |`
        # (empty), and `|   ???  |`. Case-insensitive.
        gap_pat = re.compile(r"\|\s*(\?+|TBD|TODO|FIXME|N/A)\s*\|", re.IGNORECASE)
        gap_hits = gap_pat.findall(text)
        # Empty cells: only count those that look like a final column
        # (line ends with the empty cell pipe). Skip header/separator
        # rows ("|---|---|").
        empty_count = 0
        for line in text.splitlines():
            if line.strip().startswith("|") and "---" not in line:
                cells = [c.strip() for c in line.strip().strip("|").split("|")]
                if cells and cells[-1] == "":
                    empty_count += 1
        total_gaps = len(gap_hits) + empty_count
        if total_gaps == 0:
            return None
        return {
            "kind": "coverage_gaps_in_doc",
            "count": total_gaps,
            "fix": (
                f"`.meshkore/docs/coverage.md` has {total_gaps} row(s) with"
                " a placeholder (`?`, `TBD`, `TODO`, `FIXME`, `N/A`, or"
                " empty) in the Coverage column. Resolve each: either add"
                " the task that addresses the requirement (and reference"
                " it in the cell), or replace with `defer: <reason>`."
            ),
        }

    def _check_context_coverage(self) -> Optional[Dict[str, Any]]:
        ctx_path = self.paths.docs_dir / "context.md"
        if not ctx_path.exists():
            return None
        try:
            ctx_text = ctx_path.read_text(errors="replace")
        except OSError:
            return None
        haystack_parts: List[str] = []
        for f in (
            self.project.task_files(include_boilerplate=True)
            + self.project.initiative_files()
        ):
            try:
                haystack_parts.append(f.read_text(errors="replace"))
            except OSError:
                pass
        haystack_lower = "\n".join(haystack_parts).lower()

        # Capitalised tokens, 4+ chars, allow dot + hyphen inside (FAL.ai,
        # DALL-E, Cloudflare, SvelteKit). All-caps acronyms are caught by
        # the same regex.
        pat = re.compile(r"\b[A-Z][A-Za-z0-9.\-]{3,}\b")
        counts: Dict[str, int] = {}
        for m in pat.finditer(ctx_text):
            tok = m.group(0)
            low = tok.lower()
            if low in _COVERAGE_STOPWORDS:
                continue
            counts[tok] = counts.get(tok, 0) + 1
        # Threshold: appears ≥3 times in context AND 0 times across
        # tasks + initiatives. Top 8 by frequency.
        gaps: List[Tuple[str, int]] = []
        for tok, n in counts.items():
            if n < 3:
                continue
            if tok.lower() in haystack_lower:
                continue
            gaps.append((tok, n))
        gaps.sort(key=lambda x: (-x[1], x[0]))
        gaps = gaps[:8]
        if not gaps:
            return None
        return {
            "kind": "context_coverage_gap",
            "tokens": [{"token": t, "mentions": n} for t, n in gaps],
            "fix": (
                "These proper-noun-ish terms appear repeatedly in"
                " `.meshkore/docs/context.md` but in 0 task / initiative"
                " files. Either (a) add a task that addresses them, or"
                " (b) write a `> defer: <reason>` line in context.md so"
                " future briefings stop flagging them as gaps."
            ),
        }

    @staticmethod
    def _read_id(path: Any) -> Optional[str]:
        try:
            text = path.read_text(errors="replace")
        except OSError:
            return None
        fm = parse_frontmatter(text)
        v = fm.get("id")
        return str(v) if v else None

    @staticmethod
    def _read_field(path: Any, key: str) -> Optional[str]:
        try:
            text = path.read_text(errors="replace")
        except OSError:
            return None
        fm = parse_frontmatter(text)
        v = fm.get(key)
        return str(v) if v else None


# ── inlined from daemon/prompts.py (DM3+ bundle) ─────────────────────────
"""Prompt composition for one agent turn — the briefing pipeline.

DM-modularize-2 (py-1.14.4): lifted verbatim from daemon.py. Contains
everything that turns a cluster's filesystem state + the operator's
message into the markdown prompt piped to `claude -p`:

* ``AGENT_PROMPTS``           — declarative per-agent-type registry
                                (role / focus / redirect / storage / quota).
* ``_agent_manifest`` +
  ``_agent_type_normalised`` +
  ``_agent_type_from_conv_slug`` — agent-type resolution helpers.
* ``ProjectState``            — cheap, lazy FS summary of the cluster.
* ``StateIntegrityChecker``   — orphan-module / broken-ref repair hints.
* ``_conversation_history``   — last-N-turns rolling-summary reader.
* ``BriefingPipeline``        — stacks the sections into the final prompt.

Pure, side-effect-free composition — no subprocess, no sockets, no
locks. The only inputs are a ``Paths`` + ``Cluster`` + per-turn args;
the only output is a string. That isolation is why it extracts cleanly.

Bundler note: imports its shared helpers from utils/paths (stripped by
``bundle.py``; the names resolve in the bundle's flat namespace).
daemon.py re-exports ``AGENT_PROMPTS`` / ``_agent_manifest`` /
``_agent_type_*`` / ``BriefingPipeline`` so ``daemon.X`` stays stable
for callers and tests. quota.py imports ``AGENT_PROMPTS`` +
``_agent_manifest`` from here directly."""


import json
from typing import Any, Dict, List, Optional, Tuple


# The daemon's ``Cluster`` type lives in daemon.py (loaded after this module
# + after the bundle's prompts section), so it can't be imported here. Like
# storage.py, prompts annotates cluster params as ``Any`` — the only access
# is duck-typed (``cluster.data``). A TYPE_CHECKING import is NOT used: the
# bundler strips sibling/daemon imports, which would leave an empty
# ``if TYPE_CHECKING:`` block and break the single-file build.


def _conversation_history(
    paths: "Paths",
    conv: str,
    limit: int = 12,
    rolling_summary_threshold: int = 12,
    summary_head_chars: int = 200,
) -> List[str]:
    """Walk timeline files newest→oldest, return last `limit` turns of
    `conv` formatted as 'USER: …' / 'YOU (last turn): …'.

    py-1.5.0 — Rolling-summary compaction. If the conv has more than
    `rolling_summary_threshold` turns total, the older turns (beyond
    the most-recent `limit`) are collapsed into a single 'EARLIER:'
    block listing one truncated line per turn so the agent still has
    *some* awareness of what was discussed before its recent window,
    without paying the full token cost. Previous behaviour: silently
    drop everything beyond turn 12, the agent had amnesia past that.
    """
    if not paths.timeline_dir.exists():
        return []
    # Collect ALL turns for the conv, oldest → newest, scanning all
    # timeline files (jsonl + jsonl.gz from rotation). Bounded by the
    # caller's overall history dataset size; cheap on small projects.
    all_turns: List[Tuple[str, str]] = []
    for f in sorted(_iter_timeline_files(paths)):
        for ev in _read_timeline_file(f):
            if ev.get("conv") != conv:
                continue
            t = ev.get("type")
            if t not in ("chat.user", "chat.assistant", "chat.assistant.final"):
                continue
            who = "USER" if t == "chat.user" else "YOU (last turn)"
            text = str(ev.get("text") or "").strip()
            if not text:
                continue
            all_turns.append((who, text))
    if not all_turns:
        return []
    # Split into "earlier" (everything beyond `limit`) and "recent".
    if len(all_turns) <= max(limit, rolling_summary_threshold):
        recent = all_turns
        earlier: List[Tuple[str, str]] = []
    else:
        recent = all_turns[-limit:]
        earlier = all_turns[:-limit]
    out: List[str] = []
    if earlier:
        # Collapsed view of older turns — one short line each, prefixed
        # so the agent knows these are summarised.
        head_lines = [
            f"  • {w}: {t[:summary_head_chars]}{'…' if len(t) > summary_head_chars else ''}"
            for w, t in earlier
        ]
        out.append(
            f"EARLIER turns in this conversation ({len(earlier)} compacted, oldest first):"
        )
        out.extend(head_lines)
        out.append("")  # blank line before recent block
    # Recent turns at full 800-char truncation (same as before).
    out.extend(f"{w}: {t[:800]}" for w, t in recent)
    return out


# ───────────────────────────────────────────────────────────────────────
# Briefing pipeline (py-1.4.0)
#
# The agent's prompt is composed by stacking small, independent sections.
# Each section is a method on BriefingPipeline returning a markdown block
# (or "" to skip itself). Two read-only helpers feed it:
#
#   • ProjectState         — cheap FS summary (counts, emptiness)
#   • StateIntegrityChecker — orphan-module / broken-ref detection
#
# Adding a new section is a one-line append in `build()`. Each section
# is small enough to maintain without touching others, which makes
# evolution safe even as the briefing grows.
#
# Sections, in order:
#   1. role               — who you are + where
#   2. core_rules         — stable hard rules (don't push, don't edit creds)
#   3. cluster_snapshot   — N initiatives, M tasks, P modules
#   4. project_mode       — bootstrap brief if empty, ø otherwise
#   5. integrity          — orphan modules + other repair hints
#   6. cockpit_context    — operator-attached context_docs[] from /chat/dispatch
#   7. history            — last N turns from .meshkore/timeline/
#   8. user_turn          — what the user just typed
#
# All sections are separated by `\n\n---\n\n` so the LLM reads them as
# discrete blocks rather than one flat wall.


# py-1.4.1 — Stopwords for the context-coverage heuristic. These are
# tokens that pass the capitalised-token regex but are uninformative
# (sentence starters, generic acronyms). Lowercased for comparison.


# py-1.7.0 — Specialised agent prompt registry. Each agent type gets a
# role + focus + redirect + storage rules block. The default "custom"
# (a.k.a. General coder) keeps the original coordinator behaviour: full
# roadmap / module / task authority. Service agents (deploy / db /
# testing / audit / docs / review) get a tight focus + an explicit
# "redirect to General coder" clause so they refuse out-of-scope work
# cleanly instead of bumbling into roadmap edits.
#
# Why declarative: scaling. Adding a new agent type later = one entry
# here, no `if agent_type == 'foo':` branches scattered across the
# briefing pipeline. The pipeline reads from this dict.


# AGENT_PROMPTS relocated to agent_prompts.py (DM-modularize-3) — ~940
# lines of prompt text; imported above and re-exported so callers that
# do `from prompts import AGENT_PROMPTS` (quota.py, daemon.py) are unchanged.


def _fmt_request_amendments(req: Dict[str, Any], indent: str = "  ") -> str:
    """BT-13 — the amendments recorded on one open request, as indented
    lines to append under that request wherever a batch is shown. "" when
    it has none."""
    amends = req.get("amendments") if isinstance(req, dict) else None
    if not isinstance(amends, list) or not amends:
        return ""
    out = []
    for a in amends:
        if not isinstance(a, dict):
            continue
        text = " ".join(str(a.get("text") or "").split())
        if len(text) > 300:
            text = text[:300] + "…"
        out.append(f"\n{indent}- AMENDED {str(a.get('at') or '')[:16]}: {text}")
    return "".join(out)


class BriefingPipeline:
    """Composes the prompt sent to `claude -p` for one agent turn.
    See module-level comment above for the section order + rationale."""

    SECTION_SEP = "\n\n---\n\n"

    def __init__(
        self,
        *,
        paths: "Paths",
        cluster: Any,
        identity: str,
        conv: str,
        user_text: str,
        context_docs: Optional[List[Dict[str, Any]]] = None,
        agent_type: Optional[str] = None,
        agent_id: Optional[str] = None,
        member_body: Optional[str] = None,
        member_profile_changed: bool = False,
        engine_switched: Optional[str] = None,
        daemon_port: Optional[int] = None,
        daemon: Any = None,
    ):
        self.paths = paths
        self.cluster = cluster
        # daemon-centralized — the LIVE port the central daemon is listening on,
        # injected by the runner from its daemon back-ref. This is the SINGLE
        # source of truth for the in-briefing base URL. Reading a per-project
        # `.runtime/port` file instead was fragile: an ADOPTED project never gets
        # one written, so the read fell back to a hardcoded 5570 and every agent
        # probed a dead port ("daemon down" false alarm, field 2026-07-09).
        self.daemon_port = daemon_port
        # REL1 — optional back-ref, used only to report which jobs are
        # running right now. Never required: every non-dispatch caller
        # (tests, tooling) constructs the pipeline without it.
        self.daemon = daemon
        self.identity = identity
        self.conv = conv
        self.user_text = user_text
        self.context_docs = context_docs or []
        # ATM10 (agent-team) — the init-prompt body of the team member this
        # conv is an INSTANCE of. Injected verbatim by `_section_member` on
        # the FIRST turn only (later turns get the usual tight reminder).
        self.member_body = (member_body or "").strip() or None
        self.member_profile_changed = bool(member_profile_changed)
        # py-1.7.0 — agent_type drives role / focus / redirect / rules
        # selection from AGENT_PROMPTS. Defaults to 'custom' (General
        # coder) when missing/unknown so older cockpits and direct API
        # callers keep working.
        self.agent_type = _agent_type_normalised(agent_type)
        self.agent_id = (agent_id or "").strip() or None
        self.project = ProjectState(paths)
        self.integrity = StateIntegrityChecker(paths, cluster, self.project)
        # py-1.7.0 — cadence: detect whether this conv has had any prior
        # assistant turn. The full role+rules block is sent on the first
        # turn (so the agent gets the complete onboarding); on subsequent
        # turns we send a tight role reminder only, saving tokens and
        # keeping the conversation snappier.
        self.is_first_turn = self._detect_first_turn()
        # ES-1 — a new code client has none of what the previous one was
        # told: no role block, no member profile, no project onboarding. Its
        # first turn gets the FULL briefing again, as if the conv were new;
        # the history section still carries what was said.
        self.engine_switched = (engine_switched or "").strip() or None
        if self.engine_switched:
            self.is_first_turn = True

    def _detect_first_turn(self) -> bool:
        try:
            for f in _iter_timeline_files(self.paths):
                for ev in _read_timeline_file(f):
                    if ev.get("conv") != self.conv:
                        continue
                    if ev.get("type") in (
                        "chat.assistant.final",
                        "chat.assistant.delta",
                    ):
                        return False
            return True
        except Exception:
            return True

    def build(self) -> str:
        sections = [
            # Standard §3.5 (v25 hard_rule) — invariant project context,
            # prepended BEFORE the role block. Empty when the cluster has
            # no .meshkore/context/ tree yet.
            self._section_project_context(),
            self._section_role(),
            self._section_engine_switch(),
            # ORC3 — the two SYSTEM agents have a boundary the operator must
            # be able to rely on whatever their member card says (cards are
            # operator prose and we never rewrite them). Injected by the
            # daemon so it reaches clusters seeded long before this rule.
            self._section_member(),
            self._section_team(),
            # BT-13 — what this agent has handed out that is still open, so an
            # operator message that changes its scope gets to it.
            self._section_in_flight(),
            self._section_run_to_completion(),
            self._section_core_rules(),
            self._section_jobs(),
            self._section_agent_focus(),
            # ORC1/ORC3 (orchestrator-that-plans) — the Orchestrator's SOP
            # is above; these two are the STATE it executes against, rebuilt
            # every turn: the operator's queue with per-task readiness, and
            # the roster it may dispatch to. Before this the roadmap reached
            # it as three count lines and the team as nothing at all, so its
            # only model of both was its own past narration.
            self._section_execution_queue(),
            self._section_orchestrator_team(),
            self._section_agent_redirect(),
            self._section_agent_memory(),
            self._section_cluster_snapshot(),
            self._section_project_mode(),
            self._section_integrity(),
            self._section_cockpit_context(),
            self._section_anchor_nudge(),
            self._section_history(),
            # py-1.10.8 — only non-empty when user_text starts with
            # `[architect-consult]` on the `_onboarding_v1` conv. Forces
            # A001 to decide instead of bouncing the question back.
            self._section_consult_addendum(),
            self._section_user_turn(),
        ]
        brief = self.SECTION_SEP.join(s for s in sections if s and s.strip())
        # Substitute the live daemon version into the architect's commit-
        # trailer SOP. DAEMON_VERSION lives in the leaf `constants` module
        # (DA-CONST-01) — a dependency-free import, no cycle, available at
        # module load. No-op for agent types whose briefing lacks the token.

        return brief.replace("__MESHKORE_VERSION__", DAEMON_VERSION)

    # ── sections ──────────────────────────────────────────────────

    def _knowledge_onboarding(self, manifest_path: "Any") -> str:
        """knowledge-tree-unified KT5 — build the invariant onboarding block
        from the unified knowledge manifest (`context/_index.yaml`).

        Injects a KNOWLEDGE MAP (every concept node as an indented
        `title — desc` line, so the agent learns WHAT EXISTS and WHERE) plus
        the PINNED bodies in full. Non-pinned nodes that carry a body show
        their `GET /knowledge/<id>` fetch id, so the agent knows to pull them
        on demand instead of paying for them on every spawn. Returns "" when
        the manifest is empty/unparseable so the caller can fall back to the
        legacy per-file serialization."""
        try:

            data = parse_simple_yaml(
                manifest_path.read_text(encoding="utf-8", errors="replace")
            )
        except Exception:
            return ""
        nodes = [
            n
            for n in (data.get("nodes") or [])
            if isinstance(n, dict) and n.get("id") and n.get("title")
        ]
        if not nodes:
            return ""

        meshroot = self.paths.meshkore
        by_id = {str(n["id"]).strip(): n for n in nodes}
        children: Dict[str, List[str]] = {}
        roots: List[str] = []
        for n in nodes:
            nid = str(n["id"]).strip()
            pid = str(n.get("parent")).strip() if n.get("parent") else None
            if pid and pid in by_id:
                children.setdefault(pid, []).append(nid)
            else:
                roots.append(nid)

        def read_body(src: "Any") -> str:
            if not (isinstance(src, str) and src.strip()):
                return ""
            fp = (meshroot / src.strip()).resolve()
            try:
                if not str(fp).startswith(str(meshroot.resolve())) or not fp.is_file():
                    return ""
                text = fp.read_text(encoding="utf-8", errors="replace")
            except OSError:
                return ""
            return split_frontmatter(text)[1].strip()

        map_lines: List[str] = []
        pinned: List[str] = []

        # GA-4 / BT-2 — the branches this conv's MEMBER asked for. A declared
        # branch pins itself and everything under it.
        #
        # BT-2 (base-team, 2026-09-28) — a declared slice now REPLACES the
        # project's default pinned set instead of adding to it: *"a un
        # deployer no le hace falta cargar el modelo de datos… ni todo el
        # Roadmap, ni todo el Stack"*. The map below still lists every
        # node, so the agent knows the rest exists and how to fetch it.
        #
        # A key names a node id, or a context FILE by stem
        # (`architecture` → the node whose src is `context/architecture.md`),
        # so a base-team card means the same thing in every project.
        declared = set(self.member_context())
        want: set = set()
        if declared:

            def mark(nid: str) -> None:
                want.add(nid)
                for c in children.get(nid, []):
                    mark(c)

            for n in nodes:
                nid = str(n["id"]).strip()
                src = str(n.get("src") or "").strip()
                stem = src.rsplit("/", 1)[-1][:-3] if src.endswith(".md") else ""
                if nid in declared or (src.startswith("context/") and stem in declared):
                    mark(nid)

        def walk(nid: str, depth: int) -> None:
            n = by_id[nid]
            title = str(n["title"]).strip()
            desc = str(n.get("desc") or "").strip()
            load = str(n.get("load") or "skeleton").strip()
            is_pinned = (nid in want) if declared else load == "pinned"
            indent = "  " * depth
            line = f"{indent}{'★ ' if is_pinned else ''}{title}"
            if desc:
                line += f" — {desc}"
            if not is_pinned and isinstance(n.get("src"), str) and n["src"].strip():
                line += f"  → GET /knowledge/{nid}"
            map_lines.append(line)
            if is_pinned:
                b = read_body(n.get("src"))
                if b:
                    pinned.append(f"[{title}]\n{b}")
            for c in children.get(nid, []):
                walk(c, depth + 1)

        for r in roots:
            walk(r, 0)
        if not map_lines:
            return ""

        header = (
            "Everything between the markers below is the project's INVARIANT "
            "knowledge (MeshKore Standard §3.5). Treat it as authoritative — do "
            "not re-derive or re-debate it. The KNOWLEDGE MAP lists every "
            "concept the project documents; ★ nodes are included in full under "
            "PINNED. For any other node, fetch its body on demand with the "
            "GET /knowledge/<id> shown.\n"
        )
        out = header + "\n=== KNOWLEDGE MAP ===\n" + "\n".join(map_lines)
        if pinned:
            out += "\n\n=== PINNED (full bodies) ===\n\n" + "\n\n".join(pinned)
        CAP = 24000
        if len(out) > CAP:
            out = out[:CAP] + (
                "\n…[knowledge truncated — over the §3.5 4500-token budget; "
                "trim context/_index.yaml]"
            )
        return out + "\n\n=== END CONTEXT ==="

    def _section_project_context(self) -> str:
        """Standard §3.5 (v25 hard_rule) — serialize the invariant PROJECT
        CONTEXT block, prepended before the role on every spawn.

        knowledge-tree-unified (KT5): when a unified knowledge manifest is
        present (`context/_index.yaml`), the block is the KNOWLEDGE MAP +
        pinned bodies (skeleton-loaded; the rest fetched on demand via
        /knowledge/<id>). Otherwise it falls back to the legacy per-file
        serialization (overview/product/stack/architecture/constraints/
        glossary + decisions/ + criteria/). Returns "" for a fresh cluster
        with neither — the legacy `docs/context.md` pointers still apply."""
        root = self.paths.context_dir
        manifest = root / "_index.yaml"
        if manifest.is_file():
            block = self._knowledge_onboarding(manifest)
            if block:
                return block
        if not root.is_dir():
            return ""

        def body_of(p: "Any") -> str:
            try:
                text = p.read_text(encoding="utf-8", errors="replace")
            except OSError:
                return ""
            # Strip YAML frontmatter (only when both fences are present).
            return split_frontmatter(text)[1].strip()

        parts: List[str] = []
        # BT-2 — same rule without a manifest: a member that declared its
        # slice gets those files in full and the rest as one line of paths.
        declared = set(self.member_context())
        skipped: List[str] = []

        def wanted(key: str) -> bool:
            return not declared or key in declared

        def add(marker: str, p: "Any") -> None:
            if not p.is_file():
                return
            if not wanted(p.stem):
                skipped.append(f"context/{p.name}")
                return
            b = body_of(p)
            if b:
                parts.append(f"{marker}\n{b}")

        add("=== PROJECT CONTEXT ===", root / "overview.md")
        add("=== PRODUCT ===", root / "product.md")
        add("=== STACK ===", root / "stack.md")
        add("=== ARCHITECTURE ===", root / "architecture.md")
        add("=== CONSTRAINTS ===", root / "constraints.md")
        add("=== GLOSSARY ===", root / "glossary.md")

        def folder_chunk(folder: "Any", *, newest_first: bool) -> str:
            if not folder.is_dir():
                return ""
            entries = [f for f in folder.glob("*.md") if f.name != "README.md"]
            entries.sort(reverse=newest_first)  # filenames are date- or slug-sorted
            chunk: List[str] = []
            readme = folder / "README.md"
            if readme.is_file():
                b = body_of(readme)
                if b:
                    chunk.append(b)
            for f in entries:
                b = body_of(f)
                if b:
                    chunk.append(b)
            return "\n\n".join(chunk)

        for key, title, newest in (
            ("decisions", "=== DECISIONS (newest first) ===", True),
            ("criteria", "=== CRITERIA ===", False),
        ):
            if not (root / key).is_dir():
                continue
            if not wanted(key):
                skipped.append(f"context/{key}/")
                continue
            chunk = folder_chunk(root / key, newest_first=newest)
            if chunk:
                parts.append(f"{title}\n{chunk}")
        if skipped:
            parts.append(
                "=== ALSO IN THIS PROJECT (read only when your task needs it) ===\n"
                + "\n".join(f"- .meshkore/{s}" for s in skipped)
            )

        if not parts:
            return ""

        block = "\n\n".join(parts)
        # Defensive cap (~ the §3.5 3000w/4500tok budget) so a runaway
        # context/ can't blow the prompt. Dispatch-time budget refusal is
        # a separate gate; here we just bound the briefing.
        CAP = 24000
        truncated = ""
        if len(block) > CAP:
            block = block[:CAP]
            truncated = (
                "\n…[context truncated — over the §3.5 4500-token budget; "
                "trim .meshkore/context/]"
            )

        header = (
            "Everything between the markers below is the project's INVARIANT "
            "context (MeshKore Standard §3.5). Treat it as authoritative and "
            "unchanging — do not re-derive or re-debate it.\n"
        )
        return f"{header}\n{block}{truncated}\n\n=== END CONTEXT ==="

    def _section_role(self) -> str:
        # py-1.7.0 — Role text is now driven by AGENT_PROMPTS so service
        # agents (deploy / db / testing / ...) get their own framing,
        # not a generic "coordinator" label.
        prompt = AGENT_PROMPTS.get(self.agent_type) or AGENT_PROMPTS["custom"]
        role = prompt["role"]
        # On subsequent turns, send a tight role reminder only.
        if not self.is_first_turn:
            return (
                f"## Role reminder\n\n{role}\n\n"
                f"Cluster root: `{self.paths.root}` · Identity: "
                f"`{self.identity}` · Conv: `{self.conv}`"
                + (f" · Agent: `{self.agent_id}`" if self.agent_id else "")
            )
        return (
            f"## Role\n\n{role}\n\n"
            f"Cluster root: `{self.paths.root}`\nIdentity: `{self.identity}`"
            f" · Conv: `{self.conv}`"
            + (f" · Agent: `{self.agent_id}`" if self.agent_id else "")
        )

    def _section_engine_switch(self) -> str:
        """ES-1 — say it once, on the first turn after the operator moved
        this conv to another code client, so the agent does not assume
        tool state, plans or files it never saw."""
        if not self.engine_switched:
            return ""
        return (
            "## New code client for this conversation\n\n"
            f"Until now this conversation ran on `{self.engine_switched}`. The "
            "operator switched it; you are a fresh session that has only this "
            "briefing and the recent turns below. Do not claim to remember "
            "anything that is not written here — re-read files before acting "
            "on them."
        )

    def _section_member(self) -> str:
        """ATM10 (agent-team) — inject the team member's init-prompt body on
        the FIRST turn of an instance, verbatim, right after the role block.
        Empty on later turns (the tight role reminder carries the identity)
        and for convs not bound to a member."""
        if not self.member_body:
            return ""
        if self.is_first_turn:
            return (
                "## Team member profile (your standing instructions)\n\n"
                + self.member_body
            )
        # TMR3 — the operator edited this member's card. The profile went
        # in on turn 1 and nothing has re-read it since, so an edit had no
        # way of reaching a session that was already open (the reason the
        # engine dials get pushed onto bound convs, ATM14g). Re-inject it
        # once, labelled, so the agent replaces what it was told rather
        # than trying to reconcile two sets of standing instructions.
        if self.member_profile_changed:
            return (
                "## Team member profile — UPDATED (replaces your standing "
                "instructions)\n\nThe operator changed your member card. What "
                "follows supersedes the profile you were given earlier in this "
                "conversation; where they disagree, this text wins.\n\n"
                + self.member_body
            )
        return ""

    def _delegation_position(self) -> Dict[str, Any]:
        """HD-3 — where this conv sits in the delegation tree, read from the
        conv sidecar (cheap: one small JSON).
        `{depth, parent, member, max_depth}`."""
        depth, parent, member = 0, None, None
        requests: List[Dict[str, Any]] = []
        # The coordinator conv is the operator's root by definition, whatever
        # linkage the architect-consult protocol left in its sidecar.
        if self.conv == "_onboarding_v1":
            return {
                "depth": 0,
                "parent": None,
                "member": self._sidecar_member(),
                "max_depth": self._max_depth(),
                "requests": [],
            }
        try:
            meta = (
                json.loads(
                    (self.paths.runtime / "conv_meta.json").read_text() or "{}"
                ).get(self.conv)
                or {}
            )
            parent = str(meta.get("parent_conv") or "") or None
            member = str(meta.get("member") or "") or None
            depth = int(meta.get("depth") or (1 if parent else 0))
            # HD-12 — a member session has no single parent: it has a ledger
            # of open requests. Its depth is the deepest one it is holding,
            # and the requests themselves are what it owes an answer to.
            reqs = meta.get("open_requests")
            if isinstance(reqs, list) and reqs:
                requests = [r for r in reqs if isinstance(r, dict)]
                depth = max([depth] + [len(r.get("chain") or []) for r in requests])
                parent = (
                    parent
                    or str(
                        requests[-1].get("parent_label")
                        or requests[-1].get("parent_conv")
                        or ""
                    )
                    or None
                )
        except Exception:  # noqa: BLE001 — no sidecar = a root
            pass
        return {
            "depth": depth,
            "parent": parent,
            "member": member,
            "max_depth": self._max_depth(),
            "requests": requests,
        }

    def _sidecar_member(self) -> Optional[str]:
        """The team member this conv is an instance of, from the sidecar."""
        try:
            meta = (
                json.loads(
                    (self.paths.runtime / "conv_meta.json").read_text() or "{}"
                ).get(self.conv)
                or {}
            )
            return str(meta.get("member") or "") or None
        except Exception:  # noqa: BLE001
            return None

    def _max_depth(self) -> int:
        try:
            raw = (self.cluster.data.get("delegation") or {}).get("max_depth")
            if raw is not None:
                return max(1, min(8, int(raw)))
        except Exception:  # noqa: BLE001
            pass
        return 3

    def _is_operator_agent(self) -> bool:
        """The project's one coordinator: `_onboarding_v1`, or a conv at
        depth 0 bound to the Architect member. Never a worker."""
        if self._is_orchestrator():
            return False
        if self.conv == "_onboarding_v1":
            return True
        pos = self._delegation_position()
        if pos.get("depth") or pos.get("parent"):
            return False

        return pos.get("member") in ARCHITECT_IDS

    def _section_run_to_completion(self) -> str:
        """RUN-1 / BT-19 — the Architect runs the queue itself.

        mf27, 2026-09-28: a separate Orchestrator ran in parallel to the
        Architect and both briefed the same developer. There is ONE
        coordinator now: this agent delegates the queue's READY tasks to the
        members, is woken by each report, and keeps going."""
        if not self._is_operator_agent():
            return ""
        port = self.daemon_port
        if not port:
            try:
                port = int(self.paths.port_file.read_text().strip())
            except (OSError, ValueError):
                port = 5570
        base = _daemon_base_url(port)
        cluster_id = getattr(self.cluster, "id", "") or ""
        return (
            "## Running the queue\n\n"
            "You are the project's only coordinator. When the operator says run "
            'it end to end — *"hazlo todo"*, *"no pares"*, the Run queue button '
            "— you run the `## Execution queue` yourself:\n\n"
            "1. The roadmap must say what to run (initiatives `active`/`next`, "
            "tasks with `depends_on`). Fix that first if it does not. To stage a "
            f"different set: `POST {base}/roadmap/queue` "
            '`{"initiatives":["<id>",…]}` (headers `Authorization: Bearer <token '
            "from .meshkore/credentials/portal-token>`, `X-MeshKore-Project: "
            f"{cluster_id}`).\n"
            "2. Delegate EVERY `READY NOW` task at once, each to the member that "
            "fits (`## Your team`): each brief gets its own session and they run "
            "in parallel, up to your fan-out cap. Group tasks into one brief only "
            "when they touch the same files.\n"
            "3. END YOUR TURN. Each report wakes you: apply it (task done / "
            "blocked), re-read the queue — a finished task can make an earlier one "
            "ready — and delegate what is ready now. A progress update needs one "
            "sentence to the operator, nothing else.\n"
            "4. Stop only when nothing is ready and nothing is in flight (then "
            "summarise the pass: shipped / blocked / decisions), or when a "
            "decision is genuinely the operator's. Never stop just because a turn "
            "is long."
        )

    def _in_flight_requests(self) -> List[Tuple[str, Dict[str, Any], Dict[str, Any]]]:
        """(child conv, its sidecar, request) for every open request THIS
        conv handed out."""
        try:
            all_meta = (
                json.loads((self.paths.runtime / "conv_meta.json").read_text() or "{}")
                or {}
            )
        except Exception:  # noqa: BLE001
            return []
        out = []
        for conv, meta in all_meta.items():
            if not isinstance(meta, dict) or conv == self.conv:
                continue
            for r in meta.get("open_requests") or []:
                if isinstance(r, dict) and str(r.get("parent_conv") or "") == self.conv:
                    out.append((conv, meta, r))
        out.sort(key=lambda t: str(t[2].get("at") or ""))
        return out

    def _section_in_flight(self) -> str:
        """BT-13 — `## In flight`: the open requests this conv holds on
        others, and, for the operator's own agent, the rule that every
        operator message is checked against them before answering.

        mf27, 2026-09-28: the operator narrowed #SEL1 from 20 clubs to
        LaLiga's 42 while the developer was already on it; the Architect
        answered with 20 and the change never reached anyone."""
        items = self._in_flight_requests()
        if not items:
            return ""
        rows = []
        for conv, meta, r in items:
            who = f"`{conv}`" + (
                f" ({meta.get('member')})" if meta.get("member") else ""
            )
            task = r.get("task_id") or ""
            inits = r.get("initiatives") or []
            scope = (
                f" · task `{task}`"
                if task
                else (f" · initiatives {', '.join(map(str, inits))}" if inits else "")
            )
            first = " ".join(str(r.get("brief") or "").split())[:140]
            rows.append(
                f"- `{r.get('id')}` → {who}{scope} — {first}"
                + _fmt_request_amendments(r)
            )
        body = (
            "## In flight — what you handed out that is still open\n\n"
            + "\n".join(rows)
            + "\n\nIf the scope of any of these changes, `amend` it (`## Your team`) "
            "— the child gets it at its next step and passes it down to whatever it "
            "delegated in turn."
        )
        if self._is_operator_agent():
            body += (
                "\n\n**Before you answer, check the operator's message(s) against "
                "this list.** If several arrived while you were working they reach "
                "you as `Message 1/N`, `Message 2/N`, … — every one of them is a "
                "requirement, not only the last. For each message that changes the "
                "scope of something above (narrows it, widens it, changes a number, "
                "a target, a constraint):\n"
                "1. `amend` that request FIRST;\n"
                "2. update the task file's spec so the roadmap says the new scope;\n"
                "3. THEN answer, saying in one line what you amended."
            )
        return body

    def _section_team(self) -> str:
        """GA-3 (`generic-agents`) — `## Your team`: the roster as a catalog
        of things this agent can DO, with exactly two verbs.

        What this replaces: a 200-line section that quoted an authored
        delegation contract (`owns` / `never` / `delegates_to`) and spent
        most of its length on rules about when handing off was permitted.
        It read like a permissions system, it needed three hand-maintained
        fields per member to say anything at all, and it offered exactly
        one move — spawn another session — for every situation.

        The two verbs now:

          * **become** — adopt a teammate's profile for the next turn. No
            new session, no new row in the operator's rail, no report to
            wait for. This is the right move most of the time and it did
            not exist before, which is why the old section had to argue so
            hard about when NOT to delegate.
          * **delegate** — the existing rail (HD-3): the member's own
            session does the work, appears in the rail, reports back, and
            the daemon wakes this agent when it does. For work that should
            run in parallel, or that belongs to somebody else's judgement.

        The catalog line is DERIVED (title + the first real sentence of the
        member's prompt), so adding a teammate is writing a card and
        nothing else."""
        try:

            store = TeamStore(self.paths)
            roster = store.team_list()
        except Exception:  # noqa: BLE001 — no roster, no section
            return ""
        if not roster:
            return ""
        pos = self._delegation_position()
        port = self.daemon_port
        if not port:
            try:
                port = int(self.paths.port_file.read_text().strip())
            except (OSError, ValueError):
                port = 5570
        base = _daemon_base_url(port)
        cluster_id = getattr(self.cluster, "id", "") or ""
        me = pos.get("member") or ""

        def _one_line(m: Dict[str, Any]) -> str:
            """The member's own first sentence. GA-1 removed the authored
            `owns` field: a prompt that opens "You own releases and
            deploys" already says what the member is for, and deriving it
            means the catalog can never drift from the card."""
            try:
                body = (store.team_get(str(m.get("id"))).get("body") or "").strip()
            except Exception:  # noqa: BLE001
                return ""
            for para in body.split("\n\n"):
                line = " ".join(para.split())
                if not line or line.startswith("#"):
                    continue
                # First SENTENCE, not the first paragraph: cards open with
                # one-line missions and this is quoted into every spawn.
                for stop in (". ", "; "):
                    if stop in line:
                        line = line.split(stop)[0] + "."
                        break
                return (line[:160] + "…") if len(line) > 160 else line
            return ""

        rows = []
        for m in roster:
            mid = str(m.get("id") or "")
            if not mid or mid == me:
                continue
            ctx = [str(c) for c in (m.get("context") or [])]
            ctx_s = f" · knows {', '.join(ctx)}" if ctx else ""
            rows.append(f"- `{mid}` · {m.get('title') or mid} — {_one_line(m)}{ctx_s}")
        if not rows:
            # A one-member team is a legitimate setup, and telling that
            # agent to look for teammates it does not have is how it ends
            # up inventing one.
            return (
                "## Your team\n\n"
                "You are the only member of this team. Everything is yours to "
                "do directly — there is nobody to hand work to, and that is a "
                "working configuration, not a gap to route around."
            )

        head = (
            "## Your team\n\n"
            "These are the other agent profiles defined for this project. Treat "
            "them as tools you can pick up, not as colleagues you must ask "
            "permission from."
        )
        catalog = "### Catalog\n\n" + "\n".join(rows)

        # BT-3 (base-team, v38) — delegate is the default, become the
        # exception. v37 had it the other way round, and on a real project
        # (mf27) one thread ended up carrying the developer's diff, the
        # commit rules and the deploy runbook at once: *"puede llevar a un
        # contexto grande y confuso"*. A delegated teammate loads its own
        # profile and only its slice; the coordinator keeps the plan.
        become = (
            "### `become` — only for a quick switch\n\n"
            "For a single short step squarely in another profile, when "
            "spinning up its session is not worth it, put "
            "`⟦become⟧ <member id>` on its own line and end the turn: your "
            "next turn is briefed as that member, in this same conversation. "
            "Do not use it to chain a whole pipeline through one thread — "
            "that is what `delegate` is for."
        )

        delegate = (
            "### `delegate` — the default way to use a teammate\n\n"
            "Hand a step to the member whose profile fits it. It runs in that "
            "member's own session, with its own standing instructions and only "
            "its slice of the context, and reports back to you; you chain the "
            "next step from the report (build → commit → deploy). Give "
            "independent steps to different members at once.\n\n"
            f"`POST {base}/chat/delegate` with BOTH headers "
            "`Authorization: Bearer <token from .meshkore/credentials/portal-token>` "
            f"and `X-MeshKore-Project: {cluster_id}`. Body:\n\n"
            '```json\n{"parent_conv":"'
            + self.conv
            + '","member":"<id from the catalog>",'
            '"brief":"<what to do, its acceptance, where the relevant code is>"}\n```\n\n'
            "The brief INHERITS your initiative and task — pass "
            "`initiative_id`/`task_id` only to override. It answers "
            "`202 {conv, request_id, open_requests, reused}`. **Then END YOUR "
            "TURN.** Do not poll, do not sleep: when that member reports, the "
            "daemon posts a `[delegate-wake]` turn to you naming your request "
            "id, and you pick up from there.\n\n"
            "**Each brief gets its own session, so independent briefs run in "
            "parallel** — hand out every one that is ready. The exception is "
            "members whose card says `sessions: single` (by default the git and "
            "deploy members): they keep ONE session that batches every brief, so "
            "three frontend changes become one deploy; `reused: true` says your "
            "brief joined it. A brief that names several tasks reports each one "
            "as it closes — you are woken with a progress update.\n\n"
            f"Fan-out is capped per requester and at depth {pos['max_depth']}: "
            "a 409/429 tells you why — do that part yourself.\n\n"
            "#### `amend` — change a brief that is already in flight\n\n"
            "When the scope of something you handed out changes — the operator "
            "narrowed it, a report showed the brief was wrong — do NOT wait for "
            "the report and re-delegate. Amend it: "
            f"`POST {base}/chat/amend` (same headers) with "
            '`{"parent_conv":"' + self.conv + '","text":"<what changes>"}` '
            '— add `"request_id"` to amend one request only; without it every '
            "open request you hold gets it. The member receives it at its next "
            "step (mid-turn it merges in), it is recorded on the request, and a "
            "member that already passed the work on amends its own children. "
            "`409 no-open-requests` = nothing of yours is in flight: apply the "
            "change yourself. Say only what changes, not the whole brief again."
        )

        neither = (
            "### Or neither\n\n"
            "Most work is just work. A small fix, its test and its commit are "
            "ONE agent's job — do them. Never `become` to look thorough and "
            "never `delegate` to spread a task thin, to avoid reading code, or "
            "to re-start something already running."
        )

        parts = [head, catalog, delegate, become, neither]
        parts.append(self._child_duties() if pos["parent"] else self._root_duties())
        return "\n\n".join(parts)

    def _held_requests_block(self) -> str:
        """BT-13 — the requests this session is answering, each with the
        amendments recorded on it, so a change made after the brief was
        sent is part of the brief from now on."""
        reqs = self._delegation_position().get("requests") or []
        if not reqs:
            return ""
        lines = []
        for r in reqs:
            first = " ".join(str(r.get("brief") or "").split())[:160]
            lines.append(
                f"- `{r.get('id')}` from `{r.get('parent_label') or r.get('parent_conv')}`"
                f" — {first}" + _fmt_request_amendments(r)
            )
        amended = any(r.get("amendments") for r in reqs)
        return (
            "### Requests you are holding\n\n"
            + "\n".join(lines)
            + (
                "\n\nAn AMENDED line overrides the brief where they conflict — "
                "work to the amended scope and report against it."
                if amended
                else ""
            )
            + "\n\n"
        )

    def _child_duties(self) -> str:
        """HD-11 — what an agent that was DELEGATED to owes its parent."""
        return self._held_requests_block() + self._child_duties_body()

    def _child_duties_body(self) -> str:
        return "### What you owe your parent\n\n" + "\n".join(
            [
                "1. **Anchor**: you inherit your parent's `(initiative, task)` — it is stated in your brief. "
                'Emit `⟦anchor⟧ {"i":"<init>","t":"<task>"}` with THOSE ids. Do NOT invent a new initiative or task '
                "for a step someone delegated to you; that splits one piece of work across two roadmap entries.",
                "2. **Report**: the LAST line of your final reply MUST be one JSON object on one line:\n\n"
                '   `⟦report⟧ {"outcome":"success|partial|failed|blocked|no-recipe","commit":"<sha or null>",'
                '"files":["<path>",…],"tests":"green|red|none","next":"<one line: what remains or why blocked>",'
                '"for":["rq-…"]}`\n\n'
                "   `for` lists the request ids this report answers — one, or several when you did them as one piece "
                "of work. Omit it and the daemon assumes you answered EVERY open request you were holding. The daemon "
                "strips the line from the chat and posts it to whoever asked. No report = outcome `no-report` = "
                "counted as a failure. Never claim `success` for code you committed without its real sha; when your "
                "profile leaves commits to `git-manager`, `commit` is null and `files` lists what you changed. Do not "
                "print the report object anywhere else in your reply — it is for the agents, the operator reads your prose.",
                "3. **Commits**: your trailers are `Agent: <your member id>`, `Model:`, `MeshKore:` — and, because this "
                "work was delegated, `Parent: <parent member id>@<parent conv>` (Standard §9.1). Name the task id in the "
                "commit body too, not only in the anchor.",
                "4. **Diary**: do NOT write a `.meshkore/log/<date>.md` entry for the step you were delegated. Your parent "
                "writes ONE entry covering the whole unit of work, from your report — otherwise a single feature leaves "
                "five interleaved fragments. The ONE exception is a durable operation that must be findable by date on its "
                "own (a release, a deploy, a standard bump): that writes its own entry AND reports.",
            ]
        )

    def _root_duties(self) -> str:
        """The operator asked YOU, so the whole unit of work is yours to
        account for — including the parts you handed to someone else."""
        return (
            "### You are the root of this work\n\n"
            "Nobody delegated this to you, so you write the ONE diary entry "
            "for the whole unit of work in `.meshkore/log/<date>.md` — "
            "including what teammates did, from their reports. Your commit "
            "trailers are `Agent:`, `Model:`, `MeshKore:` with no `Parent:`."
        )

    def bound_member(self) -> str:
        """GA-2 — the member id this conv is an instance of, or "".

        The axis every system behaviour keys on now. It used to be
        `agent_type`, an invisible tag nothing in the cockpit could set;
        the member IS the thing the operator picks, renames and deletes,
        so anything that treats an agent specially must key on it."""
        try:
            return str(self._delegation_position().get("member") or "")
        except Exception:  # noqa: BLE001 — never break a briefing
            return ""

    def member_context(self) -> List[str]:
        """GA-4 — the knowledge branches this conv's member declared.

        Empty for an unbound conv, for a member with no `context:` line,
        and for any project whose roster predates the field — all of which
        mean "just the project default", which is what every agent got
        before this existed."""
        mid = self.bound_member()
        if not mid:
            return []
        try:

            fm = TeamStore(self.paths).team_get(mid).get("frontmatter") or {}
        except Exception:  # noqa: BLE001 — never break a briefing
            return []
        ctx = fm.get("context")
        if not isinstance(ctx, list):
            return []
        return [str(c).strip() for c in ctx if str(c or "").strip()]

    def _is_orchestrator(self) -> bool:
        """GA-2 — does this conv run the queue?

        Two signals, because the Orchestrator is a conv SHAPE that outlived
        its member card. `roadmap-architect` is the agent_type the cockpit
        stamps on a Run-All conv, and it is what still answers here after
        GA-6 archived the seeded `orchestrator` member: a project with one
        agent can still open a queue-running session, and does.
        """

        if self.bound_member() in ORCHESTRATOR_IDS:
            return True
        return self.agent_type == "roadmap-architect"

    # ── ORC1/ORC3: what the Orchestrator executes against ─────────────
    #
    # Both sections are for the member `orchestrator` only. Every other
    # agent gets "" — a coder has no business being handed the queue, and
    # the sections are not free (rebuilt per turn from live state).
    #
    # GA-2 — the gate used to be `agent_type == "roadmap-architect"`, a tag
    # set at dispatch and invisible everywhere else. Now it is the member,
    # which is what the operator actually sees in the roster.

    #: Caps. The queue section must stay a glance, not a document: past
    #: this the agent starts skimming, which is the failure we are fixing.
    QUEUE_MAX_INITIATIVES = 12
    QUEUE_MAX_TASKS_PER_LINE = 8

    def _roadmap_snapshot(self) -> Dict[str, Any]:
        """Initiatives + tasks as the daemon already computes them for the
        cockpit. Empty dict when this pipeline has no daemon back-ref (tests,
        tooling) — every caller degrades to an empty section."""
        daemon = getattr(self, "daemon", None)
        if daemon is None:
            return {}
        try:
            return daemon.state_manager.state() or {}
        except Exception:  # noqa: BLE001 — a briefing must never fail on state
            return {}

    @staticmethod
    def _task_readiness(
        task: Dict[str, Any], status_by_id: Dict[str, str]
    ) -> Tuple[str, List[str]]:
        """(state, blockers) for one task.

        `resolved`  — done/cancelled, nothing to dispatch.
        `waiting`   — its `depends_on` upstreams are not all done.
        `blocked`   — an agent marked it blocked; needs a decision, not a slot.
        `ready`     — dispatchable right now.

        This is the whole point of ORC1: readiness is a FUNCTION of current
        state, so a wake that finishes an upstream flips a task from waiting
        to ready without anybody having to remember it did."""
        status = str(task.get("status") or "").strip().lower()
        if status in ("done", "cancelled"):
            return "resolved", []
        waiting = [
            str(dep)
            for dep in (task.get("depends_on") or [])
            if str(status_by_id.get(str(dep), "")).lower() != "done"
        ]
        if waiting:
            return "waiting", waiting
        if status == "blocked":
            return "blocked", []
        return "ready", []

    def _section_execution_queue(self) -> str:
        coordinator = self._is_operator_agent()
        if not (self._is_orchestrator() or coordinator):
            return ""
        daemon = getattr(self, "daemon", None)
        if daemon is None:
            return ""
        try:
            queued = list(daemon.roadmap_queue_ids() or [])
        except Exception:  # noqa: BLE001
            queued = []
        snap = self._roadmap_snapshot()
        inits = {str(i.get("id")): i for i in (snap.get("initiatives") or [])}
        tasks = (snap.get("roadmap") or {}).get("tasks") or []
        status_by_id = {str(t.get("id")): str(t.get("status") or "") for t in tasks}
        by_init: Dict[str, List[Dict[str, Any]]] = {}
        for t in tasks:
            iid = str(t.get("initiative") or "")
            if iid:
                by_init.setdefault(iid, []).append(t)

        head = (
            "## Execution queue — server state, not your memory\n\n"
            "This is the operator's staged order, read fresh from the daemon "
            "on EVERY turn (`GET /roadmap/queue`). The cockpit's **Run queue** "
            'button and the operator typing *"run the queue"* mean exactly '
            "this list — there is no other queue and nothing here comes from "
            "what you remember saying earlier."
        )
        if not queued:
            if coordinator:
                return ""  # nothing staged: no section, no noise
            return (
                head + "\n\n**The queue is empty.** Nothing is staged. Do not invent "
                "a scope from the roadmap: say the queue is empty, name the "
                "active initiatives you can see, and ask the operator which to "
                "stage (or to press Run queue). Then end your turn."
            )

        lines: List[str] = []
        ready_total = 0
        for pos, iid in enumerate(queued[: self.QUEUE_MAX_INITIATIVES], start=1):
            it = inits.get(iid) or {}
            kids = by_init.get(iid, [])
            buckets: Dict[str, List[str]] = {
                "ready": [],
                "waiting": [],
                "blocked": [],
            }
            waits: Dict[str, List[str]] = {}
            done = 0
            for t in kids:
                state, blockers = self._task_readiness(t, status_by_id)
                tid = str(t.get("id"))
                if state == "resolved":
                    done += 1
                    continue
                buckets[state].append(tid)
                if blockers:
                    waits[tid] = blockers
            ready_total += len(buckets["ready"])
            title = str(it.get("title") or iid)
            status = str(it.get("status") or "unknown")
            lines.append(
                f"{pos}. `{iid}` — {title} · {status} · {len(kids)} task(s): "
                f"{done} done · {len(buckets['ready'])} ready · "
                f"{len(buckets['waiting'])} waiting · {len(buckets['blocked'])} blocked"
            )
            if buckets["ready"]:
                shown = buckets["ready"][: self.QUEUE_MAX_TASKS_PER_LINE]
                more = len(buckets["ready"]) - len(shown)
                lines.append(
                    "   READY NOW → "
                    + ", ".join(f"`{t}`" for t in shown)
                    + (f" (+{more} more)" if more > 0 else "")
                )
            if buckets["waiting"]:
                shown = buckets["waiting"][: self.QUEUE_MAX_TASKS_PER_LINE]
                lines.append(
                    "   WAITING   → "
                    + ", ".join(
                        f"`{t}` (needs "
                        + ", ".join(f"`{d}`" for d in waits.get(t, []))
                        + ")"
                        for t in shown
                    )
                )
            if buckets["blocked"]:
                shown = buckets["blocked"][: self.QUEUE_MAX_TASKS_PER_LINE]
                lines.append(
                    "   BLOCKED   → "
                    + ", ".join(f"`{t}`" for t in shown)
                    + " — marked blocked by an agent: these need a DECISION "
                    "(unblock, re-scope, or hand to the operator), not a slot."
                )
        if len(queued) > self.QUEUE_MAX_INITIATIVES:
            lines.append(
                f"…and {len(queued) - self.QUEUE_MAX_INITIATIVES} more queued "
                "initiative(s) below these."
            )

        rule = (
            "### How to read this\n\n"
            "- **The next task you dispatch is the first `READY NOW` entry, "
            "reading this list from the top.** Not the next one in the "
            "initiative you happen to be inside.\n"
            "- A finished turn can make an EARLIER position ready again — that "
            "is the normal case, not an exception. Re-read this section on "
            "every wake and go back. **A blocked initiative is not a closed "
            "one**: it is waiting for exactly the upstream your last subagent "
            "may have just finished.\n"
            "- `WAITING` tasks are not yours to dispatch: the daemon refuses "
            "them (409 `task-dependencies-not-done`). Do not retry them.\n"
            "- Never reorder the queue silently. If the order is wrong — "
            "shipping before the thing being shipped works, a gate that says "
            "NO-GO — say so in ONE line, name the swap you would make, and "
            "keep going with what is ready. The operator owns the order.\n"
            + (
                "- If work is missing, put it on the roadmap first, then delegate it.\n"
                if coordinator
                else "- You do not add, split or rewrite roadmap items. If work is "
                "missing, name it and let the Architect put it on the roadmap.\n"
            )
            + f"- Right now: **{ready_total} task(s) are dispatchable** across "
            f"{len(queued)} queued initiative(s)."
        )
        return head + "\n\n" + "\n".join(lines) + "\n\n" + rule

    def _section_orchestrator_team(self) -> str:
        """ORC3 — the roster the Orchestrator dispatches INTO.

        It used to dispatch by `agent_type` alone, which names a prompt
        baseline, not a person: the member cards (their CLI, model, effort
        and standing instructions) never applied, and every `work-*` conv on
        2026-09-21 ran daemon defaults. The operator curating a six-member
        team had no effect on anything."""
        if not self._is_orchestrator():
            return ""
        try:

            roster = TeamStore(self.paths).team_list()
        except Exception:  # noqa: BLE001 — no roster, no section
            return ""
        rows = []
        for m in roster:
            mid = str(m.get("id") or "")
            if not mid or str(m.get("kind") or "") == "singleton":
                # Singletons are the system agents (you are one of them).
                continue
            engine = str(m.get("client") or "claude-code")
            model = str(m.get("model") or "").strip() or "CLI default"
            owns = str(m.get("owns") or "").strip()
            rows.append(
                f"- `{mid}` · {m.get('name') or mid} — {owns} [{engine} · {model}]"
            )
        if not rows:
            return (
                "## Your team\n\n"
                "**This project has no delegable members** — only system "
                "agents. Dispatch with `agent_type` alone; every subagent "
                "will run the daemon defaults. Tell the operator once: a "
                "member card is what gives a worker its CLI, model and "
                "standing instructions."
            )
        return (
            "## Your team — who you dispatch INTO\n\n"
            + "\n".join(rows)
            + "\n\nPut the member id on the dispatch body: "
            '`{"conv": "work-<init>-<task>-<stamp>", "member": "<id>", '
            '"text": "…", "initiative_id": "…", "task_id": "…", '
            '"parent_conv": "<your conv>"}`. The daemon then runs that turn '
            "with the member's CLI, model, effort and init prompt, and the "
            "cockpit shows the work under that member's name. Omit it and you "
            "get an anonymous agent on daemon defaults — which is what the "
            "operator curated the roster to stop.\n\n"
            "Choose by the `owns` line, not by the name. One member can hold "
            "several of your dispatches; they are separate conversations."
        )

    def _section_core_rules(self) -> str:
        # SINGLE source of truth: the live daemon port the runner injected.
        # Fall back to the per-project port file only when the builder was
        # constructed without a daemon back-ref (rare non-dispatch paths), and
        # to 5570 only as an absolute last resort.
        port = self.daemon_port
        if not port:
            try:
                port = int(self.paths.port_file.read_text().strip())
            except (OSError, ValueError):
                port = 5570
        # py-1.10.14 — single source of truth for the in-prompt base URL.
        # HTTPS over `daemon.meshkore.com:<port>` when the TLS bundle is
        # present (the default since D-TLS-01), plain HTTP only as
        # back-compat. Plain `http://localhost:<port>` against a
        # TLS-wrapped socket returns RST and breaks every spawned agent.
        base = _daemon_base_url(port)

        # py-1.7.0 — Universal rules: every agent type sees these every
        # turn. Short, load-bearing. These are NOT role-specific.
        universal = [
            "## Universal rules (every agent, every turn)",
            "",
            "- Don't push to git unless the user explicitly asks.",
            f"- Don't invent version numbers; ask `POST {base}/version/next`.",
            "- Never edit `.meshkore/credentials/`, `.meshkore/.runtime/` or generated `state.json`.",
            "- The Architect IDE auto-refreshes ~2s after any write under `.meshkore/` — don't tell the user to reload.",
            "- Reply concisely — follow the **Output contract** below. The portal renders your stdout as the chat answer.",
            "- **Mention initiatives and tasks by their `#<id>` in chat output** (Standard §22, v20+). When you add, remove, rename, defer, or otherwise touch a roadmap item, the operator-facing line MUST start with — or contain — `#<id>`. Example: `✓ added #I18 task #T-vote-API`, `✗ removed #T-fixture-loader from #I19`, `↻ split #I21 into #I21 + #I27`. This lets the operator click-locate the item in the roadmap UI; bare titles in chat are not enough.",
            "- **Anchor every turn to (initiative, task)** (Standard §24, v23+; `anchor.v1` wire protocol, py-1.12.31+). The FIRST line of EVERY assistant reply MUST be a structured anchor marker — the daemon parses it, persists to `conv_meta`, creates files if needed, and STRIPS the line from the output the user sees. Four valid shapes:",
            '    `⟦anchor⟧ {"i":"<init_id>","t":"<task_id>"}`                              — both exist; resolve + persist',
            '    `⟦anchor⟧ {"new_i":{"id","title","oneliner","modules":[...]},"new_t":{"id","title","category"}}`  — create both',
            '    `⟦anchor⟧ {"new_t":{"id","title","category","initiative":"<existing>"}}`  — task in existing init',
            '    `⟦anchor⟧ {"info":true}`                                                  — informational turn (no anchor)',
            '  Mid-turn task transitions: emit `⟦anchor-progress⟧ {"t":"<task_id>","status":"done"}` when you finish a task; the daemon writes `status: done` to the .md file. Then emit a NEW `⟦anchor⟧` if you\'re starting the next task in the same turn.',
            '  Frontmatter contracts the daemon enforces: initiative slug `^[a-z][a-z0-9-]{1,31}$`; task id `^[A-Za-z][A-Za-z0-9_-]{1,31}$`; exactly one module per task (Standard §4). The newly-created files land at the top of the Architect IDE\'s roadmap timeline with a ✨ NEW badge — that IS the chronology of "what is happening right now". Full recipe + worked examples: `.meshkore/docs/conventions/initiative-anchored-execution.md`.',
            '  **`i` is the initiative\'s lowercase SLUG (its file-stem `id`, exactly as it appears in the cluster state) — NOT the `#`-prefixed display id you use in chat.** Never build a slug from the display number. ✗ `{"i":"I32-model-v9-points-only"}` (that\'s the `#I32` display id glued to a title). ✓ `{"i":"model-v9-points-only"}` (the real file-stem). If you can see an initiative as `#I32` but don\'t know its slug, read `.meshkore/roadmap/initiatives/` and copy the actual filename stem. To CREATE a new initiative use `new_i` — do not invent an `i` for one that doesn\'t exist on disk.',
            '  Decision chain when conv_meta is empty: (a) read `.meshkore/roadmap/initiatives/` **AND `.meshkore/roadmap/initiatives/log/`** (the archive — superseded/closed work-streams are MOVED there, so an active-only listing will miss them); if one matches the operator\'s intent by title+oneliner+module → emit `⟦anchor⟧ {"i":"<match>","t":"<existing-task>"}`. **Prefer reusing an existing story — even an archived one — over minting a near-duplicate.** When the new work is the SAME work-stream resumed or widened (e.g. you\'re extending a finished `web-redesign`, not starting unrelated work), anchor to that old slug: the daemon auto-reactivates it — moves it back out of `log/` and flips its status to `active` — so it rejoins the live roadmap. Only mint a NEW initiative when the work is a genuinely distinct work-stream, not merely "similar". (b) if no real match, CREATE a new initiative + 1-3 tasks via `⟦anchor⟧ {"new_i":{...},"new_t":{...}}` (pick a slug derived from the operator\'s request; modules from the area you\'ll touch); (c) if the user\'s question is purely informational (e.g. "¿qué versión del daemon?"), emit `⟦anchor⟧ {"info":true}` instead.',
            "",
            "## Output contract — how your chat answer is shaped (EVERY agent, EVERY turn)",
            "",
            "The operator reads your stdout on a chat wall and decides from a 5-second scan — NOT a full read. This contract OVERRIDES any urge to be thorough in the visible answer. Thoroughness goes inside collapsible blocks, never at the top level.",
            "",
            "1. **Lead with a ≤8-line summary.** Answer the actual question first: what you found / what you'll do, which files or areas you touch, and the plan as N steps. No preamble, no restating the request, no 'I'll now…'.",
            "2. **All detail lives inside `<details>` blocks** — one per file or topic. Anything beyond the summary (per-file findings, SQL/code specifics, legacy-field lists, audit results, rationale) MUST be wrapped so the operator expands only what they care about. The Architect IDE renders `<details>` as a native click-to-expand block:",
            "       <details><summary>apps/api/src/pieces/list.rs — 3 changes</summary>",
            "",
            "       - reads `?cx&cy&r`, adds bbox filter, caps `LIMIT 1000`",
            "       - drops legacy `Tile` fields (cx/cy/span/tint/…)",
            "       </details>",
            "   The `<summary>` is a ONE-LINE headline: `<file> — <N changes>` or `<topic> — <verdict>`. Leave a BLANK LINE after the `</summary>`'s line so the markdown inside (lists, code fences) renders.",
            "3. **No detail prose outside a `<details>`.** If a paragraph or bullet list isn't part of the ≤8-line summary, it belongs in a details block. Never dump a wall of bullets at the top level.",
            "4. **Don't narrate process** ('I read X, then checked Y…'). State conclusions; the operator asks for steps if they want them.",
            "5. When unsure, go SHORTER. The operator can click to expand or ask a follow-up — they cannot un-read 50 lines. A reply that needs scrolling has failed this contract.",
            "",
            "Full rationale + worked before/after: `.meshkore/docs/conventions/output-contract.md`.",
            "",
            "## MeshKore standard (where things live)",
            "",
            "- `.meshkore/` — everything the cluster knows lives here. The operator never edits it by hand; you do.",
            "- `.meshkore/modules/<id>/` — module-scoped work. Tasks live at `.meshkore/modules/<id>/tasks/*.md`.",
            "- `.meshkore/roadmap/initiatives/*.md` — initiatives (work-streams). Status: `active` / `next` / `backlog` / `done`.",
            "- `.meshkore/log/<UTC-date>.md` — daily activity log (diary). **One short paragraph per relevant event** (1–4 sentences, ≤ 1 200 chars). NEVER paste full diffs, full task lists, full file dumps — point at the artifact (`commit <sha>`, `task <id>`) and summarise the outcome. The diary must stay readable end-to-end; a turn that mutates ≥3 files writes ONE summary line, not one per file.",
            "- `.meshkore/docs/coverage.md` — coverage matrix (requirement → which task delivers it).",
            "- `.meshkore/agents/_types/<agent-type>/memory.md` — your role's long-term memory (see below).",
            "",
            "## Daemon endpoints you should know",
            "",
            f"- Base URL: `{base}` (use exactly this — the loopback listener uses TLS; plain `http://localhost:<port>` is reset by the socket).",
            f"- **Project routing — CENTRALIZED daemon (read this before deciding the daemon is 'down').** You are operating on project `{self.cluster.id}`. The daemon at `{base}` is ONE central daemon that serves MANY projects at the same port, routed by the `X-MeshKore-Project` header. EVERY daemon request for THIS project MUST carry `X-MeshKore-Project: {self.cluster.id}` — e.g. `curl -sk -H 'Authorization: Bearer <token>' -H 'X-MeshKore-Project: {self.cluster.id}' {base}/chat/dispatch -d '{{...}}'`. WITHOUT the header the daemon answers for its DEFAULT project, so a bare `{base}/health` or `/state` can report a DIFFERENT `cluster_id` (e.g. `meshkore-server`) — that is EXPECTED and is NOT a 'wrong cluster' or a 'daemon down' for you. There is NO per-project daemon to start: member projects intentionally have NO `.meshkore/scripts/daemon.py` (only a `.pyc`/runtime may remain) — do NOT `git checkout` it, do NOT launch it on another port; the central daemon already serves you on `{base}` via the header. To dispatch a subagent for this project, POST `{base}/chat/dispatch` WITH the `X-MeshKore-Project: {self.cluster.id}` header and the bearer token.",
            f"- `POST {base}/version/next` — get the next valid version for a key (never invent numbers).",
            f"- `POST {base}/log/append` (or just append to `.meshkore/log/<UTC-date>.md` directly) — operator activity log.",
            f"- `GET  {base}/state` — current cluster state (initiatives, tasks, modules, integrity flags).",
            f"- `POST {base}/chat/dispatch` — used by the Architect IDE; you receive your prompt via this path, you don't call it.",
            f"- `GET  {base}/debug/tail?last=<secs>&tag=<csv>&level=<min>` — structured JSONL of everything that just happened (chat-dispatch, architect-wake, subagent-final, init-archive, http, Architect IDE logs). 30-min rolling window. Read this BEFORE asking the operator anything — most bugs reveal themselves here. See `.meshkore/docs/conventions/debug-stream.md`.",
            f'- `POST {base}/verify` — **MeshKore Verify**: render a UI at a reachable URL in a headless browser and get back screenshots (mobile+desktop), console/network errors, layout heuristics, and a pass/fail verdict — so you can SEE your own frontend work, not just narrate it. **On-demand, not per-edit**: call it when the operator asks you to check/verify the UI, or when you suspect a render/flow is broken (collapsed layout, blank page, dead button) — a one-word or copy change does NOT need it. Body: `{{"url":"…","conv":"<this-conv>"}}`; optional `steps` (click/fill/waitFor/assert) and `checks.api`. The shot PNGs come back as `shots[].loopback` paths you open with your image reader. The URL must be reachable: a login-walled page needs `state.cookies` / `state.headers` / `state.basic_auth` in the body, else you\'ll only screenshot the login screen. See `.meshkore/docs/conventions/verify.md`.',
            "- Privileged endpoints (`/chat/dispatch`, `/version/next`, `/log/append`, `/runs`, `/verify`, …) require `Authorization: Bearer <portal-token>`; the token lives at `.meshkore/credentials/portal-token`. `/health` and `/state` are open.",
            "- If a request fails with `Connection reset by peer` or `Recv failure`, you're talking to the TLS socket over plain HTTP — switch the scheme to `https://` and retry. This is NOT a daemon outage.",
            "",
            "## How to flag persistent learnings",
            "",
            "- When you discover something other agents of your role would want to know next time (a credential location, a flaky test pattern, a migration gotcha), end your reply with a line: `REMEMBER: <one short fact>`.",
            "- The daemon harvests `REMEMBER:` lines and appends them to your role's `memory.md`. Don't write to that file directly.",
            "",
            "Reference docs:",
            "  - https://api.meshkore.com/v1/standard.json — canonical schemas",
            "  - https://meshkore.com/cluster/operate — operator manual",
            "  - `.meshkore/docs/context.md` — project-specific context (if present)",
            "  - `.meshkore/docs/conventions/*.md` — repo conventions",
        ]

        # General coder ('custom') additionally owns the roadmap, so it
        # gets the granularity rules. Service agents don't.
        if self.agent_type == "custom":
            general_coder_extras = [
                "",
                "## Module / task / initiative authority (General coder only)",
                "",
                "- When you create a new module directory `.meshkore/modules/<id>/`, ALSO add `{id: <id>, kind: area, name: '<Title>'}` to `cluster.yaml.modules[]`.",
                "- Every initiative you mark `active` or `next` must have ≥1 child task linked via `initiative: <id>` in the task's frontmatter. Use `status: backlog` for placeholders.",
                "",
                "### Task granularity",
                "",
                "- Target grain: **one task ≈ one week of focused work**.",
                "- If a candidate task would take > 2 weeks to deliver, split it (with `depends_on:` chains).",
                "- If a candidate task would take < 2 days, fold it into a sibling or the parent task's body.",
                "- Every task body MUST end with a `## Done when` section listing 2-5 concrete acceptance criteria the operator can verify without asking you.",
                "",
                "### Initiative granularity",
                "",
                '- Each initiative = **ONE coherent work-stream**, never a phase or release name. ✓ "Auth & identity", "Payments & credits". ✗ "MVP", "Phase 1", "Closed beta".',
                "- Target shape: **3-8 child tasks** in `active` / `next` status.",
                "- **Hard limit: never > 12 active/next tasks** per initiative. The integrity check (next turn's briefing) flags over-dense initiatives.",
                "- **Lower limit: ≥ 2 child tasks** for any active/next initiative. If only 1 task fits — fold, or drop the initiative back to `backlog`.",
                "- When SPLITTING an initiative: create the new files first, re-point each child task's `initiative:` frontmatter, then move the old file to `.meshkore/roadmap/initiatives/log/<old-id>.md` with `status: superseded` + `superseded_by:`.",
                "- An initiative's `## Done when` is the WORK-STREAM completion signal, verifiable independently.",
                "",
                "### Coverage matrix",
                "",
                "- When you create or modify any task / initiative, update `.meshkore/docs/coverage.md` to reflect it. Create the file if missing.",
            ]
            return "\n".join(universal + general_coder_extras)
        return "\n".join(universal)

    def _section_anchor_nudge(self) -> str:
        """LAL10 — daemon-side anchor enforcement. When the previous turn(s)
        on this conv produced no anchor marker, the runner persisted an
        `anchor_missing` counter in conv_meta. Surface it here as a hard
        reminder so the miss is corrected next turn even if the agent
        skimmed the core rules. Empty (no section) when the conv is clean.
        Client-agnostic: plain text, no tool-calls, identical for every
        CLI driver (claude/codex/gemini/muse)."""
        meta: Any = {}
        try:
            data = getattr(self.cluster, "data", None) or {}
            meta = (data.get("conv_meta") or {}).get(self.conv) or {}
        except Exception:
            meta = {}
        if not meta:
            try:
                import json as _json

                mp = self.paths.runtime / "conv_meta.json"
                if mp.is_file():
                    meta = (_json.loads(mp.read_text() or "{}") or {}).get(
                        self.conv
                    ) or {}
            except Exception:
                meta = {}
        try:
            misses = int((meta or {}).get("anchor_missing") or 0)
        except (TypeError, ValueError):
            misses = 0
        if misses <= 0:
            return ""
        return (
            "## ⚠ ANCHOR MISSING — correct this turn\n\n"
            f"Your previous {misses} turn(s) on this conv emitted NO anchor marker. "
            "The queue is showing a stale initiative until you anchor.\n\n"
            "Your FIRST line this turn MUST be one of:\n"
            '  `⟦anchor⟧ {"i":"<slug>","t":"<task_id>"}` (reuse — prefer this, check '
            "the archive `initiatives/log/` too)\n"
            '  `⟦anchor⟧ {"new_t":{"id":"<ID>","title":"<t>","category":"<module>",'
            '"initiative":"<slug>"}}` (small follow-up: create a TEMPORAL task, do '
            "the fix, then mark it done with "
            '`⟦anchor-progress⟧ {"t":"<ID>","status":"done"}`)\n'
            '  `⟦anchor⟧ {"info":true}` (ONLY if this turn truly touches no work)\n'
        )

    def _section_agent_focus(self) -> str:
        # py-1.7.0 — Service agents get their narrow focus block. The
        # General coder doesn't (it has no narrowing focus — its scope
        # is the whole cluster).
        prompt = AGENT_PROMPTS.get(self.agent_type) or AGENT_PROMPTS["custom"]
        focus = prompt.get("focus") or ""
        return focus.strip()

    def _section_agent_redirect(self) -> str:
        # py-1.7.0 — Out-of-scope policy for service agents. General
        # coder has nothing to redirect.
        prompt = AGENT_PROMPTS.get(self.agent_type) or AGENT_PROMPTS["custom"]
        redirect = prompt.get("redirect") or ""
        if not redirect.strip():
            return ""
        return "## Out-of-scope policy\n\n" + redirect.strip()

    def _section_agent_memory(self) -> str:
        # py-1.7.0 — Per-type long-term memory at
        # `.meshkore/agents/_types/<agent-type>/memory.md`. Populated by
        # the daemon when the agent ends a turn with `REMEMBER: …`
        # lines. Shared across all conversations of the same role.
        try:
            mem_path = self.paths.agents_dir / "_types" / self.agent_type / "memory.md"
            if not mem_path.exists():
                return ""
            txt = mem_path.read_text(errors="replace").strip()
            if not txt:
                return ""
            # Cap to ~4 KB so this section never dominates the briefing.
            if len(txt) > 4096:
                txt = txt[-4096:]
                # Trim to start of next line so we don't cut mid-entry.
                nl = txt.find("\n")
                if nl > 0:
                    txt = txt[nl + 1 :]
            return (
                f"## Your role's accumulated memory "
                f"(`agents/_types/{self.agent_type}/memory.md`)\n\n"
                f"{txt}\n\n"
                "These are facts past instances of your role have flagged "
                "as worth remembering. Use them; don't repeat them back."
            )
        except Exception:
            return ""

    def _section_cluster_snapshot(self) -> str:
        n_ini = len(self.project.initiative_files())
        n_tasks = len(self.project.task_files())
        declared_mods = self.cluster.data.get("modules") or []
        n_decl_mods = len(declared_mods) if isinstance(declared_mods, list) else 0
        n_dir_mods = len(self.project.module_dirs())
        bits = [
            f"- {n_ini} initiative(s) at `.meshkore/roadmap/initiatives/`",
            f"- {n_tasks} task(s) across modules (excluding the wizard's T1-hello boilerplate)",
            f"- {n_decl_mods} module(s) declared in `cluster.yaml.modules[]`",
        ]
        if n_dir_mods != n_decl_mods:
            bits.append(
                f"- {n_dir_mods} module directory(ies) on disk — mismatch with declared"
                " (see Integrity section below)"
            )
        return "## Cluster snapshot\n\n" + "\n".join(bits)

    def _section_project_mode(self) -> str:
        if not self.project.is_empty():
            return ""
        # py-1.4.3 — Scale the target task count by brief size. Briefs
        # in the kilobytes deserve more granular task decomposition than
        # "build a todo list" one-liners. Sources of brief size,
        # in order of preference: context.md (already written),
        # accumulated chat.user texts in this conv, the current
        # user_text. The number is heuristic, not enforced — the agent
        # picks a sensible point inside the range.
        brief_chars = self._estimate_brief_size()
        if brief_chars < 500:
            ini_range, task_range, breadth = "1-2", "3-8", "tiny"
        elif brief_chars < 2000:
            ini_range, task_range, breadth = "2-4", "8-15", "small"
        elif brief_chars < 5000:
            ini_range, task_range, breadth = "3-5", "15-25", "medium"
        elif brief_chars < 10000:
            ini_range, task_range, breadth = "3-6", "25-40", "large"
        else:
            ini_range, task_range, breadth = "4-8", "40-60", "comprehensive"
        return "\n".join(
            [
                "## Project mode: BOOTSTRAPPING (empty cluster)",
                "",
                f"The cluster at `{self.paths.root}` has 0 initiatives + 0 real",
                "tasks. Your purpose right now is to bootstrap the roadmap,",
                "not to interrogate the user until you have a perfect brief.",
                "",
                "**Write FIRST, talk SECOND.** As soon as the user has given",
                "you ANY substantive description of the project — its goal,",
                "audience, rough scope, any constraint — STOP asking",
                "clarifying questions and write:",
                "",
                f"### Brief size: ≈ {brief_chars} chars → {breadth} scope",
                "",
                f"  - **{ini_range} initiatives** at `.meshkore/roadmap/initiatives/<id>.md`",
                "    (frontmatter per `initiative` schema). Each initiative is a",
                '    **coherent work-stream**, named by what it builds: "Auth &',
                '    identity", "Canvas viewer", "Anchoring chain", "Payments",',
                '    "Observability". NEVER name initiatives by phase ("MVP",',
                '    "Phase 1", "Closed beta") — those collapse into one giant',
                "    catch-all card and break the roadmap UX. Target 3-8 child",
                "    tasks per initiative; hard limit 12. The next-turn integrity",
                "    check flags initiatives that exceed that.",
                f"  - **{task_range} initial tasks** distributed across modules",
                "    under `.meshkore/modules/<module>/tasks/<id>.md`. Bias",
                "    towards MORE tasks if the brief is long — every numbered",
                "    section, every rule, every explicit deliverable that's",
                "    in scope for Phase 1 should map to either a task or an",
                "    explicit `defer: <reason>` marker in coverage.md (see",
                "    below). Each task ≈ one week of focused work; split",
                "    tasks that exceed two weeks; fold tasks under two days.",
                "    Module directories MUST be declared in `cluster.yaml.modules[]`",
                "    on creation (otherwise the Architect IDE tree won't show them).",
                "  - A short `.meshkore/docs/context.md` capturing goal,",
                "    audience, constraints, and non-obvious decisions from the",
                "    brief. Frontmatter per `doc_frontmatter`.",
                "",
                "### Coverage matrix (mandatory deliverable)",
                "",
                "Write `.meshkore/docs/coverage.md` mapping EVERY numbered",
                "section, EVERY rule, and EVERY explicit deliverable in the",
                "user's brief to a task id OR a `defer: <reason>` marker.",
                "This is what makes the roadmap auditable — without it, gaps",
                "stay invisible until someone notices a feature wasn't built.",
                "Required shape (3 sections, in order):",
                "",
                "```markdown",
                "---",
                "title: Coverage matrix",
                "updated: YYYY-MM-DD",
                "owner: <you>",
                "---",
                "",
                "# Coverage matrix — `<cluster>`",
                "",
                "Maps every brief requirement to a task id or a deferral.",
                "Maintained on every roadmap-modifying turn.",
                "",
                "## Sections",
                "",
                "| Source | Requirement | Coverage |",
                "|---|---|---|",
                "| §4 Cosmology | Halo FIFO eviction | API7 |",
                "| §4 Cosmology | Oort decay state machine | WEB5 |",
                "| §6 Economic | Referral program | defer: Phase 4 (growth) |",
                "",
                "## Rules",
                "",
                "| # | Rule | Coverage |",
                "|---|---|---|",
                "| 1 | AI-only generation | AI1 |",
                "| 10 | Named zones | defer: Phase 5 (B2B) |",
                "",
                "## Explicit deliverables",
                "",
                "| Deliverable | Coverage |",
                "|---|---|",
                "| Architecture document | DOC1 |",
                "| Risk register | DOC2 |",
                "```",
                "",
                "Rules for the Coverage column:",
                "- Task id (e.g., `WEB2`) → that task addresses the requirement",
                "- `defer: <one-line reason>` → out of scope for current phase",
                "- `?` / `TBD` / empty → integrity check will flag it on the",
                "  next turn. Don't leave these in the final output.",
                "",
                "### Other rules for this bootstrap turn",
                "",
                "Mark assumptions with `> assumption: …` inside file bodies.",
                "Every task body ends with `## Done when` (2-5 acceptance",
                "criteria, observable, present tense).",
                "",
                "When done writing, reply with: (a) one short paragraph summary,",
                "(b) at MOST two open questions whose answers would materially",
                "change the plan. Do NOT paste file contents back — the",
                "Architect IDE auto-refreshes within ~2 seconds.",
                "",
                "If the user said almost nothing (literally 'hi', 'test',",
                "one-word), ask ONE focused question and stop. Never more.",
                "",
                "Once this turn lands files, the cluster is no longer empty",
                "and this section disappears from future briefings.",
            ]
        )

    def _estimate_brief_size(self) -> int:
        """Best-available signal for how big the project brief is.
        Drives the bootstrap task-count target. Sources, in order:
        (1) context.md if present, (2) accumulated chat.user texts in
        the current conv from .meshkore/timeline/, (3) the current
        user_text. Returns total chars."""
        # Source 1: context.md (already written on prior turns).
        ctx = self.paths.docs_dir / "context.md"
        if ctx.exists():
            try:
                size = len(ctx.read_text(errors="replace"))
                if size > 0:
                    return size
            except OSError:
                pass
        # Source 2: sum of all chat.user texts in this conv.
        total = 0
        try:
            if self.paths.timeline_dir.exists():
                for f in sorted(self.paths.timeline_dir.glob("*.jsonl")):
                    try:
                        for line in f.read_text(errors="replace").splitlines():
                            try:
                                ev = json.loads(line)
                            except json.JSONDecodeError:
                                continue
                            if (
                                ev.get("conv") == self.conv
                                and ev.get("type") == "chat.user"
                            ):
                                total += len(ev.get("text") or "")
                    except OSError:
                        continue
        except Exception:
            pass
        if total > 0:
            return total
        # Source 3: this turn's user_text.
        return len(self.user_text or "")

    def _section_jobs(self) -> str:
        """REL1 — tell every agent that background jobs exist.

        The operator's report (2026-09-21): an agent was asked to start a
        long-running process, the process was not running, and nothing in
        the cockpit said so. Part of that is this: the jobs control plane
        (JL-1) shipped with no mention anywhere in the briefing, so an
        agent's only option was to run the thing inside its own turn —
        where it dies with the turn. Short on purpose: the full contract
        is discoverable from `GET /jobs`."""
        base = self._base_url()
        running = []
        try:
            reg = getattr(self.daemon, "jobs_registry", None)
            if reg is not None:
                for j in reg.list():
                    if str(j.get("status") or "") == "running":
                        running.append(str(j.get("id") or "?"))
        except Exception:
            running = []
        lines = [
            "## Long-running processes → jobs (never your own turn)",
            "",
            "A dev server, a watcher, a training loop, a tunnel: start it as"
            " a JOB and the daemon owns it as its own child, so it survives"
            " your turn, the browser and you. Anything you start inside your"
            " turn dies with the turn — that is the bug, not the fallback.",
            "",
            f"- start:   `POST {base}/jobs` "
            '`{"id":"gen-loop","name":"Generator","command":"make run",'
            '"cwd":"<abs path>","port":8791}`',
            f"- list:    `GET {base}/jobs` · stop / start / restart:"
            f" `POST {base}/jobs/<id>/{{stop,start,restart}}`",
            "- The operator sees every job (and its log) in the cockpit's"
            " Jobs tab, per project. Say the job id in your reply.",
        ]
        if running:
            lines.append(f"- running right now: {', '.join(running[:8])}")
        return "\n".join(lines)

    def _base_url(self) -> str:
        """The daemon base URL as the briefing must state it. Same
        resolution the other sections do inline (live port → per-project
        port file → 5570), in one place."""
        port = self.daemon_port
        if not port:
            try:
                port = int(self.paths.port_file.read_text().strip())
            except (OSError, ValueError):
                port = 5570
        return _daemon_base_url(port)

    # REL1 — how many integrity items may reach a briefing, and how much
    # room they get. Measured 2026-09-21 on this cluster: 67 violations
    # rendered 228,800 chars — ~57k tokens, 70% of EVERY turn's prompt, on
    # every agent, forever (it grows with the roadmap). The hints are a
    # nice-to-have nudge; they were crowding out the actual work. The
    # agent is told the full count and where to get the rest.
    INTEGRITY_MAX_ITEMS = 6
    INTEGRITY_MAX_CHARS = 2400

    def _section_integrity(self) -> str:
        violations = self.integrity.check()
        if not violations:
            return ""
        by_kind: Dict[str, int] = {}
        for v in violations:
            by_kind[str(v.get("kind", "unknown"))] = (
                by_kind.get(str(v.get("kind", "unknown")), 0) + 1
            )
        tally = ", ".join(f"{k}×{n}" for k, n in sorted(by_kind.items()))
        shown = violations[: self.INTEGRITY_MAX_ITEMS]
        lines = [
            "## Integrity hints (please fix as part of this turn)",
            "",
            f"State-integrity check found {len(violations)} issue(s) ({tally}).",
            "They are NOT blocking — proceed with the user's request first,"
            " then fix as you go.",
            (
                f"Showing the first {len(shown)};"
                " the rest are the same kinds — the tally above is the whole picture."
                if len(shown) < len(violations)
                else ""
            ),
            "",
        ]
        for v in shown:
            kind = v.get("kind", "unknown")
            fix = v.get("fix", "(no fix suggested)")
            if kind == "module_not_declared":
                lines.append(f"- **Orphan module** `{v.get('module_id')}` — {fix}")
            elif kind == "task_initiative_broken":
                lines.append(
                    f"- **Broken initiative ref** task=`{v.get('task_id')}`"
                    f" → initiative=`{v.get('initiative_ref')}` — {fix}"
                )
            elif kind == "initiative_without_tasks":
                lines.append(
                    f"- **Initiative without tasks** `{v.get('initiative_id')}`"
                    f" (status: `{v.get('status')}`) — {fix}"
                )
            elif kind == "initiative_too_dense":
                lines.append(
                    f"- **Initiative too dense** `{v.get('initiative_id')}`"
                    f" carries {v.get('child_count')} active/next tasks"
                    f" — {fix}"
                )
            elif kind == "context_coverage_gap":
                toks = v.get("tokens") or []
                pretty = ", ".join(
                    f"`{t.get('token')}` ({t.get('mentions')}×)" for t in toks
                )
                lines.append(
                    f"- **Potential coverage gaps (tokens)** — {pretty} — {fix}"
                )
            elif kind == "coverage_doc_missing":
                lines.append(f"- **Coverage matrix missing** — {fix}")
            elif kind == "coverage_gaps_in_doc":
                n = v.get("count", "?")
                lines.append(f"- **Coverage matrix has {n} unresolved row(s)** — {fix}")
            else:
                lines.append(f"- **{kind}** — {fix}")
        out = "\n".join(line for line in lines if line != "")
        if len(out) > self.INTEGRITY_MAX_CHARS:
            out = out[: self.INTEGRITY_MAX_CHARS] + "\n- … (truncated)"
        return out

    def _section_cockpit_context(self) -> str:
        if not self.context_docs:
            return ""
        lines = [
            "## Context attached by the operator's Architect IDE",
            "",
            "The architect Architect IDE sent these documents alongside the",
            "user's message. Treat them as authoritative context for this",
            "turn (operator's intent, scope, recent UI state).",
            "",
        ]
        for doc in self.context_docs:
            if not isinstance(doc, dict):
                continue
            fname = doc.get("filename") or "(unnamed)"
            content = (doc.get("content") or "").strip()
            if not content:
                continue
            lines.append(f"### `{fname}`")
            lines.append("")
            lines.append(content)
            lines.append("")
        return "\n".join(lines).rstrip()

    def _section_history(self) -> str:
        turns = _conversation_history(self.paths, self.conv)
        if not turns:
            return ""
        return "## Recent turns in this conversation\n\n" + "\n".join(turns)

    def _section_consult_addendum(self) -> str:
        """py-1.10.8 — When the roadmap-architect dispatches a question
        to the onboarding/_onboarding_v1 conv with the [architect-consult]
        prefix, A001 (the project coordinator) must DECIDE on the
        operator's behalf, not bounce back. This addendum is injected
        only for that exact pattern."""
        body = (self.user_text or "").strip()
        if not body.startswith("[architect-consult]"):
            return ""
        if self.conv != "_onboarding_v1":
            return ""
        return (
            "## [architect-consult] mode — DECIDE, don't bounce\n\n"
            "The roadmap-architect is mid-pass and needs a decision YOU "
            "must make on the user's behalf. The user pressed Run all "
            "specifically so they would NOT be in the loop. Bouncing "
            "the question to them defeats the whole feature.\n\n"
            "Your authority for this turn:\n"
            "- You have full power to pick. The architect will execute "
            "whatever you say.\n"
            "- Read `.meshkore/agents/_types/custom/memory.md`, "
            "`.meshkore/roadmap/initiatives/*.md`, recent chat history, "
            "any README, the project vision — anything that surfaces "
            "the user's preferences. Pick the option most aligned.\n"
            "- When in doubt, prefer: the simpler option, the cheaper "
            "option, the option that keeps shipping velocity, the "
            "option that matches the cluster's existing tech defaults.\n\n"
            "Reply format — STRICT:\n"
            "- ONE paragraph, <80 words.\n"
            "- First sentence: the decision in plain language.\n"
            "- Second sentence: one-line rationale.\n"
            "- That's it. No preamble, no caveats, no \"happy to "
            'discuss", no follow-up question.\n\n'
            "If — and ONLY if — the question is genuinely about the "
            "PRODUCT IDEA (not implementation, not tech choice, not "
            "design defaults), reply with the literal string:\n"
            "    DEFER:<one-line reason what's conceptually unclear>\n"
            "The architect will defer that single task to the end of "
            "the pass and continue with the rest. Use this sparingly — "
            "it's the only escape valve and it shouldn't be your "
            "default."
        )

    def _section_user_turn(self) -> str:
        body = self.user_text.strip() if self.user_text else ""
        if not body:
            return "## User just said\n\n(empty message)"
        return "## User just said\n\n" + body


# ── inlined from daemon/coordination.py (DM3+ bundle) ─────────────────────────
"""coordination.py — extracted from daemon.py (daemon-architecture-v2 Phase 2).

CoordinationMixin: methods moved VERBATIM; Daemon inherits it so every self.*
still resolves on the combined instance -> byte-identical."""


import re

from typing import Any, Dict, List, Optional, Tuple



#: BT-19 — a task id as briefs write it: `#ONB1`, `DASH3`, `SEL-2`.
_TASK_REF_RE = re.compile(r"#?\b([A-Z]{2,}[A-Z0-9]*-?[0-9]+[a-z]?)\b")


def _brief_first_line(brief: str) -> str:
    """BT-16 — the first non-empty line of a brief, ≤200 chars."""
    for line in str(brief or "").splitlines():
        line = " ".join(line.split())
        if line:
            return line if len(line) <= 200 else line[:199] + "…"
    return ""


class CoordinationMixin:
    def _dispatch_mutex_check(
        self,
        *,
        conv: str,
        agent_type: Optional[str],
        parent_conv: Optional[str],
        task_id: Optional[str],
        initiative_id: Optional[str] = None,
        depth: Optional[int] = None,
    ) -> Optional[Tuple[int, Dict[str, Any]]]:
        """py-1.10.25 — server-side enforcement of dispatch invariants
        the architect prompt claims but the LLM sometimes ignores.
        Returns `None` to allow the dispatch, or `(409, body)` to reject.

        Invariants enforced (both observed broken in cavioca 2026-05-30):

        1. **Single live roadmap-architect.** At most one
           `roadmap-architect-*` conv may have a live ChatRunner. A
           wake to the SAME conv is allowed (it's just the next turn
           on the existing architect); a dispatch to a DIFFERENT
           `roadmap-architect-*` while one is alive is refused.

        2. **No parallel dispatch on the same (parent_conv, task_id).**
           If the architect already dispatched task `T` and that conv
           is still streaming, a second dispatch on the same (parent,
           task) pair is refused. Prevents two subagents racing on
           the same file commits.

        The architect catches 409s on its bash tool and (per the
        prompt addendum below) should treat them as "wait for the
        wake, don't retry". Cockpit reads the `hint` and surfaces
        a soft notice.
        """
        # py-1.10.26 — Pause check FIRST. If the agent_type is in
        # cool-down because of a recent rate-limit hit, refuse 503
        # with a hint that names the ETA. Architect prompt update
        # below tells it to NOT retry — wait, or switch type.
        # `roadmap-architect` itself is exempted (we don't want to
        # lock the coordinator out of its own conv just because a
        # subagent hit a wall). The architect can still narrate +
        # dispatch other types or different convs.
        norm_target = _agent_type_normalised(agent_type)
        if norm_target != "roadmap-architect":
            pause = self._agent_type_is_paused(norm_target)
            if pause is not None:
                return 503, {
                    "error": "agent-type-paused",
                    "agent_type": norm_target,
                    "reason": pause.get("reason"),
                    "expires_at": pause.get("expires_at"),
                    "expires_epoch": pause.get("expires_epoch"),
                    "hint": (
                        f"Agent type `{norm_target}` is paused until "
                        f"{pause.get('expires_at')} (rate-limit cooldown). "
                        "Wait for the window to reset, switch to a "
                        "different agent_type, or `POST /agent-types/"
                        f"{norm_target}/unpause` to override."
                    ),
                }

        is_architect_target = (agent_type == "roadmap-architect") or conv.startswith(
            "roadmap-architect-"
        )
        live = self.chat_sessions.list_active()

        # Invariant 1: single live roadmap-architect.
        # Match BOTH by slug AND by stored agent_type in conv_meta —
        # the slug is the canonical signal for cockpit-spawned convs
        # but custom-named convs can also carry the agent_type via
        # /chat/dispatch body, and we must catch both.
        if is_architect_target:
            all_meta = self._conv_meta_load()
            others: List[str] = []
            for c in live:
                if c == conv:
                    continue
                slug_arch = c.startswith("roadmap-architect-")
                meta_arch = (
                    _agent_type_normalised((all_meta.get(c) or {}).get("agent_type"))
                    == "roadmap-architect"
                )
                if slug_arch or meta_arch:
                    others.append(c)
            if others:
                return 409, {
                    "error": "roadmap-architect-already-live",
                    "hint": (
                        "Another roadmap-architect conv is already running. "
                        "Stop it first (POST /chat/cancel) before spawning a new one."
                    ),
                    "existing_convs": others,
                    "requested_conv": conv,
                }

        # Invariants 2 + 3 both need the conv_meta sidecar.
        if parent_conv:
            all_meta = self._conv_meta_load()

            # HD-1 (hierarchical-delegation) — tree guards. These are what
            # make "any agent may delegate" safe to switch on: the wake hook
            # used to be roadmap-architect-only precisely because nothing
            # here stopped a custom conv from delegating to itself, or a
            # chain from growing without bound. All three are cheap sidecar
            # reads; all three refuse with a hint the agent can act on.
            tree_err = self._delegation_tree_check(
                conv=conv,
                parent_conv=parent_conv,
                depth=depth,
                live=live,
                all_meta=all_meta,
            )
            if tree_err is not None:
                return tree_err

            # Invariant 2: no parallel dispatch on same (parent_conv, task_id).
            # Only meaningful when both parent_conv and task_id are set —
            # i.e., the architect dispatching a subagent.
            if task_id:
                for live_conv in live:
                    if live_conv == conv:
                        continue
                    m = all_meta.get(live_conv) or {}
                    if (
                        m.get("parent_conv") == parent_conv
                        and m.get("task_id") == task_id
                    ):
                        return 409, {
                            "error": "task-already-dispatched",
                            "hint": (
                                f"Task `{task_id}` (parent `{parent_conv}`) "
                                f"already has a live dispatch: `{live_conv}`. "
                                "Wait for the [architect-wake] on its final; "
                                "do not retry while it's still running."
                            ),
                            "existing_conv": live_conv,
                            "parent_conv": parent_conv,
                            "task_id": task_id,
                        }

            # Invariant 3 (py-1.10.28): single initiative in-flight per
            # architect. Operator's product decision (2026-05-31): "una
            # iniciativa a la vez, tareas en paralelo DENTRO pero no
            # mezclando entre iniciativas". The architect is allowed
            # to dispatch parallel tasks within initiative I, but
            # cannot start I+1 while ANY task on I still has a live
            # subagent. The 409 hint names the live initiative(s) so
            # the architect knows what it's waiting on. Linear-roadmap
            # mode prevents half-finished initiatives + reduces quota
            # burn on speculative parallel work.
            if initiative_id:
                live_initiatives: set = set()
                for live_conv in live:
                    if live_conv == conv:
                        continue
                    m = all_meta.get(live_conv) or {}
                    if m.get("parent_conv") != parent_conv:
                        continue
                    other = m.get("initiative_id")
                    if other:
                        live_initiatives.add(other)
                if live_initiatives and initiative_id not in live_initiatives:
                    return 409, {
                        "error": "initiative-already-in-flight",
                        "hint": (
                            "Linear-roadmap mode: another initiative still "
                            f"has live subagents (`{', '.join(sorted(live_initiatives))}`). "
                            f"Wait for ALL its tasks to finish (or mark them "
                            f"blocked) before dispatching into "
                            f"`{initiative_id}`. Parallel work is allowed "
                            "INSIDE a single initiative, never across."
                        ),
                        "live_initiatives": sorted(live_initiatives),
                        "requested_initiative": initiative_id,
                        "parent_conv": parent_conv,
                    }

        # py-1.12.0 — Worker-dispatch invariants. Only fire when this
        # dispatch is creating/touching a `work-*` subagent slot. The
        # architect's own dispatches (roadmap-architect-*) and the
        # operator's free-form custom convs sidestep these checks —
        # they're not "worker dispatches", they're conversation starts.
        is_worker_dispatch = conv.startswith("work-")
        if is_worker_dispatch:
            # Invariant 5: required join keys. work-* dispatches MUST
            # carry both `initiative_id` AND `task_id` so that
            # Invariants 2+3 actually fire. Pre-py-1.12.0 a dispatch
            # missing either field would silently slip past the
            # mutex (line 6325 was guarded by `if task_id:`, line 6354
            # by `if initiative_id:`). The architect prompt already
            # requires both fields; this turns "should send" into
            # "must send" with a clear 400 if it forgets.
            if not initiative_id or not task_id:
                missing = []
                if not initiative_id:
                    missing.append("initiative_id")
                if not task_id:
                    missing.append("task_id")
                return 400, {
                    "error": "worker-dispatch-missing-join-keys",
                    "missing": missing,
                    "hint": (
                        f"`{conv}` is a work-* subagent dispatch — it MUST "
                        f"include both `initiative_id` AND `task_id` in the "
                        f"POST body so the daemon can enforce linear-init + "
                        f"depends_on. Missing: {', '.join(missing)}. Re-read "
                        f"the SOP `EXECUTION LOOP — LINEAR INITIATIVES` block."
                    ),
                }

            # Invariant 4: wave cap. The architect prompt promises
            # "max 3 parallel"; enforce it here so a runaway loop or a
            # confused turn can't spawn 7 workers and 5x the quota burn.
            # Cap is configurable via cluster.yaml.architect.wave_cap;
            # default 3 (matches the prompt). Per-parent_conv so two
            # operators on the same cluster (different architect convs)
            # each get their own wave budget.
            cap = self._wave_cap()
            if parent_conv:
                same_wave = 0
                all_meta_w = self._conv_meta_load()
                for live_conv in live:
                    if live_conv == conv:
                        continue
                    if not live_conv.startswith("work-"):
                        continue
                    m = all_meta_w.get(live_conv) or {}
                    if m.get("parent_conv") == parent_conv:
                        same_wave += 1
                if same_wave >= cap:
                    return 429, {
                        "error": "wave-cap-reached",
                        "wave_cap": cap,
                        "current_wave_size": same_wave,
                        "parent_conv": parent_conv,
                        "hint": (
                            f"This architect already has {same_wave} work-* "
                            f"subagent(s) in flight (cap={cap}). Wait for a "
                            f"slot to free up via [architect-wake] before "
                            f"dispatching the next task. Operator can raise "
                            f"the cap via `cluster.yaml.architect.wave_cap` "
                            f"(higher = faster, more quota burn + more "
                            f"chance of git-race)."
                        ),
                    }

            # Invariant 6: depends-on gate. Refuse the dispatch if the
            # target task's `depends_on:` frontmatter lists upstream
            # tasks that are NOT marked `done`. The architect should
            # already serialise via depends_on at the prompt level —
            # this is the server-side belt to the prompt's braces.
            # Cheap: reads one task .md file + checks the upstream
            # statuses we already cache in `_state['roadmap']['tasks']`.
            missing_deps = self._unfinished_dependencies(task_id, initiative_id)
            if missing_deps:
                return 409, {
                    "error": "task-dependencies-not-done",
                    "task_id": task_id,
                    "initiative_id": initiative_id,
                    "missing": missing_deps,
                    "hint": (
                        f"Task `{task_id}` declares `depends_on: "
                        f"{missing_deps}` in its frontmatter but those "
                        f"upstream task(s) are not `done` yet. Finish "
                        f"them first (or remove the dependency if it's "
                        f"stale). Do NOT retry this dispatch until then."
                    ),
                }

        return None

    def _member_session_conv(self, member: str) -> Optional[str]:
        """HD-12 — the ONE live conv this member is running in, or None.

        A member is a person, not a ticket. `deployer` is a chair somebody
        is sitting in: you hand it work, you do not clone it. Archived convs
        do not count (they are history, we never delete them), and among
        several live ones — a roster that predates HD-12 can have leftover
        `dg-deployer-*` convs — the most recently touched wins, so work
        converges on one session instead of splitting again."""
        try:
            all_meta = self._conv_meta_load() or {}
        except Exception:  # noqa: BLE001
            return None
        candidates: List[Tuple[str, str]] = []
        for conv, meta in all_meta.items():
            if not isinstance(meta, dict):
                continue
            if str(meta.get("member") or "").strip() != member:
                continue
            try:
                if self.chat_archive.is_archived(conv):
                    continue
            except Exception:  # noqa: BLE001 — archive lookup is best-effort
                pass
            candidates.append((conv, str(meta.get("updated_at") or "")))
        if not candidates:
            return None
        preferred = f"mb-{member}"
        for conv, _ in candidates:
            if conv == preferred:
                return conv
        candidates.sort(key=lambda c: (c[1], c[0]), reverse=True)
        return candidates[0][0]

    def _member_sessions_mode(self, member: str) -> str:
        """`single` or `per-brief`, from the member card (BT-19)."""
        try:

            fm = (self.team_store.team_get(member) or {}).get("frontmatter") or {}
            return member_sessions_mode(member, fm)
        except Exception:  # noqa: BLE001 — no card readable: the default

            return member_sessions_mode(member, {})

    def _new_member_session_name(
        self, member: str, all_meta: Dict[str, Any], suffixed: bool = False
    ) -> str:
        """`mb-<member>`, unless that name is already taken by an ARCHIVED
        session — reusing it would dispatch into the operator's history and
        silently resurrect a closed thread. We never delete convs, so the
        suffix is how a member gets a second life."""
        base = f"mb-{member}"
        if base not in all_meta and not suffixed:
            return base
        import secrets

        for _ in range(4):
            candidate = f"{base}-{secrets.token_hex(2)}"
            if candidate not in all_meta:
                return candidate
        return f"{base}-{secrets.token_hex(4)}"

    def _delegation_chain(self, conv: str) -> List[str]:
        """The convs from the root down to `conv`, inclusive.

        For a member session the chain is not `parent_conv` — it has many —
        so it is carried ON each request and the deepest open one wins. That
        is what keeps the cycle and depth guards meaningful once the tree
        stops being a tree and becomes a graph of sessions."""
        reqs = self._delegation_requests(conv)
        if reqs:
            deepest = max(reqs, key=lambda r: len(r.get("chain") or []))
            chain = [str(c) for c in (deepest.get("chain") or [])]
            if conv not in chain:
                chain.append(conv)
            return chain
        return [str(c) for c in reversed(self._conv_meta_ancestors(conv))] + [conv]

    def _open_request_targets(self, parent_conv: str) -> List[str]:
        """Member sessions currently holding a brief from `parent_conv`."""
        out: List[str] = []
        try:
            all_meta = self._conv_meta_load() or {}
        except Exception:  # noqa: BLE001
            return out
        for conv, meta in all_meta.items():
            if not isinstance(meta, dict):
                continue
            reqs = meta.get("open_requests")
            if not isinstance(reqs, list):
                continue
            if any(str((r or {}).get("parent_conv")) == parent_conv for r in reqs):
                out.append(conv)
        return out

    def chat_delegate(self, body: Dict[str, Any]) -> Tuple[int, Dict[str, Any]]:
        """HD-3/HD-12 — `POST /chat/delegate`: hand a step to a catalog member.

        Body: `parent_conv` (the caller), `member` (catalog id), `brief`
        (what to do), optional `initiative_id` / `task_id` / `module_id`.

        The brief goes to the member's ONE session (HD-12), created on first
        use and reused ever after — so five agents that all need a deploy
        queue five briefs with the SAME deployer, which then decides that
        three of them are one deploy. Before this each delegation minted its
        own `dg-<member>-<hex>` conv, which meant five deployers deploying
        the same tree at the same time, and a rail nobody could read.

        The brief is delivered live: if that session is mid-turn the
        existing chat queue merges it into its next turn, so the member
        always sees the whole batch it is holding. Returns
        `202 {conv, request_id, open_requests, reused}`."""
        if not isinstance(body, dict):
            return 400, {"error": "JSON object body required"}
        parent_conv = str(body.get("parent_conv") or "").strip()
        member = str(body.get("member") or "").strip()
        brief = str(body.get("brief") or body.get("text") or "").strip()
        missing = [
            k
            for k, v in (
                ("parent_conv", parent_conv),
                ("member", member),
                ("brief", brief),
            )
            if not v
        ]
        if missing:
            return 400, {"error": "delegate-missing-fields", "missing": missing}
        if not self.team_store.exists(member):
            return 400, {"error": f"unknown team member {member!r}", "member": member}
        all_meta = self._conv_meta_load() or {}
        if parent_conv not in all_meta:
            return 404, {
                "error": "unknown-parent-conv",
                "parent_conv": parent_conv,
                "hint": "parent_conv must be YOUR conv id (the one you were dispatched on).",
            }
        import secrets

        # HD-11 — the brief INHERITS the caller's anchor unless overridden.
        # Without this every delegated step anchors itself somewhere else and
        # one unit of work ends up split across several roadmap entries.
        parent_meta = all_meta.get(parent_conv) or {}
        initiative_id = (
            str(body.get("initiative_id") or "").strip()
            or str(parent_meta.get("initiative_id") or "").strip()
        )
        task_id = (
            str(body.get("task_id") or "").strip()
            or str(parent_meta.get("task_id") or "").strip()
        )
        parent_member = str(parent_meta.get("member") or "").strip()
        parent_label = (
            f"{parent_member}@{parent_conv}" if parent_member else parent_conv
        )

        # BT-19 — a member works on each brief in its OWN session (parallel,
        # bounded by the fan-out cap below) unless its card says
        # `sessions: single` — git-manager and deployer, where one session
        # batching every brief is the point (HD-12: three frontend changes,
        # one deploy).
        single = self._member_sessions_mode(member) == "single"
        existing = self._member_session_conv(member) if single else None
        conv = existing or self._new_member_session_name(
            member, all_meta, suffixed=not single
        )

        # ── guards, computed on the REQUEST's lineage ──────────────────
        chain = self._delegation_chain(parent_conv)
        if conv == parent_conv or conv in chain:
            return 409, {
                "error": "delegation-cycle",
                "member": member,
                "conv": conv,
                "chain": chain,
                "hint": (
                    f"`{conv}` is already upstream of you in this unit of work — "
                    "asking it to do your step would deadlock you both. Do this part "
                    "yourself, or report `blocked` naming what you need."
                ),
            }
        max_depth = self._delegation_max_depth()
        if len(chain) >= max_depth:
            return 409, {
                "error": "delegation-max-depth",
                "depth": len(chain),
                "max_depth": max_depth,
                "hint": (
                    f"this brief would sit at depth {len(chain)} and the cluster's "
                    f"limit is {max_depth} (`cluster.yaml#delegation.max_depth`). "
                    "Do it yourself or report `partial`."
                ),
            }
        cap = self._wave_cap()
        held = [t for t in self._open_request_targets(parent_conv) if t != conv]
        if len(held) >= cap:
            return 429, {
                "error": "delegation-fan-out",
                "open_with": held,
                "wave_cap": cap,
                "hint": (
                    f"you already have briefs open with {len(held)} member(s) and the "
                    f"cap is {cap} (`cluster.yaml#architect.wave_cap`). End your turn, "
                    "read the reports, then hand over the next one."
                ),
            }

        request_id = f"rq-{secrets.token_hex(3)}"
        request = {
            "id": request_id,
            "parent_conv": parent_conv,
            "parent_label": parent_label,
            "brief": brief[:400],
            "initiative_id": initiative_id or None,
            "task_id": task_id or None,
            "chain": chain,
            "at": _iso_now(),
        }
        ledger = self._delegation_request_add(conv, request, spawned=not existing)
        if existing:
            # BT-11 — the session we picked may have closed itself (its last
            # request answered) between the lookup above and the ledger
            # write. Dispatching into it would resurrect an archived thread,
            # so the brief moves to a fresh, empty session instead.
            try:
                raced = self.chat_archive.is_archived(conv)
            except Exception:  # noqa: BLE001
                raced = False
            if raced:
                self._delegation_requests_close(conv, [request_id])
                existing = None
                conv = self._new_member_session_name(
                    member, self._conv_meta_load() or {}
                )
                ledger = self._delegation_request_add(conv, request, spawned=True)
        others = [r for r in ledger if str(r.get("id")) != request_id]

        anchor_line = (
            f"Anchor for THIS request: initiative `{initiative_id}` / task `{task_id}` — "
            f'inherited from `{parent_label}`. Emit `⟦anchor⟧ {{"i":"{initiative_id}","t":"{task_id}"}}` '
            "for the work you do on it; do NOT create a new initiative or task.\n\n"
            if initiative_id and task_id
            else ""
        )
        batch_line = ""
        if others:
            lines = "\n".join(
                f"- `{r.get('id')}` from `{r.get('parent_label') or r.get('parent_conv')}`"
                f" — {str(r.get('brief') or '')[:120]}" + _fmt_request_amendments(r)
                for r in others
            )
            batch_line = (
                f"**You are already holding {len(others)} other open "
                f"{'request' if len(others) == 1 else 'requests'}:**\n\n{lines}\n\n"
                "Look at the whole batch before you act. If several of them collapse "
                "into ONE piece of work — three frontend changes that need one deploy — "
                "do it once and report once, listing every request id it covers in "
                "`for`. That judgement is the reason you are a session and not a "
                "queue.\n\n"
            )
        # BT-19 — a brief that names several tasks reports each one as it
        # closes. A ⟦report⟧ is read only at the END of a turn, so mid-turn
        # progress goes over HTTP; the parent is woken without the request
        # closing. mf27: a four-task brief said nothing for 45 minutes.
        tasks_named = sorted(set(_TASK_REF_RE.findall(brief)))
        progress_line = (
            f"This brief names {len(tasks_named)} tasks. Each time ONE of them is done "
            "(committed or handed to git-manager), tell the requester right away — "
            "don't wait for the end: `POST /chat/progress` (same host and headers "
            f'as `/chat/delegate` in `## Your team`) with `{{"conv":"<your conv id>",'
            f'"for":["{request_id}"],"summary":"<one sentence: which task, what now '
            'works>"}`. Then keep going; the final ⟦report⟧ still closes the request.\n\n'
            if len(tasks_named) >= 2
            else ""
        )
        text = (
            f"[delegated by `{parent_label}` · request `{request_id}`]\n\n{brief}\n\n"
            f"{batch_line}{anchor_line}{progress_line}"
            f"Commit trailers for this work: `Agent: {member}`, `Model:`, `MeshKore:`, "
            f"`Parent: {parent_label}`.\n\n"
            "When you have answered a request, end your final reply with the ⟦report⟧ "
            "line described in `## Your team`, naming the request ids it closes in "
            f'`"for"` (e.g. `"for":["{request_id}"]`). That is what wakes whoever asked. '
            "Do not write a diary entry for a delegated step; the agent that owns the "
            "unit of work writes one for the whole thing."
        )
        req: Dict[str, Any] = {
            "conv": conv,
            "text": text,
            "member": member,
            "author": f"delegate:{parent_conv}",
        }
        if initiative_id:
            req["initiative_id"] = initiative_id
        if task_id:
            req["task_id"] = task_id
        if body.get("module_id"):
            req["module_id"] = str(body["module_id"]).strip()
        code, resp = self.chat_dispatch(req)
        if code >= 400:
            # Never leave a brief in the ledger that nobody was told about:
            # the member would be woken for work it never received.
            self._delegation_requests_close(conv, [request_id])
            return code, resp
        # BT-16 — the box in the PARENT's thread: who got what.
        emit = getattr(self, "_emit_delegate_event", None)
        if emit is not None:
            emit(
                parent_conv,
                "delegate.sent",
                child_conv=conv,
                member=member,
                request_id=request_id,
                initiative_id=initiative_id or None,
                task_id=task_id or None,
                brief=_brief_first_line(brief),
            )
        _log(
            f"delegate: {parent_conv} → {conv} ({member}, request {request_id}, "
            f"{len(ledger)} open, {'reused' if existing else 'new session'})"
        )
        return 202, {
            "ok": True,
            "conv": conv,
            "member": member,
            "request_id": request_id,
            "reused": bool(existing),
            "open_requests": len(ledger),
            "depth": len(chain),
            "parent_conv": parent_conv,
            "initiative_id": initiative_id or None,
            "task_id": task_id or None,
            **({"queued": True} if resp.get("queued") else {}),
        }

    def chat_progress(self, body: Dict[str, Any]) -> Tuple[int, Dict[str, Any]]:
        """BT-19 — `POST /chat/progress {conv, summary, for?}`: a member
        tells whoever asked that one part of its brief is done, mid-turn.
        Same effect as a `status:"progress"` ⟦report⟧ (the parent is woken,
        the request stays open), but it does not have to end a turn."""
        if not isinstance(body, dict):
            return 400, {"error": "JSON object body required"}
        conv = str(body.get("conv") or body.get("child_conv") or "").strip()
        summary = " ".join(str(body.get("summary") or body.get("text") or "").split())
        missing = [k for k, v in (("conv", conv), ("summary", summary)) if not v]
        if missing:
            return 400, {"error": "progress-missing-fields", "missing": missing}
        pending = self._delegation_requests(conv)
        if not pending:
            return 409, {
                "error": "no-open-requests",
                "conv": conv,
                "hint": "nobody is waiting on this conv — there is no one to tell.",
            }
        named = body.get("for") or (
            [body["request_id"]] if body.get("request_id") else []
        )
        named = [str(x) for x in named] if isinstance(named, list) else []
        report = {"status": "progress", "summary": summary[:300], "for": named}
        self._wake_on_progress(
            child_conv=conv,
            child_agent_id=None,
            child_final_text="",
            child_report=report,
            pending=pending,
        )
        ids = [r.get("id") for r in pending if not named or str(r.get("id")) in named]
        return 200, {
            "ok": True,
            "conv": conv,
            "request_ids": ids or [r.get("id") for r in pending],
        }

    def chat_amend(self, body: Dict[str, Any]) -> Tuple[int, Dict[str, Any]]:
        """BT-13 — `POST /chat/amend`: change a brief that is already in flight.

        mf27, 2026-09-28: the Orchestrator handed #SEL1 to the developer as
        "20 clubs"; a minute later the operator told the Architect "LaLiga
        only, 42 clubs". There was no way to reach the developer, so the
        change was lost. Now the parent posts the amendment here: it is
        recorded on every open request it holds (or only `request_id`) and
        delivered to each child session — merged into its next step when
        it is mid-turn. A child that already passed the work on amends its
        own children the same way, one level at a time.

        Body: `parent_conv` (the caller), `text`, optional `request_id`.
        Returns `200 {amended:[{conv, request_id}]}`."""
        if not isinstance(body, dict):
            return 400, {"error": "JSON object body required"}
        parent_conv = str(body.get("parent_conv") or "").strip()
        text = str(body.get("text") or body.get("amendment") or "").strip()
        only = str(body.get("request_id") or "").strip()
        missing = [
            k for k, v in (("parent_conv", parent_conv), ("text", text)) if not v
        ]
        if missing:
            return 400, {"error": "amend-missing-fields", "missing": missing}
        all_meta = self._conv_meta_load() or {}
        if parent_conv not in all_meta:
            return 404, {
                "error": "unknown-parent-conv",
                "parent_conv": parent_conv,
                "hint": "parent_conv must be YOUR conv id (the one you were dispatched on).",
            }
        at = _iso_now()
        targets: List[Tuple[str, Dict[str, Any]]] = []
        with self._delegation_lock():
            self._conv_meta_cache = None
            all_meta = self._conv_meta_load() or {}
            touched: List[str] = []
            for conv, meta in all_meta.items():
                if not isinstance(meta, dict):
                    continue
                reqs = meta.get("open_requests")
                if not isinstance(reqs, list):
                    continue
                changed = False
                for r in reqs:
                    if not isinstance(r, dict):
                        continue
                    if str(r.get("parent_conv") or "") != parent_conv:
                        continue
                    if only and str(r.get("id") or "") != only:
                        continue
                    amends = r.get("amendments")
                    amends = list(amends) if isinstance(amends, list) else []
                    amends.append({"at": at, "text": text[:2000]})
                    r["amendments"] = amends
                    targets.append((conv, dict(r)))
                    changed = True
                if changed:
                    touched.append(conv)
            if touched:
                p = self._conv_meta_path()
                p.parent.mkdir(parents=True, exist_ok=True)
                atomic_write_json(p, all_meta, sort_keys=True)
                self._conv_meta_cache = None
        if not targets:
            return 409, {
                "error": "no-open-requests",
                "parent_conv": parent_conv,
                **({"request_id": only} if only else {}),
                "hint": (
                    "nothing you handed out is still open — no child is working on "
                    "it. Apply the change yourself (and to the task spec)."
                ),
            }
        for conv in touched:
            self._broadcast_ledger(conv)
        amended: List[Dict[str, Any]] = []
        for conv, req in targets:
            label = str(req.get("parent_label") or parent_conv)
            rid = str(req.get("id") or "")
            msg = (
                f"[amendment from `{label}` · request `{rid}`]\n\n{text}\n\n"
                "This AMENDS the brief of that request: where the two conflict, the "
                "amendment wins; everything it does not touch still stands.\n\n"
                "1. If you already handed this work (or part of it) to someone else, "
                "amend THEM first: `POST /chat/amend` with "
                f'`{{"parent_conv":"{conv}","text":"<the change, translated to their '
                'slice>"}` (add `request_id` to target one). Say only what changes '
                "for their part.\n"
                "2. Then adapt your own work in progress — including anything already "
                "done that the change invalidates.\n"
                "3. Your report for this request must reflect the amended scope."
            )
            dispatch: Dict[str, Any] = {
                "conv": conv,
                "text": msg,
                "author": f"amend:{parent_conv}",
            }
            meta = all_meta.get(conv) or {}
            if meta.get("member"):
                dispatch["member"] = meta["member"]
            if meta.get("agent_type"):
                dispatch["agent_type"] = meta["agent_type"]
            try:
                code, resp = self.chat_dispatch(dispatch)
            except Exception as e:  # noqa: BLE001
                code, resp = 500, {"error": str(e)}
            entry: Dict[str, Any] = {"conv": conv, "request_id": rid}
            if code >= 400:
                entry["error"] = (
                    resp.get("error") if isinstance(resp, dict) else str(resp)
                )
                _log(f"amend: delivery to {conv} failed ({code}): {resp}")
            elif isinstance(resp, dict) and resp.get("queued"):
                entry["queued"] = True
            if code < 400:
                emit = getattr(self, "_emit_delegate_event", None)
                if emit is not None:
                    emit(
                        parent_conv,
                        "delegate.amended",
                        child_conv=conv,
                        request_id=rid,
                        text=" ".join(text.split())[:200],
                    )
            amended.append(entry)
        _log(f"amend: {parent_conv} amended {len(amended)} request(s)")
        return 200, {"ok": True, "amended": amended, "at": at}

    def _broadcast_ledger(self, conv: str) -> None:
        hub = getattr(self, "hub", None)
        if hub is None:
            return
        try:
            entry = (self._conv_meta_load() or {}).get(conv) or {}
            hub.broadcast(
                {
                    "type": "conv.meta_updated",
                    "conv": conv,
                    "agent_type": entry.get("agent_type"),
                    "member": entry.get("member"),
                    "open_requests": entry.get("open_requests") or [],
                    "ts": _iso_now(),
                }
            )
        except Exception as e:  # noqa: BLE001
            _log(f"amend ledger broadcast failed for {conv}: {e}")

    def _delegation_tree_check(
        self,
        *,
        conv: str,
        parent_conv: str,
        depth: Optional[int],
        live: Any,
        all_meta: Dict[str, Any],
    ) -> Optional[Tuple[int, Dict[str, Any]]]:
        """HD-1 — the three guards that bound a delegation tree.

        Cycle: `conv` may not be its own parent, nor any ancestor of the
        parent (a→b→a). Depth: the child's depth (parent + 1) may not exceed
        `cluster.yaml#delegation.max_depth` (default 3). Fan-out: a parent
        may not have more live children than `architect.wave_cap` — the same
        cap the roadmap-architect's waves already obey, now for every conv.

        Re-entering an EXISTING child (a follow-up turn on the same conv from
        the same parent) passes all three: it is not a new edge."""
        if conv == parent_conv:
            return 409, {
                "error": "delegation-cycle",
                "conv": conv,
                "parent_conv": parent_conv,
                "hint": "A conv cannot delegate to itself.",
            }
        ancestors = self._conv_meta_ancestors(parent_conv)
        if conv in ancestors:
            return 409, {
                "error": "delegation-cycle",
                "conv": conv,
                "parent_conv": parent_conv,
                "ancestors": [parent_conv, *ancestors],
                "hint": (
                    f"`{conv}` is an ancestor of `{parent_conv}` — a child may "
                    "never delegate back up its own tree. Report to your parent "
                    "with a ⟦report⟧ block instead."
                ),
            }
        existing = all_meta.get(conv) or {}
        re_entry = existing.get("parent_conv") == parent_conv
        max_depth = self._delegation_max_depth()
        if depth is not None and depth > max_depth and not re_entry:
            return 409, {
                "error": "delegation-depth-exceeded",
                "conv": conv,
                "parent_conv": parent_conv,
                "depth": depth,
                "max_depth": max_depth,
                "hint": (
                    f"`{parent_conv}` sits at depth {depth - 1}; the tree is "
                    f"capped at {max_depth} (cluster.yaml#delegation.max_depth). "
                    "Do the work yourself and ⟦report⟧ to your parent."
                ),
            }
        if not re_entry:
            cap = self._wave_cap()
            children = [
                c
                for c in live
                if c != conv
                and (all_meta.get(c) or {}).get("parent_conv") == parent_conv
            ]
            if len(children) >= cap:
                return 429, {
                    "error": "wave-cap-reached",
                    "wave_cap": cap,
                    "current_wave_size": len(children),
                    "parent_conv": parent_conv,
                    "children": sorted(children),
                    "hint": (
                        f"`{parent_conv}` already has {len(children)} live "
                        f"child(ren) (cap={cap}). End your turn; each child "
                        "wakes you with its ⟦report⟧ when it finishes, then "
                        "delegate the next one. Operator can raise "
                        "`cluster.yaml.architect.wave_cap`."
                    ),
                }
        return None

    def _delegation_max_depth(self) -> int:
        """HD-1 — `cluster.yaml#delegation.max_depth`, default 3, clamped
        1..8. Depth 0 is the operator's root; 3 allows
        root → developer → deployer → tester without leaving room for
        a runaway chain."""
        try:
            raw = (self.cluster.data.get("delegation") or {}).get("max_depth")
            if raw is None:
                return 3
            return max(1, min(8, int(raw)))
        except Exception:
            return 3

    def _wave_cap(self) -> int:
        """Return the per-architect parallel-worker cap. Read from
        cluster.yaml.architect.wave_cap; default 3 (matches the
        roadmap-architect prompt's stated bound). Operator can widen
        for throughput or narrow for cost."""
        try:
            raw = (self.cluster.data.get("architect") or {}).get("wave_cap")
            if raw is None:
                return 3
            n = int(raw)
            return max(1, min(10, n))  # clamp to a sane range
        except Exception:
            return 3


# ── inlined from daemon/coordwake.py (DM3+ bundle) ─────────────────────────
"""coordwake.py — extracted from coordination.py (daemon-architecture-v2 Phase 3d).

WakeMixin: methods moved VERBATIM out of CoordinationMixin; Daemon inherits both so
every self.* resolves on the combined instance -> byte-identical."""


from pathlib import Path
from typing import Any, Dict, List, Optional



class WakeMixin:
    def _unfinished_dependencies(
        self,
        task_id: Optional[str],
        initiative_id: Optional[str],
    ) -> List[str]:
        """Read the target task's frontmatter and return the subset of
        `depends_on:` references whose current status is NOT `done`.
        Empty list = green light. Returns [] silently on any IO error
        (we don't want a missing file or a bad parse to deadlock the
        architect — the dispatch proceeds and the subagent will hit
        the real problem with a clearer error)."""
        if not task_id or not initiative_id:
            return []
        try:
            # Locate the task .md file under .meshkore/roadmap/initiatives/<init>/<task>.md
            # OR the legacy flat layout. Honour either.
            candidates = [
                self.paths.roadmap_dir
                / "initiatives"
                / initiative_id
                / f"{task_id}.md",
                self.paths.roadmap_dir / "tasks" / f"{task_id}.md",
            ]
            task_path: Optional[Path] = None
            for c in candidates:
                if c.exists():
                    task_path = c
                    break
            if task_path is None:
                return []
            raw = task_path.read_text(errors="replace")
            front = parse_frontmatter(raw)
            deps_raw = front.get("depends_on") if isinstance(front, dict) else None
            if not deps_raw:
                return []
            # Accept either a YAML list or a comma-separated string.
            if isinstance(deps_raw, str):
                deps = [s.strip() for s in deps_raw.split(",") if s.strip()]
            elif isinstance(deps_raw, list):
                deps = [str(s).strip() for s in deps_raw if str(s).strip()]
            else:
                return []
            if not deps:
                return []
            # Read current statuses from the state cache. Build a quick
            # task_id → status map; default to "unknown" (treated as
            # not-done, conservative).
            state = self.state_manager.state()
            status_by_id: Dict[str, str] = {}
            for t in (state.get("roadmap") or {}).get("tasks") or []:
                tid = t.get("id")
                if tid:
                    status_by_id[str(tid)] = str(t.get("status") or "unknown")
            missing: List[str] = []
            for dep in deps:
                if status_by_id.get(dep, "unknown") != "done":
                    missing.append(dep)
            return missing
        except Exception as e:
            _log(f"_unfinished_dependencies({task_id}) raised: {e}")
            return []

    def _maybe_wake_parent_architect(
        self,
        *,
        child_conv: str,
        child_agent_id: Optional[str],
        child_final_text: str,
        child_exit: Optional[int],
        child_report: Optional[Dict[str, Any]] = None,
        parent_conv: Optional[str] = None,
        request_ids: Optional[List[str]] = None,
    ) -> None:
        """Architect-wake hook (initiative `architect-wake-on-subagent`).

        When a child conv emits `chat.assistant.final`, look up its
        recorded `parent_conv`. If the parent is a roadmap-architect
        conv, post a `[architect-wake]` user turn back to it so the
        pass resumes automatically. If the architect is mid-turn the
        wake is merged into its pending queue (chat_sessions.queue);
        if it has already exited the wake spawns a fresh turn. Both
        paths are correct and converge on the same outcome.

        py-1.10.24 — Wake message now annotates the outcome explicitly
        ('success' / 'no-commit' / 'error') + the cumulative unproductive
        count per task_id so the architect cannot ignore the
        DECISION MATRIX rule "Sub-agent failed twice → mark blocked".

        No-op when: no parent recorded; parent isn't a roadmap-architect
        conv; parent conv has been archived/cancelled. Quiet failures —
        a missing wake never blocks the child's final from being
        broadcast.
        """
        # HD-12 — a member session answers to whoever handed it a brief, and
        # that is a LIST. Close the requests this turn covered and wake each
        # requester once; `parent_conv` being passed in means we are already
        # inside that loop and must not re-enter it.
        if parent_conv is None:
            pending = self._delegation_requests(child_conv)
            # BT-10 — a `progress` report is a status line, not an answer:
            # wake whoever asked WITHOUT closing anything.
            if child_report and self._report_outcome(child_report) == "progress":
                self._wake_on_progress(
                    child_conv=child_conv,
                    child_agent_id=child_agent_id,
                    child_final_text=child_final_text,
                    child_report=child_report,
                    pending=pending,
                )
                return
            if pending and not child_report and self._still_working(child_conv):
                # A turn that ended to WAIT — on its own children, or (for
                # the Orchestrator) on the next wake of a multi-turn pass —
                # has answered nothing yet. Closing here told the parent
                # "no-report" the moment its child delegated a sub-step.
                _log(
                    f"delegate-wake: {child_conv} ended a turn with no report while "
                    f"still working — holding {len(pending)} open request(s)"
                )
                return
            if pending:
                named = (child_report or {}).get("for")
                named = [str(x) for x in named] if isinstance(named, list) else []
                closed = self._delegation_requests_close(child_conv, named)
                if not closed and named:
                    # It named ids nobody is holding — a typo must not strand
                    # every parent waiting on this session.
                    _log(
                        f"delegate-wake: {child_conv} reported for {named} but none "
                        "are open — closing the whole batch instead"
                    )
                    closed = self._delegation_requests_close(child_conv, None)
                self._drop_amendments_for(child_conv, closed)
                self._emit_delegate_reports(
                    child_conv=child_conv,
                    closed=closed,
                    child_report=child_report,
                    child_final_text=child_final_text,
                    child_exit=child_exit,
                )
                by_parent: Dict[str, List[str]] = {}
                for r in closed:
                    by_parent.setdefault(str(r.get("parent_conv") or ""), []).append(
                        str(r.get("id") or "")
                    )
                by_parent.pop("", None)
                for pconv, ids in by_parent.items():
                    self._maybe_wake_parent_architect(
                        child_conv=child_conv,
                        child_agent_id=child_agent_id,
                        child_final_text=child_final_text,
                        child_exit=child_exit,
                        child_report=child_report,
                        parent_conv=pconv,
                        request_ids=ids,
                    )
                still = self._delegation_requests(child_conv)
                if still:
                    _log(
                        f"delegate-wake: {child_conv} still holds {len(still)} open "
                        "request(s) — it reported on part of its batch"
                    )
                return
        parent_conv = parent_conv or self._conv_meta_parent(child_conv)
        if not parent_conv:
            _debug_emit(
                "architect-wake.skipped",
                msg=f"no parent_conv recorded for {child_conv}",
                lvl="debug",
                conv=child_conv,
                agent_id=child_agent_id,
            )
            return
        # HD-1 (hierarchical-delegation) — a wake to a parent that no longer
        # exists as a live thread is dropped HERE, loudly. Dispatching into an
        # archived conv would silently resurrect it.
        try:
            if self.chat_archive.is_archived(parent_conv):
                _log(
                    f"delegate-wake: parent {parent_conv} of {child_conv} is "
                    "archived — wake dropped"
                )
                _debug_emit(
                    "delegate-wake.dropped",
                    msg=f"parent {parent_conv} is archived",
                    lvl="warn",
                    conv=child_conv,
                    data={"parent_conv": parent_conv},
                )
                return
        except Exception:  # noqa: BLE001 — archive lookup is best-effort
            pass
        parent_type = _agent_type_from_conv_slug(parent_conv)
        if parent_type != "roadmap-architect":
            # HD-1 — every OTHER parent type gets the general delegate-wake.
            # The cycle / depth / fan-out guards that this branch used to
            # wait for live in coordination._delegation_tree_check, so a
            # custom conv delegating to a catalog member is now resumed
            # exactly like the roadmap-architect always was.
            self._wake_delegating_parent(
                parent_conv=parent_conv,
                child_conv=child_conv,
                child_agent_id=child_agent_id,
                child_final_text=child_final_text,
                child_exit=child_exit,
                child_report=child_report,
                request_ids=request_ids,
            )
            return
        # Build a compact wake message. Architect needs the child id +
        # a preview of the answer to know whether the task succeeded.
        preview = (child_final_text or "").strip()
        if len(preview) > 800:
            preview = preview[:800].rstrip() + " …(truncated)"
        agent_tag = f" ({child_agent_id})" if child_agent_id else ""
        exit_tag = f" exit={child_exit}" if child_exit not in (None, 0) else ""
        # py-1.10.24 — Classify the outcome + count failures per task.
        outcome = self._classify_subagent_final(preview, child_exit)
        # HD-2 — a structured ⟦report⟧ outranks the preview heuristics: the
        # child SAID what happened. `failed`/`blocked` map onto the matrix
        # as an error; `success` still needs a real commit to count.
        if child_report and self._report_outcome(child_report) in (
            "failed",
            "blocked",
        ):
            outcome = "error"
        elif (
            child_report
            and self._report_outcome(child_report) == "success"
            and child_exit in (None, 0)
            and outcome == "no-commit"
        ):
            # BT-19 — a child that SAYS success with `commit: null` is
            # following BT-3 (commits are git-manager's job). No sha in the
            # preview is not a failure; counting it as one burned the retry
            # budget on work that was done (mf27 20:45, #MRK2).
            outcome = "success"
        # Pull the task_id the child was working on so we can name it
        # in the wake AND bump the counter.
        child_meta = self._conv_meta_load().get(child_conv) or {}
        task_id = child_meta.get("task_id") or None
        initiative_id = child_meta.get("initiative_id") or None
        child_agent_type = _agent_type_normalised(child_meta.get("agent_type"))
        fail_count = 0
        verdict_line = ""
        if outcome == "success":
            verdict_line = "VERDICT: ✓ success"
        elif outcome == "rate-limited":
            # py-1.10.26 — Quota exhausted on the upstream CLI. Pause
            # the whole agent_type so the architect doesn't keep
            # throwing dispatches at a wall. Verdict tells it WHY
            # AND how long the cooldown lasts; matrix rule forces
            # mark-blocked-and-move-on (different from a normal fail
            # because no retry helps here).
            pause = self._pause_agent_type(
                child_agent_type,
                reason=f"rate-limited final from {child_conv}",
            )
            verdict_line = (
                f"VERDICT: ⏸ rate-limited — task `{task_id or '?'}` hit the "
                f"`{child_agent_type}` CLI quota. Agent type **paused until "
                f"{pause.get('expires_at')}**; further dispatches of this "
                f"type will return 503. **MATRIX RULE: mark this task "
                f"`blocked: rate-limited` and DO NOT retry — retrying does "
                f"not help until the quota window resets. You CAN dispatch "
                f"a DIFFERENT agent_type (deploy / db / testing / docs / "
                f"review) on other tasks while we wait.**"
            )
        else:
            fail_count = self._bump_task_failure(task_id)
            kind = (
                "no-commit (subagent didn't ship)"
                if outcome == "no-commit"
                else f"error (exit={child_exit})"
            )
            if fail_count >= 2:
                verdict_line = (
                    f"VERDICT: ✗ {kind} — task `{task_id or '?'}` has now "
                    f"failed {fail_count}× this session. **MATRIX RULE: "
                    f"sub-agent failed twice → mark this task `blocked` "
                    f"with the reason and MOVE ON. Do NOT retry a third "
                    f"time.**"
                )
            else:
                verdict_line = (
                    f"VERDICT: ✗ {kind} — task `{task_id or '?'}` fail #{fail_count}. "
                    f"One retry allowed by matrix; after that mark blocked."
                )
        task_tag = f" (init={initiative_id}, task={task_id})" if task_id else ""
        # py-1.10.25 — Pass-complete detection. When no active/next
        # initiative has any task left in {next, active, in_progress},
        # the architect is done and the wake forces the 4-bucket
        # end-of-pass summary instead of allowing more dispatches.
        pass_complete = self._roadmap_pass_complete()
        if pass_complete:
            continuation = (
                "**END-OF-PASS DETECTED.** The roadmap has NO remaining "
                "actionable tasks (every active/next initiative is either "
                "fully shipped or fully blocked). DO NOT dispatch more "
                "subagents. Emit the 4-bucket summary NOW (shipped / "
                "stubs-in-place / deferred-ops / decisions, + "
                "spec-needs-clarification if any), then end your turn. "
                "The pass is closed."
            )
        else:
            continuation = (
                "Continue the roadmap pass: apply the verdict and mark the "
                "originating task done/blocked. **Then re-read the "
                "`## Execution queue` section of your briefing before "
                "choosing what to dispatch** — it is rebuilt from live state "
                "for this turn, and the task you just finished may have made "
                "an EARLIER queue position ready. Dispatch the first "
                "`READY NOW` entry from the top of that list, whichever "
                "initiative it belongs to (or emit the end-of-pass summary "
                "if nothing anywhere is ready)."
            )
        report_block = self._format_report_block(child_report)
        wake_text = (
            f"[architect-wake] Subagent `{child_conv}`{agent_tag}{task_tag} finished{exit_tag}.\n\n"
            f"{verdict_line}\n\n"
            f"{report_block}"
            f"Result preview:\n{preview}\n\n"
            f"{continuation}"
        )
        _debug_emit(
            "architect-wake",
            msg=f"waking {parent_conv} on {outcome} of {child_conv}"
            + (f" (task {task_id} fail#{fail_count})" if fail_count else ""),
            conv=parent_conv,
            agent_id=child_agent_id,
            lvl=("warn" if outcome != "success" and fail_count >= 2 else "info"),
            data={
                "child_conv": child_conv,
                "child_exit": child_exit,
                "outcome": outcome,
                "task_id": task_id,
                "initiative_id": initiative_id,
                "task_fail_count": fail_count,
                "preview_len": len(preview),
                "preview_head": preview[:200],
            },
        )
        try:
            code, resp = self.chat_dispatch(
                {
                    "conv": parent_conv,
                    "text": wake_text,
                    "author": "architect-wake",
                    "agent_type": "roadmap-architect",
                }
            )
            if code >= 400:
                _log(
                    f"architect-wake dispatch to {parent_conv} returned {code}: {resp}"
                )
                _debug_emit(
                    "architect-wake.failed",
                    msg=f"chat_dispatch returned {code}",
                    lvl="warn",
                    conv=parent_conv,
                    data={"code": code, "resp": resp},
                )
        except Exception as e:
            _log(f"architect-wake dispatch raised for {parent_conv}: {e}")
            _debug_emit(
                "architect-wake.failed",
                msg=f"chat_dispatch raised: {e}",
                lvl="error",
                conv=parent_conv,
            )
        # py-1.11.0 — Re-broadcast the PARENT's activity. The wake just
        # re-dispatched the architect (live=true again) or queued it
        # (still live with pending merged). Child broadcast + child
        # auto-archive happen directly from the runner's emit-final
        # path so they fire even when there's no parent to wake.
        self._broadcast_conv_activity(parent_conv)

    # ── BT-16: the parent's thread records the delegation ────────────
    #: statuses a `delegate.report` may carry (the cockpit's contract).
    _DELEGATE_REPORT_STATUSES = ("success", "partial", "failed", "blocked", "done")

    def _emit_delegate_event(
        self, parent_conv: str, ev_type: str, **fields: Any
    ) -> None:
        """One `delegate.*` event in the PARENT conv: persisted to the
        timeline (so `/chat/conv/<parent>/messages` returns it after a
        refresh) and broadcast on the WS with the same shape. Never raises
        — a missing box must not cost a delegation."""
        if not parent_conv:
            return
        ev: Dict[str, Any] = {"type": ev_type, "conv": parent_conv, **fields}
        try:
            ev = _append_timeline(self.paths, ev)
        except Exception as e:  # noqa: BLE001
            _log(f"{ev_type}: timeline append failed for {parent_conv}: {e}")
            ev = {**ev, "ts": ev.get("ts") or _iso_now()}
        hub = getattr(self, "hub", None)
        if hub is not None:
            try:
                hub.broadcast(ev)
            except Exception as e:  # noqa: BLE001
                _log(f"{ev_type}: broadcast failed for {parent_conv}: {e}")

    @staticmethod
    def _one_sentence(text: str, cap: int) -> str:
        one = " ".join(str(text or "").split())
        for stop in (". ", "! ", "? ", "\n"):
            i = one.find(stop)
            if 0 < i < cap:
                one = one[: i + 1]
                break
        return one if len(one) <= cap else one[: cap - 1] + "…"

    def _report_status(
        self, report: Optional[Dict[str, Any]], exit_code: Optional[int]
    ) -> str:
        r = report or {}
        raw = str(r.get("status") or r.get("outcome") or "").strip().lower()
        if raw in self._DELEGATE_REPORT_STATUSES:
            status = raw
        else:
            mapped = self._OUTCOME_ALIASES.get(raw, raw)
            status = (
                mapped
                if mapped in self._DELEGATE_REPORT_STATUSES
                else ("partial" if report else "failed")
            )
        if exit_code not in (None, 0) and status in ("success", "done", "partial"):
            status = "failed"
        return status

    def _emit_delegate_reports(
        self,
        *,
        child_conv: str,
        closed: List[Dict[str, Any]],
        child_report: Optional[Dict[str, Any]],
        child_final_text: str,
        child_exit: Optional[int],
    ) -> None:
        """BT-16 — `delegate.report` in each parent whose requests closed."""
        if not closed:
            return
        try:
            member = str(
                ((self._conv_meta_load() or {}).get(child_conv) or {}).get("member")
                or ""
            )
        except Exception:  # noqa: BLE001
            member = ""
        if not member and _agent_type_from_conv_slug(child_conv) == "roadmap-architect":
            member = "orchestrator"
        r = child_report or {}
        summary = self._one_sentence(
            str(r.get("summary") or "") or child_final_text or "", 300
        )
        status = self._report_status(child_report, child_exit)
        by_parent: Dict[str, List[str]] = {}
        for req in closed:
            p = str(req.get("parent_conv") or "")
            if p:
                by_parent.setdefault(p, []).append(str(req.get("id") or ""))
        for pconv, ids in by_parent.items():
            fields: Dict[str, Any] = {
                "child_conv": child_conv,
                "member": member or None,
                "request_id": ids[0] if len(ids) == 1 else None,
                "request_ids": ids,
                "status": status,
                "summary": summary,
            }
            if not child_report:
                fields["no_report"] = True
            commit = r.get("commit")
            if commit:
                fields["commit"] = str(commit)[:64]
            self._emit_delegate_event(pconv, "delegate.report", **fields)

    # ── BT-10 / BT-11: progress reports and sessions that close ──────
    def _still_working(self, conv: str) -> bool:
        """Did this conv end its turn to WAIT rather than to answer?

        True for any conv with a child still in flight: a member session it
        handed a brief to, or a live conv dispatched with `parent_conv` =
        this one."""
        try:
            if self._open_request_targets(conv):
                return True
        except Exception:  # noqa: BLE001
            pass
        sessions = getattr(self, "chat_sessions", None)
        if sessions is None:
            return False
        try:
            live = [c for c in sessions.list_active() if c != conv]
            all_meta = self._conv_meta_load() or {}
        except Exception:  # noqa: BLE001
            return False
        return any(
            str((all_meta.get(c) or {}).get("parent_conv") or "") == conv for c in live
        )

    def _wake_on_progress(
        self,
        *,
        child_conv: str,
        child_agent_id: Optional[str],
        child_final_text: str,
        child_report: Dict[str, Any],
        pending: List[Dict[str, Any]],
    ) -> None:
        """BT-10 — fan a `progress` report out to the parents of the named
        requests (or of every open one) and leave the ledger untouched."""
        named = child_report.get("for")
        named = {str(x) for x in named} if isinstance(named, list) else set()
        picked = [r for r in pending if str(r.get("id")) in named] or list(pending)
        by_parent: Dict[str, List[str]] = {}
        for r in picked:
            by_parent.setdefault(str(r.get("parent_conv") or ""), []).append(
                str(r.get("id") or "")
            )
        by_parent.pop("", None)
        if not by_parent and not pending:
            legacy = self._conv_meta_parent(child_conv)
            if legacy:
                by_parent[legacy] = []
        summary = self._one_sentence(
            str(child_report.get("summary") or "") or child_final_text or "", 300
        )
        for pconv, ids in by_parent.items():
            for rid in ids or [""]:
                self._emit_delegate_event(
                    pconv,
                    "delegate.progress",
                    child_conv=child_conv,
                    request_id=rid or None,
                    summary=summary,
                )
            try:
                if self.chat_archive.is_archived(pconv):
                    continue
            except Exception:  # noqa: BLE001
                pass
            self._wake_delegating_parent(
                parent_conv=pconv,
                child_conv=child_conv,
                child_agent_id=child_agent_id,
                child_final_text=child_final_text,
                child_exit=None,
                child_report=child_report,
                request_ids=ids,
                progress=True,
            )

    def _archive_conv_auto(self, conv: str, by: str) -> bool:
        """Archive `conv` and tell every cockpit, the way the runner's
        subagent auto-archive does. Never raises."""
        try:
            entry = self.chat_archive.archive(conv, by=by)
        except Exception as e:  # noqa: BLE001
            _log(f"auto-archive of {conv} failed: {e}")
            return False
        hub = getattr(self, "hub", None)
        if hub is not None:
            try:
                hub.broadcast(
                    {
                        "type": "conv.archived",
                        "conv": conv,
                        "archived_at": entry.get("archived_at"),
                        "by": entry.get("by"),
                        "ts": entry.get("archived_at"),
                    }
                )
            except Exception as e:  # noqa: BLE001
                _log(f"conv.archived broadcast failed for {conv}: {e}")
        return True

    @staticmethod
    def _is_delegated_session(conv: str, meta: Dict[str, Any]) -> bool:
        """A conv the delegation rail created: a member session (`mb-*`, or
        stamped `spawned_by_delegation`) or an Orchestrator an agent started.
        The operator's own convs — the coordinator, a tab they opened, an
        Orchestrator they launched from the cockpit — never qualify."""
        if conv == "_onboarding_v1":
            return False
        if meta.get("spawned_by_delegation"):
            return True
        return conv.startswith("mb-") and bool(str(meta.get("member") or "").strip())

    def _close_session_if_done(self, conv: str, *, require_idle: bool = False) -> bool:
        """BT-11 — archive a delegated session that holds no open request.

        Called right AFTER the turn's wake to its parents has been
        dispatched (runner final), and from the reaper's sweep with
        `require_idle` (no turn in flight). The check and the archive run
        under the ledger lock, so a brief being added concurrently either
        lands first (→ kept open) or finds the conv archived and moves to a
        fresh session (coordination.chat_delegate)."""
        with self._delegation_lock():
            self._conv_meta_cache = None
            try:
                meta = (self._conv_meta_load() or {}).get(conv) or {}
            except Exception:  # noqa: BLE001
                return False
            if not self._is_delegated_session(conv, meta):
                return False
            if meta.get("open_requests"):
                return False
            try:
                if self.chat_archive.is_archived(conv):
                    return False
            except Exception:  # noqa: BLE001
                return False
            sessions = getattr(self, "chat_sessions", None)
            if sessions is not None:
                try:
                    if require_idle and sessions.has(conv):
                        return False
                    has_pending = getattr(sessions, "has_pending", None)
                    if has_pending is not None and has_pending(conv):
                        return False
                except Exception:  # noqa: BLE001
                    return False
            queue = getattr(self, "chat_queue_manager", None)
            if queue is not None:
                try:
                    if queue.list(conv):
                        return False
                except Exception:  # noqa: BLE001
                    pass
            ok = self._archive_conv_auto(conv, "auto-member-idle")
        if ok:
            _log(f"session-close: {conv} answered its last request — archived")
        return ok

    def _sweep_idle_delegated_sessions(self) -> int:
        """BT-11 — boot/tick sweep: idle delegated sessions with nothing
        open are archived. BT-19 — so are idle Orchestrator convs (one
        coordinator per project now), and any open request whose parent is
        archived passes to the Architect. Returns how many were closed."""
        try:
            n = self._retire_orchestrators()
            self._reparent_orphan_requests()
        except Exception as e:  # noqa: BLE001
            _log(f"coordinator sweep failed: {e}")
            n = 0
        try:
            all_meta = self._conv_meta_load() or {}
        except Exception:  # noqa: BLE001
            return n
        for conv, meta in list(all_meta.items()):
            if not isinstance(meta, dict) or meta.get("open_requests"):
                continue
            if not self._is_delegated_session(conv, meta):
                continue
            if self._close_session_if_done(conv, require_idle=True):
                n += 1
        return n

    def _drop_amendments_for(self, conv: str, closed: List[Dict[str, Any]]) -> None:
        """BT-19 — an amendment still queued for a request that just closed
        is never delivered: the work it amends is over."""
        sessions = getattr(self, "chat_sessions", None)
        drop = getattr(sessions, "drop_pending", None)
        ids = {str(r.get("id") or "") for r in closed} - {""}
        if drop is None or not ids:
            return

        def stale(author: str, text: str) -> bool:
            if not str(author or "").startswith("amend:"):
                return False
            return any(f"· request `{i}`]" in str(text or "") for i in ids)

        try:
            n = drop(conv, stale)
        except Exception as e:  # noqa: BLE001
            _log(f"drop stale amendments for {conv} failed: {e}")
            return
        if n:
            _log(
                f"delegate-wake: dropped {n} queued amendment(s) for closed request(s) on {conv}"
            )

    # ── BT-19 · one coordinator ──────────────────────────────────────
    def _retire_orchestrators(self) -> int:
        """Archive every idle `roadmap-architect-*` conv. The requests it
        still held (an agent-started pass, BT-10) are closed — it will never
        answer them; the requests it had handed OUT are re-parented next."""
        try:
            all_meta = self._conv_meta_load() or {}
        except Exception:  # noqa: BLE001
            return 0
        sessions = getattr(self, "chat_sessions", None)
        n = 0
        for conv, meta in list(all_meta.items()):
            if not isinstance(meta, dict):
                continue
            if not (
                conv.startswith("roadmap-architect-")
                or _agent_type_normalised(meta.get("agent_type")) == "roadmap-architect"
            ):
                continue
            try:
                if self.chat_archive.is_archived(conv):
                    continue
                if sessions is not None and sessions.has(conv):
                    continue  # a turn in flight finishes; next sweep retires it
            except Exception:  # noqa: BLE001
                continue
            if meta.get("open_requests"):
                self._delegation_requests_close(conv, None)
            if self._archive_conv_auto(conv, "auto-one-coordinator"):
                n += 1
                _log(f"one-coordinator: retired {conv}")
        return n

    def _reparent_orphan_requests(self) -> List[Dict[str, Any]]:
        """An open request whose parent conv is archived would report into
        nothing. Hand it to the Architect, and tell it once what it now
        owns. Returns the moved requests."""
        find = getattr(self, "_architect_conv", None)
        if find is None:
            return []
        architect = find()
        moved: List[Dict[str, Any]] = []
        with self._delegation_lock():
            self._conv_meta_cache = None
            all_meta = self._conv_meta_load() or {}
            touched = []
            member = str((all_meta.get(architect) or {}).get("member") or "")
            label = f"{member}@{architect}" if member else architect
            for conv, meta in all_meta.items():
                if not isinstance(meta, dict) or conv == architect:
                    continue
                reqs = meta.get("open_requests")
                if not isinstance(reqs, list):
                    continue
                for r in reqs:
                    if not isinstance(r, dict):
                        continue
                    parent = str(r.get("parent_conv") or "")
                    if not parent or parent == architect:
                        continue
                    try:
                        gone = self.chat_archive.is_archived(parent)
                    except Exception:  # noqa: BLE001
                        gone = False
                    if not gone:
                        continue
                    r["inherited_from"] = parent
                    r["parent_conv"] = architect
                    r["parent_label"] = label
                    r["chain"] = []
                    moved.append({"conv": conv, **r})
                    if conv not in touched:
                        touched.append(conv)
            if touched:
                p = self._conv_meta_path()
                p.parent.mkdir(parents=True, exist_ok=True)
                atomic_write_json(p, all_meta, sort_keys=True)
                self._conv_meta_cache = None
        if not moved:
            return moved
        lines = "\n".join(
            f"- `{m.get('id')}` → `{m['conv']}` (was for `{m.get('inherited_from')}`)"
            + (f" · task `{m.get('task_id')}`" if m.get("task_id") else "")
            + f" — {' '.join(str(m.get('brief') or '').split())[:140]}"
            for m in moved
        )
        text = (
            "[inherited work] These briefs were handed out by a conv that is "
            "now archived (one coordinator per project: the Orchestrator is "
            "retired). Their reports come to YOU from now on:\n\n"
            f"{lines}\n\n"
            "Nothing to do now unless one of them is no longer wanted (then "
            "`amend` it to stop). Handle each report as your own delegation."
        )
        try:
            self.chat_dispatch(
                {"conv": architect, "text": text, "author": "architect-wake"}
            )
        except Exception as e:  # noqa: BLE001
            _log(f"inherited-work wake to {architect} failed: {e}")
        _log(f"one-coordinator: {len(moved)} orphan request(s) passed to {architect}")
        return moved

    # ── HD-1/HD-2: the general delegate-wake ─────────────────────────
    _REPORT_OUTCOMES = ("success", "partial", "failed", "blocked", "no-recipe")

    #: BT-4 — what CLIs actually write instead of `outcome` (mf27: Muse sent
    #: `{"status":"done","commit":…}`, which read as a partial).
    _OUTCOME_ALIASES = {
        "done": "success",
        "ok": "success",
        "completed": "success",
        "complete": "success",
        "succeeded": "success",
        "error": "failed",
        "failure": "failed",
    }

    @classmethod
    def _report_outcome(cls, report: Optional[Dict[str, Any]]) -> str:
        r = report or {}
        raw = str(r.get("outcome") or r.get("status") or "").strip().lower()
        return cls._OUTCOME_ALIASES.get(raw, raw)

    @staticmethod
    def _format_report_block(report: Optional[Dict[str, Any]]) -> str:
        """Render the child's ⟦report⟧ as a fenced JSON block for the wake
        text, or "" when the child gave none."""
        if not report:
            return ""
        import json

        try:
            body = json.dumps(report, ensure_ascii=False, indent=2, sort_keys=True)
        except Exception:  # noqa: BLE001
            body = str(report)
        return f"Child report:\n```json\n{body}\n```\n\n"

    def _wake_delegating_parent(
        self,
        *,
        parent_conv: str,
        child_conv: str,
        child_agent_id: Optional[str],
        child_final_text: str,
        child_exit: Optional[int],
        child_report: Optional[Dict[str, Any]],
        request_ids: Optional[List[str]] = None,
        progress: bool = False,
    ) -> None:
        """HD-1 — resume ANY parent conv when one of its children finishes.

        The wake is a `[delegate-wake]` user turn on the parent carrying the
        child's ⟦report⟧ verbatim (HD-2) — or an explicit `no-report`
        outcome when the child ended without one, which is a failure the
        parent must handle, not a detail to guess at. Runs through
        `chat_dispatch` so a parent mid-turn gets the wake queued, an idle
        parent gets a fresh turn, and every dispatch invariant still holds.
        The parent's own agent_type / member come from its sidecar so the
        wake turn spawns the same engine the operator configured."""
        outcome = self._report_outcome(child_report)
        if progress:
            outcome = "progress"
        elif outcome not in self._REPORT_OUTCOMES:
            outcome = "no-report" if not child_report else "partial"
        if child_exit not in (None, 0) and outcome in ("success", "partial"):
            # A non-zero exit contradicts a happy report; the exit wins.
            outcome = "failed"
        child_meta = self._conv_meta_load().get(child_conv) or {}
        member = str(child_meta.get("member") or "").strip()
        task_id = child_meta.get("task_id") or None
        preview = (child_final_text or "").strip()
        if len(preview) > 800:
            preview = preview[:800].rstrip() + " …(truncated)"
        who = f"`{child_conv}`" + (f" ({member})" if member else "")
        exit_tag = f" exit={child_exit}" if child_exit not in (None, 0) else ""
        task_tag = f" on task `{task_id}`" if task_id else ""
        if outcome == "progress":
            verdict = (
                "PROGRESS UPDATE — this is a status line, not an answer: the "
                "request stays open and the child keeps working. Relay it to the "
                "operator in ONE sentence from its `summary`. Do not act on it, "
                "do not re-delegate, do not poll — its final report will wake you."
            )
        elif outcome == "no-report":
            verdict = (
                "VERDICT: ✗ no-report — the child ended its turn WITHOUT a "
                "⟦report⟧ block, so its outcome is unknown. Treat it as not "
                "done: read its thread if the preview is not enough, and either "
                "re-delegate with a clearer brief or finish the step yourself."
            )
        elif outcome == "success":
            verdict = "VERDICT: ✓ success — apply the report and continue your task."
        elif outcome == "partial":
            verdict = (
                "VERDICT: ◐ partial — the child did part of the work; its `next` "
                "field says what remains. Decide: finish it yourself or delegate "
                "the remainder."
            )
        elif outcome == "no-recipe":
            verdict = (
                "VERDICT: ✗ no-recipe — the child had no workflow to follow "
                "(e.g. no W10 verify recipe for this project). Nothing was run. "
                "Write the missing recipe or verify by hand; do not re-delegate."
            )
        elif outcome == "blocked":
            verdict = (
                "VERDICT: ⏸ blocked — the child hit something it cannot resolve "
                "(see `next`). Unblock it, route around it, or report blocked to "
                "YOUR parent."
            )
        else:
            verdict = (
                f"VERDICT: ✗ failed{exit_tag} — the child did not complete the "
                "step. One retry with a corrected brief is reasonable; a second "
                "failure means do it yourself or report blocked upward."
            )
        # HD-12 — name the request, because the same session may be holding
        # briefs from other agents and one report can cover several of them.
        req_tag = ""
        if request_ids:
            ids = ", ".join(f"`{i}`" for i in request_ids if i)
            if ids:
                req_tag = (
                    f" answering your request {ids}"
                    if len(request_ids) == 1
                    else f" answering your requests {ids}"
                )
        if outcome == "progress":
            summary = str((child_report or {}).get("summary") or "").strip()
            wake_text = (
                f"[delegate-wake] progress update from {who}{req_tag}{task_tag}.\n\n"
                f"{verdict}\n\n"
                + (f"Summary: {summary}\n\n" if summary else "")
                + f"{self._format_report_block(child_report)}"
                "End your turn after relaying it."
            )
        else:
            wake_text = (
                f"[delegate-wake] {who}{req_tag}{task_tag} finished{exit_tag}.\n\n"
                f"{verdict}\n\n"
                f"{self._format_report_block(child_report)}"
                f"Result preview:\n{preview}\n\n"
                "Continue your own task from here. If you still have other children "
                "in flight, each will wake you the same way — do not poll and do not "
                "re-delegate a step that is already running. When YOUR work is "
                "complete, end with your own ⟦report⟧ if you have a parent."
            )
        parent_type, _parent_agent_id = self._conv_meta_get(parent_conv)
        parent_member = self._conv_meta_get_member(parent_conv)
        _debug_emit(
            "delegate-wake",
            msg=f"waking {parent_conv} on {outcome} of {child_conv}",
            conv=parent_conv,
            agent_id=child_agent_id,
            lvl=("info" if outcome in ("success", "partial", "progress") else "warn"),
            data={
                "child_conv": child_conv,
                "child_exit": child_exit,
                "outcome": outcome,
                "report": child_report,
                "task_id": task_id,
            },
        )
        body: Dict[str, Any] = {
            "conv": parent_conv,
            "text": wake_text,
            "author": "delegate-wake",
            "agent_type": parent_type,
        }
        if parent_member:
            body["member"] = parent_member
        try:
            code, resp = self.chat_dispatch(body)
            if code >= 400:
                _log(f"delegate-wake dispatch to {parent_conv} returned {code}: {resp}")
                _debug_emit(
                    "delegate-wake.failed",
                    msg=f"chat_dispatch returned {code}",
                    lvl="warn",
                    conv=parent_conv,
                    data={"code": code, "resp": resp},
                )
        except Exception as e:  # noqa: BLE001
            _log(f"delegate-wake dispatch raised for {parent_conv}: {e}")
            _debug_emit(
                "delegate-wake.failed",
                msg=str(e),
                lvl="warn",
                conv=parent_conv,
            )
        # Same as the architect branch: the parent is live (or queued) again —
        # flip its `coordinating` / `waiting_on` for the cockpit right away.
        try:
            self._broadcast_conv_activity(parent_conv)
        except Exception:  # noqa: BLE001
            pass


# ── inlined from daemon/pausemgr.py (DM3+ bundle) ─────────────────────────
"""pausemgr.py — extracted from coordination.py (daemon-architecture-v2 Phase 3d).

PauseMixin: methods moved VERBATIM out of CoordinationMixin; Daemon inherits both so
every self.* resolves on the combined instance -> byte-identical."""


import re
import time
from typing import Any, Dict, List, Optional



class PauseMixin:
    def _classify_subagent_final(self, preview: str, exit_code: Optional[int]) -> str:
        """Return one of:
            'success'     — committed work landed AND `git cat-file -e` confirms the sha
            'no-commit'   — turn ended with no commit hash in preview, OR the
                             claimed hash doesn't exist in the repo (py-1.12.0
                             Invariant 7 — ghost commit detection)
            'error'       — non-zero exit (CLI crashed or was killed)
            'rate-limited' — upstream CLI told us the quota is out
        Rate-limit detection runs first because some CLIs report the
        condition with exit=0 + a polite "try again later" message,
        which would otherwise look like a normal `no-commit`."""
        text = preview or ""
        if any(p.search(text) for p in self._RATE_LIMIT_PATTERNS):
            return "rate-limited"
        if exit_code not in (None, 0):
            return "error"
        commit_match = False
        for pat in self._COMMIT_PATTERNS:
            m = pat.search(text)
            if not m:
                continue
            # py-1.12.0 Invariant 7 — verify the claimed sha exists in
            # the repo. Subagents occasionally hallucinate commit
            # hashes; without this check the architect would mark the
            # task `done` and move on, leaving the work undone forever.
            # If the pattern doesn't capture a sha (e.g. the ✓-line
            # pattern) we still trust it — the prompt mandates the
            # commit line too, and we don't want false negatives from
            # a pattern that's intentionally permissive.
            sha = m.group(1) if m.lastindex and m.lastindex >= 1 else None
            if sha and not self._git_commit_exists(sha):
                _log(
                    f"classify: subagent claimed commit {sha} but it doesn't exist in repo — demoting to no-commit"
                )
                _debug_emit(
                    "subagent-final.ghost-commit",
                    msg=f"claimed commit {sha} does not exist",
                    lvl="warn",
                    data={"claimed_sha": sha, "preview_head": text[:200]},
                )
                continue
            commit_match = True
            break
        return "success" if commit_match else "no-commit"

    def _git_commit_exists(self, sha: str) -> bool:
        """Run `git cat-file -e <sha>` from the project root. Returns
        True iff the sha is a valid object in the repo. Silently False
        on any error (no git binary, not a repo, etc.) — the architect
        will get the 'no-commit' verdict and the task fail-counter will
        bump, which is the correct safe default."""
        if not re.match(r"^[0-9a-f]{6,40}$", sha):
            return False
        try:
            import subprocess

            r = subprocess.run(
                ["git", "cat-file", "-e", sha],
                cwd=str(self.paths.root),
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                timeout=5,
            )
            return r.returncode == 0
        except Exception:
            return False

    def _roadmap_pass_complete(self) -> bool:
        """py-1.10.25 — True iff no active/next initiative has any
        non-terminal task left. Used by the architect-wake hook to
        flip the message into "emit the summary and stop" mode when
        the pass has run out of actionable work.

        Terminal task statuses (count as 'done for the pass'):
        `done`, `blocked`, `cancelled`. Anything else (`next`,
        `active`, `in_progress`, `pending-operator`, …) still needs
        an agent.

        Falls back to False on any error — better to keep retrying
        than to falsely terminate a live pass."""
        try:
            snap = self.state_manager.state()
            inits = snap.get("initiatives") or []
            tasks_by_init: Dict[str, List[Dict[str, Any]]] = {}
            for t in (snap.get("roadmap") or {}).get("tasks") or []:
                iid = t.get("initiative")
                if iid:
                    tasks_by_init.setdefault(iid, []).append(t)
            terminal = {"done", "blocked", "cancelled"}
            for it in inits:
                status = normalize_status(it.get("status"))
                if status in ("done", "backlog"):
                    continue
                # active/next/in_progress — does it have actionable tasks?
                kids = tasks_by_init.get(it.get("id"), [])
                if any(normalize_status(k.get("status")) not in terminal for k in kids):
                    return False
            return True
        except Exception:
            return False

    def _pause_agent_type(
        self,
        agent_type: str,
        *,
        reason: str,
        duration_secs: Optional[int] = None,
    ) -> Dict[str, Any]:
        """Pause the quota pool that `agent_type` belongs to. Multiple
        types sharing a platform+model pause together (that's the
        point — they share the same upstream account)."""
        if not agent_type:
            return {}
        m = _agent_manifest(agent_type)
        entry = self.quota.pause(
            m["quota_key"],
            reason=reason,
            duration_secs=duration_secs,
            platform=m["platform"],
            model=m["model"],
        )
        # Back-compat shape for existing cockpit reader (until V108 lands).
        return {
            "since": entry.get("paused_at"),
            "epoch": entry.get("paused_until_epoch", 0)
            - (entry.get("paused_until_epoch", 0) - int(time.time())),
            "expires_at": entry.get("paused_until"),
            "expires_epoch": entry.get("paused_until_epoch"),
            "reason": entry.get("reason"),
            "duration_secs": duration_secs,
            "quota_key": m["quota_key"],
            "platform": m["platform"],
            "model": m["model"],
        }

    def _unpause_agent_type(self, agent_type: str) -> bool:
        if not agent_type:
            return False
        m = _agent_manifest(agent_type)
        return self.quota.unpause(m["quota_key"])

    def _agent_type_is_paused(
        self, agent_type: Optional[str]
    ) -> Optional[Dict[str, Any]]:
        if not agent_type:
            return None
        m = _agent_manifest(agent_type)
        if not self.quota.is_paused(m["quota_key"]):
            return None
        entry = self.quota.get(m["quota_key"]) or {}
        return {
            "expires_at": entry.get("paused_until"),
            "expires_epoch": entry.get("paused_until_epoch"),
            "reason": entry.get("reason"),
            "quota_key": m["quota_key"],
            "platform": m["platform"],
            "model": m["model"],
        }

    def _paused_agent_types_view(self) -> Dict[str, Dict[str, Any]]:
        """Back-compat projection: map every agent_type whose
        quota_key is paused onto the legacy /health field shape.
        Built by walking AGENT_PROMPTS so multiple types sharing a
        pool all appear paused together (correct — they actually are)."""
        paused = self.quota.paused_view()
        out: Dict[str, Dict[str, Any]] = {}
        for t in AGENT_PROMPTS.keys():
            m = _agent_manifest(t)
            entry = paused.get(m["quota_key"])
            if entry:
                out[t] = {
                    "since": entry.get("paused_at"),
                    "expires_at": entry.get("paused_until"),
                    "expires_epoch": entry.get("paused_until_epoch"),
                    "reason": entry.get("reason"),
                    "quota_key": m["quota_key"],
                    "platform": entry.get("platform"),
                    "model": entry.get("model"),
                    "consecutive_rate_limits": entry.get("consecutive_rate_limits", 0),
                }
        return out

    def _bump_task_failure(self, task_id: Optional[str]) -> int:
        """Increment + return the cumulative unproductive-final count
        for `task_id` since daemon boot. Returns 0 when task_id is
        missing (untrackable)."""
        if not task_id:
            return 0
        if not hasattr(self, "_task_failures"):
            self._task_failures: Dict[str, int] = {}
        self._task_failures[task_id] = self._task_failures.get(task_id, 0) + 1
        return self._task_failures[task_id]


