# ── inlined from daemon/runneranchor.py (DM3+ bundle) ─────────────────────────
"""runneranchor.py — extracted from runner.py (daemon-architecture-v2 Phase 3d).

RunnerAnchorMixin: methods moved VERBATIM out of ChatRunner; Daemon inherits both so
every self.* resolves on the combined instance -> byte-identical."""


import json
import re
from typing import List



#: BT-4 — the opening of any marker in the family, bracket-agnostic like
#: the runner's `_ANCHOR_RE`. The payload is NOT part of the pattern: it is
#: read with `raw_decode` from where the marker ends, so it stops at the
#: JSON's own closing brace. The old `\{[^\n]*\}` ran greedily to the
#: LAST brace on the line, so `⟦report⟧ {..}⟦anchor⟧ {..} prose` (mf27,
#: 2026-09-28, one line from Muse) was unparseable JSON, matched nothing
#: and reached the operator verbatim.
_MARKER_OPEN = r"(?:⟦|〚|【|\[\[?)"
_MARKER_CLOSE = r"(?:⟧|〛|】|\]\]?)"
_DECODER = json.JSONDecoder()


def sweep_markers(text: str, name: str, on_payload=None, *, count: int = 0) -> str:
    """Remove every `⟦<name>⟧ {json}` in `text` (at most `count` when > 0),
    wherever it sits on its line, calling `on_payload(obj_or_None, raw)` for
    each. A payload that does not decode is removed to the end of its line:
    a broken marker must not leak into the chat either."""
    if name not in text:
        return text
    rx = re.compile(_MARKER_OPEN + re.escape(name) + _MARKER_CLOSE + r"[ \t]*")
    out: List[str] = []
    pos = 0
    n = 0
    while True:
        m = rx.search(text, pos)
        if not m or (count and n >= count):
            break
        start, end = m.start(), m.end()
        if end < len(text) and text[end] == "{":
            try:
                obj, stop = _DECODER.raw_decode(text, end)
                raw = text[end:stop]
            except ValueError:
                nl = text.find("\n", end)
                stop = len(text) if nl < 0 else nl
                obj, raw = None, text[end:stop]
        else:
            # A bare mention of the marker name in prose, not a marker.
            out.append(text[pos:end])
            pos = end
            continue
        if on_payload is not None:
            on_payload(obj, raw)
        out.append(text[pos:start])
        # Eat the spaces after the payload, and its newline when the marker
        # was the whole rest of the line.
        while stop < len(text) and text[stop] in " \t":
            stop += 1
        if (
            stop < len(text)
            and text[stop] == "\n"
            and (not out[-1] or out[-1].endswith("\n"))
        ):
            stop += 1
        pos = stop
        n += 1
    out.append(text[pos:])
    return "".join(out)


def drop_echoed_payload(text: str, payload) -> str:
    """BT-4 — remove lines that are nothing but `payload` as JSON. Some CLIs
    (Muse) print the report object once bare and once behind its marker."""
    if not isinstance(payload, dict) or "{" not in text:
        return text
    kept = []
    for ln in text.split("\n"):
        s = ln.strip()
        if s.startswith("{") and s.endswith("}"):
            try:
                if json.loads(s) == payload:
                    continue
            except ValueError:
                pass
        kept.append(ln)
    return "\n".join(kept)


class RunnerAnchorMixin:
    def _resolve_anchor_head(self, more_text: str, *, force: bool = False) -> str:
        """Buffer the head of the reply until we can decide whether
        it opens with an anchor marker. Returns the text that's safe
        to forward downstream (i.e. the head minus any marker line).

        Called for every delta until `_anchor_head_resolved` is True.
        `force=True` resolves unconditionally — for the end-of-stream
        flush (DM-CLI-10), when no more fragments can arrive so waiting
        for a first line is pointless."""
        self._head_buffer += more_text
        # Wait for at least one full line OR a hard 4 KB cap before
        # deciding — protects against fragmented first deltas.
        if (
            not force
            and "\n" not in self._head_buffer
            and len(self._head_buffer) < 4096
        ):
            return ""  # hold the entire buffer for now
        head = self._head_buffer.lstrip()
        # Strip leading whitespace; re-anchor the offset.
        lstripped_len = len(self._head_buffer) - len(head)
        # BT-4 — decode the payload from where the marker ends instead of
        # to the last `}` on the line, so a second marker (or prose) on the
        # same line does not turn a valid anchor into "malformed JSON".
        m = re.match(_MARKER_OPEN + r"anchor" + _MARKER_CLOSE + r"[ \t]*", head)
        consumed = 0
        raw_payload = ""
        err = None
        if m and head[m.end() : m.end() + 1] == "{":
            try:
                _obj, stop = _DECODER.raw_decode(head, m.end())
                raw_payload = head[m.end() : stop]
            except ValueError as e:
                nl = head.find("\n", m.end())
                stop = len(head) if nl < 0 else nl
                raw_payload, err = head[m.end() : stop], e
            while stop < len(head) and head[stop] in " \t":
                stop += 1
            if stop < len(head) and head[stop] == "\n":
                stop += 1
            consumed = stop
        else:
            m = None
        if m:
            try:
                if err is not None:
                    raise json.JSONDecodeError(str(err), raw_payload, 0)
                payload = json.loads(raw_payload)
            except json.JSONDecodeError as e:
                if self.daemon is not None:
                    try:
                        self.daemon._handle_anchor_rejected(
                            self.conv, f"malformed JSON: {e}", raw=raw_payload
                        )
                    except Exception:
                        pass
                else:
                    _log(f"anchor: malformed JSON in conv {self.conv}: {e}")
                payload = None
            if payload is not None and self.daemon is not None:
                try:
                    self.daemon._handle_anchor(self.conv, payload, raw=raw_payload)
                except Exception as e:
                    _log(f"anchor: handler raised for conv {self.conv}: {e}")
            elif payload is not None:
                # No daemon ref (standalone) — log and continue.
                _log(f"anchor (no daemon ref): conv={self.conv} payload={payload!r}")
            # Consume up to + including the matched marker line.
            consumed_end = lstripped_len + consumed
            visible = self._head_buffer[consumed_end:]
        else:
            # No marker → operator-visible from the start. Notify the
            # daemon so it can broadcast `conv.anchor_missing` once.
            if self.daemon is not None:
                try:
                    self.daemon._handle_anchor_missing(self.conv)
                except Exception:
                    pass
            visible = self._head_buffer
        self._head_buffer = ""
        self._anchor_head_resolved = True
        return self._strip_anchor_progress(visible)

    def _strip_anchor_progress(self, text: str) -> str:
        """HD-2: also captures + strips a streamed `⟦report⟧` marker.

        Detect `⟦anchor-progress⟧ {...}` lines anywhere in `text`,
        notify the daemon, and remove them so they don't reach the
        chat thread."""
        # py-1.14.10 — bracket-agnostic fast-path guard (see _ANCHOR_RE).
        text = self._take_report(text)
        text = self._take_become(text)

        def _progress(payload, raw: str) -> None:
            if payload is not None and self.daemon is not None:
                try:
                    self.daemon._handle_anchor_progress(self.conv, payload, raw=raw)
                except Exception as e:
                    _log(f"anchor-progress: handler raised: {e}")

        return sweep_markers(text, "anchor-progress", _progress)

    def _take_report(self, text: str) -> str:
        """HD-2 — pull a `⟦report⟧ {...}` marker out of `text`: parse the JSON
        into `self.report` (last one wins) and return the text without it.
        Malformed JSON is logged and stripped anyway — a broken marker must
        not leak into the chat, and "no report" is the honest outcome."""
        if "report" not in text:
            return text

        def _grab(payload, raw: str) -> None:
            if isinstance(payload, dict):
                self.report = payload
            elif payload is None:
                _log(f"report: malformed JSON in conv {self.conv}: {raw[:120]}")
            else:
                _log(f"report: not an object in conv {self.conv}: {raw[:120]}")

        text = sweep_markers(text, "report", _grab)
        return drop_echoed_payload(text, getattr(self, "report", None))

    def _take_become(self, text: str) -> str:
        """GA-3 — pull `⟦become⟧ <member id>` out of `text`.

        Recorded on the runner and applied when the turn finalises; the
        marker itself never reaches the chat bubble, like every other
        marker in this family. Last one wins: an agent that changes its
        mind twice in one turn ends up as the profile it named last."""
        if "become" not in text:
            return text

        def _grab(m: "re.Match[str]") -> str:
            self.become = m.group(1).strip()
            return ""

        return self._BECOME_RE.sub(_grab, text)

    def _strip_all_anchor_markers(self, text: str) -> str:
        """py-1.13.2 (anchor-strip-final fix, 2026-06-12). Belt-and-
        suspenders strip for the FINAL assistant message. The Claude SDK
        emits a `result` event with the entire reply in one piece; when
        present, daemon prefers `result_text` over `_cumulative_text`
        (the latter was already stripped delta-by-delta in
        `_resolve_anchor_head` + `_strip_anchor_progress`). That bypass
        meant `⟦anchor⟧ {...}` and `⟦anchor-progress⟧ {...}` lines
        leaked into the persisted timeline AND the broadcast chat
        message — operator saw the wire-protocol marker in chat.

        This helper sweeps both marker shapes from the final text. Pure
        text scrubbing — the side-effects (anchor handler, init/task
        file creation, conv_meta persist) already ran during the
        streaming pass. We only need to redact for display."""
        # py-1.14.10 — bracket-agnostic fast-path guard (see _ANCHOR_RE).
        # "anchor" in prose is harmless: the regexes still require a
        # bracket-wrapped marker + JSON body, so a bare word never matches.
        # HD-2 — the report marker rides the same sweep (and the delta path
        # below), so the final text is clean whichever path produced it.
        text = self._take_report(text)
        text = self._take_become(text)
        if "anchor" not in text:
            return text
        cleaned = sweep_markers(text, "anchor", count=1)
        cleaned = sweep_markers(cleaned, "anchor-progress")
        return cleaned.lstrip("\n")


# ── inlined from daemon/runnerloop.py (DM3+ bundle) ─────────────────────────
"""runnerloop.py — extracted from runner.py (daemon-architecture-v2 Phase 3d).

RunnerLoopMixin: methods moved VERBATIM out of ChatRunner; Daemon inherits both so
every self.* resolves on the combined instance -> byte-identical.

DM-CLI-01 (multi-cli-clients) — the per-line JSON recognition (`ev_type
== "stream_event"/"user"/"result"`) moved to each ClientDriver's
`parse_stream_line()`, which returns the four NormalizedEvent shapes
(TextDelta/ToolUse/ToolResult/Final). Everything else in this loop —
anchor-marker head buffering, delta throttling, tool timeline
persistence, usage/cost capture — is UNCHANGED: it's wire-protocol
orchestration MeshKore owns regardless of which client produced the
event, so it stays generic here rather than being duplicated per
driver."""


import secrets
import time
import traceback
from typing import Any, Dict, List, Optional, Tuple



class RunnerLoopMixin:
    #: BT-16 — keys that name what a tool call acts on, most specific first.
    _ACTION_KEYS = (
        "file_path",
        "path",
        "notebook_path",
        "command",
        "url",
        "pattern",
        "query",
        "description",
        "prompt",
    )

    @classmethod
    def _action_target(cls, data: Any) -> Optional[str]:
        """The one thing a tool call is working on, ≤80 chars: a file
        path, the head of a command, a URL. None when the call says
        nothing (Muse's up-front events)."""
        if not isinstance(data, dict):
            return None
        # BT-20 — a command that comes with the agent's own one-line
        # description (claude-code's Bash) reads better as that sentence
        # than as `/private/tmp/…/script.sh`.
        keys = cls._ACTION_KEYS
        if (
            isinstance(data.get("command"), str)
            and isinstance(data.get("description"), str)
            and data["description"].strip()
        ):
            keys = ("description",)
        for key in keys:
            v = data.get(key)
            if isinstance(v, str) and v.strip():
                one = " ".join(v.split())
                return one if len(one) <= 80 else one[:79] + "…"
        return None

    def current_action(self) -> Optional[Dict[str, Any]]:
        """BT-16 — `{tool, target, since}` for the live progress line, or
        None when the turn is not inside a tool call."""
        tool = getattr(self, "_open_tool", None)
        if not tool:
            return None
        return {
            "tool": tool,
            "target": getattr(self, "_open_tool_target", None)
            or getattr(self, "_last_action_target", None),
            "since": getattr(self, "_open_tool_since", None),
        }

    def action_counts(self) -> Dict[str, int]:
        """BT-20 — this turn's tool calls by tool name."""
        return dict(getattr(self, "_action_counts", None) or {})

    def _note_action(self, tool: str, *, new: bool) -> None:
        """BT-20 — count a new tool call, then tell the cockpit right away
        (a new call, or the target of the open one just arrived): the 30 s
        progress tick alone made a busy agent look idle."""
        if new:
            counts = getattr(self, "_action_counts", None)
            if counts is None:
                counts = self._action_counts = {}
            counts[tool] = counts.get(tool, 0) + 1
        self._broadcast_action_frame()

    def _broadcast_action_frame(self) -> None:
        """BT-20 — a `conv.progress` frame NOW, same shape as the reaper's
        tick, so the live line and trail move with every tool call."""
        started = getattr(self, "_started_at", None)
        if started is None:
            return
        tool = getattr(self, "_open_tool", None)
        tool_at = getattr(self, "_open_tool_at", None)
        mono = time.monotonic()
        try:
            self.hub.broadcast(
                {
                    "type": "conv.progress",
                    "conv": self.conv,
                    "ts": _iso_now(),
                    "elapsed_secs": int(max(0.0, time.time() - started)),
                    "idle_secs": 0,
                    "phase": "tool" if tool else "streaming",
                    "tool": tool,
                    "tool_secs": int(mono - tool_at) if tool and tool_at else None,
                    "current_action": self.current_action(),
                    "action_counts": self.action_counts(),
                    "tool_calls": int(getattr(self, "tool_calls_count", 0) or 0),
                    "deltas": int(getattr(self, "deltas_seen", 0) or 0),
                }
            )
        except Exception as e:  # noqa: BLE001 — observability never breaks a turn
            _log(f"runner: action frame emit failed for {self.conv}: {e}")

    def _emit_delta(self) -> None:
        """Broadcast the cumulative text of this turn as a delta."""
        self._emitted_len = len(self._cumulative_text)
        self.hub.broadcast(
            {
                "type": "chat.assistant.delta",
                "author": self.identity,
                "conv": self.conv,
                "stream_id": self.stream_id,
                "text": self._cumulative_text[:16000],
                "ts": _iso_now(),
            }
        )

    def _reader_loop(self) -> None:
        assert self.proc and self.proc.stdout
        # FC-2 (daemon-centralized) — this is a DEDICATED background thread that
        # outlives the POST /chat/dispatch request, so the request threadlocal
        # is already cleared. Re-bind this turn's project on THIS thread so every
        # self.daemon.* callback below (record_usage, _maybe_wake_parent_architect,
        # _persist_task_resolution, _handle_anchor*, _broadcast_conv_activity,
        # chat_archive, _conv_meta_load) resolves to THIS project — not the
        # default. Without this, project B's chat corrupts project A's roadmap/
        # conv_meta/archive. self.paths/self.cluster/self.hub on the runner are
        # already project-correct (captured at spawn); this fixes the daemon
        # callbacks that resolve via the threadlocal.
        if self._project_id and self.daemon is not None:
            self.daemon._set_req_project(self._project_id)
        driver = driver_for(getattr(self, "client", None))
        last_emit_at = 0.0
        result_text = ""
        for raw in self.proc.stdout:
            try:
                line = raw.decode("utf-8", "replace").strip()
            except Exception:
                continue
            if not line:
                continue
            # HOTFIX py-1.42.2 — one event we fail to handle must never stop
            # this loop: if it dies, nobody drains the child's stdout, the
            # pipe fills and the agent blocks forever with zero CPU (every
            # turn hung that way on py-1.42.0/1 after a bad call in BT-20).
            try:
                for ev in driver.parse_stream_line(line):
                    # LT-1 — every parsed event is proof of life. Stamped
                    # before any of the per-kind handling so even an event we
                    # end up dropping (an empty delta, a buffered anchor head)
                    # still counts as the process moving.
                    self._last_progress_at = time.monotonic()
                    if isinstance(ev, TextDelta):
                        delta = ev.text
                        if not delta:
                            continue
                        self.deltas_seen += 1
                        # LAL2 — Anchor protocol head buffering. Until the
                        # first newline (or 4 KB) the delta is held in
                        # `_head_buffer`; once we can decide whether it
                        # opens with `⟦anchor⟧ {...}` we strip the marker
                        # and forward the rest. After the head is resolved
                        # subsequent deltas just pass through the
                        # `⟦anchor-progress⟧` stripper.
                        if not self._anchor_head_resolved:
                            visible = self._resolve_anchor_head(delta)
                            if not self._anchor_head_resolved:
                                # Still buffering; nothing to broadcast yet.
                                continue
                            self._cumulative_text += visible
                        else:
                            self._cumulative_text += self._strip_anchor_progress(delta)
                        now = time.monotonic()
                        if now - last_emit_at > 0.2:
                            last_emit_at = now
                            self._emit_delta()
                    elif isinstance(ev, ToolInput):
                        # BT-16 — claude-code streams a tool's arguments AFTER
                        # its start event; the full assistant message carries
                        # them. Only the target changes: not a new call.
                        target = self._action_target(ev.input)
                        if target:
                            self._last_action_target = target
                            if self._open_tool and (
                                not ev.name or ev.name == self._open_tool
                            ):
                                self._open_tool_target = target
                                self._note_action(self._open_tool, new=False)
                    elif isinstance(ev, ToolUse):
                        # LIVE2 — the 0.2 s throttle drops the tail of a
                        # burst; flush it before the tool runs, or the
                        # cockpit shows cut text (`⟦anchor`) for as long as
                        # the tool takes (mf27, 2026-10-14: minutes).
                        if len(self._cumulative_text) != self._emitted_len:
                            self._emit_delta()
                        self.tool_calls_count += 1
                        # LT-2 — remember what we are blocked in and since
                        # when. This is the only place that knows; the reaper
                        # and the cockpit both read it from here.
                        self._open_tool = ev.name or "tool"
                        self._open_tool_at = time.monotonic()
                        self._open_tool_since = _iso_now()
                        self._open_tool_target = self._action_target(ev.input)
                        if self._open_tool_target:
                            self._last_action_target = self._open_tool_target
                        self._note_action(self._open_tool, new=True)
                        # py-1.5.0 — Persist tool.use to timeline so the
                        # cockpit can replay full turn detail after a reload
                        # or a daemon restart. Previously broadcast-only,
                        # which made historical turns auditable only via
                        # git log of the files the agent touched.
                        self.hub.broadcast(
                            _append_timeline(
                                self.paths,
                                {
                                    "type": "tool.use",
                                    "author": self.identity,
                                    "conv": self.conv,
                                    "stream_id": self.stream_id,
                                    "tool": ev.name,
                                    "input": ev.input,
                                },
                            )
                        )
                    elif isinstance(ev, ToolResult):
                        self._open_tool = None
                        self._open_tool_at = None
                        self._open_tool_target = None
                        self._open_tool_since = None
                        # BT-16 — Muse names what ran only here, after the fact.
                        done_target = self._action_target(getattr(ev, "detail", None))
                        if done_target:
                            self._last_action_target = done_target
                        # py-1.5.0 — Persist tool.result too (was
                        # broadcast-only). Pair-matched to a tool.use
                        # via stream_id in the cockpit.
                        self.hub.broadcast(
                            _append_timeline(
                                self.paths,
                                {
                                    "type": "tool.result",
                                    "author": self.identity,
                                    "conv": self.conv,
                                    "stream_id": self.stream_id,
                                    "ok": ev.ok,
                                    **(
                                        {"detail": ev.detail}
                                        if getattr(ev, "detail", None)
                                        else {}
                                    ),
                                },
                            )
                        )
                    elif isinstance(ev, Final):
                        result_text = ev.text
                        # CU1 (py-1.13.3) — Capture token usage + cost from
                        # the client's terminal event, when it reports one.
                        # Stored on the runner so the finalize block below
                        # can broadcast + accumulate after the loop exits.
                        if ev.usage is not None:
                            self.last_turn_usage = ev.usage
                        if ev.cost_usd is not None:
                            self.last_turn_cost_usd = ev.cost_usd
            except Exception as e:  # noqa: BLE001
                _debug_emit(
                    "runner.event-failed",
                    msg=f"{self.conv}: event handling failed: {type(e).__name__}: {e}",
                    lvl="error",
                    conv=self.conv,
                    data={"traceback": traceback.format_exc()[-2000:]},
                )
        # Finalize. py-1.13.2 — `result_text` (from the Claude SDK
        # `result` event) was bypassing the anchor stripper because the
        # stripper runs delta-by-delta on `_cumulative_text`. Sweep both
        # marker kinds from the final text before persisting/broadcasting.
        # DM-CLI-10 — flush an UNRESOLVED head buffer. Single-delta
        # clients (codex emits the whole reply as ONE TextDelta) whose
        # reply has no newline never trip the head resolver above, so
        # the reply sat in `_head_buffer` and the turn finalised empty
        # despite exit=0. The stream is over — no more fragments can
        # arrive — so resolve unconditionally. Skipped when the buffer
        # is empty so genuinely textless turns stay textless (and
        # `anchor_missing` doesn't fire for a turn that said nothing).
        if not self._anchor_head_resolved and self._head_buffer:
            self._cumulative_text += self._resolve_anchor_head("", force=True)
        final_text = self._strip_all_anchor_markers(
            result_text or self._cumulative_text
        )
        # py-1.21.1 — TRANSIENT API-ERROR RETRY SHIELD (TR1). claude-code
        # 2.1.145 occasionally fails a long interleaved-thinking + multi-
        # tool turn with `API Error: 400 … thinking/redacted_thinking
        # blocks in the latest assistant message cannot be modified` — a
        # CLI bug reconstructing the multi-block assistant message for the
        # tool-loop continuation (the daemon never touches that array), so
        # a fresh spawn rebuilds a clean array and the same turn succeeds.
        # Siblings: transient 5xx / overloaded / rate-limit. These are
        # TRANSPORT failures, NOT task outcomes. Before this shield the
        # error string got persisted as the turn's chat.assistant.final —
        # poisoning EVERY future briefing via `_section_history` — AND woke
        # the parent architect with a bogus task-failure verdict (field
        # 2026-06-18: `_onboarding_v1` exit=1 at content.12 → false
        # one-retry-then-blocked on the roadmap). Re-spawn the SAME turn up
        # to `_MAX_TRANSIENT_RETRIES`; the error is surfaced normally only
        # after the budget is spent. We branch on `result_text` (the raw
        # SDK `result`) so anchor-stripping can't mask the signature.
        if self._maybe_retry_transient(result_text or self._cumulative_text):
            return
        # py-1.7.0 — Harvest REMEMBER: lines into the role's shared
        # memory. Anything the agent flags ("REMEMBER: credentials live
        # at …") gets appended once, deduplicated. Lines are also
        # stripped from the final response shown in the chat so they
        # don't clutter the UI.
        cleaned_text, harvested = self._harvest_remember_lines(final_text)
        if harvested:
            try:
                self._append_role_memory(harvested)
            except Exception as e:
                _log(f"role memory append failed: {e}")
        self._emit_final(cleaned_text)
        # GA-3 — apply `⟦become⟧` AFTER the final lands. Rebinding before
        # would change the profile out from under the turn that asked for
        # it, and the operator would see the new identity on a message the
        # old one wrote.
        if self.become and self.daemon is not None:
            try:
                self.daemon._apply_become(self.conv, self.become)
            except Exception as e:  # noqa: BLE001 — never fail a turn over this
                _log(f"become: applying {self.become!r} on {self.conv} failed: {e}")
        # CU1 (py-1.13.3) — Broadcast token usage + cost AFTER the
        # final lands. Cockpit ingests via `chat.usage` and updates
        # `chatStore.state.convs[conv].usage` so the operator sees
        # `12.3k in · 4.5k out · $0.15` in the agent's scope strip.
        if self.last_turn_usage is not None and self.daemon is not None:
            try:
                cumulative = self.daemon.chat_sessions.record_usage(
                    self.conv,
                    self.last_turn_usage,
                    self.last_turn_cost_usd,
                )
                # CTX1 (py-1.28.0) — context-window awareness. Resolve the
                # policy from the CLIENT that actually ran this turn
                # (claude-code knows its window + self-compacts; an
                # unmodelled client gets a null policy — no gauge, no
                # compaction claim). `describe()` turns this turn's prompt
                # tokens into a fill ratio + a should_compact flag the
                # cockpit paints as the context gauge / "will compact"
                # hint. See contextpolicy.py for the headless-turn
                # rationale. DM-CLI-02 (multi-cli-clients) — was keyed by
                # `_agent_manifest(agent_type).get("platform")` (a
                # role-level, always-claude-code-in-practice value); now
                # keyed by `self.client`, the actual per-member dispatch
                # target, so a future Gemini/Codex member reports
                # "unmodelled" instead of a false claude-code claim.
                context_block = policy_for(self.client or "claude-code").describe(
                    self.last_turn_usage, self.model
                )
                self.hub.broadcast(
                    {
                        "type": "chat.usage",
                        "conv": self.conv,
                        "stream_id": self.stream_id,
                        "turn": {
                            **self.last_turn_usage,
                            "cost_usd": self.last_turn_cost_usd,
                        },
                        "total": cumulative,
                        "model": self.model,
                        "context": context_block,
                        "ts": _iso_now(),
                    }
                )
            except Exception as e:
                _log(f"chat.usage broadcast failed for {self.conv}: {e}")
        # py-1.10.4 — surface the exit code in the daemon log so a
        # silent claude failure (empty stdout, no final, etc.) can
        # be traced back to e.g. "exited 1 with stderr 'context
        # length exceeded'". Without this line, every empty-final
        # looked identical regardless of whether claude crashed,
        # blocked on a tool, or genuinely had nothing to say.
        exit_code = self.proc.wait() if self.proc else None
        text_len = len(cleaned_text or "")
        _log(
            f"{getattr(self, 'client', None) or 'claude-code'}({self.conv}) "
            f"exit={exit_code} stream={self.stream_id} "
            f"text_len={text_len} agent_type={self.agent_type}"
        )
        _debug_emit(
            "subagent-final",
            msg=f"{self.conv} exit={exit_code} text_len={text_len}",
            lvl=("warn" if exit_code not in (None, 0) else "info"),
            conv=self.conv,
            agent_id=self.agent_id,
            data={
                "agent_type": self.agent_type,
                "exit": exit_code,
                "text_len": text_len,
                "stream_id": self.stream_id,
                "preview": (cleaned_text or "")[:200],
            },
        )
        self.hub.broadcast(
            {
                "type": "task.finished",
                "id": f"chat:{self.conv}",
                "ts": _iso_now(),
                "exit": exit_code,
                "conv": self.conv,
            }
        )
        # py-1.10.16 — Architect wake hook. If this conv was dispatched
        # by a roadmap-architect (parent_conv recorded in conv_meta),
        # post a `[architect-wake]` turn back to the parent so the
        # pass resumes the moment the subagent finishes. Without this,
        # the architect would have to poll inside its own turn (burns
        # tokens) or rely on the operator to nudge it.
        if self.daemon is not None:
            try:
                # HD-2 — persist the turn's ⟦report⟧ on the conv first, so the
                # parent (and the cockpit) can read it even if the wake fails.
                if self.report is not None:
                    try:
                        a_type, a_id = self.daemon._conv_meta_get(self.conv)
                        self.daemon._conv_meta_set(
                            self.conv, a_type, a_id, report=self.report
                        )
                    except Exception as e:
                        _log(f"report persist failed for {self.conv}: {e}")
                self.daemon._maybe_wake_parent_architect(
                    child_conv=self.conv,
                    child_agent_id=self.agent_id,
                    child_final_text=cleaned_text,
                    child_exit=exit_code,
                    child_report=self.report,
                )
            except Exception as e:
                _log(f"architect wake hook failed for {self.conv}: {e}")
            # Standard v26 — persist the task's resolution record (frontmatter
            # pointers + `## Resolution` body) when this turn finished a task.
            # Fires for EVERY conv, not just architect children, so a task
            # closed by any agent gets a durable summary.
            try:
                self.daemon._persist_task_resolution(
                    conv=self.conv,
                    agent_id=self.agent_id,
                    final_text=cleaned_text,
                    exit_code=exit_code,
                    start_sha=getattr(self, "_turn_start_sha", None),
                )
            except Exception as e:
                _log(f"task-resolution persist failed for {self.conv}: {e}")
            # py-1.11.0 — Broadcast conv.activity for this conv with
            # live=false override. Fires before ChatSessions._wait pops
            # us from `_s`; the override ensures the cockpit sees the
            # right state regardless of the race.
            try:
                self.daemon._broadcast_conv_activity(self.conv, live_override=False)
            except Exception as e:
                _log(f"conv.activity broadcast on final failed for {self.conv}: {e}")
            # py-1.12.9 — Auto-archive any finished SUBAGENT conv.
            # Criterion broadened from "work-* prefix" (py-1.11.2) to
            # "has parent_conv in meta OR matches `work-*` slug". A
            # subagent is anything the architect dispatched — workers
            # (work-*), deploy, db, testing, and ad-hoc customs all
            # carry `parent_conv` in conv_meta. The new rule catches
            # them uniformly.
            #
            # NOT auto-archived (operator-owned, multi-turn):
            #   - Master `_onboarding_v1` (the Coordinator)
            #   - `roadmap-architect-*` (carries the pass summary)
            #   - Any conv WITHOUT parent_conv and not prefixed work-
            #     (= the operator opened it manually, keep it open)
            #
            # Operator field report 2026-06-06: "garantizar que cuando
            # se lanzan agentes que hacen tareas se cierran. Si el
            # usuario quiere abrir tres a mano y dejarlos ahí no hay
            # problema." This matches the rule exactly: dispatched →
            # auto-archive; operator-opened → leave alone.
            should_auto_archive = False
            if not self.daemon.chat_archive.is_archived(self.conv):
                if self.conv.startswith("work-"):
                    should_auto_archive = True
                elif self.conv == "_onboarding_v1":
                    should_auto_archive = False
                elif self.conv.startswith("roadmap-architect-"):
                    should_auto_archive = False
                else:
                    # Look up parent_conv from meta sidecar.
                    try:
                        meta = self.daemon._conv_meta_load().get(self.conv) or {}
                        if meta.get("parent_conv"):
                            should_auto_archive = True
                    except Exception as e:
                        _log(f"auto-archive meta check failed for {self.conv}: {e}")
            if should_auto_archive:
                try:
                    entry = self.daemon.chat_archive.archive(
                        self.conv,
                        by="auto-subagent-finish",
                    )
                    self.hub.broadcast(
                        {
                            "type": "conv.archived",
                            "conv": self.conv,
                            "archived_at": entry.get("archived_at"),
                            "by": entry.get("by"),
                            "ts": entry.get("archived_at"),
                        }
                    )
                except Exception as e:
                    _log(f"auto-archive of {self.conv} failed: {e}")
            else:
                # BT-11 — a delegated session (member `mb-*`, or an
                # Orchestrator an agent started) closes once it holds no
                # open request. Runs AFTER the wake above, so the parent has
                # already been dispatched its report; the next brief for that
                # member opens a fresh, empty session.
                try:
                    self.daemon._close_session_if_done(self.conv)
                except Exception as e:
                    _log(f"session-close check failed for {self.conv}: {e}")
        # REL1 — an EMPTY reply is the failure the operator actually hits:
        # the CLI was killed, ran out of quota, crashed after the last tool
        # call. The turn still finalises (consumers — the delegation rail,
        # external asks — wait on that final), but an empty bubble tells the
        # person waiting nothing at all. Say what happened, in the thread,
        # with the exit code and whatever the process put on stderr.
        # LT-1 — unless the reaper already killed it and SAID SO. A
        # hard-timeout cancel is SIGTERM to the process group, so the
        # child exits 143 and lands here 0.35 s after the reaper's own
        # notice: the operator got two alarming, unrelated-looking
        # errors for one event. The reaper's message is the accurate
        # one (it knows WHY), so this one stands down.
        if not (cleaned_text or "").strip() and not getattr(
            self, "_reaped_reason", None
        ):
            why = "the process produced no output"
            if exit_code not in (None, 0):
                why = f"the process exited with code {exit_code}"
            tail = [t for t in (getattr(self, "_stderr_tail", None) or []) if t][-2:]
            detail = (" · " + " / ".join(tail)[:300]) if tail else ""
            try:
                self.hub.broadcast(
                    _append_timeline(
                        self.paths,
                        {
                            "type": "chat.error",
                            "conv": self.conv,
                            "author": self.identity,
                            "reason": "empty-reply",
                            "stream_id": self.stream_id,
                            "text": (
                                f"The turn ended with no reply — {why}{detail}."
                                " Resend to try again; if it keeps happening,"
                                " check the client/model on this agent."
                            ),
                        },
                    )
                )
            except Exception as e:  # noqa: BLE001 — never fail a turn over this
                _log(f"chat.error emit failed for {self.conv}: {e}")

        # REL1 — one structured line per finished turn, so turn health is
        # measurable instead of anecdotal: `.meshkore/.runtime/debug.jsonl`
        # (and the cockpit's debug stream) now carry every turn's client,
        # duration, output size and whether it produced anything at all.
        # "A veces no contesta" was impossible to quantify before this.
        try:
            started = getattr(self, "_started_at", None)
            secs = int(time.time() - started) if started else None
            _debug_emit(
                "chat-turn.done",
                msg=(
                    f"turn {self.conv} · {getattr(self, 'client', None) or 'claude-code'}"
                    f" · {secs if secs is not None else '?'}s"
                    f" · {len(final_text or '')}ch"
                ),
                lvl="info" if (final_text or "").strip() else "warn",
                conv=self.conv,
                data={
                    "client": getattr(self, "client", None) or "claude-code",
                    "provider": getattr(self, "provider", None) or "anthropic",
                    "model": getattr(self, "model", None),
                    "secs": secs,
                    "chars": len(final_text or ""),
                    "empty": not (final_text or "").strip(),
                    "stream_id": self.stream_id,
                },
            )
        except Exception:  # noqa: BLE001 — observability never fails a turn
            pass
        self.done.set()

    # TR1 (py-1.21.1) — re-spawn budget for transport-class API errors.
    # 2 retries = 3 attempts total. Past this we surface the error so a
    # genuinely stuck turn can't loop forever. (Driver-agnostic: the
    # budget applies regardless of which client is running; only the
    # error-string CLASSIFIER below is driver-specific.)
    _MAX_TRANSIENT_RETRIES = 2

    def _is_transient_api_error(self, text: str) -> bool:
        """True iff `text` is a TRANSPORT failure (rate limit, upstream
        5xx, timeout) the current client's driver recognizes as
        plausibly cleared by a fresh spawn — not a task outcome.
        DM-CLI-01: thin delegate to the resolved driver so this method
        name/signature stays stable for every existing caller/test;
        the actual per-client error vocabulary now lives in
        `clidrivers/*.py:is_transient_error()`."""
        return driver_for(getattr(self, "client", None)).is_transient_error(text)

    def _maybe_retry_transient(self, result_text: str) -> bool:
        """If the turn died on a transient API error and we still have
        budget, reap the dead child, reset per-turn streaming state, and
        re-spawn the SAME turn on a fresh `claude -p` process. Returns
        True when a re-spawn was launched (the caller must `return`
        immediately so the failed run does NOT broadcast a final / wake
        the architect / set `done`). Returns False to let the normal
        finalize path run (success, cancel, non-transient error, or
        budget exhausted)."""
        if self.cancelled:
            return False
        if not self._is_transient_api_error(result_text):
            return False
        # Reap the dead child + confirm it actually failed. A clean exit
        # whose text merely *discusses* an API error must not be retried.
        exit_code = None
        try:
            if self.proc is not None:
                exit_code = self.proc.wait(timeout=5)
        except Exception:
            exit_code = None
        if exit_code in (None, 0):
            return False
        attempt = getattr(self, "_transient_attempt", 0)
        if attempt >= self._MAX_TRANSIENT_RETRIES:
            _log(
                f"{getattr(self, 'client', None) or 'claude-code'}({self.conv}) "
                f"transient API error — retry budget "
                f"({self._MAX_TRANSIENT_RETRIES}) exhausted; surfacing error"
            )
            return False
        self._transient_attempt = attempt + 1
        preview = (result_text or "").strip()[:200]
        _log(
            f"{getattr(self, 'client', None) or 'claude-code'}({self.conv}) "
            f"transient API error "
            f"(attempt {self._transient_attempt}/{self._MAX_TRANSIENT_RETRIES}) "
            f"— re-spawning. err={preview!r}"
        )
        _debug_emit(
            "transient-retry",
            msg=(
                f"{self.conv} transient API error — re-spawn "
                f"{self._transient_attempt}/{self._MAX_TRANSIENT_RETRIES}"
            ),
            lvl="warn",
            conv=self.conv,
            agent_id=self.agent_id,
            data={
                "attempt": self._transient_attempt,
                "agent_type": self.agent_type,
                "preview": preview,
            },
        )
        # Reset per-turn streaming + anchor + usage state so the fresh run
        # starts from a clean slate (a NEW stream_id so the cockpit treats
        # it as a brand-new bubble rather than appending to the dead one).
        self._cumulative_text = ""
        self._emitted_len = 0
        self._head_buffer = ""
        self._anchor_head_resolved = False
        self.deltas_seen = 0
        self.tool_calls_count = 0
        self.last_turn_usage = None
        self.last_turn_cost_usd = None
        self.stream_id = f"s_{int(time.time() * 1000):x}_{secrets.token_hex(2)}"
        # Small backoff — helps 5xx/overloaded settle; harmless for the
        # thinking-block 400 (which is instant-clearable).
        time.sleep(min(2**self._transient_attempt, 8))
        if self.cancelled:
            return False
        # Fresh spawn → new _reader_loop thread; THIS loop returns. The
        # failed turn's error was never persisted, so `_briefing()` rebuilds
        # clean history (the user turn was persisted at dispatch).
        self.spawn()
        return True

    def _harvest_remember_lines(self, text: str) -> Tuple[str, List[str]]:
        """Extract any `REMEMBER: …` lines from `text` and return
        (cleaned text, list of remembered facts). Case-insensitive on
        the marker; one fact per line."""
        if not text:
            return text, []
        kept: List[str] = []
        harvested: List[str] = []
        for line in text.splitlines():
            stripped = line.strip()
            low = stripped.lower()
            # Allow "REMEMBER: ...", "- REMEMBER: ...", "* REMEMBER: ..."
            for prefix in ("remember:", "- remember:", "* remember:"):
                if low.startswith(prefix):
                    fact = stripped[len(prefix) :].strip()
                    # When the prefix had a list bullet, strip the bullet.
                    if prefix.startswith(("-", "*")):
                        fact = fact.lstrip()
                    if fact:
                        harvested.append(fact)
                    break
            else:
                kept.append(line)
                continue
        cleaned = "\n".join(kept).rstrip()
        return cleaned, harvested

    def _append_role_memory(self, facts: List[str]) -> None:
        """Append facts to `.meshkore/agents/_types/<agent-type>/memory.md`,
        deduplicating against what's already in the file. Each entry
        prefixed with its UTC date so memory has provenance."""
        if not facts:
            return
        from datetime import datetime as _dt

        today = _dt.utcnow().strftime("%Y-%m-%d")
        d = self.paths.agents_dir / "_types" / self.agent_type
        d.mkdir(parents=True, exist_ok=True)
        path = d / "memory.md"
        existing = ""
        try:
            existing = path.read_text(errors="replace") if path.exists() else ""
        except OSError:
            existing = ""
        existing_lc = existing.lower()
        new_blocks: List[str] = []
        for fact in facts:
            if fact.lower() in existing_lc:
                continue
            new_blocks.append(f"- {today} · {fact}")
        if not new_blocks:
            return
        header = ""
        if not existing.strip():
            header = (
                f"# `{self.agent_type}` role memory\n\n"
                f"Long-lived facts captured by past instances of this role "
                f"via `REMEMBER: …` lines. Append-only.\n\n"
            )
        addition = (
            ("\n" if existing and not existing.endswith("\n") else "")
            + "\n".join(new_blocks)
            + "\n"
        )
        with path.open("a", encoding="utf-8") as fh:
            if header:
                fh.write(header)
            fh.write(addition)


